<%_ if (season === '春') { _%>
          - 春季天气池：[晴(30%), 多云(40%), 雨(20%), 大风(10%)]。禁止出现'雪'。
<%_ } else if (season === '夏') { _%>
          - 夏季天气池：[晴(40%), 多云(20%), 雨(30%), 大风(10%)]。禁止出现'雪'。
<%_ } else if (season === '秋') { _%>
          - 秋季天气池：[晴(50%), 多云(30%), 大风(15%), 雨(5%)]。禁止出现'雪'。
<%_ } else { _%>
          - 冬季天气池：[晴(10%), 多云(10%), 雪(50%), 大风(30%)]。禁止出现'雨'。
<%_ } _%>

