                '居家': 'home',
                '健身房': 'gym',
                '丝袜': 'silk_nsfw',
                '全裸': 'nude_nsfw'
            };

            const fallbackAvatars = {
                '尹以菽': '🌙'
            };

            function parseField(label, fallback) {
                const m = sceneText.match(new RegExp(label + '[：:]\\s*(.+)'));
                return m ? m[1].trim() : fallback;
            }

            function parseCharacters() {
                const match = sceneText.match(/在场角色[：:]\s*([\s\S]*?)(?=\n\n|\n$|$)/);
                if (!match) return [];

                const lines = match[1]
                    .split('\n')
                    .map(line => line.trim())
                    .filter(line => line.startsWith('-'))
                    .map(line => line.replace(/^[-]\s*/, '').trim());

                const chars = lines.map(line => {
                    const parts = line.split('|');
                    const name = (parts[0] || '').trim();
                    const typeZhRaw = (parts[1] || '日常T恤').trim();
                    if (!roleMap.hasOwnProperty(name)) return null;

                    const typeZh = typeMap.hasOwnProperty(typeZhRaw) ? typeZhRaw : '日常T恤';
                    return {
                        name: name,
                        typeZh: typeZh
                    };
                }).filter(Boolean);

                return chars;
            }

            function buildFileName(nameZh, typeZh) {
                const role = roleMap[nameZh];
                const typeEn = typeMap[typeZh] || 'tee';
                return role + '_' + typeEn + '.png';
            }

            function buildUrlForFileName(fileName) {
                return SPECIAL_FILE_URL_MAP[fileName] || (BASE_URL + '/' + fileName);
            }

            // 回退顺序：当前类型 -> 居家 -> 日常T恤 -> JK服
            function getFallbackCandidates(nameZh, typeZh) {
                const safeType = typeMap.hasOwnProperty(typeZh) ? typeZh : '日常T恤';
                const typeFallbacks = [safeType, '居家', '日常T恤', 'JK服'];

                const dedupTypes = [];
                for (let i = 0; i < typeFallbacks.length; i++) {
                    const t = typeFallbacks[i];
                    if (!dedupTypes.includes(t)) dedupTypes.push(t);
                }

                const urls = [];
                for (let i = 0; i < dedupTypes.length; i++) {
                    const fileName = buildFileName(nameZh, dedupTypes[i]);
                    urls.push(buildUrlForFileName(fileName));
                }
                return urls;
            }

            const location = parseField('地点', '未知地点');
            const time = parseField('时间', '未知时间');
            const characters = parseCharacters();

            // 场景信息
            const metaContainer = document.getElementById('scene-meta');
            metaContainer.innerHTML = '' +
                '<div class="meta-row"><span class="meta-label">地点</span><span class="meta-text">' + location + '</span></div>' +
                '<div class="meta-row"><span class="meta-label">时间</span><span class="meta-text">' + time + '</span></div>';

            // 角色卡
            const container = document.getElementById('character-container');
            if (!characters.length) {
                container.innerHTML = '<div class="empty-tip">未识别到白名单角色。</div>';
                return;
            }

            let cardsHTML = '<div class="character-grid">';
            for (let i = 0; i < characters.length; i++) {
                const ch = characters[i];
                const fallback = fallbackAvatars[ch.name] || '👤';
                cardsHTML += '' +
                    '<div class="character-card">' +
                        '<div class="character-avatar">' +
                            '<img data-role="img-' + i + '" alt="' + ch.name + '">' +
                            '<div data-role="fb-' + i + '" class="character-avatar-fallback" style="display:none;">' + fallback + '</div>' +
                        '</div>' +
                        '<div class="character-meta">' +
                            '<div class="character-name">' + ch.name + '</div>' +
                            '<div class="type-chip">' + ch.typeZh + '</div>' +
                        '</div>' +
                    '</div>';
            }
            cardsHTML += '</div>';
            container.innerHTML = cardsHTML;

            // 逐卡绑定回退加载
            for (let i = 0; i < characters.length; i++) {
                const ch = characters[i];
                const urls = getFallbackCandidates(ch.name, ch.typeZh);
                const img = container.querySelector('[data-role="img-' + i + '"]');
                const fb = container.querySelector('[data-role="fb-' + i + '"]');

                let idx = 0;
                const tryNext = function() {
                    if (idx >= urls.length) {
                        img.style.display = 'none';
                        fb.style.display = 'flex';
                        return;
                    }
                    img.src = urls[idx++];
                };

                img.onerror = tryNext;
                tryNext();
            }
        })();

        function toggleCollapse() {
            const container = document.getElementById('character-container');
            const icon = document.getElementById('collapse-icon');
            const text = document.getElementById('collapse-text');

            container.classList.toggle('collapsed');
            icon.classList.toggle('collapsed');

            if (container.classList.contains('collapsed')) {
                text.textContent = '展开角色区';
            } else {
                text.textContent = '收起角色区';
            }
        }
    </script>
</body>
</html>
