                    });
                    pregNsfwSection.appendChild(pregNsfwGrid);
                    galleryContainer.appendChild(pregNsfwSection);
                }
            }
        }

        function createGridItem(imgSrc, tag, filename) {
            const div = document.createElement('div');
            div.className = 'grid-item';
            div.innerHTML = `
                <div class="grid-thumb">
                    ${imgSrc ? `<img src="${imgSrc}" alt="${tag}" loading="lazy" onerror="this.style.display='none'; this.nextElementSibling.style.display='block';">` : ''}
                    <div class="placeholder-text" style="${imgSrc ? 'display:none;' : 'display:block;'}">?</div>
                </div>
                <div class="grid-info">
                    <div class="grid-tag">${tag}</div>
                    <div class="grid-filename">${filename}</div>
                </div>
            `;
            return div;
        }

        init();

    </script>
