        const left = Math.random() * 100;
        const dur = (Math.random() * 4 + 3.5);
        const delay = Math.random() * 5;
        const drift = Math.random() * 60 - 30;

        if (type === 'snow') {
            const sz = Math.random() * 3 + 2;
            p.style.width = sz + 'px'; p.style.height = sz + 'px';
            p.style.borderRadius = '50%';
