function parseSecretLetter(raw) {
    const data = {
        char: 'ji_qingmei',
        medium: '',
        time: '',
        letter: ''
    };

    const m = raw.match(/<secret_letter>([\s\S]*?)(?:<\/secret_letter>|$)/);
    const content = m ? m[1] : raw;

    const get = (k) => {
        const match = content.match(new RegExp('\\[' + k + '\\|([\\s\\S]*?)\\]'));
        return match ? match[1].trim() : '';
    };

    data.char = get('角色') || data.char;
    data.medium = get('信物') || get('媒介');
    data.time = get('时辰') || get('时间');
    data.letter = get('信文') || get('内容') || get('私语');

    if (!LETTER_PROFILES[data.char]) {
        for (let k in LETTER_PROFILES) {
            if (content.includes(LETTER_PROFILES[k].cn) || content.includes(LETTER_PROFILES[k].title)) {
                data.char = k;
                break;
            }
        }
    }
    if (!LETTER_PROFILES[data.char]) data.char = 'ji_qingmei';

    return data;
}

function renderLetter(d) {
