    document.getElementById('sbTitleRole').textContent = `【禁中絕密 · ${p.cn} 鞘底密箋】`;
    document.getElementById('paperWaxSurname').textContent = p.surname;

    // 2. 密信内容更新
    document.getElementById('lsMedium').textContent = d.medium || p.defaultMedium;
    document.getElementById('lsTime').textContent = d.time || p.defaultTime;
    document.getElementById('lsRoleTitle').textContent = p.title;
    document.getElementById('lsSealTxt').textContent = p.seal;
    document.getElementById('lsBodyText').textContent = d.letter || p.defaultLetter;

    // 3. 头像注入
    const avatarUrl = REPO_BASE + d.char + '_daily.png';
    const avatarImg = document.getElementById('lsAvatarImg');
    avatarImg.classList.remove('loaded');
    avatarImg.src = avatarUrl;

    // 4. 专属粒子生成
    spawnFxParticles(p.particleType, p.color);
}

/* ================= 酒馆宿主环境接入与初始化 ================= */
function pickLetterData() {
    try {
        if (typeof getChatMessages === 'function') {
            const id = (typeof getCurrentMessageId === 'function') ? getCurrentMessageId() : null;
            if (id !== null && id !== undefined) {
                const cur = getChatMessages(id);
                if (cur && cur.length) {
                    for (let i = 0; i < cur.length; i++) {
                        if (cur[i].message && cur[i].message.includes('<secret_letter>')) return cur[i].message;
                    }
                }
            }
            const all = getChatMessages();
            if (all && all.length) {
                for (let j = all.length - 1; j >= 0; j--) {
                    if (all[j].message && all[j].message.includes('<secret_letter>')) return all[j].message;
                }
            }
        }
    } catch(e){}
    return null;
}

function demoLetterData() {
