    var s='<svg xmlns="http://www.w3.org/2000/svg" width="92" height="108" viewBox="0 0 92 108"><rect width="92" height="108" fill="#120e0b"/><rect x="4" y="4" width="84" height="100" fill="none" stroke="'+color+'" stroke-width="1.2" stroke-dasharray="3,3"/><circle cx="46" cy="54" r="28" fill="'+color+'" fill-opacity="0.12"/><text x="46" y="63" font-family="STSong,Songti SC,serif" font-size="42" font-weight="900" fill="'+color+'" fill-opacity="0.8" text-anchor="middle">'+sur+'</text></svg>';
    return 'data:image/svg+xml;charset=utf-8,'+encodeURIComponent(s);
  }

  var raw=document.getElementById('d').textContent||'';
  var p=raw.split('|');
  var name=(p[0]||'').trim();
  var mood=(p[1]||'').trim();
  var text=p.slice(2).join('|').trim();

  if(text.length>1){
    var q0=text.charAt(0), q1=text.charAt(text.length-1);
    if((q0==='"'&&q1==='"')||(q0==='“'&&q1==='”')||(q0==='‘'&&q1==='’')){
      text=text.slice(1,-1).trim();
    }
  }

  var key=resolve(name);
  /* 兜底角色（{{user}} 或未登记人物）：占位头像取名字首字 */
  var role=key?CHARS[key]:{cn:name||'暗探',sur:(name||'密').charAt(0),title:'',img:'',color:'#9c8c77'};
  var color=role.color;

  var el=document.getElementById('rpb');
  el.style.setProperty('--c', color);

  el.style.setProperty('--bg-l', blend(color, 'faf6ee', 0.12));
  el.style.setProperty('--bd-l', blend(color, 'ded5c2', 0.40));
  el.style.setProperty('--bg-d', blend(color, '111419', 0.25));
  el.style.setProperty('--bd-d', blend(color, '111419', 0.55));

  document.getElementById('nm').textContent=role.cn;
  var tt=document.getElementById('tt');
  if(role.title){tt.textContent=role.title;}else{tt.style.display='none';}
  document.getElementById('bb').textContent=text||'……';

  var md=document.getElementById('md');
  if(mood){
    var mColor = MOODS[mood] || color;
    md.style.setProperty('--mc', mColor);
    md.textContent=(MICON[mood]?MICON[mood]+' ':'')+mood;
  }else{md.style.display='none';}

  var av=document.getElementById('av');
  var img=document.createElement('img');
  img.decoding='async';
  img.loading='lazy'; /* 性能优化⑥（全端）：离屏气泡头像延迟加载，视口内行为不变 */
  img.onload=function(){this.classList.add('on');reheight();};
  if(role.img){
    img.onerror=function(){this.onerror=null;this.src=ph(role.sur,color);};
    img.src=REPO+role.img+'_daily.png';
  }else{img.src=ph(role.sur,color);}
  av.appendChild(img);

  function syncTheme(){
    try{
      var isLight = localStorage.getItem('yanchao_theme')==='light' || localStorage.getItem('char_card_theme')==='light';
      document.body.classList.toggle('light', isLight);
    }catch(e){}
  }
  syncTheme();

  /* ▼ 性能优化②：主题轮询只在「前台 + 气泡在视口内」时执行。
     多气泡 = 多个 iframe，原来各自每秒读一次 localStorage 且永不停止，
     翻旧消息/切后台也在跑；现在离屏全停，回视口第一帧即恢复同步 ▼ */
  var inView=true;
  if(window.IntersectionObserver){
    try{
      new IntersectionObserver(function(es){
        for(var i=0;i<es.length;i++){
          inView=es[i].isIntersecting;
          el.classList.toggle('rpb-off',!es[i].isIntersecting); /* 优化⑤：离屏冻结动画 */
        }
      }).observe(el);
    }catch(e){}
  }
  setInterval(function(){
    if(document.hidden||!inView){return;}
    syncTheme();
  },1000);
  window.addEventListener('storage', function(e){
    if(e.key==='yanchao_theme'||e.key==='char_card_theme') syncTheme();
  });
  /* ▼ 性能优化③：接收主场景卡的 postMessage 主题广播（有则秒级同步，无则静默忽略） ▼ */
  window.addEventListener('message', function(e){
    if(e&&e.data&&e.data.type==='yanchao_theme_change') syncTheme();
  });

  /* ▼ 性能优化④：高度回写去重。原来每次 reheight 都无条件写
     frameElement.style.height（触发父页面回流），挂载时 60/300/800ms 三连发
     + onload + ResizeObserver，N 个气泡同时出现 = 约 5N 次父页布局抖动，
     正好与入场动画撞车。现在数值不变就不写 ▼ */
  var lastH=0;
  function reheight(){
    var h=document.getElementById('rpb').offsetHeight+14;
    if(h===lastH){return;}
    lastH=h;
    try{if(window.frameElement)window.frameElement.style.height=h+'px';}catch(e){}
  }
  reheight();
  setTimeout(reheight,60);
  setTimeout(reheight,300);
  setTimeout(reheight,800);
  if(document.fonts&&document.fonts.ready){document.fonts.ready.then(function(){reheight();});}
  if(window.ResizeObserver){new ResizeObserver(function(){reheight();}).observe(document.getElementById('rpb'));}
  window.addEventListener('resize',reheight);
})();
</script>
</body></html>

