  toastTimer = setTimeout(function(){ $t.removeClass('show'); }, 1800);
}

/* ---------- Swipe 切换 ---------- */
function switchSwipe(swipeId, roleName){
  try {
    if(typeof SillyTavern === 'undefined' || !SillyTavern.chat || !SillyTavern.chat[0]){
      showToast('⚠ 未检测到酒馆环境'); return;
    }
    var msg = SillyTavern.chat[0];
    if(!msg.swipes || msg.swipes[swipeId] === undefined){
      showToast('⚠ 未找到「'+roleName+'」开局 (swipe '+swipeId+')'); return;
    }
    if(msg.swipe_id === swipeId && msg.mes === msg.swipes[swipeId]){
      showToast('📌 当前已是「'+roleName+'」开局'); return;
    }
    msg.swipe_id = swipeId;
    msg.mes = msg.swipes[swipeId];

    // 通过 MVU 框架写入 stat_data.世界.开局选择
    if (typeof waitGlobalInitialized === 'function') {
      waitGlobalInitialized('Mvu').then(function() {
        try {
          var mvuData = Mvu.getMvuData({ type: 'message', message_id: 0 });
          if (!mvuData.stat_data) mvuData.stat_data = {};
          if (!mvuData.stat_data['世界']) mvuData.stat_data['世界'] = {};
          mvuData.stat_data['世界']['开局选择'] = swipeId;
          Mvu.replaceMvuData(mvuData, { type: 'message', message_id: 0 });
          console.info('[青恋首页] 开局选择已设为', swipeId);
        } catch(e) { console.warn('[青恋首页] MVU 设置开局选择失败:', e); }
      });
    }

    SillyTavern.saveChat().then(function(){
      SillyTavern.reloadCurrentChat();
    });
    showToast('✅ 已切换至「'+roleName+'」开局');
  } catch(e) {
    console.error(e);
    showToast('❌ 切换失败');
  }
}

/* ---------- 绑定点击 ---------- */
$('.sy-card').on('click', function(){
  var $this = $(this);
  var swipeId = parseInt($this.attr('data-swipe')) || 0;
  var name = $this.find('.sy-card-name').text().trim() || '未知';
  $('.sy-card').removeClass('selected');
  $this.addClass('selected');
  switchSwipe(swipeId, name);
});

$('.sy-harem').on('click', function(){
  switchSwipe(5, '群星闪耀');
});

/* ---------- 卸载清理 ---------- */
$(window).on('pagehide', function(){
  $('.sy-card,.sy-harem').off('click');
  if(toastTimer) clearTimeout(toastTimer);
});

console.info('[青恋首页] 开局选择界面已加载');

});
</script>
