    function getRolePortrait(role, vars) {
      const roleData = vars?.stat_data?.[role] || {};
      const isNSFW = String(roleData.NSFW).toLowerCase() === 'true';
      let outfit;
      if (role === '白初弦') {
        outfit = String(roleData['约会']).toLowerCase() === 'true' ? '约会' : '日常';
      } else {
        outfit = String(roleData['校服']).toLowerCase() === 'true' ? '校服' : '常服';
      }
      if (!isNSFW) {
        const sfwGroup = cgData[role].sfw;
        return sfwGroup[outfit] || sfwGroup[Object.keys(sfwGroup)[0]];
      } else {
        const nsfwGroup = cgData[role].nsfw;
        const outfitPoses = nsfwGroup[outfit] || nsfwGroup[Object.keys(nsfwGroup)[0]];
        let pose = '传教士位';
        for (let p of POSE_ORDER) {
          if (String(roleData[p]).toLowerCase() === 'true') { pose = p; break; }
        }
        return outfitPoses[pose] || outfitPoses['传教士位'];
      }
    }

    function getCurrentIllustKey(role, vars) {
      const roleData = vars?.stat_data?.[role] || {};
      const isNSFW = String(roleData.NSFW).toLowerCase() === 'true';
      let outfit;
      if (role === '白初弦') {
        outfit = String(roleData['约会']).toLowerCase() === 'true' ? '约会' : '日常';
      } else {
        outfit = String(roleData['校服']).toLowerCase() === 'true' ? '校服' : '常服';
      }
      if (!isNSFW) {
        return `${role}_SFW_${outfit}`;
      } else {
        let pose = '传教士位';
        for (let p of POSE_ORDER) {
          if (String(roleData[p]).toLowerCase() === 'true') { pose = p; break; }
        }
        return `${role}_NSFW_${outfit}_${pose}`;
      }
    }

    function getAffection(role) {
      if (allVars && allVars.stat_data && allVars.stat_data[role]) {
        const val = parseInt(allVars.stat_data[role].亲密度);
        if (!isNaN(val)) return Math.min(100, Math.max(0, val));
      }
      return 0;
    }

    function getAllIllustKeysForHeroine(heroine) {
      const keys = { sfw: [], nsfw: {} };
      const ill = cgData[heroine];
      if (!ill) return keys;
      for (const outfit in ill.sfw) {
        keys.sfw.push({
          key: `${heroine}_SFW_${outfit}`,
          outfit: outfit,
          url: ill.sfw[outfit],
          name: outfitNames[heroine]?.[outfit] || outfit,
          type: 'sfw'
        });
      }
      for (const outfit in ill.nsfw) {
        keys.nsfw[outfit] = [];
        for (const pose of POSE_ORDER) {
          if (ill.nsfw[outfit][pose]) {
            keys.nsfw[outfit].push({
              key: `${heroine}_NSFW_${outfit}_${pose}`,
              outfit: outfit,
              pose: pose,
              url: ill.nsfw[outfit][pose],
              name: pose,
              outfitName: outfitNames[heroine]?.[outfit] || outfit,
              type: 'nsfw'
            });
          }
        }
      }
      return keys;
    }

    function getAllIllustFlatList(heroine) {
      const allKeys = getAllIllustKeysForHeroine(heroine);
      const flat = [];
      allKeys.sfw.forEach(item => {
        flat.push({
          key: item.key,
          url: item.url,
          label: item.name,
          subLabel: 'SFW',
          type: 'sfw'
        });
      });
      for (const outfit in allKeys.nsfw) {
        allKeys.nsfw[outfit].forEach(item => {
          flat.push({
            key: item.key,
            url: item.url,
            label: item.name,
            subLabel: item.outfitName,
            type: 'nsfw'
          });
        });
      }
      return flat;
    }

    function getUrlByKey(heroine, key) {
      const ill = cgData[heroine];
      if (!ill) return null;
      const parts = key.split('_');
      if (parts[1] === 'SFW') {
        const outfit = parts.slice(2).join('_');
        return ill.sfw[outfit] || null;
      } else if (parts[1] === 'NSFW') {
        const outfit = parts[2];
        const pose = parts.slice(3).join('_');
        return ill.nsfw?.[outfit]?.[pose] || null;
      }
      return null;
    }

