#tj-actions{display:grid;grid-template-columns:1fr 1fr 1fr;gap:6px;margin-top:6px}
.tj-mini-btn{display:inline-flex;align-items:center;justify-content:center;gap:4px;background:#fff;border:2px solid #141414;border-radius:6px;padding:6px 2px;font-weight:800;font-size:12px;line-height:1.3;color:#141414;box-shadow:2px 2px 0 #141414}
