#tj-sticker{position:absolute;top:6px;right:8px;font-size:11px;font-weight:900;background:#fff;color:#141414;border:2px solid #141414;border-radius:4px;padding:2px 6px;transform:rotate(6deg);box-shadow:2px 2px 0 #141414;line-height:1.4;animation:tj-float 3.8s ease-in-out infinite}
#tj-meta{display:grid;grid-template-columns:1fr 1fr 62px;gap:6px;align-items:end;font-size:12px;font-weight:700;margin-top:4px;line-height:1.5;border-top:2px solid #141414;padding-top:4px}
