#tj-weather-row{display:flex;align-items:center;gap:8px;font-weight:900;font-size:14px;line-height:1.6}
.tj-mini-tag{margin-left:auto;background:var(--tj-soft);color:#141414;border:1.5px dashed var(--tj-accent);border-radius:4px;font-size:12px;padding:2px 6px;font-weight:800;white-space:nowrap;line-height:1.6}
#tj-root.eye .tj-mini-tag{color:#fff}
#tj-status-text,#tj-inner-text{border:1.5px dashed var(--tj-accent);border-radius:4px;padding:6px;min-height:32px;font-size:13px;line-height:1.6;background:#fff;margin-top:4px;word-break:break-word}
#tj-root.eye #tj-status-text,#tj-root.eye #tj-inner-text{background:#141118}
.tj-count{font-size:11px;font-weight:700;opacity:.6;letter-spacing:.05em}
#tj-status-text::first-letter,#tj-inner-text::first-letter{font-size:1.7em;font-weight:900;color:var(--tj-accent);line-height:1}
