#tj-novel-div{position:relative;text-align:center;font-size:11px;font-weight:900;letter-spacing:.32em;color:var(--tj-accent)}
#tj-novel-div::before,#tj-novel-div::after{content:"";position:absolute;top:50%;width:30%;height:2px;background:#141414}
