#tj-novel-div::after{right:0}
#tj-foot-note{position:relative;text-align:center;font-size:10px;font-weight:800;letter-spacing:.25em;opacity:.65;margin-top:6px}
@media(prefers-reduced-motion:reduce){#tj-active-pill::after,.tj-face .tj-hint,#tj-emblem,#tj-sticker,#tj-nsfw-badge,.tj-chip[aria-pressed="true"]{animation:none}#tj-flip-inner,.tj-face img,#tj-nsfw-layer img{transition:none}.tj-card{animation:none}}
