.tj-lib-title svg{width:14px;height:14px;color:var(--tj-accent,#dd9226)}
#tj-lib-tabs,#tj-lib-tabs2{display:flex;gap:6px;flex-wrap:wrap;margin-bottom:6px}
.tj-lib-tab{background:#fff;border:2px solid #141414;border-radius:6px;padding:5px 10px;font-weight:800;font-size:12px;color:#141414;box-shadow:2px 2px 0 #141414;cursor:pointer}
.tj-lib-tab[aria-pressed="true"]{background:var(--tj-accent,#dd9226);color:#fff}
#tj-lib-count{color:#f2e9ee;font-size:11px;font-weight:700;margin:2px 2px 6px;letter-spacing:.04em}
#tj-lib-grid{flex:0 1 auto;min-height:0;max-height:calc(100vh - 205px);overflow-y:auto;background:#fff;border:2px solid #141414;border-radius:8px;box-shadow:3px 3px 0 rgba(20,20,20,.85);padding:10px;display:grid;grid-template-columns:repeat(auto-fill,minmax(96px,1fr));gap:8px;align-content:start}
.tj-lib-cell{position:relative;display:flex;flex-direction:column;gap:3px;background:#fff;border:2px solid #141414;border-radius:6px;padding:4px;cursor:pointer;text-align:left}
.tj-lib-ph{display:block;aspect-ratio:3/4;overflow:hidden;border-radius:4px;background:#eef3fa}
.tj-lib-ph img{width:100%;height:100%;object-fit:cover;display:block;opacity:0;transition:opacity .35s ease}
.tj-lib-ph img.ld{opacity:1}
.tj-lib-miss .tj-lib-ph{background:repeating-linear-gradient(45deg,#ffedae 0 12px,#ffd3dd 12px 24px)}
.tj-lib-cap{font-size:10px;font-weight:800;color:#141414;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.tj-lib-gate{grid-column:1/-1;display:flex;flex-direction:column;align-items:center;gap:8px;padding:26px 10px;border:2px dashed #141414;border-radius:8px;background:var(--tj-soft,#fff1d3)}
.tj-lib-gate b{font-size:14px}
.tj-lib-gate p{margin:0;font-size:11px;color:#444}
#tj-lib-view{position:fixed;inset:0;z-index:9995;background:rgba(16,14,18,.92);display:none;flex-direction:column;align-items:center;justify-content:center;gap:8px;padding:16px}
#tj-lib-view.open{display:flex}
#tj-lib-view-img{max-width:min(92vw,760px);max-height:74vh;border:3px solid #141414;border-radius:8px;box-shadow:4px 4px 0 rgba(20,20,20,.85);background:#eef3fa}
#tj-lib-view-cap{color:#f2e9ee;font-size:12px;font-weight:800;letter-spacing:.05em}
#tj-lib-view button{width:38px;height:38px;border:2px solid #141414;border-radius:6px;background:#fff;color:#141414;font-size:18px;font-weight:900;box-shadow:2px 2px 0 #141414;cursor:pointer}
#tj-lib-view-prev,#tj-lib-view-next{position:fixed;top:50%;transform:translateY(-50%)}
#tj-lib-view-prev{left:10px}#tj-lib-view-next{right:10px}
#tj-lib-view-close{position:fixed;top:12px;right:12px}
#tj-root.eye #tj-lib-grid{background:#1d1921;border-color:#000}
#tj-root.eye .tj-lib-cell{background:#1d1921;border-color:#000}
#tj-root.eye .tj-lib-cap{color:#f2e9ee}
@media (prefers-reduced-motion:reduce){.tj-lib-ph img{transition:none}}
/* ---- mobile: narrow-screen completeness (v32) ---- */
#tj-name-row{flex-wrap:wrap;row-gap:2px}
@media(max-width:480px){
#tj-topbar{flex-wrap:wrap}
#tj-toggles{flex:1 1 100%}
#tj-toggles .tj-toggle{flex:1;justify-content:center}
#tj-actions{grid-template-columns:1fr 1fr}
#tj-meta{grid-template-columns:1fr 1fr}
#tj-meta .m{white-space:normal}
#tj-weather-row{flex-wrap:wrap}
.tj-mini-tag{white-space:normal;text-align:right}
