            display: flex;
            align-items: center;
            justify-content: center;
            position: relative;
            padding: 20px;
            overflow: hidden;
        }

        .nav-btn {
            background: rgba(0, 0, 0, 0.4);
            border: 1px solid var(--card-border);
            color: white;
            width: 50px;
            height: 50px;
            border-radius: 50%;
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 24px;
            cursor: pointer;
            z-index: 10;
            transition: all 0.3s;
            backdrop-filter: blur(8px);
        }

        .nav-btn:active {
            transform: scale(0.9);
            background: var(--accent);
        }

        .prev-btn { margin-right: 10px; }
        .next-btn { left: auto; right: 20px; margin-left: 10px;}

        .card-wrapper {
            position: relative;
            width: 100%;
            max-width: 320px;
            aspect-ratio: 9 / 14;
            cursor: pointer;
            perspective: 1000px;
        }

        .main-card {
            width: 100%;
            height: 100%;
            border-radius: 20px;
            overflow: hidden;
            background: var(--card-bg);
            border: 1px solid var(--card-border);
            box-shadow: 0 20px 50px rgba(0,0,0,0.5);
            position: relative;
            transition: transform 0.3s ease;
        }

        .main-card:active {
            transform: scale(0.97);
        }

        .main-card img {
            width: 100%;
            height: 100%;
            object-fit: cover;
            display: block;
        }

        .card-info {
            position: absolute;
            bottom: 0;
            left: 0;
            width: 100%;
            padding: 40px 20px 20px;
            background: linear-gradient(to top, rgba(0,0,0,0.9) 0%, transparent 100%);
            text-align: center;
        }

        .card-name {
            font-size: 24px;
            font-weight: bold;
            margin-bottom: 4px;
            text-shadow: 0 2px 4px rgba(0,0,0,0.5);
        }

        .card-hint {
            font-size: 13px;
            color: var(--accent);
            opacity: 0.9;
        }

        .pagination {
            display: flex;
            justify-content: center;
            gap: 8px;
            padding: 20px;
        }

        .dot {
            width: 8px;
            height: 8px;
            border-radius: 50%;
            background: var(--card-border);
            transition: background 0.3s;
        }

        .dot.active {
            background: var(--accent);
            transform: scale(1.2);
        }

        /* --- Detail View Styles --- */
        .detail-nav {
            position: sticky;
            top: 0;
            z-index: 100;
            background: rgba(13, 18, 32, 0.85);
            backdrop-filter: blur(16px);
            border-bottom: 1px solid var(--card-border);
            display: flex;
            align-items: center;
            padding: 16px 20px;
            gap: 16px;
        }

        .back-btn {
            background: transparent;
            border: none;
            color: var(--accent);
            font-size: 16px;
            display: flex;
            align-items: center;
            gap: 6px;
            cursor: pointer;
            padding: 8px 0;
        }

        .detail-title {
            font-size: 18px;
            font-weight: 600;
            flex: 1;
        }

        .gallery-container {
            padding: 20px;
            overflow-y: auto;
        }

        .section-title {
            margin: 30px 0 16px;
            font-size: 20px;
            font-weight: 600;
            padding-left: 12px;
            border-left: 4px solid var(--accent);
        }

        .section-title:first-child {
            margin-top: 10px;
        }

        .grid {
            display: grid;
            grid-template-columns: repeat(2, 1fr);
            gap: 16px;
        }

        @media (min-width: 600px) {
            .grid { grid-template-columns: repeat(3, 1fr); }
            .card-wrapper { max-width: 400px; }
        }

        @media (min-width: 900px) {
            .grid { grid-template-columns: repeat(4, 1fr); }
            .card-wrapper { max-width: 450px; }
        }

        .grid-item {
            background: var(--card-bg);
            border: 1px solid var(--card-border);
            border-radius: 12px;
            overflow: hidden;
            display: flex;
            flex-direction: column;
        }

        .grid-thumb {
            width: 100%;
            aspect-ratio: 3 / 4;
            background: rgba(0,0,0,0.2);
            position: relative;
        }

        .grid-thumb img {
            width: 100%;
            height: 100%;
            object-fit: cover;
            display: block;
        }

        .grid-info {
            padding: 12px;
            text-align: center;
            background: rgba(255,255,255,0.02);
            border-top: 1px solid var(--card-border);
        }

        .grid-tag {
            font-size: 13px;
            color: #fff;
            font-weight: 500;
        }

        .grid-filename {
            font-family: monospace;
            font-size: 10px;
            color: var(--text-secondary);
            margin-top: 4px;
            word-break: break-all;
        }

        .empty-state {
            grid-column: 1 / -1;
            padding: 40px;
            text-align: center;
            color: var(--text-secondary);
            background: var(--card-bg);
            border-radius: 12px;
        }

        /* Swipe container specifically for mobile */
        .swipe-area {
            display: flex;
            align-items: center;
            justify-content: center;
            width: 100%;
            height: 100%;
        }

    </style>
