                sfwBase: 'https://raw.githubusercontent.com/xuanyuy2019-ops/Image/main/zhangqi',
                nsfwBase: 'https://raw.githubusercontent.com/xuanyuy2019-ops/Image/main/zhangqi',
                overrides: {}
            }
        ];

        /* Helper functions */
        function getImageUrl(charData, isSfw, variantKey) {
            if (isSfw && charData.overrides[variantKey]) {
                return charData.overrides[variantKey];
            }
            if (!isSfw && charData.overrides[variantKey]) {
                return charData.overrides[variantKey];
            }
            const base = isSfw ? charData.sfwBase : charData.nsfwBase;
            return `${base}/${charData.id}_${variantKey}.png`;
        }

        /* App State */
        let currentIndex = 0;

        /* UI Elements */
        const mainAvatar = document.getElementById('main-avatar');
        const mainName = document.getElementById('main-name');
        const pagination = document.getElementById('pagination');
        const selectionView = document.getElementById('selection-view');
        const detailView = document.getElementById('detail-view');
        const galleryContainer = document.getElementById('gallery-container');
        const detailTitle = document.getElementById('detail-title');

        /* Initialization */
        function init() {
            /* Build pagination dots */
            charactersData.forEach((_, index) => {
                const dot = document.createElement('div');
                dot.className = 'dot';
                dot.onclick = () => {
                    currentIndex = index;
                    updateCarousel();
                };
                pagination.appendChild(dot);
            });

            updateCarousel();
            setupTouchSwipe();
        }

        function updateCarousel() {
            const char = charactersData[currentIndex];
            /* Prefer battle as main image */
            mainAvatar.src = getImageUrl(char, true, 'battle');
            mainName.textContent = char.name;

            /* Update dots */
            Array.from(pagination.children).forEach((dot, index) => {
                dot.className = index === currentIndex ? 'dot active' : 'dot';
            });
        }

        function prevChar() {
            currentIndex = (currentIndex - 1 + charactersData.length) % charactersData.length;
            updateCarousel();
        }

        function nextChar() {
            currentIndex = (currentIndex + 1) % charactersData.length;
            updateCarousel();
        }

        /* Touch Swipe Logic */
        function setupTouchSwipe() {
            const el = document.getElementById('swipe-area');
            let touchStartX = 0;
            let touchEndX = 0;

            el.addEventListener('touchstart', e => {
                touchStartX = e.changedTouches[0].screenX;
            });

            el.addEventListener('touchend', e => {
                touchEndX = e.changedTouches[0].screenX;
                handleSwipe();
            });

            function handleSwipe() {
                const threshold = 40;
                if (touchEndX < touchStartX - threshold) {
                    nextChar(); /* Swipe left -> next */
                }
                if (touchEndX > touchStartX + threshold) {
                    prevChar(); /* Swipe right -> prev */
                }
            }
        }

        /* View Navigation */
        function openDetail() {
            const char = charactersData[currentIndex];
            detailTitle.textContent = `${char.name} 全套档案`;
            buildGallery(char);

            selectionView.classList.remove('active');
            detailView.classList.add('active');
            window.scrollTo(0, 0);
        }

        function closeDetail() {
            detailView.classList.remove('active');
            selectionView.classList.add('active');
        }

        function buildGallery(char) {
            galleryContainer.innerHTML = ''; /* Clear previous */

            /* SFW Section */
            const sfwSection = document.createElement('div');
            sfwSection.innerHTML = `<div class="section-title">普通情境 (SFW)</div>`;
            const sfwGrid = document.createElement('div');
            sfwGrid.className = 'grid';

            SFW_VARIANTS.forEach(variant => {
                const url = getImageUrl(char, true, variant.key);
                sfwGrid.appendChild(createGridItem(url, variant.label, `${char.id}_${variant.key}.png`));
            });
            sfwSection.appendChild(sfwGrid);
            galleryContainer.appendChild(sfwSection);

            /* NSFW Section */
            const nsfwSection = document.createElement('div');
            nsfwSection.innerHTML = `<div class="section-title">私密情境 (NSFW)</div>`;
            const nsfwGrid = document.createElement('div');
            nsfwGrid.className = 'grid';

            NSFW_VARIANTS.forEach(variant => {
                const url = getImageUrl(char, false, variant.key);
                nsfwGrid.appendChild(createGridItem(url, variant.label, `${char.id}_${variant.key}.png`));
            });
            nsfwSection.appendChild(nsfwGrid);
            galleryContainer.appendChild(nsfwSection);
        }

        function createGridItem(imgSrc, tag, filename) {
            const div = document.createElement('div');
            div.className = 'grid-item';
            div.innerHTML = `
                <div class="grid-thumb">
                    <img src="${imgSrc}" alt="${tag}" loading="lazy">
                </div>
                <div class="grid-info">
                    <div class="grid-tag">${tag}</div>
                    <div class="grid-filename">${filename}</div>
                </div>
            `;
            return div;
        }

        /* Start */
        init();

    </script>
</body>
</html>
