                            <span class="nsfw-hint">点击切换</span>
                        </div>
                    </div>
                `;

                gallery.appendChild(card);

                // 绑定点击切换逻辑
                const wrapper = card.querySelector(`#wrapper-${index}`);
                const img = card.querySelector(`#img-${index}`);
                const errorDiv = card.querySelector('.nsfw-error');

                wrapper.addEventListener('click', () => {
                    // 循环逻辑：基础图('') -> '1' -> 基础图('')
                    currentVariant = currentVariant === '' ? '1' : '';

                    // 重置错误状态
                    img.style.display = 'block';
                    errorDiv.style.display = 'none';

                    // 更新图片源
                    img.src = getImageUrl(currentVariant);
