scripts.content:
/* ============================================================
 * Ruby宇宙 · 性能守护 v1.0（渲染减负）
 * ------------------------------------------------------------
 * 解决：长对话 / 多立绘卡片场景下的滚动与输入卡顿。
 * 原则：不改动任何视觉设计，只改变「什么时候渲染 / 什么时候播动画」。
 *
 * 原理（全部浏览器原生能力，可一键关闭）：
 *   1) 可见性调度（标准模式即生效，零视觉改动）
 *      只有「接近视口」的消息才播放 CSS 动画；远端消息冻结动画
 *      （animation-play-state: paused），rootMargin 预热带 600px，
 *      滚到的瞬间动画已经在跑，肉眼看不出差别。
 *      → 聊到几十楼时，同时在跑的动画数量从「全部」降到「两屏内」。
 *   2) 省电模式（额外三项，均为可选视觉取舍）
 *      a. 离屏消息 content-visibility:auto：布局与绘制整块跳过
 *      b. 停掉装饰性无限循环动画（只停 infinite，入场动画保留）
 *      c. 移除毛玻璃 backdrop-filter（最贵的逐帧重绘来源）
 *   3) 拖动按钮可移动位置，设置写入本地存储（跨刷新生效）。
 *
 * 开关：右下角 ⚡ 按钮，点击循环「标准 → 省电 → 关闭」，可拖动。
 * 控制台 API：__RUBY_PERF__.set('std'|'eco'|'off')
 * ============================================================ */
(function () {
  'use strict';

  /* ---------- 运行宿主：优先主页面（TH 脚本跑在沙箱 iframe 里）---------- */
  var H = window, D = document;
  try {
    if (window.parent && window.parent !== window && window.parent.document) {
      H = window.parent;
      D = H.document;
    }
  } catch (_) {}
  if (!D || !D.body) return;

  var SLOT = '__RUBY_PERF_GUARD__';

  /* 幂等：切卡时 TH 会销毁并重建脚本 iframe，若上一个实例没清干净会留死按钮 */
  var prev = H[SLOT];
  if (prev && typeof prev.teardown === 'function') {
    try { prev.teardown(); } catch (_) {}
  }

  var LSKEY = 'ruby_perf_guard_v1';
  var STYLE_ID = 'ruby-perf-guard-style';
  var BTN_ID = 'ruby-perf-guard-btn';
  var TOAST_ID = 'ruby-perf-guard-toast';
  var MODES = ['std', 'eco', 'off'];
  var LABEL = { std: '标准', eco: '省电', off: '关闭' };
  var DESC = {
    std: '标准：远端消息暂停动画（零视觉改动）',
    eco: '省电：离屏跳过渲染 + 停装饰动画 + 去毛玻璃',
    off: '关闭：恢复原始渲染'
  };

  /* ---------- 配置持久化 ---------- */
  function loadCfg() {
    try { return JSON.parse(H.localStorage.getItem(LSKEY) || '{}') || {}; }
    catch (_) { return {}; }
  }
  function saveCfg() {
    try { H.localStorage.setItem(LSKEY, JSON.stringify(CFG)); } catch (_) {}
  }
  var CFG = loadCfg();
  if (MODES.indexOf(CFG.mode) < 0) CFG.mode = 'std';
  if (typeof CFG.x !== 'number') CFG.x = -1;   /* -1 = 用默认位置 */
  if (typeof CFG.y !== 'number') CFG.y = -1;

  var torn = false;
  var io = null, mo = null, rafId = null, retryTimer = null, ecoTimer = null;
  var observed = [];   /* 已交给 IntersectionObserver 的消息 */
  var ecoQueue = [];   /* 待做省电扫描的消息 */
  var bound = [];      /* 已注册的宿主事件：teardown 时逐个注销，避免切卡累积泄漏 */

  /* 统一事件注册：所有挂在宿主 H 上的监听都记账，便于彻底清理 */
  function on(t, type, fn, opts) {
    try { t.addEventListener(type, fn, opts); bound.push([t, type, fn, opts]); } catch (_) {}
  }
  function offAll() {
    for (var i = 0; i < bound.length; i++) {
      var it = bound[i];
      try { it[0].removeEventListener(it[1], it[2], it[3]); } catch (_) {}
    }
    bound.length = 0;
  }

  /* ---------- 样式注入 ---------- */
  function styleText() {
    return [
      /* 1) 远端消息冻结动画：只暂停，不删除（恢复可见即从当前帧继续） */
      'body.ruby-perf-on #chat .mes.ruby-frozen,',
      'body.ruby-perf-on #chat .mes.ruby-frozen * {',
      '  animation-play-state: paused !important;',
      '}',
      /* 2a) 省电：离屏消息整块跳过布局与绘制（含 position:fixed 的消息除外） */
      'body.ruby-perf-eco #chat .mes:not([data-ruby-fixed]):not(.ruby-frozen) {',
      '  content-visibility: auto;',
      '  contain-intrinsic-size: auto 320px;',
      '}',
      /* 2b) 省电：只冻结「被标记元素自身及其伪元素」的装饰性循环动画。
       *     刻意不使用 ".ruby-noloop *"——那会连带杀死后代的一次性入场动画。
       *     用 paused 而非 animation:none：动画停在当前帧（视觉位置不跳变），
       *     且暂停态不产生逐帧合成开销。 */
      'body.ruby-perf-eco .ruby-noloop,',
      'body.ruby-perf-eco .ruby-noloop::before,',
      'body.ruby-perf-eco .ruby-noloop::after {',
      '  animation-play-state: paused !important;',
      '}',
      /* 2c) 省电：移除毛玻璃（纯色半透明底仍在，排版不受影响） */
      'body.ruby-perf-eco .ruby-nobdf,',
      'body.ruby-perf-eco .ruby-nobdf::before,',
      'body.ruby-perf-eco .ruby-nobdf::after {',
      '  -webkit-backdrop-filter: none !important;',
      '  backdrop-filter: none !important;',
      '}',
      /* 按钮与提示 */
      '#' + BTN_ID + ' {',
      '  position: fixed; z-index: 2147483000; width: 30px; height: 30px;',
      '  border-radius: 50%; display: flex; align-items: center; justify-content: center;',
      '  font-size: 14px; line-height: 1; cursor: pointer;',
      '  background: rgba(20,22,30,.55); color: #fff;',
      '  border: 1px solid rgba(255,255,255,.22);',
      '  box-shadow: 0 2px 10px rgba(0,0,0,.28);',
      '  -webkit-user-select: none; user-select: none;',
      '  touch-action: none; opacity: .42; transition: opacity .18s ease;',
      '}',
      '#' + BTN_ID + ':hover, #' + BTN_ID + '.ruby-dragging { opacity: .95; }',
      '#' + BTN_ID + '.ruby-off { opacity: .2; }',
      '#' + TOAST_ID + ' {',
      '  position: fixed; left: 50%; bottom: 76px; transform: translateX(-50%);',
      '  z-index: 2147483000; max-width: 78vw; padding: 7px 13px;',
      '  border-radius: 8px; font-size: 12px; line-height: 1.45;',
      '  background: rgba(18,20,28,.86); color: #f2f3f7;',
      '  pointer-events: none; opacity: 0; transition: opacity .2s ease;',
      '  box-shadow: 0 4px 16px rgba(0,0,0,.3);',
      '}',
      '#' + TOAST_ID + '.ruby-show { opacity: 1; }'
    ].join('\n');
  }

  function ensureStyle() {
    var st = D.getElementById(STYLE_ID);
    if (!st) {
      st = D.createElement('style');
      st.id = STYLE_ID;
      st.textContent = styleText();
      (D.head || D.documentElement).appendChild(st);
    }
  }

  /* ---------- 目标：消息容器与消息节点 ---------- */
  function chatBox() {
    return D.querySelector('#chat') || D.querySelector('#chat_container') || null;
  }

  function messages() {
    var box = chatBox();
    if (!box) return [];
    return Array.prototype.slice.call(box.querySelectorAll('.mes'));
  }

  /* ---------- 标准模式核心：可见性调度 ---------- */
  function initObserver() {
    if (io || typeof H.IntersectionObserver !== 'function') return;
    try {
      io = new H.IntersectionObserver(function (entries) {
        for (var i = 0; i < entries.length; i++) {
          var e = entries[i];
          var el = e.target;
          if (torn || !el || !el.classList) continue;
          if (e.isIntersecting) el.classList.remove('ruby-frozen');
          else el.classList.add('ruby-frozen');
        }
      }, { root: null, rootMargin: '600px 0px 600px 0px', threshold: 0 });
    } catch (_) { io = null; }
  }

  /* 无 IntersectionObserver 时的兜底：滚动位置直接算 */
  function fallbackSweep() {
    var vs = H.innerHeight || 800;
    var list = messages();
    for (var i = 0; i < list.length; i++) {
      var el = list[i];
      var r = el.getBoundingClientRect();
      var near = (r.bottom > -600) && (r.top < vs + 600);
      if (near) el.classList.remove('ruby-frozen');
      else el.classList.add('ruby-frozen');
    }
  }

  function scan() {
    if (torn) return;
    var list = messages();
    if (!list.length) return;
    if (io) {
      for (var i = 0; i < list.length; i++) {
        var el = list[i];
        if (el.getAttribute('data-ruby-obs') === '1') continue;
        el.setAttribute('data-ruby-obs', '1');
        try { io.observe(el); } catch (_) {}
        observed.push(el);
      }
    } else {
      fallbackSweep();
    }
    if (CFG.mode === 'eco') enqueueEco(list);
  }

  function schedule() {
    if (torn) return;
    if (rafId !== null) return;
    rafId = (H.requestAnimationFrame || function (f) { return setTimeout(f, 16); })(function () {
      rafId = null;
      try { scan(); } catch (_) {}
    });
  }

  /* ---------- 省电模式：逐条、分帧扫描（避免一次性 getComputedStyle 卡顿） ---------- */
  function enqueueEco(list) {
    for (var i = 0; i < list.length; i++) {
      var el = list[i];
      if (el.getAttribute('data-ruby-eco') === '1') continue;
      if (ecoQueue.indexOf(el) >= 0) continue;
      ecoQueue.push(el);
    }
    if (ecoQueue.length && ecoTimer === null) ecoTick();
  }

  function ecoTick() {
    ecoTimer = null;
    if (torn || CFG.mode !== 'eco') { ecoQueue.length = 0; return; }
    var budget = 2;   /* 每帧最多处理 2 条消息，防止长对话下的长任务 */
    while (budget-- > 0 && ecoQueue.length) {
      var mes = ecoQueue.shift();
      try { ecoScanMessage(mes); } catch (_) {}
    }
    if (ecoQueue.length) {
      ecoTimer = (H.requestIdleCallback || function (f) { return setTimeout(function () { f(); }, 120); })(
        function () { ecoTick(); }
      );
    }
  }

  function ecoScanMessage(mes) {
    if (!mes || !mes.querySelectorAll) return;
    mes.setAttribute('data-ruby-eco', '1');
    var nodes = mes.querySelectorAll('*');
    var list = [mes].concat(Array.prototype.slice.call(nodes));
    var hasFixed = false;
    for (var i = 0; i < list.length; i++) {
      var el = list[i];
      if (el.tagName === 'SCRIPT' || el.tagName === 'STYLE' ||
          el.tagName === 'HEAD' || el.tagName === 'META' ||
          el.tagName === 'LINK' || el.tagName === 'TITLE') continue;
      var cs;
      try { cs = H.getComputedStyle(el); } catch (_) { continue; }
      if (!cs) continue;

      /* a. position:fixed 的消息不能套 content-visibility（会改变其定位基准） */
      if (cs.position === 'fixed') hasFixed = true;

      /* b. 只冻结「无限循环」动画；入场/一次性动画（forwards/both）保留。
       *    注意：不能靠 el.classList 判断——如 SVG 元素没有 classList，
       *    所以统一用属性标记，避免漏标或重复处理。 */
      var itc = String(cs.animationIterationCount || '');
      if (itc.indexOf('infinite') >= 0 && el.getAttribute('data-ruby-noloop') !== '1') {
        el.setAttribute('data-ruby-noloop', '1');
        try { el.classList.add('ruby-noloop'); } catch (_) {}
      }
      /* c. 毛玻璃：最贵的逐帧重绘来源 */
      var bd = cs.backdropFilter || cs.webkitBackdropFilter;
      if (bd && bd !== 'none' && el.getAttribute('data-ruby-nobdf') !== '1') {
        el.setAttribute('data-ruby-nobdf', '1');
        try { el.classList.add('ruby-nobdf'); } catch (_) {}
      }
    }
    if (hasFixed) mes.setAttribute('data-ruby-fixed', '1');
    else mes.removeAttribute('data-ruby-fixed');
  }

  /* ---------- 模式切换 ---------- */
  function applyMode(silent) {
    ensureStyle();
    var b = D.body;
    if (!b) return;
    b.classList.toggle('ruby-perf-on', CFG.mode !== 'off');
    b.classList.toggle('ruby-perf-eco', CFG.mode === 'eco');

    if (CFG.mode === 'off') {
      var fr = D.querySelectorAll('#chat .mes.ruby-frozen');
      for (var i = 0; i < fr.length; i++) fr[i].classList.remove('ruby-frozen');
      ecoQueue.length = 0;
    } else {
      initObserver();
      schedule();
      if (CFG.mode === 'eco') enqueueEco(messages());
    }
    syncButton();
    if (!silent) toast(DESC[CFG.mode]);
  }

  /* ---------- 按钮（可拖动） ---------- */
  function syncButton() {
    var b = D.getElementById(BTN_ID);
    if (!b) return;
    b.textContent = CFG.mode === 'off' ? '○' : '⚡';
    b.title = 'Ruby宇宙 · 性能守护：' + LABEL[CFG.mode] + '\n' + DESC[CFG.mode] +
      '\n（点击切换 / 拖动移动）';
    b.classList.toggle('ruby-off', CFG.mode === 'off');
  }

  function placeButton() {
    var b = D.getElementById(BTN_ID);
    if (!b) return;
    if (CFG.x < 0 || CFG.y < 0) {
      b.style.right = '10px';
      b.style.bottom = '120px';
      b.style.left = 'auto';
      b.style.top = 'auto';
    } else {
      b.style.left = CFG.x + 'px';
      b.style.top = CFG.y + 'px';
      b.style.right = 'auto';
      b.style.bottom = 'auto';
    }
  }

  function buildButton() {
    var old = D.getElementById(BTN_ID);
    if (old && old.parentNode) old.parentNode.removeChild(old);
    var b = D.createElement('div');
    b.id = BTN_ID;
    b.setAttribute('role', 'button');
    b.setAttribute('aria-label', '性能守护开关');
    placeButton();
    syncButton();

    var dragging = false, moved = false, sx = 0, sy = 0, ox = 0, oy = 0;

    function down(ev) {
      var p = ev.touches ? ev.touches[0] : ev;
      dragging = true; moved = false;
      sx = p.clientX; sy = p.clientY;
      var r = b.getBoundingClientRect();
      ox = r.left; oy = r.top;
      b.classList.add('ruby-dragging');
      if (ev.preventDefault && ev.cancelable) ev.preventDefault();
    }
    function move(ev) {
      if (!dragging) return;
      var p = ev.touches ? ev.touches[0] : ev;
      var dx = p.clientX - sx, dy = p.clientY - sy;
      if (!moved && (Math.abs(dx) > 4 || Math.abs(dy) > 4)) moved = true;
      if (!moved) return;
      var x = Math.max(0, Math.min(ox + dx, (H.innerWidth || 400) - 30));
      var y = Math.max(0, Math.min(oy + dy, (H.innerHeight || 800) - 30));
      b.style.left = x + 'px'; b.style.top = y + 'px';
      b.style.right = 'auto'; b.style.bottom = 'auto';
      if (ev.preventDefault && ev.cancelable) ev.preventDefault();
    }
    function up() {
      if (!dragging) return;
      dragging = false;
      b.classList.remove('ruby-dragging');
      if (moved) {
        CFG.x = parseInt(b.style.left, 10) || 0;
        CFG.y = parseInt(b.style.top, 10) || 0;
        saveCfg();
      } else {
        var i = MODES.indexOf(CFG.mode);
        CFG.mode = MODES[(i + 1) % MODES.length];
        saveCfg();
        applyMode(false);
      }
    }

    b.addEventListener('mousedown', down);
    b.addEventListener('touchstart', down, { passive: false });
    on(H, 'mousemove', move);
    on(H, 'touchmove', move, { passive: false });
    on(H, 'mouseup', up);
    on(H, 'touchend', up);
    on(H, 'touchcancel', up);

    (D.body || D.documentElement).appendChild(b);
  }

  /* ---------- 轻提示 ---------- */
  var toastTimer = null;
  function toast(msg) {
    var t = D.getElementById(TOAST_ID);
    if (!t) {
      t = D.createElement('div');
      t.id = TOAST_ID;
      (D.body || D.documentElement).appendChild(t);
    }
    t.textContent = msg;
    t.classList.add('ruby-show');
    if (toastTimer) clearTimeout(toastTimer);
    toastTimer = setTimeout(function () {
      try { t.classList.remove('ruby-show'); } catch (_) {}
    }, 1600);
  }

  /* ---------- 生命周期 ---------- */
  function startWatch() {
    initObserver();
    scan();
    /* 新楼层 / 重新渲染 */
    var box = chatBox();
    if (box && typeof H.MutationObserver === 'function') {
      mo = new H.MutationObserver(function () { schedule(); });
      try { mo.observe(box, { childList: true, subtree: true }); } catch (_) {}
    }
    /* #chat 可能晚于脚本出现 */
    var tries = 0;
    (function retry() {
      if (torn) return;
      if (chatBox()) { scan(); bindScroll(); return; }
      if (++tries < 40) retryTimer = setTimeout(retry, 250);
    })();
  }

  function bindScroll() {
    if (!io) {
      var fn = function () { schedule(); };
      on(H, 'scroll', fn, true);
      on(H, 'resize', fn);
    }
  }

  function teardown() {
    torn = true;
    try { if (io) io.disconnect(); } catch (_) {}
    try { if (mo) mo.disconnect(); } catch (_) {}
    if (rafId !== null) { try { (H.cancelAnimationFrame || clearTimeout)(rafId); } catch (_) {} }
    if (retryTimer) clearTimeout(retryTimer);
    if (ecoTimer) { try { (H.cancelIdleCallback || clearTimeout)(ecoTimer); } catch (_) {} }
    for (var i = 0; i < observed.length; i++) {
      try {
        var msg = observed[i];
        msg.classList.remove('ruby-frozen');
        msg.removeAttribute('data-ruby-obs');
        /* 清掉省电模式留下的标记，避免下次进入时被跳过或旧样式残留 */
        msg.removeAttribute('data-ruby-eco');
        msg.removeAttribute('data-ruby-fixed');
        msg.removeAttribute('data-ruby-noloop');
        msg.removeAttribute('data-ruby-nobdf');
        msg.classList.remove('ruby-noloop');
        msg.classList.remove('ruby-nobdf');
        var sub = msg.querySelectorAll('*');
        for (var k = 0; k < sub.length; k++) {
          var s = sub[k];
          s.removeAttribute('data-ruby-noloop');
          s.removeAttribute('data-ruby-nobdf');
          if (s.classList) { s.classList.remove('ruby-noloop'); s.classList.remove('ruby-nobdf'); }
        }
      } catch (_) {}
    }
    var rm = [STYLE_ID, BTN_ID, TOAST_ID];
    for (var j = 0; j < rm.length; j++) {
      var n = D.getElementById(rm[j]);
      if (n && n.parentNode) n.parentNode.removeChild(n);
    }
    try { D.body.classList.remove('ruby-perf-on', 'ruby-perf-eco'); } catch (_) {}
    try { if (H[SLOT] === api) delete H[SLOT]; } catch (_) {}
    offAll();
  }

  var api = {
    version: '1.0',
    get mode() { return CFG.mode; },
    set: function (m) {
      if (MODES.indexOf(m) < 0) return CFG.mode;
      CFG.mode = m; saveCfg(); applyMode(false); return CFG.mode;
    },
    refresh: function () { schedule(); },
    teardown: teardown
  };
  H[SLOT] = api;

  /* ---------- 启动 ---------- */
  ensureStyle();
  applyMode(true);
  buildButton();
  startWatch();
  H.addEventListener('pagehide', teardown);
})();

