  var searchBox = hostDocument.getElementById('qz-search-box');
  var searchInput = hostDocument.getElementById('qz-search-input');
  var searchResults = hostDocument.getElementById('qz-search-results');
  var btnLoop = hostDocument.getElementById('qz-btn-loop');
  var btnPlayPause = hostDocument.getElementById('qz-btn-playpause');
  var btnNext = hostDocument.getElementById('qz-btn-next');
  var btnPrev = hostDocument.getElementById('qz-btn-prev');
  var btnClose = hostDocument.getElementById('qz-btn-close');
  var progressBar = hostDocument.getElementById('qz-progress-bar');
  var progressFill = hostDocument.getElementById('qz-progress-fill');
  var timeCurrent = hostDocument.getElementById('qz-time-current');
  var timeTotal = hostDocument.getElementById('qz-time-total');
  var audio = hostDocument.getElementById('qz-mp3-audio');

  function formatTime(seconds) {
    if (!seconds || isNaN(seconds) || !isFinite(seconds)) return '00:00';
    var m = Math.floor(seconds / 60);
    var s = Math.floor(seconds % 60);
    return (m < 10 ? '0' + m : m) + ':' + (s < 10 ? '0' + s : s);
  }

  function getPlaylistItems() {
    return playlistScroll.querySelectorAll('.qz-playlist-item');
  }

  function updatePlaylistUI() {
    var items = getPlaylistItems();
    items.forEach(function(item, idx) {
      if (idx === currentIndex) {
        item.classList.add('active');
      } else {
        item.classList.remove('active');
      }
    });
  }

  function scrollToActiveItem() {
    var items = getPlaylistItems();
    if (items[currentIndex]) {
      items[currentIndex].scrollIntoView({ behavior: 'smooth', block: 'nearest' });
    }
  }

  function updateLoopButton() {
    if (isLoopMode) {
      btnLoop.innerText = '🔂';
      btnLoop.title = '单曲循环';
      btnLoop.classList.add('on');
      audio.loop = true;
    } else {
      btnLoop.innerText = '🔁';
      btnLoop.title = '列表循环';
      btnLoop.classList.remove('on');
      audio.loop = false;
    }
  }

  function updatePlayPauseButton() {
    if (audio.paused) {
      btnPlayPause.innerText = '⏸';
      btnPlayPause.title = '暂停中';
      btnPlayPause.classList.add('on');
    } else {
      btnPlayPause.innerText = '▶';
      btnPlayPause.title = '播放中';
      btnPlayPause.classList.remove('on');
    }
  }

  function loadSong(index) {
    currentIndex = index;
    var song = playlist[currentIndex];
    audio.src = song.src;
    songName.innerText = song.name;
    panelBg.style.backgroundImage = 'url("' + song.bg + '")';
    timeTotal.innerText = '00:00';
    timeCurrent.innerText = '00:00';
    progressFill.style.width = '0%';
    updatePlaylistUI();
    scrollToActiveItem();
    audio.load();
    audio.play().catch(function(err){ console.log("播放被拦截", err); });
  }

  function nextSong() {
    var nextIndex = (currentIndex + 1) % playlist.length;
    loadSong(nextIndex);
  }

  function prevSong() {
    var prevIndex = (currentIndex - 1 + playlist.length) % playlist.length;
    loadSong(prevIndex);
  }

  function showPlayer() {
    root.style.display = 'block';
    entry.style.display = 'flex';
    panel.style.display = 'none';
    playlistEl.style.display = 'none';
  }

  function expandPlayer() {
    root.style.display = 'block';
    entry.style.display = 'none';
    panel.style.display = 'flex';
    playlistEl.style.display = 'flex';
  }

  // 初始化
  loadSong(0);
  updateLoopButton();

  // 搜索功能
  btnSearch.addEventListener('click', function(e) {
    e.stopPropagation();
    searchBox.classList.toggle('show');
    if (searchBox.classList.contains('show')) {
      searchInput.focus();
    }
  });

  searchInput.addEventListener('input', function(e) {
    var keyword = searchInput.value.trim().toLowerCase();
    searchResults.innerHTML = '';
    if (!keyword) return;

    var matched = [];
    playlist.forEach(function(song, idx) {
      if (song.name.toLowerCase().indexOf(keyword) !== -1) {
        matched.push({ name: song.name, index: idx });
      }
    });

    matched.forEach(function(match) {
      var div = hostDocument.createElement('div');
      div.className = 'qz-search-result-item';
      div.innerText = match.name;
      div.addEventListener('click', function(e) {
        e.stopPropagation();
        loadSong(match.index);
        searchBox.classList.remove('show');
        searchInput.value = '';
        searchResults.innerHTML = '';
      });
      searchResults.appendChild(div);
    });
  });

  // 点击外部关闭搜索框
  hostDocument.addEventListener('click', function(e) {
    if (!searchBox.contains(e.target) && e.target !== btnSearch) {
      searchBox.classList.remove('show');
      searchInput.value = '';
      searchResults.innerHTML = '';
    }
  });

  // 循环模式切换
  btnLoop.addEventListener('click', function(e) {
    isLoopMode = !isLoopMode;
    updateLoopButton();
  });

  // 播放/暂停切换按钮
  btnPlayPause.addEventListener('click', function(e) {
    if (audio.paused) {
      audio.play().catch(function(err){ console.log("播放被拦截", err); });
    } else {
      audio.pause();
    }
