  const NOTEBOOK_BASE_URL ='https://cdn.jsdelivr.net/gh/abao1141965846/character_script_st@1aa032c9adb44bfc52dbe485863544e8bcd2dcfc/';

  // 根据 User-Agent 判断是否为手机/平板
