    const bodyMatch = htmlText.match(/<body[^>]*>([\s\S]*)<\/body>/i);
    const headStyleMatch = htmlText.match(/<style[^>]*>([\s\S]*?)<\/style>/gi);
    const googleFontLinks = htmlText.match(/<link[^>]*fonts\.googleapis\.com[^>]*>/gi) || [];
    const lxgFontLink = htmlText.match(/<link[^>]*lxgw-wenkai-webfont[^>]*>/gi) || [];

    const bodyContent = bodyMatch ? bodyMatch[1].trim() : '';
    const styles = (headStyleMatch || []).join('\n');
    const fontLinks = googleFontLinks.concat(lxgFontLink).join('\n');

    return (
      '<!DOCTYPE html>\n' +
      '<html lang="zh-CN">\n' +
      '  <head>\n' +
      '    <meta charset="UTF-8" />\n' +
      '    ' +
      fontLinks +
      '\n' +
      '    ' +
      styles +
      '\n' +
      '  </head>\n' +
      '  <body>\n' +
      '    ' +
      bodyContent +
      '\n' +
      '  </body>\n' +
      '</html>'
    );
  }

  function mountApisToWindow(targetWindow) {
    // 把脚本运行环境的全局接口挂载到 iframe window，让原 HTML 里的脚本在 iframe 内可用
    targetWindow.$ = window.$;
    targetWindow.jQuery = window.jQuery;
    targetWindow.toastr = window.toastr;
    targetWindow._ = window._;
    targetWindow.getVariables = window.getVariables;
    targetWindow.replaceVariables = window.replaceVariables;
    targetWindow.Mvu = window.Mvu;
    targetWindow.eventOn = window.eventOn;
    targetWindow.tavern_events = window.tavern_events;
    targetWindow.waitGlobalInitialized = window.waitGlobalInitialized;
    targetWindow.getChatMessages = window.getChatMessages;
    targetWindow.getCurrentMessageId = function () {
      const lastMessage = window.getChatMessages(-1)[0];
      return lastMessage ? lastMessage.message_id : -1;
    };
  }

  function openNotebook(htmlText) {
    if ($container) return; // 已经打开

    const myToken = ++openToken;

    const containerCss = isMobile
      ? {
          position: 'fixed',
          top: '5vh',
          right: '2.5vw',
          width: '95vw',
          height: '90vh',
          'z-index': '9999',
        }
      : {
          position: 'fixed',
          top: '50%',
          left: '50%',
          transform: 'translate(-50%, -50%)',
          width: 'min(1600px, 70vw)',
          height: 'min(1000px, 70vh)',
          'z-index': '9999',
        };

    $container = $('<div>').css(containerCss).appendTo('body');

    $iframe = $('<iframe>')
      .attr({
        frameborder: 0,
        srcdoc: '<!DOCTYPE html><html><body></body></html>',
      })
      .css({
        width: '100%',
        height: '100%',
        'border-radius': '16px',
        'box-shadow': '0 8px 32px rgba(0,0,0,0.35)',
        background: '#e8d5a5',
      })
      .appendTo($container);

    // 在 iframe 外层右上角加一个关闭按钮
    $('<button>')
      .text('✕')
      .attr('title', '关闭状态栏')
      .css({
        position: 'absolute',
        top: '8px',
        right: '8px',
        width: '40px',
        height: '40px',
        'border-radius': '50%',
        border: '2px solid #6b4c2b',
        background: '#d4b896',
        color: '#3a2818',
        'font-size': '20px',
        'font-weight': 'bold',
        'line-height': '1',
        cursor: 'pointer',
        'z-index': '10001',
        'box-shadow': '0 2px 6px rgba(0,0,0,0.25)',
      })
      .appendTo($container)
      .on('click', function () {
        closeNotebook();
      });

    $iframe.on('load', function () {
      const iframeEl = $iframe ? $iframe[0] : null;
      // 如果窗口已经被关闭或替换，token 不匹配，直接放弃旧加载
      if (!iframeEl || myToken !== openToken) {
        console.log('检测到旧的 iframe 加载回调，已忽略');
        return;
      }

      const doc = iframeEl.contentDocument;
      if (!doc) return;

      // 先挂载全局接口，确保 HTML 内部脚本执行时 $ 等 API 已可用
      mountApisToWindow(iframeEl.contentWindow);

      // 写入 HTML 内容
      doc.open();
      doc.write(buildNotebookDocument(htmlText));
      doc.close();
    });
  }

  function closeNotebook() {
    // 失效当前 token，防止旧加载回调继续写入
    openToken++;

    if ($iframe) {
      const iframeEl = $iframe[0];
      if (iframeEl && iframeEl.contentWindow) {
        try {
          // 先清空 iframe 内部文档，释放 DOM 和脚本资源
          const doc = iframeEl.contentWindow.document;
          doc.open();
          doc.write('');
          doc.close();
          // 强制 iframe 卸载，避免旧文档残留
          iframeEl.contentWindow.location.href = 'about:blank';
        } catch (e) {
          // 跨域或安全限制时忽略
        }
      }
      // 移除 srcdoc，防止再次加载旧内容
      $iframe.removeAttr('srcdoc');
      $iframe.attr('src', 'about:blank');
    }

    if ($container) {
      $container.remove();
      $container = null;
      $iframe = null;
    }
  }

  function toggleNotebook() {
    if ($container) {
      closeNotebook();
    } else {
      openNotebook(cachedHtmlText);
    }
  }

  function createFloatButton() {
    if ($floatBtn) return;

    floatBtnStyleId = 'tavern-statusbar-trigger-style-' + Date.now();
    $('<style>')
      .attr('id', floatBtnStyleId)
      .text(
        '#' +
          floatBtnStyleId +
          ' { display: none; }\n' +
          '#tavern-statusbar-trigger {\n' +
          '  position: fixed;\n' +
          '  top: 80px;\n' +
          '  right: 20px;\n' +
          '  width: 56px;\n' +
          '  height: 56px;\n' +
          '  border-radius: 50%;\n' +
          '  z-index: 999999;\n' +
          '  cursor: pointer;\n' +
          '  user-select: none;\n' +
          '  display: flex;\n' +
          '  align-items: center;\n' +
          '  justify-content: center;\n' +
          '  background: transparent;\n' +
          '}\n' +
          '#tavern-statusbar-trigger .tavern-statusbar-glow {\n' +
          '  position: absolute;\n' +
          '  width: 34px;\n' +
          '  height: 34px;\n' +
          '  border-radius: 50%;\n' +
          '  z-index: 0;\n' +
          '  background: rgba(212, 184, 150, 0.55);\n' +
          '  box-shadow: 0 0 10px rgba(212, 184, 150, 0.9), 0 0 26px rgba(212, 184, 150, 0.7), 0 0 48px rgba(212, 184, 150, 0.45), 0 0 72px rgba(212, 184, 150, 0.25);\n' +
          '  transition: background 0.2s ease, box-shadow 0.2s ease;\n' +
          '}\n' +
          '#tavern-statusbar-trigger:hover .tavern-statusbar-glow {\n' +
          '  background: rgba(212, 184, 150, 0.75);\n' +
          '  box-shadow: 0 0 14px rgba(212, 184, 150, 1), 0 0 36px rgba(212, 184, 150, 0.85), 0 0 64px rgba(212, 184, 150, 0.6), 0 0 96px rgba(212, 184, 150, 0.35);\n' +
          '}\n' +
          '#tavern-statusbar-trigger .tavern-statusbar-inner {\n' +
          '  position: relative;\n' +
          '  width: 48px;\n' +
          '  height: 48px;\n' +
          '  border-radius: 50%;\n' +
          '  z-index: 1;\n' +
          '  background: rgba(58, 40, 24, 0.85);\n' +
          '  color: #d4b896;\n' +
          '  font-size: 20px;\n' +
          '  font-weight: bold;\n' +
          '  display: flex;\n' +
          '  align-items: center;\n' +
          '  justify-content: center;\n' +
          '  transition: transform 0.15s ease, background 0.15s ease;\n' +
          '}\n' +
          '#tavern-statusbar-trigger:hover .tavern-statusbar-inner {\n' +
          '  transform: scale(1.06);\n' +
          '  background: rgba(58, 40, 24, 0.95);\n' +
          '}\n' +
          '#tavern-statusbar-trigger:active .tavern-statusbar-inner {\n' +
          '  transform: scale(0.96);\n' +
          '}\n',
      )
      .appendTo('head');

    $floatBtn = $('<div>')
      .attr('id', 'tavern-statusbar-trigger')
      .append($('<div>').addClass('tavern-statusbar-glow'))
      .append($('<div>').addClass('tavern-statusbar-inner').text('☰'))
      .appendTo('body');

    let dragStartX = 0;
    let dragStartY = 0;
    const clickThreshold = 4;

    $floatBtn.on('mousedown', function (e) {
      dragStartX = e.clientX;
      dragStartY = e.clientY;
    });

    $floatBtn.on('mouseup', function (e) {
      const dx = Math.abs(e.clientX - dragStartX);
      const dy = Math.abs(e.clientY - dragStartY);
      if (dx <= clickThreshold && dy <= clickThreshold) {
        toggleNotebook();
      }
    });

    if (typeof $floatBtn.draggable === 'function') {
      $floatBtn.draggable({
        containment: 'window',
        scroll: false,
        start: function () {
          $(this).css('cursor', 'grabbing');
        },
        stop: function () {
          $(this).css('cursor', 'pointer');
        },
      });
    }
  }

  function destroyFloatButton() {
    if ($floatBtn) {
      try {
        $floatBtn.draggable('destroy');
      } catch (e) {
        // draggable 未初始化时忽略
      }
      $floatBtn.remove();
      $floatBtn = null;
    }
    if (floatBtnStyleId) {
      $('#' + floatBtnStyleId).remove();
      floatBtnStyleId = null;
    }
  }

  function init(htmlText) {
    cachedHtmlText = htmlText;
    createFloatButton();

    // 卸载时清理
    $(window).on('pagehide', function () {
      closeNotebook();
      destroyFloatButton();
    });
  }

  // 加载 HTML 内容后启动
  if (!NOTEBOOK_HTML_URL) {
    console.error('请在 小夜_悬浮窗口.js 顶部填写 NOTEBOOK_HTML_URL 为你的 HTML 文件完整 URL');
    toastr.error('状态栏脚本未配置 HTML 地址，请查看脚本顶部注释');
    return;
  }

  fetch(NOTEBOOK_HTML_URL)
    .then(function (res) {
      if (!res.ok) throw new Error('加载记事板 HTML 失败: ' + res.status);
      return res.text();
    })
    .then(function (htmlText) {
      init(htmlText);
    })
    .catch(function (err) {
      console.error('状态栏脚本初始化失败:', err);
      toastr.error('状态栏脚本初始化失败: ' + err.message);
    });
})();

