   flex:1 的内部滚动容器（stuScroll/feed/日历…）靠这个高度才有边界，才能真正内部滚动。 */
.phone{position:relative;width:100%;height:100vh;height:100dvh;max-height:100vh;max-height:100dvh;background:linear-gradient(180deg,#0d1122 0%,#1a1530 55%,#2a1a3e 100%);display:flex;flex-direction:column;overflow-y:auto;overflow-x:hidden;}
.pullBar{position:absolute;top:0;left:0;right:0;height:36px;display:flex;align-items:center;justify-content:center;color:#b48ef2;font-size:12px;letter-spacing:1px;transform:translateY(-100%);transition:transform .18s ease;pointer-events:none;z-index:6;}
.pullBar.show{transform:translateY(0);transition:none;}
/* 通知条 + 下拉通知栏（像真手机：从顶部拉下来，向上滑收起） */
.pNotifBar{flex:none;text-align:center;color:#cfe0ff;font-size:11.5px;padding:6px 12px 0;cursor:pointer;letter-spacing:.5px;}
.pNotifBar b{color:#ffd66e;}
#hpShade{position:absolute;left:0;right:0;top:0;bottom:0;z-index:30;background:linear-gradient(180deg,#101626 0%,#141b2e 68%,#0c111d 100%);transform:translateY(-100%);display:flex;flex-direction:column;pointer-events:none;box-shadow:0 14px 34px rgba(0,0,0,.55);}
.shadeTop{flex:none;display:flex;align-items:center;gap:8px;padding:11px 14px 9px;color:#dbe9ff;font-size:12px;border-bottom:1px solid rgba(255,255,255,.1);}
.shadeTit{font-weight:bold;}
.shadeCount{color:#ffd66e;}
.shadeHint{margin-left:auto;color:#8fa3c8;font-size:11px;cursor:pointer;}
#shadeList{flex:1;min-height:0;overflow-y:auto;padding:10px 12px 16px;-webkit-overflow-scrolling:touch;overscroll-behavior:contain;}
.shadeItem{display:flex;gap:8px;align-items:flex-start;background:rgba(255,255,255,.06);border:1px solid rgba(255,255,255,.1);border-radius:12px;padding:9px 11px;margin-bottom:8px;cursor:pointer;}
.shadeItem:active{background:rgba(255,255,255,.13);}
.shadeItem .siIcon{flex:none;font-size:15px;line-height:1.2;}
.shadeItem .siBody{flex:1;min-width:0;}
.shadeItem .siFrom{color:#bfe0ff;font-size:12px;font-weight:600;}
.shadeItem .siText{color:#e7ecf8;font-size:12px;line-height:1.45;margin-top:2px;overflow-wrap:break-word;word-break:break-word;}
.shadeItem .siAt{color:#7d88a0;font-size:10px;margin-top:3px;}
.shadeEmpty{color:#8fa3c8;font-size:12px;text-align:center;padding:28px 0;}
/* 主页不滚动，把纵向手势留给下拉刷新，避免浏览器接管导致 pointercancel */
#phoneHome{touch-action:pan-x;overscroll-behavior:contain;}
/* 所有可点元素去掉点按高亮、去掉双击缩放的 300ms 延迟 */
*{-webkit-tap-highlight-color:transparent;}
button,[onclick]{touch-action:manipulation;}
html,body{-webkit-text-size-adjust:100%;}
/* 手机端：顶部这几行用来下拉通知栏，禁止浏览器自己接管纵向手势（必须写在 [onclick] 之后，
   同优先级靠顺序取胜，否则 .pNotifBar 会被上面的 manipulation 覆盖）；通知栏本体也禁止，
   内部列表单独放行（还能滚） */
.pNotifBar,.pStatus,.pClock,.pDate{touch-action:none;}
#hpShade{touch-action:pan-y;}
#shadeList{touch-action:pan-y;-webkit-overflow-scrolling:touch;}
.pStatus{display:flex;justify-content:space-between;align-items:center;padding:10px 18px 4px;color:#fff;font-size:12px;}
.pClock{text-align:center;color:#fff;font-size:30px;font-weight:200;letter-spacing:2px;margin-top:6px;}
.pDate{text-align:center;color:#c8c8d4;font-size:13px;margin-bottom:12px;}
/* 主页「今天」卡：剧情日期推断出的当天信息（课程/同桌/活动），数据都来自已有真源 */
.todayCard{margin:0 22px 12px;padding:7px 11px;border-radius:14px;background:rgba(255,255,255,.08);border:1px solid rgba(255,255,255,.14);}
.todayCard .tdTitle{color:#9fb4ff;font-size:11px;letter-spacing:2px;margin-bottom:5px;}
.todayCard .tdRow{display:flex;gap:7px;align-items:flex-start;margin-top:3px;line-height:1.34;}
.todayCard .tdRow i{flex:0 0 36px;font-style:normal;color:#8e93a8;font-size:11px;padding-top:1px;}
.todayCard .tdRow b{flex:1;color:#f0f2f8;font-size:11.5px;font-weight:500;word-break:break-all;}
.todayCard .tdRow.emph b{color:#ffd66e;}
/* 今天卡里的通知 / 催眠规则行 */
.tdNotifWrap{margin-top:6px;border-top:1px solid rgba(255,255,255,.12);padding-top:4px;}
.tdNotif{display:flex;gap:6px;align-items:flex-start;margin-top:3px;cursor:pointer;line-height:1.35;border-radius:8px;padding:2px 4px;}
.tdNotif:active{background:rgba(255,255,255,.08);}
.tnTag{flex:none;font-size:10px;border-radius:999px;padding:1px 6px;border:1px solid rgba(255,255,255,.3);color:#cfe0ff;}
.tnTag.dm{color:#9fe8b0;border-color:rgba(120,230,160,.5);}
.tnTag.ad{color:#ffd479;border-color:rgba(255,214,110,.5);}
.tnBody{flex:1;min-width:0;color:#eaeefb;font-size:11.5px;overflow-wrap:break-word;word-break:break-word;}
.tnBody b{color:#bfe0ff;font-weight:600;}
.tdNotif.tdMore{color:#9fb4ff;font-size:11px;justify-content:center;padding:4px;}
/* 面板高度偏矮时（酒馆面板是 min(600px,80vh)，小窗口会更矮）再压一档，尽量不出现内部滚动 */
@media (max-height:560px){
  .pClock{font-size:30px;margin-top:6px;}
  .pDate{margin-bottom:6px;}
  .todayCard{margin-bottom:8px;padding:7px 10px;}
  .pApps{gap:11px 8px;}
  .appIcon .icon{width:46px;height:46px;border-radius:12px;font-size:22px;}
  .appIcon .appName{font-size:10px;}
  .pDock{padding:8px 16px;margin-bottom:9px;}
}
.pApps{flex:1;min-height:0;overflow-y:auto;display:grid;grid-template-columns:repeat(4,1fr);gap:16px 10px;align-content:start;padding:0 22px 6px;}
.appIcon{display:flex;flex-direction:column;align-items:center;gap:5px;background:none;border:none;cursor:pointer;}
.appIcon .icon{width:52px;height:52px;border-radius:14px;display:flex;align-items:center;justify-content:center;font-size:25px;color:#fff;box-shadow:0 5px 14px rgba(0,0,0,.4);}
.appIcon .appName{color:#fff;font-size:11px;text-shadow:0 1px 3px rgba(0,0,0,.65);}
.ic-sns{background:linear-gradient(135deg,#3aa0ff,#1f6fb2);}
.ic-live{background:linear-gradient(135deg,#ff5ea8,#b02fd0);}
.ic-hypno{background:linear-gradient(135deg,#b06bff,#6a22d0);}
.ic-forum{background:linear-gradient(135deg,#4cd964,#1fa34c);}
.ic-board{background:linear-gradient(135deg,#e0a458,#b5651d);}
.pDock{display:flex;justify-content:center;gap:26px;padding:7px 16px;background:rgba(255,255,255,.09);backdrop-filter:blur(10px);margin:0 14px 8px;border-radius:22px;flex:none;}
.pHome{color:#b48ef2;cursor:pointer;font-size:13px;}
.dialWrap{margin:22px 22px 14px;display:flex;flex-direction:column;gap:14px;flex:none;}
.dialTitle{color:#fff;font-size:19px;font-weight:bold;text-align:center;}
.dialInput{background:rgba(255,255,255,.1);border:1px solid #4a3a6a;border-radius:12px;padding:13px 14px;color:#fff;font-size:15px;outline:none;}
.dialInput::placeholder{color:#8b7aa6;}
.dialBtns{display:flex;gap:12px;}
.dialBtn{flex:1;padding:13px;border-radius:12px;border:none;font-size:15px;cursor:pointer;background:rgba(255,255,255,.14);color:#fff;}
.dialBtn.dialGo{background:linear-gradient(135deg,#3aa0ff,#1f6fb2);}
/* 通话记录（电话 App 内） */
#dialTab{height:100vh;height:100dvh;min-height:0;display:flex;flex-direction:column;}
.callLogWrap{flex:1;min-height:0;display:flex;flex-direction:column;padding:0 22px 16px;}
.callLogTit{color:#9d8db8;font-size:12px;letter-spacing:1px;padding:0 2px 8px;flex:none;}
.callLogList{flex:1;overflow-y:auto;min-height:0;-webkit-overflow-scrolling:touch;}
.callLogRow{display:flex;align-items:center;gap:10px;background:rgba(255,255,255,.05);border:1px solid rgba(255,255,255,.1);border-radius:10px;padding:9px 12px;margin-bottom:6px;cursor:pointer;}
.callLogRow:active{background:rgba(255,255,255,.12);}
.clIcon{font-size:14px;flex:none;}
.clName{flex:1;min-width:0;color:#e8e0ff;font-size:13px;overflow-wrap:break-word;word-break:break-word;}
.clTime{flex:none;color:#9d8db8;font-size:11px;}
.callLogEmpty{color:#7e7096;font-size:12px;text-align:center;padding:16px 0;}
/* ——— 音乐播放器（第 5 个应用）——— */
.ic-music{background:linear-gradient(135deg,#ffb347,#ff5e62);}
.musicHead{display:flex;align-items:center;gap:8px;padding:12px 18px 2px;color:#fff;}
.musicTit{font-size:18px;font-weight:bold;}
.musicCount{font-size:12px;color:#8b7aa6;}
.musicCats{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;padding:10px 18px;}
.musicCat{display:block;text-align:center;padding:7px 6px;border-radius:999px;border:1px solid #4a3a6a;background:rgba(255,255,255,.06);color:#c8c8d4;font-size:13px;cursor:pointer;white-space:nowrap;user-select:none;}
.musicCat.on{background:linear-gradient(135deg,#ffb347,#ff5e62);border-color:transparent;color:#fff;font-weight:bold;}
.musicList{flex:1;padding:4px 18px 8px;}
.musicPage{display:flex;align-items:center;justify-content:center;gap:14px;padding:8px 18px 10px;}
.pageBtn{padding:6px 16px;border:1px solid #4a3a6a;border-radius:999px;background:rgba(255,255,255,.06);color:#c8c8d4;font-size:13px;cursor:pointer;}
.pageBtn:disabled{opacity:.4;cursor:default;}
.pageInfo{color:#8b7aa6;font-size:12px;}
.songRow{display:flex;flex-direction:column;gap:2px;padding:11px 12px;margin-bottom:6px;border-radius:10px;background:rgba(255,255,255,.05);border:1px solid rgba(255,255,255,.06);cursor:pointer;}
.songRow:hover{background:rgba(255,255,255,.1);}
.songRow.on{border-color:#ffb347;background:rgba(255,179,71,.14);}
.songName{color:#fff;font-size:14px;}
.songSub{color:#8b7aa6;font-size:11px;}
.miniPlayer{background:rgba(13,17,34,.96);border-top:1px solid #3a2a55;padding:10px 14px;display:flex;flex-direction:column;gap:8px;}
.miniName{color:#ffd9a8;font-size:13px;font-weight:bold;text-align:center;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}
.miniPlayer audio{width:100%;height:34px;}
.pushBtn{width:100%;padding:10px;border:none;border-radius:10px;font-size:14px;font-weight:bold;color:#fff;background:linear-gradient(120deg,#ffb347,#ff5e62);cursor:pointer;letter-spacing:2px;}
.pushBtn:disabled{opacity:.45;cursor:default;}
/* ——— 学生助手（第 6 个应用）——— */
.ic-stu{background:linear-gradient(135deg,#4aa3ff,#2056c9);}
/* 学生助手三页固定为手机视口高度，内部滚动（修复课表/座位表被 overflow:hidden 裁掉） */
#studentTab{height:100vh;height:100dvh;min-height:0;}
#studentCard,#schedTab,#seatTab,#relTab{display:flex;flex-direction:column;flex:1;min-height:0;overflow:hidden;}
.stuHead{display:flex;align-items:center;gap:8px;padding:10px 14px 4px;color:#fff;flex:none;}
.stuTit{font-size:16px;font-weight:bold;}
.stuUpd{background:rgba(74,163,255,.18);border:1px solid #4aa3ff;color:#a8d0ff;border-radius:999px;padding:3px 9px;font-size:11px;cursor:pointer;white-space:nowrap;flex:none;}
.stuUpd:active{transform:scale(.96);}
.stuHead .headFb{flex:1;min-width:0;font-size:11px;text-align:right;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;margin:0;padding:0 2px;}
.stuHead .pHome{flex:none;}
/* 当前角色手动指定行 */
.stuWho{display:flex;align-items:center;gap:6px;padding:5px 14px 3px;flex:none;}
.stuWho .swLabel{color:#8e93a8;font-size:11px;flex:none;}
.stuWho input{flex:1;min-width:0;background:rgba(255,255,255,.08);border:1px solid rgba(255,255,255,.18);border-radius:8px;color:#fff;font-size:12px;padding:4px 8px;outline:none;}
.stuWho input::placeholder{color:#6b7086;}
.swBtn{flex:none;background:rgba(255,255,255,.1);border:1px solid rgba(255,255,255,.22);color:#cfd4e6;border-radius:999px;padding:4px 10px;font-size:11px;cursor:pointer;}
.swBtn.on{background:rgba(255,214,110,.18);border-color:#ffd66e;color:#ffd66e;}
.stuScroll{flex:1;overflow:auto;padding:10px 13px 14px;min-height:0;display:flex;flex-direction:column;-webkit-overflow-scrolling:touch;}
/* 卡片/表格必须保持自然高度：flex 列容器里 overflow:hidden 的卡片会被压扁、
   内容被裁掉（成绩雷达图就是这么被切掉的），超出部分交给 .stuScroll 内部滚动。
   #stuBody / .stuCard 自带 flex:1，必须用同等或更高优先级覆盖。 */
.stuScroll > *{flex:0 0 auto;}
.stuScroll > #stuBody{flex:0 0 auto;}
#stuBody > .stuCard{flex:0 0 auto;}
#stuBody{flex:1;display:flex;flex-direction:column;min-height:0;}
.stuCard{background:linear-gradient(150deg,#0d2a52 0%,#143c74 50%,#0a1b36 100%);border:1px solid #2b5da8;border-radius:16px;padding:15px 13px;position:relative;overflow:hidden;box-shadow:0 6px 18px rgba(0,0,0,.32);flex:1;display:flex;flex-direction:column;}
.stuCard::before{content:'';position:absolute;top:-50px;right:-50px;width:180px;height:180px;background:radial-gradient(circle,rgba(74,163,255,.35),transparent 70%);pointer-events:none;}
.stuCard::after{content:'';position:absolute;bottom:-60px;left:-40px;width:150px;height:150px;background:radial-gradient(circle,rgba(160,90,255,.22),transparent 70%);pointer-events:none;}
.stuSchool{color:#7fb4e8;font-size:11px;letter-spacing:2px;text-align:center;position:relative;}
.stuAvatar{width:52px;height:52px;border-radius:50%;margin:10px auto 7px;display:flex;align-items:center;justify-content:center;font-size:22px;font-weight:bold;color:#fff;background:linear-gradient(135deg,#4aa3ff,#8a4dff);box-shadow:0 0 0 3px rgba(74,163,255,.2);position:relative;}
.stuName{color:#fff;font-size:23px;font-weight:bold;text-align:center;margin:0 0 3px;letter-spacing:1px;position:relative;}
.stuSub{color:#8fb6e0;font-size:11px;text-align:center;margin-bottom:13px;position:relative;letter-spacing:1px;}
.stuGrid{display:grid;grid-template-columns:repeat(2,1fr);gap:8px;position:relative;}
.stuField{background:rgba(255,255,255,.06);border:1px solid rgba(255,255,255,.1);border-radius:9px;padding:7px 11px 8px;display:flex;flex-direction:column;gap:2px;min-width:0;}
.stuField i{font-style:normal;color:#7fb4e8;font-size:10px;letter-spacing:1px;}
.stuField b{color:#fff;font-size:14px;font-weight:bold;line-height:1.35;overflow-wrap:break-word;word-break:break-word;}
.stuField.wide{grid-column:1 / -1;}
.stuSrc{position:relative;color:#7fb4e8;font-size:10px;text-align:center;margin-top:8px;line-height:1.5;overflow-wrap:break-word;word-break:break-word;}
/* 绩点维度图 */
.gradeBox{margin-top:auto;background:rgba(255,255,255,.05);border:1px solid rgba(255,255,255,.1);border-radius:12px;padding:8px 10px 9px;position:relative;}
.gradeSvg{width:100%;max-width:186px;height:auto;display:block;margin:0 auto;}
.gradeLegend{display:flex;flex-wrap:wrap;gap:3px 10px;justify-content:center;margin-top:2px;}
.gradeLegend span{color:#9db8d8;font-size:11px;}
.gradeLegend b{color:#dcebff;}
