.teacherRow{display:flex;gap:8px;align-items:flex-start;background:rgba(255,255,255,.04);border:1px solid rgba(255,255,255,.08);border-radius:10px;padding:7px 10px;margin-bottom:6px;}
.teacherRow.hr{background:rgba(74,163,255,.12);border-color:rgba(74,163,255,.3);}
.tSub{flex:none;color:#7fb4e8;font-size:11px;min-width:42px;padding-top:2px;}
/* 任课教师可点选换人（代课） */
.tPick{color:#bcd9ff;border-bottom:1px dashed rgba(160,200,255,.55);cursor:pointer;}
.tPick:hover{color:#fff;}
.tOv{color:#ffd479;font-size:11px;}
.tWas{color:#9fb6cc;font-size:11px;}
.tOvNow{font-size:12px;color:#3a4a5a;margin:2px 0 8px;line-height:1.6;}
