.stuBtns{display:flex;gap:9px;margin-top:auto;padding-top:10px;flex:none;}
.stuBtn{flex:1;padding:13px;border:none;border-radius:11px;font-size:14px;font-weight:bold;color:#fff;cursor:pointer;background:linear-gradient(135deg,#4aa3ff,#2056c9);}
.stuBtn:active{transform:scale(.97);}
/* 关系账本 */
.stuBtn.ghost{background:rgba(255,255,255,.12);border:1px solid rgba(255,255,255,.25);color:#dcebff;font-weight:normal;}
.relTit{color:#a8d0ff;font-size:12px;margin:0 0 8px;line-height:1.5;}
.relWarn{color:#ffb4c8;font-size:11px;margin:0 0 8px;line-height:1.5;}
.relRow{display:flex;flex-wrap:wrap;align-items:center;gap:4px 8px;background:rgba(255,255,255,.05);border:1px solid rgba(255,255,255,.1);border-radius:11px;padding:8px 10px;margin-bottom:7px;}
.relNm{flex:0 0 auto;color:#dcebff;font-size:13px;font-weight:bold;overflow-wrap:break-word;word-break:break-word;}
.relAff{flex:0 0 auto;color:#ffd479;font-size:14px;font-weight:bold;}
.relMeta{flex:1 1 100%;min-width:0;order:9;}
.relMeta i{display:block;font-style:normal;color:#9db8d8;font-size:11px;line-height:1.45;overflow-wrap:break-word;word-break:break-word;}
.relOps{flex:1 0 auto;display:flex;gap:5px;justify-content:flex-end;}
.relOps button{background:rgba(255,255,255,.1);border:1px solid rgba(255,255,255,.22);color:#cfd4e6;border-radius:7px;padding:3px 8px;font-size:11px;cursor:pointer;white-space:nowrap;}
.relForm{margin-top:12px;border-top:1px solid rgba(74,163,255,.2);padding-top:10px;display:flex;flex-direction:column;gap:6px;}
.relFormTit{color:#a8d0ff;font-size:12px;font-weight:bold;}
/* 提取候选：多选后保存到关系人 */
.relCandBox{margin:4px 0 10px;border:1px solid rgba(255,214,110,.35);background:rgba(255,214,110,.07);border-radius:11px;padding:9px 10px;}
.relCandRow{display:flex;align-items:center;gap:8px;padding:6px 8px;border-radius:8px;background:rgba(255,255,255,.05);margin-bottom:5px;cursor:pointer;}
.relCandRow.in{opacity:.5;}
.relCandRow input{pointer-events:none;flex:none;}
.relCandRow b{flex:0 0 auto;color:#dcebff;font-size:13px;}
.relCandRow i{flex:1;min-width:0;font-style:normal;color:#9db8d8;font-size:11px;overflow-wrap:break-word;word-break:break-word;}
.relIn{flex:none;color:#ffd479;font-size:10px;border:1px solid rgba(255,214,110,.5);border-radius:999px;padding:1px 6px;}
/* 催眠：生效中的规则页 */
#ruleTab{flex:1;min-height:0;flex-direction:column;overflow:hidden;}
.ruleBody{flex:1;min-height:0;overflow-y:auto;padding:12px 14px;-webkit-overflow-scrolling:touch;}
.ruleRow{display:flex;flex-wrap:wrap;align-items:center;gap:5px 8px;background:rgba(255,255,255,.05);border:1px solid rgba(255,255,255,.1);border-radius:11px;padding:8px 10px;margin-bottom:7px;}
.ruleTag{flex:none;color:#e0b3ff;font-size:10px;border:1px solid rgba(224,179,255,.45);border-radius:999px;padding:1px 7px;}
.ruleTgt{flex:0 1 auto;color:#dcebff;font-size:12px;font-weight:bold;}
.ruleAt{flex:none;margin-left:auto;color:#7d88a0;font-size:10px;}
.ruleTxt{flex:1 1 100%;order:9;color:#c9d4e8;font-size:12px;line-height:1.5;overflow-wrap:break-word;word-break:break-word;}
