/* 课表 */
.schedGrid{display:grid;grid-template-columns:64px repeat(7,1fr);gap:3px;}
.schedHead{background:rgba(74,163,255,.16);border:1px solid rgba(74,163,255,.3);color:#a8d0ff;text-align:center;padding:6px 2px;font-size:12px;font-weight:bold;border-radius:6px;}
.schedCorner{color:#7fb4e8;}
.schedTime{background:rgba(255,255,255,.05);border:1px solid rgba(255,255,255,.08);color:#9db8d8;text-align:center;padding:5px 1px;font-size:10px;border-radius:6px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:1px;line-height:1.3;}
.schedTime b{color:#cfe2ff;font-size:11px;font-weight:bold;}
.schedTime span{color:#8fa8c6;font-size:9px;}
.schedCell{background:rgba(74,163,255,.1);border:1px solid rgba(74,163,255,.25);color:#e6f0ff;text-align:center;padding:8px 2px;font-size:12px;border-radius:6px;min-height:34px;display:flex;align-items:center;justify-content:center;word-break:break-all;}
.schedCell.empty{background:rgba(255,255,255,.03);border-color:rgba(255,255,255,.06);color:#5a6b85;}
.schedCell.club{font-size:10px;line-height:1.3;padding:5px 1px;background:rgba(160,90,255,.14);border-color:rgba(160,90,255,.32);color:#e2d3ff;}
.schedCell.lunch{font-size:10px;background:rgba(255,180,80,.14);border-color:rgba(255,180,80,.32);color:#ffd9a0;}
/* 课表拖动换课（同座位表；空格列/时间列仍可滚动） */
.schedCell[data-d]{cursor:grab;}
.schedCell[data-d].has{touch-action:none;-webkit-user-select:none;user-select:none;}
.schedCell.dragging{opacity:.4;}
.schedCell.over{border-color:#37c871;background:rgba(55,200,113,.22);}
.schedCell.picked{border-color:#ffd479;box-shadow:inset 0 0 0 1px #ffd479;}
/* 当前时间高亮（按剧情时钟） */
.schedHead.todayCol{background:rgba(255,212,121,.22);border-color:rgba(255,212,121,.55);color:#ffd479;}
.schedTime.now{border-color:#ffd479;background:rgba(255,212,121,.18);}
.schedTime.now b{color:#ffd479;}
.schedTime.now span{color:#e8c98a;}
.schedCell.todayCol{background:rgba(255,212,121,.07);}
.schedCell.now{border-color:#ffd479;background:rgba(255,212,121,.3);color:#fff;font-weight:bold;box-shadow:inset 0 0 0 1px #ffd479;}
.schedExtra{color:#8b9bb8;font-size:12px;text-align:center;margin-top:12px;line-height:1.7;}
/* 座位表（紧凑：整体缩小，多桌均分宽度，尽量单屏放下、不横滚） */
.seatLegend{color:#8b9bb8;font-size:12px;text-align:center;margin-bottom:10px;}
.seatRoom{display:flex;flex-direction:column;gap:6px;align-items:stretch;}
.seatRow{display:flex;gap:3px;align-items:stretch;}
.seatAisle{width:10px;flex:none;}
.seatDesk{flex:1;min-width:0;background:rgba(255,255,255,.06);border:1px solid rgba(255,255,255,.14);border-radius:6px;padding:3px;display:flex;gap:2px;align-items:center;}
.seatSide{display:flex;flex-direction:column;gap:2px;flex:1;min-width:0;}
.seatDivider{width:1px;align-self:stretch;background:rgba(255,255,255,.1);}
.seatName{background:rgba(74,163,255,.16);border:1px solid rgba(74,163,255,.35);color:#dcebff;border-radius:4px;padding:3px 1px;font-size:10px;line-height:1.2;text-align:center;cursor:grab;min-height:22px;display:flex;align-items:center;justify-content:center;word-break:break-all;touch-action:none;-webkit-user-select:none;user-select:none;}
.seatName.empty{background:rgba(255,255,255,.03);border-color:rgba(255,255,255,.06);cursor:default;}
.seatName.dragging{opacity:.4;}
.seatName.over{border-color:#37c871;background:rgba(55,200,113,.2);}
.seatName.picked{border-color:#ffd479;background:rgba(255,212,121,.22);box-shadow:inset 0 0 0 1px #ffd479;}

