#snsTab #contacts.on{display:flex;}
#ctList{flex:1;min-height:0;overflow-y:auto;padding:8px 12px 14px;-webkit-overflow-scrolling:touch;}
.ctCount{color:#64748b;font-size:11px;margin:0 0 8px;}
.ctGroup{color:#1b73e8;font-size:12px;font-weight:bold;margin:12px 0 6px;padding-bottom:4px;border-bottom:1px solid rgba(27,115,232,.25);}
.ctRow{display:flex;align-items:center;gap:8px;padding:7px 10px;border-radius:9px;background:rgba(27,115,232,.06);margin-bottom:5px;cursor:pointer;}
.ctRow:active{background:rgba(27,115,232,.16);}
.ctRow b{flex:1;color:#12325c;font-size:13px;font-weight:600;overflow-wrap:break-word;word-break:break-word;}
.ctClub{flex:none;color:#5b7fa8;font-size:10px;border:1px solid rgba(91,127,168,.45);border-radius:999px;padding:1px 7px;font-style:normal;}
#snsTab .pStatus{color:#334155;}
#snsTab .pHome{color:#1b73e8;}
#forumTab{background:#f2f8ff;color:#2b3a4a;}
#forumTab .pStatus{color:#334155;}
#forumTab .pHome{color:#3aa0ff;}
#liveTab{background:#1e2027;color:#e8e8f0;}
#liveTab .pHome{color:#1da1f2;}
#snsTab,#liveTab,#forumTab,#cameraTab{height:100vh;height:100dvh;min-height:0;}
/* 内置 app 内容视图：占满顶栏下方剩余空间并内部滚动（修复内容超长被 .phone overflow:hidden 裁掉、无法下滑上翻） */
#snsTab #feed,#snsTab #profile,#snsTab #dm,#snsTab #group,
#liveTab #live,#liveTab #room,
#forumTab #forum,#forumTab #post,#forumTab #fdm{flex:1;min-height:0;overflow-y:auto;overflow-x:hidden;-webkit-overflow-scrolling:touch;}
/* ═══ 相机文字超框修复 ═══ */
#cameraTab .camShot{overflow-wrap:break-word;word-break:break-word;min-width:0;}
#cameraTab .galText{overflow-wrap:break-word;word-break:break-word;min-width:0;flex:1;}
#cameraTab .galCard{overflow:hidden;}
#cameraTab .galModalText{overflow-wrap:break-word;word-break:break-word;max-height:55vh;overflow-y:auto;}
#cameraTab .modal{max-height:82vh;display:flex;flex-direction:column;overflow:hidden;}
#cameraTab .modal h4{flex:none;}
#cameraTab .modal textarea{width:100%;box-sizing:border-box;border:1px solid #e3e5e8;border-radius:8px;padding:8px 10px;font-size:14px;font-family:inherit;resize:vertical;min-height:76px;margin-bottom:4px;}
/* ═══ 论坛发帖：附带媒体 ═══ */
#forumTab .postMediaRow{display:flex;align-items:center;gap:8px;margin-bottom:8px;}
#forumTab .postMediaHint{font-size:12px;color:#8aa2bd;}
#forumTab .postAttachChips,#forumTab .postMediaChips{display:flex;flex-wrap:wrap;gap:6px;margin-bottom:8px;}
