#forumTab .attachChip{display:flex;align-items:center;gap:5px;background:#eef6ff;border:1px solid #d6e8ff;border-radius:999px;padding:3px 5px 3px 10px;font-size:12px;color:#2b3a4a;max-width:100%;}
#forumTab .attachChip .atxt{overflow-wrap:break-word;word-break:break-word;min-width:0;}
#forumTab .attachChip .arm{background:none;border:none;color:#9aa0a6;font-size:14px;cursor:pointer;line-height:1;padding:0 2px;flex:none;}
/* ═══ 内置 app：日历 ═══ */
#calTab{height:100vh;height:100dvh;min-height:0;}
.ic-cal{background:linear-gradient(135deg,#ff8a5c,#d64545);}
.ic-hist{background:linear-gradient(135deg,#8f8ce7,#4a46a8);}
.calHead{display:flex;align-items:center;gap:6px;padding:10px 14px 4px;color:#fff;flex:none;}
.calNav{background:rgba(255,255,255,.1);border:1px solid rgba(255,255,255,.18);color:#e8dcff;border-radius:8px;width:30px;height:28px;font-size:14px;cursor:pointer;line-height:1;flex:none;padding:0;}
