.calCell.range{background:rgba(160,90,255,.13);}
.cdNum{color:#e6dcff;font-size:12px;font-weight:bold;line-height:1.25;flex:none;}
.cdDots{display:flex;gap:2px;margin-top:2px;flex-wrap:wrap;justify-content:center;flex:none;}
.cdDot{width:4px;height:4px;border-radius:50%;}
.cdDot.fes{background:#ff6b8a;}
.cdDot.evt{background:#5cc8ff;}
.cdDot.mine{background:#ffd479;}
.cdTag{font-size:9px;color:#ddd0f5;line-height:1.15;margin-top:1px;text-align:center;max-height:21px;overflow:hidden;word-break:break-all;}
.calBody{flex:1;min-height:0;display:flex;flex-direction:column;padding:10px 12px 12px;}
.calListTit{color:#9d8db8;font-size:12px;letter-spacing:1px;padding-bottom:6px;flex:none;}
.calList{flex:1;overflow-y:auto;min-height:0;-webkit-overflow-scrolling:touch;}
.calRow{display:flex;gap:8px;align-items:flex-start;background:rgba(255,255,255,.05);border:1px solid rgba(255,255,255,.09);border-radius:9px;padding:7px 10px;margin-bottom:5px;cursor:pointer;}
.calRow.fes{border-color:rgba(255,107,138,.45);}
.calRow.evt{border-color:rgba(92,200,255,.45);}
.calRow.mine{border-color:rgba(255,212,121,.5);}
.calRowD{flex:none;color:#ffd479;font-size:11px;font-weight:bold;min-width:46px;padding-top:1px;}
.calRowT{flex:1;min-width:0;color:#e6dcff;font-size:12px;line-height:1.6;overflow-wrap:break-word;word-break:break-word;}
.calEmpty{color:#7e7096;font-size:12px;text-align:center;padding:14px 0;}
#calTab .calCalHint{font-size:12px;color:#6b7787;line-height:1.6;margin-bottom:7px;}
#calTab .modalBg{display:none;position:absolute;top:0;left:0;right:0;bottom:0;background:rgba(0,0,0,.6);z-index:30;align-items:center;justify-content:center;}
#calTab .modalBg.show{display:flex;}
#calTab .modal{background:#fff;border-radius:12px;padding:16px;width:84%;max-width:340px;max-height:82vh;display:flex;flex-direction:column;overflow:hidden;box-shadow:0 4px 20px rgba(0,0,0,.4);}
#calTab .modal h4{margin:0 0 10px;font-size:15px;color:#2b3a4a;flex:none;}
#calTab .modal input{width:100%;box-sizing:border-box;border:1px solid #e3e5e8;border-radius:8px;padding:7px 10px;font-size:14px;font-family:inherit;margin-top:8px;flex:none;}
#calTab .modal .mrow{display:flex;justify-content:flex-end;gap:8px;margin-top:10px;flex:none;}
#calTab .modal .cancel{background:#f0f4f8;color:#5a6b7d;border:none;border-radius:6px;padding:5px 14px;font-size:13px;cursor:pointer;}
.calDayEvents{overflow-y:auto;min-height:0;max-height:38vh;}
.calDayEvents .calRow{margin-bottom:4px;cursor:default;}
.calDel{flex:none;background:none;border:none;color:#c0392b;font-size:13px;cursor:pointer;padding:0 2px;line-height:1;}
/* 弹出层是白底，行样式需换成深色文字（否则沿用深色主题的浅紫字会看不清） */
#calTab .modal .calRow{background:#f5f8fc;border:1px solid #dde5ee;align-items:center;}
#calTab .modal .calRow.fes{background:#fff2f5;border-color:#ffc9d6;}
#calTab .modal .calRow.evt{background:#eef7ff;border-color:#c2e1ff;}
#calTab .modal .calRow.mine{background:#fff8e6;border-color:#ffdfa0;}
#calTab .modal .calRowD{color:#5a6b7d;font-size:11px;font-weight:bold;}
#calTab .modal .calRow.fes .calRowD{color:#c2185b;}
#calTab .modal .calRow.evt .calRowD{color:#1565c0;}
#calTab .modal .calRow.mine .calRowD{color:#8a5a00;}
#calTab .modal .calRowT{color:#1b2430;font-size:13px;line-height:1.65;}
#calTab .modal .calEmpty{color:#6b7787;}
#calTab .modal .calDel{font-size:14px;padding:0 4px;}
/* ═══ 网络崩溃 / 权限锁定 覆盖层 ═══ */
.errOverlay{display:none;position:absolute;top:0;left:0;right:0;bottom:0;z-index:40;flex-direction:column;align-items:center;justify-content:center;padding:0 30px;text-align:center;background:linear-gradient(180deg,#0d1122 0%,#1a1530 55%,#2a1a3e 100%);}
.errOverlay.show{display:flex;}
.errIcon{font-size:54px;margin-bottom:16px;}
.errTitle{font-size:17px;font-weight:bold;color:#f2ecff;margin-bottom:10px;line-height:1.5;}
.errDesc{font-size:13px;color:#9b8bb8;margin-bottom:24px;line-height:1.7;}
.errOverlay .errRow{display:flex;gap:10px;width:78%;max-width:240px;}
.errOverlay .errBack{flex:1;background:rgba(255,255,255,0.06);color:#cfc4e8;border:1px solid rgba(255,255,255,0.22);border-radius:999px;padding:13px;font-size:13px;font-weight:bold;cursor:pointer;letter-spacing:1px;}
.errOverlay .send{flex:1;padding:13px;letter-spacing:1px;}
#forumTab .netErrBox{text-align:center;padding:48px 22px;}
#forumTab .netErrBox .errIcon{font-size:46px;margin-bottom:14px;color:#c7b3e6;}
#forumTab .netErrBox .errTitle{font-size:16px;font-weight:bold;color:#3a4a5a;margin-bottom:8px;line-height:1.5;}
#forumTab .netErrBox .errDesc{font-size:13px;color:#8a9ab0;margin-bottom:20px;line-height:1.7;}
#forumTab .netErrBox .send{padding:10px 28px;}
/* ═══ 网络修复工具 ═══ */
.ic-repair{background:linear-gradient(135deg,#7dd3fc,#0ea5e9);}
#repairTab{color:#f2ecff;}
#repairTab .repairBody{flex:1;min-height:0;overflow-y:auto;padding:16px;}
#repairTab .repairCard{background:rgba(255,255,255,.05);border:1px solid rgba(255,255,255,.12);border-radius:14px;padding:16px;margin-bottom:12px;}
#repairTab .repairCard h4{margin:0 0 8px;font-size:15px;color:#d9b8ff;}
#repairTab .repairCard p{margin:0;font-size:13px;color:#c9b7e6;line-height:1.75;}
#repairTab .repairFixBtn{display:block;width:100%;margin:18px 0 8px;padding:16px;border:none;border-radius:14px;font-size:16px;font-weight:bold;cursor:pointer;background:linear-gradient(135deg,#3aa0ff,#1f6fb2);color:#fff;letter-spacing:1px;}
#repairTab .repairStatus{font-size:13px;color:#9b8bb8;text-align:center;margin-top:6px;}
/* ── 版本回顾（样式必须带 #histTab 前缀：repair* 的规则都限定在 #repairTab 下）── */
#histTab .histBody{flex:1;min-height:0;overflow-y:auto;padding:6px 18px 26px;}
#histTab .histCur{font-size:12px;color:#9b8bb8;text-align:center;padding:2px 0 16px;line-height:1.7;}
#histTab .histCard{background:rgba(255,255,255,.05);border:1px solid rgba(255,255,255,.14);border-radius:14px;
  padding:15px 18px 17px;margin:0 0 15px;}
#histTab .histVer{font-size:14px;color:#8fd0ff;font-weight:bold;margin:0 0 11px;letter-spacing:.6px;
  padding-bottom:9px;border-bottom:1px solid rgba(255,255,255,.11);}
#histTab .histSec{font-size:13px;color:#d9b8ff;font-weight:bold;margin:13px 0 6px;}
#histTab .histSec:first-of-type{margin-top:0;}
#histTab .histCard ul{margin:0;padding-left:19px;}
#histTab .histCard li{font-size:13px;color:#cfc4e0;line-height:1.78;margin-bottom:6px;}
#histTab .histCard li:last-child{margin-bottom:0;}
/* ═══ 私聊「+」媒体发送 ═══ */
.plusBtn{background:#eef1f5;color:#475569;border:1px solid #d7dbe0;border-radius:999px;padding:8px 15px;font-size:16px;font-weight:bold;cursor:pointer;flex:none;line-height:1;}
.mediaPop{display:none;position:fixed;top:0;left:0;right:0;bottom:0;z-index:60;align-items:center;justify-content:center;background:rgba(0,0,0,.55);}
.mediaPop.show{display:flex;}
.mediaPopBox{background:#fff;border-radius:14px;width:88%;max-width:340px;max-height:78%;display:flex;flex-direction:column;overflow:hidden;box-shadow:0 8px 28px rgba(0,0,0,.4);}
.mediaPopHead{display:flex;align-items:center;justify-content:space-between;padding:12px 14px;border-bottom:1px solid #eef1f5;color:#2b3a4a;font-size:15px;font-weight:bold;flex:none;}
.mediaPopClose{background:none;border:none;color:#9aa0a6;font-size:20px;cursor:pointer;line-height:1;}
.mediaPick{display:grid;grid-template-columns:1fr 1fr;gap:10px;padding:16px;}
.mediaPickBtn{background:#f5f7fa;border:1px solid #e3e5e8;border-radius:12px;padding:20px 10px;text-align:center;cursor:pointer;font-size:14px;color:#2b3a4a;}
.mediaPickBtn .mi{font-size:32px;display:block;margin-bottom:8px;}
.mediaList{overflow-y:auto;padding:8px 12px 12px;flex:1;min-height:0;}
.mediaListHead{display:flex;align-items:center;gap:6px;padding:6px 4px;color:#9aa0a6;font-size:12px;}
.mediaListHead .back{color:#3aa0ff;cursor:pointer;}
.mediaRow{display:flex;align-items:center;gap:10px;padding:11px 10px;border-bottom:1px solid #f0f3f7;cursor:pointer;border-radius:8px;}
.mediaRow:hover{background:#f5f7fa;}
.mediaRowIcon{font-size:20px;flex:none;}
.mediaRowTxt{flex:1;min-width:0;display:flex;flex-direction:column;gap:2px;}
.mediaRowName{font-size:13px;color:#2b3a4a;overflow-wrap:break-word;word-break:break-word;line-height:1.5;}
.mediaRowSub{font-size:11px;color:#9aa0a6;}
/* ═══ 媒体气泡 ═══ */
.mChip{display:flex;align-items:center;gap:8px;}
.mChip .mic{font-size:20px;flex:none;}
.mChip .mtxt{font-size:13px;line-height:1.5;overflow-wrap:break-word;word-break:break-word;min-width:0;flex:1;}
.mPlay{background:#eef1f5;color:#24404f;border:1px solid #cfd8e0;border-radius:999px;padding:4px 12px;font-size:12px;font-weight:bold;cursor:pointer;flex:none;}
.mView{background:#eef1f5;color:#24404f;border:1px solid #cfd8e0;border-radius:999px;padding:4px 12px;font-size:12px;font-weight:bold;cursor:pointer;flex:none;}
/* ——— 触屏设备专用微调（用 pointer:coarse 判定，不影响鼠标）——— */
@media (pointer:coarse){
  input,textarea,select{font-size:16px !important;}   /* 压过类选择器，否则 iOS 聚焦时会自动放大页面 */
  .relOps button,.ruleOps button,.swBtn,.stuUpd,.calTodayBtn,.pageBtn{min-height:26px;padding:5px 9px;}
  .appIcon .icon{width:54px;height:54px;}
}
</style>
</head>
<body>

<!-- 手机主页（起始页） -->
<div class="phone" id="phoneHome" onpointerdown="hpPullStart(event)" onpointermove="hpPullMove(event)" onpointerup="hpPullEnd(event)" onpointercancel="hpPullCancel()">
  <div class="pNotifBar" id="hpNotifBar" onclick="hpShadeOpen()"><span id="notifBarTxt">📩 暂无通知 · 下拉查看</span></div>
  <div id="hpShade">
    <div class="shadeTop"><span class="shadeTit">通知</span><span class="shadeCount" id="shadeCount">0</span><span class="shadeHint" onclick="hpShadeClose()">上滑收起 ▲</span></div>
    <div id="shadeList"></div>
  </div>
  <div class="pStatus"><span id="pStatusTime">12:00</span><span>新中市网络 📶 🔋</span></div>
  <div class="pClock" id="pClock">12:00</div>
  <div class="pDate" id="pDate">8月23日 星期六</div>
  <div class="todayCard" id="hpTodayCard" style="display:none;"></div>
  <!-- 未上传世界书提示：书没建、或换聊天被清空过 → 一直显示；点过「身份卡 · 整体上传」才消失 -->
  <div id="hpWbWarn" style="display:none;margin:8px 12px 0;padding:8px 10px;border-radius:10px;
       background:rgba(255,150,80,.18);border:1px solid rgba(255,150,80,.55);color:#ffe3c2;
       font-size:12px;line-height:1.5;">⚠ 还没上传世界书 · 点「身份卡」→「📤 整体上传」，AI 才能看到你的身份卡、课表、今日等内容</div>
  <div class="pApps">
    <button class="appIcon" onclick="hpOpenSNS()"><span class="icon ic-sns">💬</span><span class="appName">SNS</span></button>
    <button class="appIcon" onclick="hpOpenLive()"><span class="icon ic-live">📺</span><span class="appName">X站</span></button>
    <button class="appIcon" onclick="hpOpenForum()"><span class="icon ic-forum">🎓</span><span class="appName">学校论坛</span></button>
    <button class="appIcon" onclick="hpOpenBoard()"><span class="icon ic-board">📌</span><span class="appName">布告板</span></button>
    <button class="appIcon" onclick="hpOpenHypno()"><span class="icon ic-hypno">Ψ</span><span class="appName">催眠</span></button>
    <button class="appIcon" onclick="hpOpenMusic()"><span class="icon ic-music">🎵</span><span class="appName">音乐</span></button>
    <button class="appIcon" onclick="hpOpenStudent()"><span class="icon ic-stu">🪪</span><span class="appName">身份卡</span></button>
    <button class="appIcon" onclick="hpOpenCalendar()"><span class="icon ic-cal">📅</span><span class="appName">日历</span></button>
    <button class="appIcon" onclick="hpOpenHistory()"><span class="icon ic-hist">📜</span><span class="appName">版本回顾</span></button>
    <button class="appIcon" onclick="hpOpenRepair()"><span class="icon ic-repair">🔧</span><span class="appName">修复</span></button>
  </div>
  <div class="pDock">
    <button class="appIcon" onclick="hpOpenDial()"><span class="icon ic-sns">📞</span><span class="appName">电话</span></button>
    <button class="appIcon" onclick="hpOpenCamera()"><span class="icon ic-live">📷</span><span class="appName">相机</span></button>
  </div>
</div>

<!-- 拨号页（电话按钮） -->
<div class="phone" id="dialTab" style="display:none;">
  <div class="pStatus"><span id="dialTime">12:00</span><span>新中市网络 📶 🔋</span></div>
  <div class="dialWrap">
    <div class="dialTitle">📞 拨打给谁</div>
    <input id="dialName" class="dialInput" placeholder="输入对方昵称 / 真名" onkeydown="if(event.key==='Enter')hpDial()">
    <div class="dialBtns">
      <button class="dialBtn" onclick="hpHome()">取消</button>
      <button class="dialBtn dialGo" onclick="hpDial()">拨打</button>
    </div>
  </div>
  <div class="callLogWrap">
    <div class="callLogTit">📋 最近通话</div>
    <div class="callLogList" id="callLogList"></div>
  </div>
</div>

<!-- 音乐播放器（第 5 个应用） -->
<div class="phone" id="musicTab" style="display:none;">
  <div class="pStatus"><span>🎵 音乐</span><span>新中市网络 📶 🔋</span></div>
  <div class="musicHead">
    <span class="musicTit">音乐播放器</span>
    <span class="musicCount" id="musicCount"></span>
    <span style="flex:1"></span>
    <span class="pHome" onclick="hpHome()">🏠 主页</span>
  </div>
  <div class="musicCats" id="musicCats"></div>
  <div class="musicList" id="musicList"></div>
  <div class="musicPage">
    <button class="pageBtn" id="musicPrev" onclick="musicPage(-1)" disabled>‹ 上一页</button>
    <span class="pageInfo" id="musicPageInfo">第 1 页</span>
    <button class="pageBtn" id="musicNext" onclick="musicPage(1)">下一页 ›</button>
  </div>
  <div class="miniPlayer">
    <div class="miniName" id="miniName">点击上方歌曲播放</div>
    <audio id="miniAudio" controls preload="none"></audio>
    <button class="pushBtn" id="pushBtn" onclick="hpPushSong()" disabled>📤 推送剧情</button>
    <div class="feedback" id="musicFeedback"></div>
  </div>
</div>

<!-- 学生助手（第 6 个应用） -->
<div class="phone" id="studentTab" style="display:none;">
  <div class="pStatus"><span>🪪 身份卡</span><span>新中市网络 📶 🔋</span></div>

  <!-- 身份卡（首页） -->
  <div id="studentCard">
    <div class="stuHead">
      <button class="stuUpd" onclick="refreshStudent()">🔄 更新</button>
      <button class="stuUpd" onclick="hpStuCalibrate()">📌 校准</button>
      <button class="stuUpd" onclick="hpSyncWorld()">📤 整体上传</button>
      <span class="headFb feedback" id="stuFeedback"></span>
      <span class="pHome" onclick="hpHome()">🏠 主页</span>
    </div>
    <div class="stuWho">
      <span class="swLabel">当前角色</span>
      <input id="stuActorInput" placeholder="如 绫羽（留空＝自动判定）">
      <button class="swBtn" id="stuActorLockBtn" onclick="hpActorLockToggle()">锁定</button>
    </div>
    <div class="stuScroll">
      <div id="stuBody"></div>
      <div class="stuBtns">
        <button class="stuBtn" id="stuBtnSched" onclick="hpStuShow('schedTab')">📅 当前课表</button>
        <button class="stuBtn" id="stuBtnSeat" onclick="hpStuShow('seatTab')">🪑 班级座位表</button>
        <button class="stuBtn" onclick="hpOpenRel()">💗 关系账本</button>
      </div>
    </div>
  </div>

  <!-- 当前课表 -->
  <div id="schedTab" style="display:none;">
    <div class="stuHead">
      <span class="back" onclick="hpStuBack()">← 返回</span>
      <span class="stuTit">当前课表</span>
      <span style="flex:1"></span>
      <span class="pHome" onclick="hpHome()">🏠 主页</span>
    </div>
    <div class="stuScroll"><div id="schedBody"></div></div>
  </div>

  <!-- 班级座位表 -->
  <div id="seatTab" style="display:none;">
    <div class="stuHead">
      <span class="back" onclick="hpStuBack()">← 返回</span>
      <span class="stuTit">班级座位表</span>
      <span style="flex:1"></span>
      <span class="pHome" onclick="hpHome()">🏠 主页</span>
    </div>
    <div class="stuScroll"><div id="seatBody"></div></div>
  </div>

  <!-- 关系账本（手动为主 + 一键 AI 结算；写进同步世界书「新中市·关系账本」） -->
  <div id="relTab" style="display:none;">
    <div class="stuHead">
      <span class="back" onclick="hpStuBack()">← 返回</span>
      <span class="stuTit">关系账本</span>
      <span style="flex:1"></span>
      <span class="headFb feedback" id="relFeedback"></span>
      <span class="pHome" onclick="hpHome()">🏠 主页</span>
    </div>
    <div class="stuScroll">
      <div id="relBody"></div>
      <div class="relForm" id="relFormBox">
        <div class="relFormTit" id="relFormTit">添加关系人</div>
        <input id="relName" placeholder="角色名（如 绫羽）">
        <input id="relTag" placeholder="标签（如 夫妻实习对象 · 同班）">
        <input id="relRecent" placeholder="最近事件（如 一起在图书馆复习）">
        <div class="relBtns">
          <button class="stuBtn" id="relSaveBtn" onclick="hpRelSaveForm()">💾 保存</button>
          <button class="stuBtn ghost" id="relCancelBtn" onclick="hpRelCancelEdit()" style="display:none">取消编辑</button>
        </div>
        <div class="relBtns">
          <button class="stuBtn ghost" onclick="hpRelExtract()">👥 从最近 5 条回复提取角色</button>
        </div>
      </div>
    </div>
  </div>

  <!-- 校准玩家角色（写入世界书「user设定（别动！）」） -->
  <div class="modalBg" id="tOvModal">
    <div class="modal">
      <h4 id="tOvTitle">选择任课老师</h4>
      <div class="tOvNow" id="tOvNow"></div>
      <div class="tOvList" id="tOvList"></div>
      <div class="mrow"><button class="cancel" onclick="hpTOvClose()">取消</button></div>
    </div>
  </div>
  <div class="modalBg" id="stuCalModal">
    <div class="modal">
      <h4>📌 校准玩家角色</h4>
      <div class="calCalHint">确认后**覆盖写入**世界书「user设定（别动！）」，作为身份卡的判定依据。开始新聊天时会自动清空。</div>
      <input id="stuCalName" placeholder="角色名称（如 绫羽）">
      <div class="calGrid">
        <label><span>种族</span><input id="stuCalRace" placeholder="人类"></label>
        <label><span>性别</span><input id="stuCalGender" placeholder="女"></label>
        <label><span>年龄</span><input id="stuCalAge" placeholder="16"></label>
        <label><span>职业</span><input id="stuCalJob" placeholder="学生"></label>
      </div>
      <textarea id="stuCalInfo" placeholder="其他信息，可自由书写。例如：&#10;高一C班&#10;社团：轻音部&#10;外貌：黑长直，常戴发带"></textarea>
      <div class="mrow"><button class="cancel" onclick="hpStuCalClose()">取消</button><button class="send" onclick="hpStuCalSave()">确认</button></div>
    </div>
  </div>
</div>


<!-- ══════ 内置 SNS（四视图：feed/profile/dm/group） ══════ -->
<div class="phone" id="snsTab" style="display:none;">
  <div class="pStatus"><span>💬 SNS</span><span class="pHome" onclick="hpOpenContacts()" style="cursor:pointer;">📇 通讯录</span><span class="pHome" onclick="hpHome()" style="cursor:pointer;">🏠 主页</span></div>

  <!-- ▍视图A：信息流（默认显示） -->
  <div id="feed">
    <div class="topbar"><span class="brand">X站</span> <span class="small">关注页 · [SNS]</span><input id="feedSearch" class="searchBox" placeholder="搜角色名跳主页" onkeydown="if(event.key==='Enter')searchProfile()"><button class="send mini" onclick="searchProfile()">查找</button><button class="grpBtn" onclick="openGrpModal()">💬 创建群聊</button></div>
    <div class="feedBody">
      <div id="feedCards"></div>
      <div class="hint">（操作：点发布者昵称看主页 ｜ 点 💬 评论按钮或评论者网名进私信 ｜ 输入「私信 @网名（真名）」｜「回复 @网名」｜「发帖」）</div>
      <div class="pageBar"><button class="pageBtn" id="feedPrevBtn" onclick="feedPrev()" disabled>‹ 上一页</button><span class="pageInfo" id="feedPageInfo">第 1 页</span><button class="pageBtn" id="feedNextBtn" onclick="feedNext()">下一页 ›</button></div>
