// 所有页都是 .phone{display:flex;flex-direction:column} 容器：**每个都要设成 flex**。
// 漏掉哪个，那个页就退化成 block —— 内部的 .pApps/.musicList{flex:1} 全部失效
//（主页宫格不占满、Dock 不吸底；音乐列表不内部滚动）。别再用白名单逐个列。
function hpShowTab(id){
  for(var i=0;i<HP_TABS.length;i++){
    var e=document.getElementById(HP_TABS[i]);
    if(!e) continue;
    e.style.display=(HP_TABS[i]===id)?'flex':'none';
  }
}
function hpHome(){ hpShowTab('phoneHome'); hpSyncTime(); }
function hpOpenHypno(){ hpShowTab('hpApp'); hpShow('mainTab'); }
function hpOpenDial(){
  hpShowTab('dialTab');
  var st=document.getElementById('pClock'), dt=document.getElementById('dialTime');
  if(dt&&st)dt.textContent=st.textContent;
  var inp=document.getElementById('dialName'); if(inp)inp.value='';
  hpLoadCallLog();
}
// 通话记录列表：本地缓存（本次会话即时可见）+ 聊天历史（跨重载恢复），两条路合并
var hpCallLogLocal=[];
function hpRenderCallLog(items){
  var list=document.getElementById('callLogList'); if(!list) return;
  list.innerHTML='';
  if(!items.length){
    var em=document.createElement('div'); em.className='callLogEmpty'; em.textContent='暂无通话记录，拨一通电话试试';
    list.appendChild(em);
    return;
  }
  for(var j=0;j<items.length;j++){
    (function(it){
      var row=document.createElement('div'); row.className='callLogRow';
      var ic=document.createElement('span'); ic.className='clIcon'; ic.textContent='📞';
      var nm=document.createElement('span'); nm.className='clName'; nm.textContent=it.name;
      var tm=document.createElement('span'); tm.className='clTime'; tm.textContent=it.time;
      row.appendChild(ic); row.appendChild(nm); row.appendChild(tm);
      row.onclick=function(){ hpRedial(it.name, it.real); };
      list.appendChild(row);
    })(items[j]);
  }
}
function hpLoadCallLog(){
  var list=document.getElementById('callLogList'); if(!list) return;
  hpRenderCallLog(hpCallLogLocal.slice().reverse().slice(0,20));
  hpReadMessages().then(function(msgs){
    var arr=Array.isArray(msgs)?msgs:[];
    var remote=[];
    for(var i=arr.length-1;i>=0 && remote.length<20;i--){
      var m=arr[i]; if(!m||typeof m!=='object') continue;
      var txt=m.mes||''; if(typeof txt!=='string'||!txt) continue;
      var cc=txt.match(/^【通话记录】@([^\s]+)\s+(\d{1,2}:\d{2})/);
      if(cc) remote.push({name:cc[1], time:cc[2]});
    }
    var local=hpCallLogLocal.slice().reverse();
    var seen={}, merged=[];
    for(var a=0;a<local.length;a++){ seen[local[a].name+'|'+local[a].time]=1; merged.push(local[a]); }
    for(var b=0;b<remote.length;b++){
      var k=remote[b].name+'|'+remote[b].time;
      if(!seen[k]){ seen[k]=1; merged.push(remote[b]); }
    }
    if(merged.length) hpRenderCallLog(merged.slice(0,20));
  }).catch(function(){});
}
// 通话记录 = **私聊会话列表**（不是真实通话、也不是"再拨一次"）：
// 点进去只做一件事 —— 打开这段私聊并恢复历史。绝不在这里写新的通话记录或画「拨出」行，
// 否则每点一次就多一条记录（用户报过）。
function hpRedial(name, real){
  name=String(name||'').trim(); if(!name) return;
  hpShowTab('snsTab');
  openDM(name, real||name);          // 走 openDM 的默认恢复（内部会 hpRestoreDM）
}
// 只走 API 的读取：app 用 refresh:'none' 写进聊天的消息不在 DOM 里，
// 私信页/通话记录这类「刚写完就要读回来」的场景必须走 API，否则读到的还是旧内容。
var hpReadMsSrc='';   // 本次内容是从哪条通道读到的（诊断用：私信页显示不出记录时看这个）
// 酒馆助手 getChatMessages 返回的是 {role, message}：**没有 is_user，正文在 message 里**；
// 而 app 内部一律按 {mes, is_user} 读（hpLastUserInputs / hpDmParseRows / hpEnsureCallLog …），
// 于是只要读取走 API 通道，这些地方全部落空（身份卡认不出当前角色、私信页空白、
// 通话记录判重永不命中）。在唯一的读取出口补齐字段，别再让每个调用方各猜一套。
function hpNormMsg(m){
  if(!m || typeof m!=='object') return m;
  if(m.mes==null && typeof m.message==='string') m.mes=m.message;
  if(m.mes==null && typeof m.content==='string') m.mes=m.content;
  if(m.is_user==null) m.is_user=(m.role==='user');
  return m;
}
function hpReadMessagesApi(){
  var dom=null;
  // range 必须是 string|number：传 null 每次都会失败，再退回 DOM 就读不到刚用
  // refresh:'none' 写进来的消息（私信页空白就是这么来的）。
  var calls=[
    // hide_state:'all' 显式带上：app 写的纯 UI/元数据消息是隐藏楼层（is_hidden），
    // 不显式要就可能读不到，私信记录/通话记录就恢复不出来。带参数的放前面，不支持时自动退回下面的旧写法。
    function(){ return getChatMessages('0-{{lastMessageId}}',{hide_state:'all'}); },
    function(){ return getChatMessages('0-{{lastMessageId}}'); },
    function(){ return getChatMessages('0-{{lastMessageId}}',{}); },
    function(){ return getChatMessages('0-{last}'); },
    function(){ return getChatMessages(-1,{hide_state:'all'}); },
    function(){ return getChatMessages(-1); }
  ];
  var i=0;
  hpReadMsSrc='';
  function next(){
    if(i>=calls.length){
      // API 全失败时：先试旧版全局 chat（它含 refresh:'none' 写的消息），最后才退回 DOM
      var c=null; try{ var p=window.parent; c=(p&&p.chat)||null; }catch(e){ c=null; }
      if(c && c.length){ hpReadMsSrc='parent.chat'; return Promise.resolve(c); }
      var d=hpReadChatDomAll();
      hpReadMsSrc='dom';                 // DOM 里没有 refresh:'none' 写的消息 → 刚写的读不回来
      return Promise.resolve(d||[]);
    }
    var idx=i, fn=calls[i++], pr;
    try{ pr=fn(); }catch(e){ return next(); }
    return Promise.resolve(pr).then(function(msgs){
      if(Array.isArray(msgs) && msgs.length){ hpReadMsSrc='api#'+(idx+1); return msgs; }
      return next();
    }, function(){ return next(); });
  }
  // 唯一出口：把 API 形状（role/message）补齐成 app 内部认的 {mes, is_user}
  return next().then(function(msgs){
    if(!Array.isArray(msgs)) return msgs;
    for(var z=0;z<msgs.length;z++) hpNormMsg(msgs[z]);
    return msgs;
  });
}
// 进私信页后，如果这段对话里有内容（对方或玩家发过消息/有过通话），补一条通话记录到电话页。
// 只在"一条记录都没有"时补，避免每次点进去都多一行。
function hpEnsureCallLog(name, real){
  name=String(name||'').trim(); if(!name) return;
  for(var i=0;i<hpCallLogLocal.length;i++){ if(hpCallLogLocal[i].name===name) return; }
  hpReadMessagesApi().then(function(msgs){
    var arr=Array.isArray(msgs)?msgs:[], has=false;
    for(var j=0;j<arr.length;j++){
      var m=arr[j]; if(!m||typeof m!=='object') continue;
      var cc=String(m.mes||'').match(/^【通话记录】@([^\s]+)\s+/);
      if(cc && (cc[1]===name)){ has=true; break; }
    }
    if(has) return;
    var hh='', mm='';
    if(hpStoryDate && hpStoryDate.time){ var t=hpStoryDate.time.match(/(\d{1,2}:\d{2})/); if(t) hh=t[1].slice(0,2), mm=t[1].slice(3,5); }
    if(!hh){ var now=new Date(); hh=('0'+now.getHours()).slice(-2); mm=('0'+now.getMinutes()).slice(-2); }
    if(hpLogCall(name, hh, mm, real)){          // 写进聊天 + 本地缓存 → 电话页立刻能看到
      var list=document.getElementById('callLogList');
      if(list && document.getElementById('dialTab') && document.getElementById('dialTab').style.display!=='none') hpLoadCallLog();
    }
  }).catch(function(){});
}
// ——— 统一读取聊天消息（顺序：① TavernHelper API 多签名 → ② 旧版全局 chat → ③ 主页面 DOM 直读）———
// **必须 API 优先**：app 用 refresh:'none' 写进聊天的消息（通话记录/日历标记/私信）不在 DOM 里，
// 只要酒馆页面上有别的楼层，DOM 优先就会返回"缺这些行"的残缺列表 —— 这个坑复发过三次。
// 不同酒馆版本对 getChatMessages 的 range/options 支持不一致，单用某个签名会静默返回空。
var hpReadWarned=false;
function hpReadMessages(){
  return hpReadMessagesApi().then(function(msgs){
    if(msgs && msgs.length) return msgs;
    // 聊天里明明有楼层却一条都读不出来 → 是真的失败（不是空聊天），要让人看得见
    var n=0; try{ var p=window.parent; n=((p&&p.chat)||[]).length; }catch(e){ n=0; }
    if(n>0 && !hpReadWarned){ hpReadWarned=true; hpWarn('读取聊天记录失败：'+n+' 层读不到内容（读取通道：'+(hpReadMsSrc||'全部失败')+'），角色判定/私信记录会不准'); }
    return msgs||[];
  });
}
// ——— 电话拨打：跳转 SNS 私聊页 + 从聊天历史恢复通话/私信记录 + 记下本次通话 ———
var CALL_PREFIX='【通话记录】', hpLastCallKey='';
function hpDial(){
  var inp=document.getElementById('dialName'); var name=inp?inp.value.trim():'';
  if(!name) return;
  hpShowTab('snsTab');
  openDM(name, name, true);        // 拨号自己会恢复历史并在其后补通话行，跳过 openDM 的自动恢复，避免两次恢复抢渲染
  var now=new Date();
  var hm=hpStoryHHMM().split(':');
  var hh=hm[0], mm=hm[1];       // 拨号/通话记录也用剧情时间，别再写系统时间
  var timeStr=hh+':'+mm;
  hpRestoreDM(name, name).then(function(stale){
    // 通话记录照样写（拨号确实发生了），但页面已经切走时不要把这行画到别人的私信页里
    if(hpLogCall(name, hh, mm) && stale!=='stale') hpAddCallRow(name, timeStr);
  });
}
// 把本次拨号写入聊天历史，使下次拨打能恢复出通话记录（同一人同一分钟内只记一条，防连点刷屏）
// 返回是否真的记录了（去重时返回 false，界面据此保持一致）
// real 一并存下来：通话记录点进去要用 (网名, 真名) 这对才恢复得全（标记里两个名字都可能出现）
function hpLogCall(name, hh, mm, real){
  var key=name+'|'+hh+':'+mm;
  if(key===hpLastCallKey) return false;
  hpLastCallKey=key;
  hpCallLogLocal.push({name:name, real:real||name, time:hh+':'+mm});
  var msg=CALL_PREFIX+'@'+name+' '+hh+':'+mm;
  createChatMessages([{role:'user',message:msg,content:msg}],{refresh:'none'});
  return true;
}
function hpAddCallRow(name, timeStr){
  var body=document.getElementById('dmBody'); if(!body)return;
  var st=document.getElementById('dmStart'); if(st)st.style.display='none';
  var d=document.createElement('div');
  d.className='callRow';
  d.textContent='📞 '+name+' · '+timeStr+' 拨出';
  body.appendChild(d);
  body.scrollTop=body.scrollHeight;
}
// 从聊天记录里解析出「这一段私聊」的气泡行。SNS 私信与论坛私信共用同一份解析，
// 免得两处规则各自漂移 —— 论坛私信此前就是因为没有解析方而完全恢复不出历史。
function hpDmParseRows(arr, account, real){
  var rows=[], lastWasDM=false;
  // 正文若是一条「媒体记录」→ 变成媒体行（恢复时画成可查看/可播放的气泡，而不是一串文字）
  var pushRow=function(side,body,time){
    var md=hpMediaOfText(body);
    if(md) rows.push({side:side, kind:md.kind, data:md.data, time:time||''});
    else rows.push({side:side, text:body, time:time||''});
  };
  for(var i=0;i<arr.length;i++){
    var m=arr[i];
    if(!m||typeof m!=='object') continue;
    var txt=m.mes||'';
    if(typeof txt!=='string'||!txt) continue;
    var isAssistant=(m.is_user===false)||(m.role==='assistant');
    var cc=txt.match(/^【通话记录】@([^\s]+)\s+(\d{1,2}:\d{2})/);
    // 时间戳可选（形如「[16:15]」）：新写的私信会带，老记录没有 → 两种情况都要能解析
    var mm=txt.match(/^私信 @([^（(]+)[（(]([^）)]*)[）)]\s*(?:[\[［](\d{1,2}:\d{2})[\]］])?\s*：/);
    var om=txt.match(/^【对方私信】@([^（(]+)[（(]([^）)]*)[）)]\s*(?:[\[［](\d{1,2}:\d{2})[\]］])?\s*：/);   // 对方发来的（通知推送/私信回复写的），气泡靠左
    if(om && (om[1]===account||om[2]===real||om[1]===real||om[2]===account)){
      pushRow('L',txt.slice(om[0].length),om[3]);
      lastWasDM=false;
    } else if(cc && (cc[1]===account||cc[1]===real)){
      rows.push({type:'call', name:cc[1], time:cc[2]});
      lastWasDM=false;
    } else if(mm && (mm[1]===account||mm[2]===real||mm[1]===real||mm[2]===account)){
      pushRow('R',txt.slice(mm[0].length),mm[3]);
      lastWasDM=true;
    } else if(isAssistant && lastWasDM){
      var t=txt.replace(/<swl>[\s\S]*?<\/swl>/g,'').replace(/<\/?swl>/g,'').trim();
      if(t) rows.push({side:'L',text:t});
      lastWasDM=false;
    } else {
      lastWasDM=false;
    }
  }
  return rows;
}
function hpRestoreDM(account,real){
  var body=document.getElementById('dmBody'); if(!body)return Promise.resolve();
  return hpReadMessagesApi().then(function(msgs){
    // 期间已经切到别的会话 → 返回 'stale'（不是 false）：调用方据此区分
    // 「没历史」和「这次恢复作废」，别把 A 的内容画进 B 的页面
    if(dmAccount!==account) return 'stale';
    var rows=hpDmParseRows(Array.isArray(msgs)?msgs:[], account, real);
    // 记下「对方最后一条消息的时间」：玩家回复时据此算间隔，角色就能抱怨/追问"怎么这么久才回"
    hpDmInboundAt='';
    for(var wi=0;wi<rows.length;wi++){ if(rows[wi].side==='L' && rows[wi].time) hpDmInboundAt=rows[wi].time; }
    // 补充本地通话记录：通话记录用 refresh:'none' 写入，不渲染进酒馆 DOM，跨路径读取可能拿不到，
    // 本次会话内用本地缓存兜底（去重后追加）
    var haveCall={}, lc;
    for(var w=0;w<rows.length;w++){ if(rows[w].type==='call') haveCall[rows[w].name+'|'+rows[w].time]=1; }
    for(var q=0;q<hpCallLogLocal.length;q++){
      lc=hpCallLogLocal[q];
      if(lc.name!==account && lc.name!==real) continue;
      if(haveCall[lc.name+'|'+lc.time]) continue;
      haveCall[lc.name+'|'+lc.time]=1;
      rows.push({type:'call', name:lc.name, time:lc.time});
    }
    body.innerHTML='';
    if(rows.length) hpEnsureCallLog(account, real);      // 有内容 → 电话页补一条通话记录（不管从哪跳进来的）
    if(!rows.length){
      // 读不全时把通道名显示出来（这个坑复发过多次：只有 DOM 通道就必然读不到刚写的私信）
      var src=hpReadMsSrc||'失败', viaApi=(src.indexOf('api#')===0);
      body.innerHTML='<div id="dmStart" style="color:#9aa0a6;font-size:12px;text-align:center;margin:4px 0;">你已进入与 @'+hpEsc(account)+'（'+hpEsc(real)+'）的通话，说点什么吧</div>'
        + (viaApi?'':'<div style="color:#c08a52;font-size:11px;text-align:center;margin:6px 0;line-height:1.5;">⚠ 私信记录读取通道：'+hpEsc(src)+'（非 API）<br>此前写过的私信可能读不回来</div>');
    } else {
      for(var j=0;j<rows.length;j++){
        if(rows[j].type==='call') hpAddCallRow(rows[j].name, rows[j].time);
        else if(rows[j].kind){
          var mp3=hpPushMedia(rows[j].kind, rows[j].data);
          addBubbleMedia(rows[j].side, mp3.kind, mp3.data, mp3.idx, rows[j].time);
        }
        else addBubble(rows[j].side, rows[j].text, rows[j].time);
      }
    }
    body.scrollTop=body.scrollHeight;
    return rows.length>0;
  }).catch(function(e){ hpWarn('私信/通话记录恢复失败：'+((e&&e.message)||e)); return false; });
}
// 论坛私信页的恢复：同一份解析，渲染到 fdmBody、用 fAddBubble（论坛页没有电话/通话记录）
function fRestoreDM(account,real){
  var body=document.getElementById('fdmBody'); if(!body)return Promise.resolve();
  return hpReadMessagesApi().then(function(msgs){
    if(fdmAccount!==account) return 'stale';
    var rows=hpDmParseRows(Array.isArray(msgs)?msgs:[], account, real);
    // 记下「对方最后一条消息的时间」：玩家回复时据此算间隔，角色就能抱怨/追问"怎么这么久才回"
    hpDmInboundAt='';
    for(var wi=0;wi<rows.length;wi++){ if(rows[wi].side==='L' && rows[wi].time) hpDmInboundAt=rows[wi].time; }
    body.innerHTML='';
    if(!rows.length){
      body.innerHTML='<div id="fdmStart" style="color:#8aa2bd;font-size:12px;text-align:center;margin:4px 0;">你已进入与 @'+hpEsc(account)+'（'+hpEsc(real)+'）的私信，说点什么吧</div>';
    } else {
      for(var j=0;j<rows.length;j++){
        if(rows[j].type==='call') continue;      // 论坛私信不显示通话记录
        if(rows[j].kind){
          var fm3=hpPushMedia(rows[j].kind, rows[j].data);
          fAddBubbleMedia(rows[j].side, fm3.kind, fm3.data, fm3.idx, rows[j].time);
        }
        else fAddBubble(rows[j].side, rows[j].text, rows[j].time);
      }
    }
    body.scrollTop=body.scrollHeight;
    return rows.length>0;
  }).catch(function(e){ hpWarn('论坛私信恢复失败：'+((e&&e.message)||e)); return false; });
}
// ——— 全局 shim：指向酒馆助手 API（真实酒馆 window.parent.TavernHelper；demo 由第二 script mock 覆盖）———
function generateRaw(config){ var TH=window.parent.TavernHelper; if(TH&&TH.generateRaw){ return TH.generateRaw(config); } return Promise.reject(new Error('generateRaw unavailable')); }
// 消息分三类处理（见 createChatMessages）：
//  · 纯 UI 导航（翻看/回看/打开）：**没有任何代码读回**，写进聊天只会污染上下文、并在页面上留小字 → 直接不写
//  · 元数据（通话记录/日历标记/剧情日期校准）：app 自己要读回来恢复，必须留档；打 is_hidden 不进模型
//  · 私信/群聊/论坛私信正文、拍照动作、app 生成的剧情回复：剧情事实，保持可见
var HP_DROP_PREFIX=/^(?:翻看|回看|打开)/;
var HP_HIDDEN_PREFIX=/^(?:【通话记录】|【日历标记】|【剧情日期校准】)/;
function createChatMessages(msgs,opts){
  // 写入前统一剥掉模型漏出来的推理过程与内心独白：内部组装路径不带酒馆的 reasoning 剥离，
  // 模型偶尔会把 "Thinking Process: …" 或 <swl>/🧠 独白整段当正文吐出来（后者该留在气泡折叠里）。
  var out=[];
  if(msgs && msgs.forEach){ msgs.forEach(function(m){
    if(!m || typeof m!=='object') return;
    var raw=(m.message!=null?m.message:m.content);
    if(m.role==='assistant'){
      var c=hpDropThought(hpStripReasoning(raw));
      m.message=c; m.content=c;
      out.push(m);
      return;
    }
    var txt=String(raw||'').trim();
    if(HP_DROP_PREFIX.test(txt)) return;                  // 纯 UI 导航：不写
    // is_hidden → 酒馆映射成 is_system → 拼 prompt 时被 chat.filter(x=>!x.is_system) 滤掉
    //（见酒馆 script.js 的 getCoreChat）。app 自己仍读得到：getChatMessages 默认 hide_state:'all'
    if(HP_HIDDEN_PREFIX.test(txt)) m.is_hidden=true;
    out.push(m);
  }); }
  if(!out.length) return Promise.resolve();
  msgs=out;
  var TH=window.parent.TavernHelper;
