function hpCtxDiagRender(){
  var el=document.getElementById('ctxDiag'); if(!el) return;
  var pd=null; try{ pd=window.parent; }catch(e){}
  if(!pd || !pd.document){ el.textContent='（演示模式：不在酒馆页面里）'; return; }
  // ⚠ 不要用 window.parent.chat：酒馆没把聊天数组挂到 window 上，而 HTML 的「命名元素访问」
  // 会让 window.chat 变成 <div id="chat"> 那个 DOM 元素（有值、但没有 length）——
  // 实测就打印成了「undefined 层」。数组要从 SillyTavern.getContext().chat 拿。
  var arrLen=null, last='(读不到)';
  try{
    var ctx=(pd.SillyTavern && pd.SillyTavern.getContext) ? pd.SillyTavern.getContext() : null;
    var arr=ctx && ctx.chat;
    if(Array.isArray(arr)){
      arrLen=arr.length;
      var m=arr[arr.length-1];
      if(m) last=(m.is_user?'玩家：':'AI：')+String(m.mes||'').replace(/\s+/g,' ').slice(0,36);
    }
  }catch(e){}
  if(arrLen===null){   // 退一步：问酒馆助手要最后一条楼层号
    try{ var TH=pd.TavernHelper; if(TH && TH.getLastMessageId){ var lid=TH.getLastMessageId();
      if(typeof lid==='number' && lid>=-1) arrLen=lid+1; } }catch(e){}
  }
  var domLen=-1; try{ domLen=pd.document.querySelectorAll('#chat .mes').length; }catch(e){}
  var sending=null; try{ if(typeof pd.is_send_press!=='undefined') sending=!!pd.is_send_press; }catch(e){}
  var stopShown=false;
  try{ var sb=pd.document.getElementById('mes_stop'); stopShown=!!(sb && sb.getClientRects && sb.getClientRects().length); }catch(e){}
  var out=[];
  out.push('聊天数组：'+(arrLen===null?'读不到':arrLen+' 层'));
  out.push('页面已渲染：'+(domLen<0?'读取失败':domLen+' 层'));
  if(arrLen!==null && domLen>=0) out.push('差值：'+(arrLen-domLen)+(arrLen>domLen?'（页面少于数组**很常见，不等于出问题**：① cocktail 的「聊天渲染优化」默认只渲染首屏 20 条，往上滚会加载更多；② app 写的消息本来就不渲染）':' ✓ 两边一致'));
  out.push('末尾消息：'+last);
  out.push('生成状态：'+((sending===true||stopShown)?'⚠ 正在生成中（此时点发送会被静默忽略）':'空闲 ✓'));
  out.push('最近酒馆报错：'+(hpErrLog.length?'':'（无）'));
  for(var q=0;q<hpErrLog.length;q++) out.push('　· '+hpErrLog[q]);
  el.innerHTML=out.map(function(s){ return hpEsc(s); }).join('<br>');
}
