      hpLaunchBusy=true;
      var ps=[];
      ps.push({ role:'system', content:'【拍摄方式·固定不变】这张照片一定是「'+how+'」拍出来的。拍摄前的动作只影响画面里人物的状态与姿态，绝不会改变拍摄方式：不是别人代拍、不是相机/相机架拍、不是第三人称视角。'+(selfShot?'画面是前置摄像头视角（自拍角度），'+actor+' 本人是画面主角。':'画面是后置摄像头视角，'+actor+' 本人通常不在画面里。')+'【无闪光灯】这台相机不使用闪光灯：画面光线一律是环境光（自然光/室内灯光），禁止出现闪光灯亮光、补光、被闪光晃到之类的描写。' });
      if(selfShot){
        ps.push({ role:'system', content:'【自拍照片描写】'+actor+' 刚刚用手机前置摄像头拍了一张自拍。'+actPart+'你要输出的文字，就是这张自拍照片的画面内容本身：镜头对着 '+actor+' 自己，通常是脸部特写或上半身、手持手机的角度，可能带些仰角、俯角或歪头的随意感。请通读本聊天最近剧情，判定 '+actor+' 此刻的样貌、表情、神态、发型、衣着、所处环境与光线，把「快门定格的那一帧自拍」具体描绘出来，像照片一样静止、可观看。' });
      } else {
        ps.push({ role:'system', content:'【外拍照片描写】'+actor+' 刚刚用手机后置摄像头拍了一张照片。'+actPart+'你要输出的文字，就是这张照片的画面内容本身：镜头背对着 '+actor+'，拍下的是 '+actor+' 眼前看到的世界（'+actor+' 本人通常不出现在画面里，除非镜面反射）。请通读本聊天最近剧情，判定此刻的时间、地点、天气、光线、环境、在场人物与他们的状态，把「快门定格的那一帧」具体描绘出来，像照片一样静止、可观看：画面里有什么、人物在做什么、光线氛围如何，都要交代清楚。' });
      }
      ps.push({ role:'system', content:'【照片是剧情事实】这张照片与它的内容属于剧情中真实存在的事实：之后剧情若提及「之前拍的那张照片」「照片里的内容」「相机里的照片」，指的就是你这一段描写。请让描写足够具体、能独立成图，方便之后被引用。' });
      ps.push({ role:'system', content:'【输出格式】只输出照片画面内容的纯文本描写，严禁 markdown 代码围栏、严禁 HTML 标签、严禁清单/编号/卡片/面板结构、严禁前缀说明文字、严禁写「我拍了一张照片」之类旁白。直接输出照片画面本身。画面是静默拍下的：不要写快门声（"咔嚓"之类）、不要写闪光灯亮光。' });
      var order=['world_info_before','persona_description','char_description','char_personality','scenario','world_info_after'].concat(ps).concat(['dialogue_examples','chat_history','user_input']);
      TH.generateRaw({ user_input: action, ordered_prompts: order })
      .then(function(reply){
        if(reply&&typeof reply==='object'&&reply.content!=null)reply=reply.content;
        var text=hpCleanText(reply);
        galleryPush((selfShot?'【自拍】':'【外拍】')+text);
        hpGallerySave();
        hpSendPhotoAction(act, selfShot);          // 送进酒馆：剧情里给"拍照"这个动作一个回应
