    }
  } else {
    var mockText=selfShot?('【演示·自拍】镜头怼近，'+actor+' 微微歪头，嘴角挂着点笑，光线把发梢照得透亮。'):'【演示·外拍】午后教室的光线斜斜地照进来，窗边的座位空着，课本摊在桌上，空气里浮着淡淡的尘埃。';
    galleryPush((selfShot?'【自拍】':'【外拍】')+mockText);
