// 拍照后把「动作」送进酒馆 → 触发一次正常生成，让剧情真的输出一段（拍摄前的互动 + 周围角色的反应）。
// ⚠ act 必须传进来并写进提示词：以前这里没收 act，动作串写死成"举起手机按下快门"，
//    于是玩家输入的「让角色比耶」只出现在照片描写里、剧情里完全没发生（用户报过）。
// ⚠ 这段文本刻意避开相册条目的关键词（相册/看照片/自拍照片/镜头…），
//    否则会把相册条目激活，AI 就提前看到照片内容了。
function hpSendPhotoAction(act, selfShot){
  if(!hpIsTavern()) return;
  var who=hpActorVal()||'主角';
  act=String(act||'').trim();
  var action='（小手机·相机）'+(act?('拍摄前 '+who+' '+act+'，随后 '):'')
    + who + (selfShot?(' 举起手机，用前置摄像头对着自己，无声地拍下一张自拍。'):(' 举起手机，用后置摄像头对着眼前，无声地拍下一张照片。'));
  var sys={ role:'system', content:'【先演出拍摄前的动作，再写镜头对准之后的当下】'
    + (act?('主角在按下快门前做了这个动作：'+act+'。**这一段必须在剧情里真的发生** —— 相关角色要做出对应的姿态与反应，不能跳过、更不能只写"主角掏出手机拍了一张"。'):'')
    + '然后把快门前后这一刻写下去：谁注意到了、有没有搭话/制止/起哄，在场角色当下的神态动作。'
    + '【静默拍摄】这部手机拍照是**完全静默**的：不要写快门声（"咔嚓"之类一律不许）、不要写闪光灯/补光/亮光、不要写震动或提示音；也不要用"被快门声惊到"之类的反应做剧情 —— 除非玩家在拍摄前的动作里明确要求出声或开闪光灯。'
    + '**不要描写照片画面内容**（照片拍到了什么只有主角自己知道），也不要说明摄像头朝向 —— 除非剧情里对方确实看到了手机屏幕。'
    + '只输出一段纯文本剧情，不要输出面板/清单/编号/代码围栏。' };
  var TH=window.parent.TavernHelper;
  // 走 hpGenerateReply：内部生成，只把 AI 的回复落进聊天（不会留下"玩家发的那条指令"）
  if(TH && TH.generateRaw){ hpGenerateReply(action, [sys, hpNarrationRule()], null, function(e){ hpWarn('拍照的剧情回应生成失败：'+((e&&e.message)||e)); }); }
  else { hpSendToTavern(action); }        // 极少数没有生成能力的场景才退回输入栏
}
