  var totalPages=Math.max(1, Math.ceil(galleryPhotos.length/galleryPageSize));
  if(galleryPageNo>=totalPages)galleryPageNo=totalPages-1;
  if(galleryPageNo<0)galleryPageNo=0;
  var start=galleryPageNo*galleryPageSize;
  var page=galleryPhotos.slice(start, start+galleryPageSize);
  var h='';
  for(var i=0;i<page.length;i++){
    var idx=start+i+1;
    h+='<div class="galCard" onclick="openGalleryPhoto('+idx+')"><span class="galIdx">#'+idx+'</span><span class="galText">'+hpEsc(page[i])+'</span></div>';
  }
  body.innerHTML=h;
  var prev=document.getElementById('galPrev'), next=document.getElementById('galNext'), info=document.getElementById('galPageInfo');
  if(prev)prev.disabled=(galleryPageNo===0);
  if(next)next.disabled=(galleryPageNo>=totalPages-1);
  if(info)info.textContent='第 '+(galleryPageNo+1)+' / '+totalPages+' 页';
}
