    ];
    var order=['world_info_before','persona_description','char_description','char_personality','scenario','world_info_after'].concat(ps).concat(['chat_history','user_input']);
    return TH.generateRaw({ user_input:'【请生成今天的走廊布告板。】', ordered_prompts: order });
  }).then(function(reply){
