    //（尤其从拍照/相册进来）恢复时页面还是空的 → 必须在这里兜一次，否则电话页永远没有记录。
    .then(function(){ hpEnsureCallLog(account, real); })
    .catch(function(e){ setTyping(false); console.error(e); hpWarn('生成失败（AI 未返回内容）：'+((e&&e.message)||e)); hpEnsureCallLog(account, real); });
