function renderPostContent(raw){
  var s=String(raw||'');
  var parts=s.split('====REPLIES====');
  // 正文也能带媒体：抽出来单独渲染成可查看/可播放的 chip（正文本身仍是纯文本，不解析 HTML）
  var bd=hpTextAndMedia((parts[0]||'').replace(/<swl>[\s\S]*?<\/swl>/g,'').replace(/<\/?swl>/g,'').trim());
  postContentText=bd.text;
  var el=document.getElementById('postContent');
  el.innerHTML='';
  el.textContent=bd.text||'（本帖无正文）';
  if(bd.media.length){
    var mb=document.createElement('div'); mb.className='postMediaChips';
    for(var bi=0;bi<bd.media.length;bi++) mb.appendChild(mediaChip(bd.media[bi].kind,bd.media[bi].data,bd.media[bi].idx));
    el.appendChild(mb);
  }
  var replyRaw=(parts[1]||'').trim();
  renderReplies(replyRaw);
  savePostCache();
}
function renderReplies(raw){
  var list=document.getElementById('replyList');
  var hint=document.getElementById('replyHint');
  list.innerHTML='';
  var replies=parseReplies(raw);
  if(replies.length){
    for(var i=0;i<replies.length;i++){
      addReply(replies[i].floor, replies[i].account, replies[i].real, replies[i].text, false, replies[i].media);
    }
    for(var fi=0;fi<replies.length;fi++){ if(replies[fi].floor>maxFloor) maxFloor=replies[fi].floor; }   // 取最大楼层，别依赖 AI 输出顺序
  }else{
    list.innerHTML='<div class="hint">还没有回复，来抢沙发吧～</div>';
    maxFloor=0;
  }
}
function parseReplies(raw){
  var replies=[];
  var lines=String(raw||'').split(/\r?\n+/);
  for(var i=0;i<lines.length;i++){
    var line=lines[i].trim();
    if(!line)continue;
    var m=line.match(/^(\d+)\s*楼\s*@?\s*(.+?)[:：]\s*([\s\S]*)$/);
    if(!m)continue;
    var floor=parseInt(m[1],10)||0;
    var namePart=m[2].trim();
    var content=m[3].trim();
    var nm=namePart.match(/^(.+?)\s*（\s*(.+?)\s*）\s*$/);
    var account=nm?nm[1].trim():namePart;
    var real=nm?nm[2].trim():namePart;
    var p=splitThought(content);
    var tm=hpTextAndMedia(p.text);   // 回帖也能带媒体（<photo>/<music>）
    replies.push({floor:floor,account:account,real:real,text:tm.text,thoughts:p.thoughts,media:tm.media});
  }
  return replies;
}
