function buildReplyHistory(){
  var rows=document.querySelectorAll('#replyList .reply');
  var lines=[];
  for(var i=0;i<rows.length;i++){
    var f=rows[i].querySelector('.rFloor');
    var n=rows[i].querySelector('.rName');
    var c=rows[i].querySelector('.rContent');
    var floor=f?f.textContent.trim().replace('楼',''):'';
    var nm=n?n.textContent.trim().replace(/^@/,''):'';
    var ct=c?c.textContent:'';
    var mrow=rows[i].querySelector('.replyMedia');
    var mt='';
    if(mrow){
      var chips=mrow.querySelectorAll('.mChip');
      var tags=[];
      for(var m=0;m<chips.length;m++){
        var tx=chips[m].querySelector('.mtxt');
        tags.push(tx?tx.textContent.trim():'媒体');
      }
      if(tags.length) mt='（含媒体：'+tags.join('、')+'）';
    }
    lines.push(floor+'楼 '+nm+'：'+ct+mt);
  }
  return lines.join('\n')||'（暂无回复）';
}
