function liveNext(){
  if(liveLoading)return;
  var page=livePage+1;
  if(livePageCache[page]){
    livePage=page;
    document.getElementById('liveCards').innerHTML=livePageCache[page];
    document.getElementById('livePageInfo').textContent='第 '+page+' 页';
    updateLivePageButtons();
    return;
  }
  if(liveEnd) return;
  if(livePageCache[1]===undefined)livePageCache[1]=document.getElementById('liveCards').innerHTML;
  liveLoading=true;
  document.getElementById('livePageInfo').textContent='加载第 '+page+' 页…';
  createChatMessages([{role:'user',message:'翻看X站直播首页第 '+page+' 页',content:'翻看X站直播首页第 '+page+' 页'}],{refresh:'none'})
    .then(function(){ return generateRaw(livePrompt(page)); })
    .then(function(reply){
      liveLoading=false;
      if(reply&&typeof reply==='object'&&reply.content)reply=reply.content;
      var ln2=renderLiveCards(reply);
      liveEnd=(ln2===0);
      if(!liveEnd) livePageCache[page]=document.getElementById('liveCards').innerHTML;
      livePage=page;
      document.getElementById('livePageInfo').textContent='第 '+page+' 页'+(liveEnd?' · 到底了':'');
      updateLivePageButtons();
    })
    .catch(function(e){ liveLoading=false; console.error(e); document.getElementById('livePageInfo').textContent='第 '+livePage+' 页（加载失败，请重试）'; });
}
