function renderLiveCards(raw){
  var liveCards=document.getElementById('liveCards');
  liveCards.innerHTML='';
  var tmp=document.createElement('div');
  // 动态/主页/帖子等 AI 内容里若带 <photo>/<music>，就地换成可查看/可播放的 chip（没有标记时是空操作）
  tmp.innerHTML=hpRenderInlineMedia(String(raw||'').replace(/<swl>[\s\S]*?<\/swl>/g,'').replace(/<\/?swl>/g,''));
  var cards=tmp.querySelectorAll('.card');
  if(cards.length){
    for(var i=0;i<cards.length;i++){
      var c=cards[i];
      if(!c.querySelector('.name')){
        var nb=c.querySelector('b');
        if(nb && !nb.className) nb.className='name';
      }
      liveCards.appendChild(c);
    }
  }else{
    var d=document.createElement('div');
    d.className='card';
    d.textContent=(tmp.textContent||'暂时没有更多直播了').replace(/\s+/g,' ').trim().slice(0,120);
    liveCards.appendChild(d);
  }
  return cards.length;                          // 0 = 到底了
}
function buildLiveCardsContext(){
  var out=[];
  for(var p=1;p<livePageCache.length;p++){
    if(!livePageCache[p])continue;
    var tmp=document.createElement('div');
    tmp.innerHTML=livePageCache[p];
    var cards=tmp.querySelectorAll('.card');
    for(var i=0;i<cards.length;i++){ out.push(cards[i].textContent.replace(/\s+/g,' ').trim()); }
  }
  return out.join('\n')||'（当前无直播推荐）';
}
