    .then(function(){
      return generateRaw({
        user_input:'【你以 '+real+'（@'+host+'）的身份，公开回应刚才这条弹幕。若此刻有其他观众跟风起哄，可先用 <danmu>内容</danmu> 生成 2~5 条观众弹幕；若这条弹幕让你改变动作/画面，先输出 <scene>新画面</scene>；再输出你的回应。别的不输出。】',
