function genFollower(kind){
  var pool;
  if(kind==='gift')pool=DANMU_POOL['打赏'];
  else if(kind==='bounty')pool=DANMU_POOL['悬赏'];
  else{
    var typeEl=document.getElementById('roomType');
    var cat=typeEl?typeEl.textContent.trim():'';
    pool=DANMU_POOL[cat]||DANMU_POOL['杂谈'];
  }
  var n=3+Math.floor(Math.random()*2);
  var arr=[],seen={},i,s;
  for(i=0;i<n;i++){
    s=pick(pool);
    if(seen[s])continue;
    seen[s]=1; arr.push(s);
  }
  return arr;
}
function genGiftFollower(isBounty){
  var n=1+Math.floor(Math.random()*2);
  var arr=[],i;
  for(i=0;i<n;i++){
    var amt=isBounty?pick([10000,10000,5000,20000]):pick([10,10,100,100,100,500,1000,1000,5000]);
    arr.push({ nick:pick(NICK), amount:amt,
      msg:((isBounty||Math.random()<.4)?pick(['好活','膜拜大佬','壕无人性','主播快接','老板大气']):'') });
  }
  return arr;
}
function scheduleFollow(danmus,gifts,finalFn){
  var steps=[];
  gifts.forEach(function(g){ steps.push(function(){ addGiftDanmu(g.nick,g.amount,g.msg); }); });
  danmus.forEach(function(t){ steps.push(function(){ addDanmu(t,'normal'); }); });
  steps.push(function(){ KEEP_TYPING=false; finalFn(); });
  KEEP_TYPING=true;
  var i=0;
  function next(){
    if(i>=steps.length)return;
    steps[i++]();
    if(i<steps.length)setTimeout(next,1300);
  }
  next();
}
function splitDanmu(raw){
  var list=[];
  var noTags=String(raw||'').replace(/<danmu>[\s\S]*?<\/danmu>/g,function(m){ list.push(m.replace(/<\/?danmu>/g,'').trim()); return ''; });
  noTags=noTags.replace(/<danmu>/g,'').replace(/<\/danmu>/g,'');
  return { danmus:list.filter(Boolean), text:noTags.trim() };
}
function splitScene(raw){
  var scene=null;
  var clean=String(raw||'').replace(/<scene>[\s\S]*?<\/scene>/g,function(m){ scene=m.replace(/<\/?scene>/g,'').trim(); return ''; });
  clean=clean.replace(/<scene>/g,'').replace(/<\/scene>/g,'');
  return { scene:scene, text:clean.trim() };
}
function buildLiveHistory(){
  var lines=[];
  var area=document.getElementById('dmArea');
  var rows=area?area.querySelectorAll('.sc,.anchorReply'):[];
  for(var i=0;i<rows.length;i++){
    var r=rows[i];
    var cls=String(r.className||'');
    if(cls.indexOf('anchorReply')>=0){
      lines.push('主播回应：'+r.textContent.replace(/^🎤\s*/,''));
    }else if(cls.indexOf('sc')>=0){
      var head=r.querySelector('.scHead');
      lines.push('打赏('+(head?head.textContent:'')+')');
      var body=r.querySelector('.scBody');
      if(body)lines.push('  留言：'+body.textContent);
      var warn=r.querySelector('.bountyWarn');
      if(warn)lines.push('  '+warn.textContent);
    }
  }
  var track=document.getElementById('danmuTrack');
  var dms=track?Array.prototype.slice.call(track.querySelectorAll('.flyDanmu')):[];
  var last=dms.slice(-12);
  for(var j=0;j<last.length;j++){
    var dd=last[j];
    var dc=String(dd.className||'');
    var dt=dd.textContent;
    if(dc.indexOf('mine')>=0)lines.push('当前角色：'+dt);
    else if(dc.indexOf('gift')>=0)lines.push('观众打赏：'+dt);
    else lines.push('观众：'+dt);
  }
  return lines.join('\n')||'（暂无历史，这是直播间第一条互动）';
}
