function splitThoughtLive(raw){
  var thoughts=[];
  var clean=hpStripReasoning(raw||'').replace(/<swl>[\s\S]*?<\/swl>/g,function(m){ thoughts.push(m.replace(/<\/?swl>/g,'').trim()); return ''; });
  clean=clean.replace(/<swl>/g,'').replace(/<\/swl>/g,'');
  return { thoughts:thoughts, text:clean.trim() };
}
function lAddThought(arr){
