var curSong=null, curCat=0, curSongs=[], musicPageNo=0, musicPageSize=5;
function hpEsc(s){ return String(s==null?'':s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }
function hpOpenMusic(){ hpShowTab('musicTab'); renderMusic(); }
function hpMusicSongs(){
  var lib=MUSIC_LIB||[];
  if(curCat===0){ var out=[]; for(var i=0;i<lib.length;i++)out=out.concat(lib[i].songs||[]); return out; }
  var g=lib[curCat-1]; return g?(g.songs||[]):[];
}
function renderMusic(){
  var lib=MUSIC_LIB||[];
  var tabs=['全部']; for(var i=0;i<lib.length;i++)tabs.push(lib[i].cat);
  var cats=document.getElementById('musicCats');
  if(cats){ var h=''; for(var j=0;j<tabs.length;j++)h+='<span class="musicCat'+(j===curCat?' on':'')+'" onclick="switchMusicCat('+j+')">'+tabs[j]+'</span>'; cats.innerHTML=h; }
  var cnt=0; for(var k=0;k<lib.length;k++)cnt+=((lib[k].songs)||[]).length;
  var mc=document.getElementById('musicCount'); if(mc)mc.textContent='共 '+cnt+' 首';
  curSongs=hpMusicSongs();
  var totalPages=Math.max(1, Math.ceil(curSongs.length/musicPageSize));
  if(musicPageNo>=totalPages)musicPageNo=totalPages-1;
  if(musicPageNo<0)musicPageNo=0;
  var start=musicPageNo*musicPageSize;
  var page=curSongs.slice(start, start+musicPageSize);
  var list=document.getElementById('musicList');
  if(list){
    var h2='';
    for(var n=0;n<page.length;n++){
      var s=page[n];
      var g=start+n;
      h2+='<div class="songRow" data-i="'+g+'" onclick="playSong('+g+')"><span class="songName">'+hpEsc(s.name)+'</span>'+(s.sub?'<span class="songSub">'+hpEsc(s.sub)+'</span>':'')+'</div>';
    }
    list.innerHTML=h2||'<div class="feedback">暂无歌曲</div>';
    if(curSong){ var rows=list.querySelectorAll('.songRow'); for(var m=0;m<rows.length;m++){ var gi=parseInt(rows[m].getAttribute('data-i'),10); var sm=curSongs[gi]; if(sm&&sm.name===curSong.name&&sm.url===curSong.url&&(sm.sub||'')===(curSong.sub||'')){ rows[m].className='songRow on'; } } }
  }
  var prev=document.getElementById('musicPrev'), next=document.getElementById('musicNext'), info=document.getElementById('musicPageInfo');
  if(prev)prev.disabled=(musicPageNo===0);
  if(next)next.disabled=(musicPageNo>=totalPages-1);
  if(info)info.textContent='第 '+(musicPageNo+1)+' / '+totalPages+' 页';
}
function musicPage(dir){
  var totalPages=Math.max(1, Math.ceil(curSongs.length/musicPageSize));
  var np=musicPageNo+dir;
  if(np<0||np>=totalPages)return;
  musicPageNo=np;
  renderMusic();
}
function switchMusicCat(i){ curCat=i; musicPageNo=0; renderMusic(); }
function playSong(i){
  var s=curSongs[i]; if(!s)return;
  curSong=s;
  var list=document.getElementById('musicList');
  if(list){ var rows=list.querySelectorAll('.songRow'); for(var n=0;n<rows.length;n++){ rows[n].className='songRow'+((parseInt(rows[n].getAttribute('data-i'),10)===i)?' on':''); } }
  var mn=document.getElementById('miniName'); if(mn)mn.textContent=(s.sub?s.sub+' · ':'')+s.name;
  var au=document.getElementById('miniAudio'); if(au){ au.src=s.url; try{ au.play(); }catch(e){} }
  var pb=document.getElementById('pushBtn'); if(pb)pb.disabled=false;
  var fb=document.getElementById('musicFeedback'); if(fb)fb.innerHTML='';
}
