var studentCache=null, studentBusy=false, seatDrag=null, seatStart=null, seatPick=null;
var STU_DAYS=['周一','周二','周三','周四','周五','周六','周日'];
var STU_TIMES=['8:30-9:10','9:50-10:30','10:40-11:20','13:00-13:40','13:50-14:30','14:40-15:20'];
// 世界书名称见 hpWbUpload 处的 HP_SYNC_WB（所有功能共用同一个）
