];
// ——— 身份卡缓存：让卡在酒馆重启 / 重进聊天后能直接读回来 ———
// 内存里的 studentCache 一刷新就没了；不缓存的话每次打开都要**重新推导**（判定当前角色 + 读名册
// + 可能触发一次生成），既慢又可能失败（用户报过「重开后要重新读取、没保留记忆」）。
// 缓存写进同步书里的单条目（用 hpWbSetEntry，不走 hpWbUpload，和「今日」「电量」同一条路）。
var HP_STU_ENTRY='新中市·身份卡缓存';
function hpStuSaveCache(){
  if(!studentCache || !studentCache.card) return Promise.resolve();
  var json='';
  try{ json=JSON.stringify(studentCache); }catch(e){ return Promise.resolve(); }
  if(!json || json.length>200000) return Promise.resolve();   // 异常大就不写，别把书撑坏
  // ⚠ 必须用「关键词激活」+ 一个不可能出现的触发词：hpWbSetEntry 默认是 constant，
  // 那这段 JSON 会被**每轮注入给 AI**（白白撑上下文、还会让 AI 困惑）。
  return hpWbSetEntry(HP_STU_ENTRY, json, false, { type:'selective', keys:['__hp_stucard_cache__'], scan_depth:1 })
    .catch(function(e){ hpWarn('身份卡缓存保存失败：'+((e&&e.message)||e)); });
}
function hpStuLoadCache(){
  var TH=hpWbApi(); if(!TH) return Promise.resolve(null);
  return hpWbRead(TH, HP_SYNC_WB).then(function(eb){
    for(var i=0;i<eb.length;i++){
      if(hpWbEntryName(eb[i])!==HP_STU_ENTRY) continue;
      var txt=String(eb[i].content||''); if(!txt) return null;
      try{ var d=JSON.parse(txt); return (d && d.card) ? d : null; }catch(e){ return null; }
    }
    return null;
  }).catch(function(){ return null; });
}
function hpOpenStudent(){
  hpShowTab('studentTab'); hpStuShow('studentCard');
  hpActorSyncUi();   // 先把「当前角色」栏填上当前值
  // 换聊天后校准内容会被清空，此时丢掉缓存重新拉取
  hpCheckCalibrationScope().then(function(cleared){
    if(cleared){ studentCache=null; hpCurrentActor=''; }
    if(studentCache){ renderStudent(); return; }
    // 先读同步书里上次保存的身份卡（秒开、不消耗生成、不会再出现「认不出角色」）；
    // 读不到才走重新推导。想强制重算点「🔄 更新」。
    return hpStuLoadCache().then(function(saved){
      if(saved){ saved.fromCache=true; studentCache=saved; renderStudent(); return; }
      refreshStudent();
    });
  });
}
function hpStuShow(v){
  // 课表/座位表仅学生可用
  if((v==='schedTab'||v==='seatTab') && studentCache && studentCache.card && studentCache.card.isStudent===false) return;
  var ids=['studentCard','schedTab','seatTab','relTab'];
  for(var i=0;i<ids.length;i++){ var e=document.getElementById(ids[i]); if(e)e.style.display=(ids[i]===v)?'flex':'none'; }
}
function hpStuBack(){ hpStuShow('studentCard'); }
function refreshStudent(){
  if(studentBusy) return;
  studentBusy=true;
  hpFeedback('检索中…','stuFeedback');
  var chain=Promise.resolve();
  chain=chain.then(function(){ return hpJudgeActor(); });
  chain=chain.then(function(actor){
    if(!actor) throw new Error('未能识别当前玩家控制角色，请先让该角色在聊天中出现');
    return hpLoadStudentData(actor);
  });
  return chain.then(function(data){
    studentCache=data;
    hpStuSaveCache();      // 重新推导出来的结果存回同步书，下次打开直接读回来
    renderStudent();
    hpAutoCardSync();      // 身份卡/任课教师跟着自动同步（书不存在时内部会跳过）
    studentBusy=false;
    hpFeedback('✓ 已更新','stuFeedback');
  })
  .catch(function(e){
    studentBusy=false;
    console.error(e);
    hpFeedback('⚠ '+(e&&e.message?e.message:String(e)),'stuFeedback');
    if(!studentCache){ renderStudent(); }
  });
}
// AI 判定当前玩家控制角色 → 只输出姓名
// ——— 当前玩家控制角色判定 ———
// 规则（优先级从高到低）：
//   ① 世界书「user设定（别动！）」里有明确角色信息 → 一律以它为准（不管与酒馆 user 是否一致）
//   ② 该条目为空时：看最近两条玩家输入里提到的角色，最新那条优先
//   ③ 两条都没提到 → 用酒馆 user 名（若它不是默认的 "user"）
//   ④ 仍无结果 → AI 兜底，且只把这最近两条输入喂给它（不注入其它剧情）
function hpTavernUserName(){
  try{
    var ctx=window.parent.SillyTavern && window.parent.SillyTavern.getContext ? window.parent.SillyTavern.getContext() : null;
    if(ctx && ctx.name1) return String(ctx.name1).trim();
  }catch(e){}
  return '';
}
function hpIsDefaultUser(n){ return !n || /^user$/i.test(String(n).trim()); }
// ——— 世界书「user设定（别动！）」读写 ———
function hpTavernChatId(){
  try{
    var ctx=window.parent.SillyTavern && window.parent.SillyTavern.getContext ? window.parent.SillyTavern.getContext() : null;
    if(ctx && ctx.chatId) return String(ctx.chatId);
  }catch(e){}
  return '';
}
function hpUserSettingEntryName(e){
  if(!e) return false;
  var n=String(e.name||e.comment||'').trim();
  // 必须同时含「user设定/用户设定」和「别动」，避免撞上其它世界书里的相似条目
  return (/user设定|用户设定/i.test(n) && /别动/.test(n));
}
// 在已启用的世界书里找承载「user设定（别动！）」的那一本（先查角色卡/全局/聊天绑定，再退回全量）
function hpFindUserSetting(TH){
  if(!TH || !TH.getWorldbook) return Promise.resolve(null);
  var names=[], seen={};
  function add(n){ if(n && !seen[n]){ seen[n]=1; names.push(n); } }
  try{
    if(TH.getCharWorldbookNames){ var cw=TH.getCharWorldbookNames('current')||{}; add(cw.primary); var a=cw.additional||[]; for(var i=0;i<a.length;i++) add(a[i]); }
  }catch(e){}
  try{ if(TH.getGlobalWorldbookNames){ var g=TH.getGlobalWorldbookNames()||[]; for(var j=0;j<g.length;j++) add(g[j]); } }catch(e){}
  try{ if(TH.getChatWorldbookName) add(TH.getChatWorldbookName('current')); }catch(e){}
  try{ if(TH.getWorldbookNames){ var al=TH.getWorldbookNames()||[]; for(var k=0;k<al.length;k++) add(al[k]); } }catch(e){}
  var chain=Promise.resolve(null);
  names.forEach(function(nm){
    chain=chain.then(function(found){
      if(found) return found;
      return hpWbRead(TH, nm).then(function(eb){
        for(var i=0;i<eb.length;i++){ if(hpUserSettingEntryName(eb[i])) return {book:nm, entry:eb[i]}; }
        return null;
      });
    });
  });
  return chain;
}
// 只改这一条的 content，其余条目原样回写
function hpSetUserSettingContent(TH, book, text){
  if(!TH || !TH.updateWorldbookWith) return Promise.reject(new Error('世界书 API 不支持单条更新'));
  return Promise.resolve(TH.updateWorldbookWith(book, function(list){
    var out=[];
    for(var i=0;i<list.length;i++){
      var e=list[i];
      if(hpUserSettingEntryName(e)){
        var copy={}, f;
        for(f in e){ if(Object.prototype.hasOwnProperty.call(e,f)) copy[f]=e[f]; }
        copy.content=text;
        out.push(copy);
      } else out.push(e);
    }
    return out;
  })).then(function(list){
    hpWbInvalidate();   // 刚改过条目内容 → 读缓存失效（紧接着会回读/装配身份卡）
    // 回读校验：把实际写进去的字数返回，便于确认是否真的写入
    var len=0;
    if(Array.isArray(list)){
      for(var i=0;i<list.length;i++){ if(hpUserSettingEntryName(list[i])) len+=String(list[i].content||'').length; }
    }
    return len;
  });
}
// 换聊天清空「user设定（别动！）」由悬浮球外壳统一负责 —— 面板要点开悬浮球才加载，
// 而「新建聊天」多半发生在没开面板的时候。这里只问外壳「刚才是被清空了吗」，
// 好据此丢掉上一个角色留下的缓存；返回是否清空了。
function hpCheckCalibrationScope(){
  try{
    var sh=window.parent && window.parent.__hpCalClearScope;
    if(typeof sh==='function') return Promise.resolve(sh()).then(function(r){ return !!r; }, function(e){ hpWarn('换聊天清空检查失败：'+((e&&e.message)||e)); return false; });
  }catch(e){}
  return Promise.resolve(false);
}
// ——— 校准玩家角色（覆盖写入「user设定（别动！）」）———
function hpStuCalSet(id, v){ var e=document.getElementById(id); if(e) e.value=v||''; }
function hpStuCalVal(id){ var e=document.getElementById(id); return e?e.value.trim():''; }
function hpStuCalibrate(){
  var c=(studentCache&&studentCache.card)||null;
  hpStuCalSet('stuCalName', c?c.name:'');
  hpStuCalSet('stuCalRace', c?c.race:'');
  hpStuCalSet('stuCalGender', c?c.gender:'');
  hpStuCalSet('stuCalAge', c?c.age:'');
  hpStuCalSet('stuCalJob', c?c.job:'');
  hpStuCalSet('stuCalInfo','');
  var m=document.getElementById('stuCalModal'); if(m) m.className='modalBg show';
  var n=document.getElementById('stuCalName'); if(n) n.focus();
}
function hpStuCalClose(){ var m=document.getElementById('stuCalModal'); if(m)m.className='modalBg'; }
function hpStuCalSave(){
  var nm=hpStuCalVal('stuCalName');
  var race=hpStuCalVal('stuCalRace'), gender=hpStuCalVal('stuCalGender');
  var age=hpStuCalVal('stuCalAge'), job=hpStuCalVal('stuCalJob');
  var info=hpStuCalVal('stuCalInfo');
  // 固定项必填
  var missing='';
  if(!nm) missing='角色名称'; else if(!race) missing='种族'; else if(!gender) missing='性别';
  else if(!age) missing='年龄'; else if(!job) missing='职业';
  if(missing){ hpFeedback('⚠ 请填写'+missing,'stuFeedback'); return; }
  if(!hpIsTavern()){ hpStuCalClose(); hpFeedback('✓ 已校准（演示模式）','stuFeedback'); return; }
  var TH=window.parent.TavernHelper;
  if(!TH || !TH.updateWorldbookWith){ hpFeedback('⚠ 世界书 API 不可用','stuFeedback'); return; }
  hpFeedback('正在写入……','stuFeedback');
  var text='姓名：'+nm+'\n种族：'+race+'\n性别：'+gender+'\n年龄：'+age+'\n职业：'+job+'\n'
          +(info?info+'\n':'')+'【校准标记·聊天：'+hpTavernChatId()+'】';
  hpFindUserSetting(TH).then(function(f){
    if(!f) throw new Error('未找到「user设定」条目');
    return hpSetUserSettingContent(TH, f.book, text).then(function(len){
      hpStuCalClose();
      // 直接按校准出来的角色重新装配，避免 refreshStudent 的提示盖掉校准结果
      hpCurrentActor=nm;
      hpFeedback('✓ 已校准，正在读取……','stuFeedback');
      return hpLoadStudentData(nm).then(function(data){
        studentCache=data; hpStuSaveCache(); renderStudent();
        hpFeedback('✓ 已校准为 '+nm+'（写入 '+len+' 字）','stuFeedback');
      });
    });
  }).catch(function(e){
    console.error('[小手机] 校准失败', e);
    hpFeedback('⚠ 失败：'+String((e&&e.message)||e).slice(0,14),'stuFeedback');
  });
}
function hpParseNameFromText(t){
  var s=String(t||'');
  var m=s.match(/(?:姓名|名字|角色名|名称|Name)\s*[:：]\s*([^\n\r，,。；;]{1,14})/i);
  if(m){ var v=m[1].trim(); if(v) return v; }
  return '';
}
// 最近 N 条玩家输入（按时间顺序，旧的在前）
function hpLastUserInputs(list, n){
  var out=[];
  if(!Array.isArray(list)) return out;
  for(var i=list.length-1;i>=0 && out.length<(n||2);i--){
    var m=list[i]; if(!m||typeof m!=='object') continue;
    if(m.is_user===true && typeof m.mes==='string' && m.mes.trim()) out.push(m.mes);
  }
  return out.reverse();
}
// 从已激活世界书里汇总候选角色名（角色条目「名字（班级）」+ 学生人员表）
function hpActorNamesFromEntries(entries){
  var out=[], seen={};
  function add(n){
    n=String(n||'').trim();
    if(n.length<2 || n.length>12) return;
    if(seen[n]) return;
    seen[n]=1; out.push(n);
  }
  for(var i=0;i<entries.length;i++){
    var nm=String(entries[i].name||'');
    var m=nm.match(/^(.{2,12}?)\s*[（(](.{1,24})[）)]$/);
    if(m && /学生|老师|教师|校长|部员|社员|从者|主任|会长/.test(m[2])){ add(m[1]); continue; }
    var c=String(entries[i].content||'');
    var h=c.match(/【([^（(\n]{2,12})[（(]/);
    if(h) add(h[1]);
  }
  // 学生人员表里的全部姓名
  for(var j=0;j<entries.length;j++){
    if(String(entries[j].name||'').indexOf('学生人员表')<0) continue;
    var lines=String(entries[j].content||'').split(/\r?\n/);
    for(var k=0;k<lines.length;k++){
      var mm=lines[k].match(/^\s*[^\n:：]*学生\s*[:：]\s*([^\n]+)$/);
      if(!mm) continue;
      var arr=hpSplitNames(mm[1]);
      for(var q=0;q<arr.length;q++) add(arr[q]);
    }
  }
  out.sort(function(a,b){ return b.length-a.length; });
  return out;
}
// 文本里最早出现、且名字最长的候选角色
function hpNameInText(text, names){
  var s=String(text||''), best='', bestAt=-1;
  for(var i=0;i<names.length;i++){
    var at=s.indexOf(names[i]);
    if(at<0) continue;
    if(bestAt<0 || at<bestAt || (at===bestAt && names[i].length>best.length)){ bestAt=at; best=names[i]; }
  }
  return best;
}
// AI 兜底：只喂最近两条玩家输入，不注入任何其它剧情
function hpJudgeActorByAI(inputs){
  var TH=window.parent.TavernHelper;
  if(!TH||!TH.generateRaw) return Promise.resolve('');
  var txt=(inputs&&inputs.length)?inputs.join('\n---\n'):'';
  if(!txt) return Promise.resolve('');
  var ps=[
    { role:'system', content:'【任务】下面是玩家最近的两条输入。判断玩家此刻正在扮演／控制的是哪一位角色——只依据这两条输入里明确出现的角色名，不要参考其它剧情，也不要凭印象推测。只输出姓名。' },
    { role:'system', content:'【输出格式】严格只输出一个 JSON 对象：{"name":"角色姓名"}。无法判断则输出 {"name":""}。' },
    { role:'system', content:'【玩家最近两条输入】\n'+txt }
  ];
  return new Promise(function(resolve){
    TH.generateRaw({ user_input:'【请判定玩家当前控制的角色。】', ordered_prompts: ps.concat(['user_input']) })
    .then(function(reply){
      if(reply&&typeof reply==='object'&&reply.content!=null)reply=reply.content;
      resolve(hpParseActorName(reply));
    })
    .catch(function(){ resolve(''); });
  });
}
// ——— 当前角色：手动指定 + 锁定 ———
// 上帝视角下「我现在演谁」换得很勤（群戏尤甚），AI 判定又费一次生成；
// 锁定后 hpJudgeActor 直接返回锁定名，整条判定链（含 AI 兜底）都不走。
var hpActorLocked='';
function hpActorLockToggle(){
  var inp=document.getElementById('stuActorInput');
  var shown=(studentCache&&studentCache.card)?String(studentCache.card.name||''):'';
  var cur=hpActorLocked || hpCurrentActor || shown;
  if(hpActorLocked){
    hpActorLocked=''; hpCurrentActor='';
    hpActorSyncUi();
    hpFeedback('已解锁，恢复自动判定','stuFeedback');
    return;
  }
  var v=(inp&&inp.value.trim())||cur;
  if(!v){ hpFeedback('⚠ 先填写角色名再锁定','stuFeedback'); return; }
  hpActorLocked=v; hpCurrentActor=v;
  hpActorSyncUi();
  // 只改锁定状态，**不重读角色**（2026-09-15 用户：点锁定就是因为这个角色是对的，
  // 别的什么都不用管）。要重新推导就点「🔄 更新」。
  hpFeedback('已锁定为 '+v+'（不再走 AI 判定）','stuFeedback');
}
function hpActorSyncUi(){
  var inp=document.getElementById('stuActorInput'), btn=document.getElementById('stuActorLockBtn');
  var cur=hpActorLocked || hpCurrentActor || (studentCache&&studentCache.card?String(studentCache.card.name||''):'');
  if(inp && document.activeElement!==inp) inp.value=cur||'';
  if(btn){
    btn.textContent=hpActorLocked?'已锁定':'锁定';
    btn.className='swBtn'+(hpActorLocked?' on':'');
    btn.title=hpActorLocked?('已锁定：'+hpActorLocked+'（点一下解锁）'):'锁定当前角色（锁定后不再走 AI 判定）';
  }
}
function hpJudgeActor(){
  if(hpActorLocked) return Promise.resolve(hpActorLocked);   // 手动锁定优先，不再猜
  if(!hpIsTavern()) return Promise.resolve('凌路');
  var TH=window.parent.TavernHelper;
  if(!TH || !TH.getWorldbook) return hpJudgeActorByAI([]);
  var tavUser=hpTavernUserName();
  return hpLoadWorldbooks(TH).then(function(entries){
    var us=hpFindEntry(entries,'user设定（别动！）');
    var usContent=us?String(us.content||'').trim():'';
    var names=hpActorNamesFromEntries(entries);
    return hpReadMessages().then(function(msgs){
      var inputs=hpLastUserInputs(msgs,2);
      // ① user设定 有内容 → 以它为准
      if(usContent){
        var n1=hpParseNameFromText(usContent);
        if(n1) return n1;
        if(!hpIsDefaultUser(tavUser)) return tavUser;
      }
      // ② 最近两条玩家输入里提到的角色（新的优先）
      for(var i=inputs.length-1;i>=0;i--){
        var nm=hpNameInText(inputs[i], names);
        if(nm) return nm;
      }
      // ③ 都没提到 → 酒馆 user 名
      if(!hpIsDefaultUser(tavUser)) return tavUser;
      // ④ AI 兜底
      return hpJudgeActorByAI(inputs);
    });
  }).catch(function(){ return hpJudgeActorByAI([]); });
}
function hpParseActorName(reply){
  var s=hpCleanText(reply);
  if(!s) return '';
  var name='';
  try{ var o=JSON.parse(s); if(o&&o.name) name=String(o.name).trim(); }
  catch(e){ name=''; }
  if(!name){ var m=s.match(/"name"\s*[:：]\s*"([^"]*)"/); if(m) name=m[1].trim(); }
  if(!name){
    name=s.replace(/[{}"']/g,'').trim();
    name=name.replace(/^.*?(?:当前|现在|目前|玩家|角色|主角|人物|是|为|：|:)+/,'');
    name=name.replace(/[，。！？、,\.!?\s]+/g,'').trim();
    if(name.length>12 || /[a-z]{3,}/i.test(name)) name='';
  }
  return name;
}
// 读取所有「已启用」世界书（角色卡绑定 + 全局）并合并条目
function hpLoadWorldbooks(TH){
  if(!TH || !TH.getWorldbook) return Promise.resolve([]);
  if(HP_WB_CACHE && (new Date().getTime()-HP_WB_CACHE_T)<4000) return Promise.resolve(HP_WB_CACHE);
  var names=[];
  function add(n){ if(!n)return; if(names.indexOf(n)<0) names.push(n); }
  try{
    if(TH.getCharWorldbookNames){ var cw=TH.getCharWorldbookNames('current')||{}; if(cw.primary) add(cw.primary); var a=cw.additional||[]; for(var i=0;i<a.length;i++) add(a[i]); }
  }catch(e){}
  try{
    if(TH.getGlobalWorldbookNames){ var g=TH.getGlobalWorldbookNames()||[]; for(var j=0;j<g.length;j++) add(g[j]); }
  }catch(e){}
  try{
    // 聊天绑定的世界书也要读，否则「只绑到聊天」时脚本自己取不到刚上传的数据
    if(TH.getChatWorldbookName) add(TH.getChatWorldbookName('current'));
  }catch(e){}
  var out=[];
  var chain=Promise.resolve();
  for(var k=0;k<names.length;k++){
    (function(nm){
      chain=chain.then(function(){
        return TH.getWorldbook(nm).then(function(eb){
          // key 也带上：领域条目注入时要用触发词判断「酒馆是不是已经注入过」
          for(var x=0;x<eb.length;x++){ var en=eb[x]; if(en && en.enabled && en.content){ out.push({name:en.name, content:en.content, key:(en.key||en.keys||'')}); } }
          return null;
        }).catch(function(){ return null; });
      });
    })(names[k]);
  }
  return chain.then(function(){
    HP_WB_CACHE=out; HP_WB_CACHE_T=new Date().getTime();
    return out;
  });
}
// 世界书读取要拉整本（主书 8.7MB），多个功能会在同一瞬间各读一次 → 4 秒内复用同一份。
// 写盘后必须调 hpWbInvalidate()，否则紧接着的「回读校验」会读到旧内容。
var HP_WB_CACHE=null, HP_WB_CACHE_T=0;
function hpWbInvalidate(){ HP_WB_CACHE=null; HP_WB_CACHE_T=0; }
function hpFindEntry(entries, name){
  var i, best=null;
  for(i=0;i<entries.length;i++){ if(entries[i].name===name) return entries[i]; }        // 精确优先
  for(i=0;i<entries.length;i++){                                                       // 只认「条目名比查询长」＝带后缀（如 （高一C））
    var nm=entries[i].name||'';
    if(nm.indexOf(name)>=0 && nm.length-name.length<=8){ if(!best || nm.length<best.name.length) best=entries[i]; }
  }
  return best;
}
// ——— 领域条目显式注入 ———
// 酒馆只在「最近消息里出现条目触发词」时才把条目注进上下文；点开 app 生成内容（SNS/直播/论坛）时
// 未必满足该条件 → 生成时缺规则。这里 app 自己显式注入：先读条目正文，若最近两条消息已含触发词
// （说明酒馆已注入）就跳过，避免同一份规则在上下文里出现两遍。
var HP_DOMAIN={
  sns:{name:'X站·[SNS]内容发布系统（通用版）', msg:'', ready:false, pending:null},
  live:{name:'X站-直播平台（9）', msg:'', ready:false, pending:null},
  forum:{name:'学校论坛（校园贴吧·交互版）', msg:'', ready:false, pending:null}
};
function hpDomainMsg(kind){
  var d=HP_DOMAIN[kind];
  if(!d || !d.msg) return [];
  return [{ role:'system', content:d.msg }];
}
// 最近两条消息里是否已出现该条目的触发词（近似酒馆的激活判定）
function hpDomainAlreadyActive(entry){
  var raw=entry?entry.key:null, keys=[];
  if(Object.prototype.toString.call(raw)==='[object Array]') keys=raw.map(function(x){ return String(x).trim(); });
  else keys=String(raw||'').split(/[,，]/).map(function(x){ return x.trim(); });
  keys=keys.filter(function(x){ return x.length>=2; });
  if(!keys.length) return Promise.resolve(false);
  return hpReadMessages().then(function(msgs){
    var arr=Object.prototype.toString.call(msgs)==='[object Array]'?msgs:[];
    var txt='';
    for(var i=Math.max(0,arr.length-2);i<arr.length;i++){ var m=arr[i]||{}; txt+=String(m.mes||m.content||m.message||''); }
    if(!txt) return false;
    for(var j=0;j<keys.length;j++){ if(txt.indexOf(keys[j])>=0) return true; }
    return false;
  }).catch(function(){ return false; });
}
function hpDomainWarm(kind, force){
  var d=HP_DOMAIN[kind];
  if(!d) return Promise.resolve();
  if(d.ready && !force) return Promise.resolve();
  if(d.pending) return d.pending;                        // 并发调用复用同一次读取
  var TH=window.parent.TavernHelper;
  d.pending=hpLoadWorldbooks(TH).then(function(entries){
    var e=hpFindEntry(entries, d.name);
    d.ready=true; d.pending=null;
    if(!e || !e.content){ d.msg=''; hpWarn('找不到世界书条目「'+d.name+'」，生成内容可能不守该领域规则'); return; }
    return hpDomainAlreadyActive(e).then(function(active){
      d.msg = active ? '' : ('【'+d.name+'（本 app 生成时必须遵守）】\n'+e.content);
    });
  }).catch(function(err){
    d.ready=true; d.pending=null; d.msg='';
    hpWarn('领域条目读取失败（'+d.name+'）：'+((err&&err.message)||err));
  });
  return d.pending;
}
function hpCleanName(s){ return String(s==null?'':s).replace(/[（(][^）)]*[）)]/g,'').replace(/\s+/g,'').trim(); }
function hpSplitNames(tail){
  var parts=String(tail==null?'':tail).split(/[,，、]/);
  var out=[], seen={};
  for(var i=0;i<parts.length;i++){ var n=hpCleanName(parts[i]); if(!n||seen[n]) continue; seen[n]=1; out.push(n); }
  return out;
}
function hpFindRoleEntry(entries, actor){
  var fuzzy=null;
  for(var i=0;i<entries.length;i++){
    var nm=entries[i].name||''; if(!nm) continue;
    var base=hpCleanName(nm);
    if(base===actor) return entries[i];
    if(base.indexOf(actor)>=0 || (actor&&actor.indexOf(base)>=0)){ if(!fuzzy) fuzzy=entries[i]; }
  }
  if(!fuzzy){
    for(var j=0;j<entries.length;j++){
      var c=entries[j].content||'';
      if(c.indexOf('【'+actor)>=0 || c.indexOf(actor+'(')>=0 || c.indexOf(actor+'（')>=0){ fuzzy=entries[j]; break; }
    }
  }
  return fuzzy;
}
function hpGradeOfHead(head){
  var m=head.match(/^(大[一二三四五六])学生$/); if(m) return m[1];
  m=head.match(/^([高初][一二三])[A-Z]班学生$/); if(m) return m[1];
  if(/^小学[A-Z]班学生$/.test(head)) return '小学';
