function hpParseTeachers(text){
  var out={};
  if(!text) return out;
  var s=String(text);
  var i=s.indexOf('各学部教师编制');
  if(i>=0) s=s.slice(i);
  var j=s.indexOf('第四章');
  if(j>=0) s=s.slice(0,j);
  var lines=s.split(/\r?\n/);
  var fac='', subj='';
  for(var k=0;k<lines.length;k++){
    var ln=lines[k];
    var fm=ln.match(/^\s*[一二三四五六七八九十]、\s*(\S+?)教师/);
    if(fm){
      fac=fm[1].trim();
      if(fac.indexOf('外部')>=0 || fac.indexOf('非教学')>=0){ fac=''; continue; }
      subj='';
      if(!out[fac]) out[fac]={teachers:[]};
      continue;
    }
    if(!fac) continue;
    var sm=ln.match(/^\s*【(.+?)】/);
    if(sm){
      subj=sm[1].replace(/[（(].*$/,'').replace(/科$/,'').trim();
      // 这个学部是按学科分组写的（【语文科】【数学科】…）→ 它的科目是真学科，
      // 才可以被别的学部借去代课。大学部/小学部/幼儿园是选课制或包班制，没有学科分组，
      // 它们的科目只是从职称描述里抠出来的（如「数学教授」→数学），不能当同科老师用。
      out[fac].bySubject=true;
      continue;
    }
    var tm=ln.match(/^\s{1,8}([^\s—\-]{1,12})\s+[—\-]\s*(.+)$/);
    if(!tm) continue;
    var nm=tm[1].trim(), desc=tm[2].trim();
    if(!nm || nm.length<2) continue;
    if(nm.indexOf('：')>=0 || nm.indexOf(':')>=0) continue;
    var isHr=desc.indexOf('★')>=0;
    var cls='';
    var cm=desc.match(/★\s*([^\s（(｜|]+)/);
    if(cm) cls=cm[1].replace(/班主任$|老师$|教师$/,'').trim();
    var subject=subj;
    if(!subject){
      var raw=desc.replace(/[★☆]/g,'').trim();
      var dm=raw.match(/^([^（(｜|\s]{2,16})/);
      if(dm){
        var sv=dm[1].split('·')[0];
        if(/班主任$/.test(sv)) subject='全科';
        else subject=sv.replace(/(教授|博士|老师|顾问)$/,'').trim();
      }
    }
    if(!subject) subject='其他';
    // 合科标题（【理化生科】）下的每行开头常带具体学科：用具体学科，否则课表写「物理」「化学」，
    // 本表却只有「理化生」一栏，AI 对不上号、进而乱安老师（2026-09-19）
    if(/^(理化生|理科|文科|综合)$/.test(subject)){
      var sm2=desc.match(/^\s*(物理|化学|生物|科学)/);
      if(sm2) subject=sm2[1];
    }
    out[fac].teachers.push({name:nm, subject:subject, hr:isHr, cls:cls});
  }
  return out;
}
