// 课表：大学生按专业 AI 生成周一~周日；非大学生固定周一~周五（周六日空），含大课间/午休行与 15:20-17:00 社团/自由活动
var STU_PERIOD_CN=['一','二','三','四','五','六','七','八'];
function hpBuildSchedule(grade, roleContent, club){
  if(/^大[一二三四五六]$/.test(grade)) return hpBuildCollegeSchedule(roleContent);
  var last=(club&&club.length)?club:'自由活动';
  var times=[], labels=[], days=[];
  for(var d=0;d<7;d++) days.push([]);
  for(var p=0;p<STU_STD.length;p++){
    // 第一节与第二节之间的 30 分钟大课间（2026-09-21 用户要的；原来只有 10 分钟课间）
    if(p===1){
      times.push('9:10-9:40'); labels.push('大课间');
      for(var db=0;db<7;db++) days[db].push(db<5?'大课间':'');
    }
    if(p===3){
      times.push('11:30-13:00'); labels.push('午休');
      for(var d1=0;d1<7;d1++) days[d1].push(d1<5?'午休':'');
    }
    times.push(STU_TIMES[p]); labels.push('第'+(STU_PERIOD_CN[p]||(p+1))+'节');
    for(var d2=0;d2<7;d2++) days[d2].push(d2<5?STU_STD[p][d2]:'');
  }
  times.push('15:20-17:00'); labels.push('课外');
  for(var d3=0;d3<7;d3++) days[d3].push(d3<5?last:'');
  return Promise.resolve({ college:false, times:times, labels:labels, days:days, lunch:'', free:'' });
}
function hpRoleProfile(content){
  var parts=[];
  var m=String(content||'').match(/Occupation\s*[:：]\s*([^\n\r]+)/i); if(m) parts.push('职业/身份：'+m[1].trim());
  m=String(content||'').match(/属性标签\s*[:：]\s*([^\n\r]+)/); if(m) parts.push('属性标签：'+m[1].trim());
  m=String(content||'').match(/一句话总结\s*[:：]\s*([^\n\r]+)/); if(m) parts.push('一句话总结：'+m[1].trim());
  if(!parts.length) parts.push(String(content||'').slice(0,300));
  return parts.join('；');
}
