// 座位表布局：双人同桌，左/中/右三组 + 两条过道（左右靠墙），人数>40 增加列、行数≤4
function hpSeatLayout(n){
  if(n<=0) return {rows:0, cols:0, left:0, mid:0, right:0};
  var T=Math.ceil(n/2);
  var R=Math.max(1, Math.min(4, Math.ceil(T/5)));
  var C=Math.ceil(T/R);
  var left=(C>=3)?1:0, right=(C>=3)?1:0;
  var mid=C-left-right; if(mid<1){ mid=1; C=left+mid+right; }
  return {rows:R, cols:C, left:left, mid:mid, right:right};
}
function hpBuildSeats(names){
  var n=(names&&names.length)?names.length:0;
  var layout=hpSeatLayout(n);
  var desks=[];
  var idx=0;
  for(var r=0;r<layout.rows;r++){
    var row=[];
    for(var c=0;c<layout.cols;c++){
      var left=idx<n?names[idx]:''; idx++;
      var right=idx<n?names[idx]:''; idx++;
      row.push({left:left, right:right});
    }
    desks.push(row);
  }
  return { rows:layout.rows, cols:layout.cols, leftCols:layout.left, midCols:layout.mid, rightCols:layout.right, names:n, desks:desks };
}
