// 绩点雷达图（SVG，六维）
function hpGradeRadar(list){
  var N=list.length; if(!N) return '';
  var cx=100, cy=100, R=58;
  function pt(i,rad){
    var a=-Math.PI/2 + i*2*Math.PI/N;
    return [cx+Math.cos(a)*rad, cy+Math.sin(a)*rad];
  }
  var svg='<svg class="gradeSvg" viewBox="0 12 200 176" xmlns="http://www.w3.org/2000/svg">';
  svg+='<defs><linearGradient id="hpGradeGrad" x1="0" y1="0" x2="1" y2="1"><stop offset="0%" stop-color="#4aa3ff" stop-opacity="0.8"/><stop offset="100%" stop-color="#a05aff" stop-opacity="0.55"/></linearGradient></defs>';
  for(var g=1;g<=3;g++){
    var rr=R*g/3, gp=[];
    for(var i=0;i<N;i++){ var p=pt(i,rr); gp.push(p[0].toFixed(1)+','+p[1].toFixed(1)); }
    svg+='<polygon points="'+gp.join(' ')+'" fill="none" stroke="rgba(255,255,255,0.12)" stroke-width="1"/>';
  }
  for(var i2=0;i2<N;i2++){
    var pe=pt(i2,R);
    svg+='<line x1="'+cx+'" y1="'+cy+'" x2="'+pe[0].toFixed(1)+'" y2="'+pe[1].toFixed(1)+'" stroke="rgba(255,255,255,0.1)" stroke-width="1"/>';
  }
  var dp=[];
  for(var i3=0;i3<N;i3++){ var p3=pt(i3, R*list[i3].v/100); dp.push(p3[0].toFixed(1)+','+p3[1].toFixed(1)); }
  svg+='<polygon points="'+dp.join(' ')+'" fill="url(#hpGradeGrad)" stroke="#7fc0ff" stroke-width="1.8" stroke-linejoin="round"/>';
  for(var i4=0;i4<N;i4++){
    var p4=pt(i4, R*list[i4].v/100);
    svg+='<circle cx="'+p4[0].toFixed(1)+'" cy="'+p4[1].toFixed(1)+'" r="2.6" fill="#cfe8ff"/>';
  }
  for(var i5=0;i5<N;i5++){
    var pl=pt(i5, R+19);
    svg+='<text x="'+pl[0].toFixed(1)+'" y="'+(pl[1]+3.5).toFixed(1)+'" text-anchor="middle" font-size="11" fill="#9db8d8">'+hpEsc(list[i5].k)+'</text>';
  }
  svg+='</svg>';
  return svg;
}
// ——— 班级 × 科目 → 指定任课老师 ———
// 为什么需要：教师编制只到「年级段」颗粒度（如高中部语文 7 人），不指定班级，
// 于是 AI 写「初三A上体育课」时只能在曹茗瑜/街雄鸣造里随便挑一个。这里把课落实到具体班级，
// 规则固定且可复现：
//   ① 某老师若是这个班的班主任 → 这个班的那一科先归他
//   ② 其余班级按顺序轮流分给该科老师（保证同科老师之间负载均衡）
function hpClassNorm(s){ return String(s||'').replace(/\s|班/g,''); }
function hpParseClasses(text){
  var out={}, lines=String(text||'').split(/\r?\n/), seen={};
  var RANK={'初一':1,'初二':2,'初三':3,'高一':1,'高二':2,'高三':3};
  for(var i=0;i<lines.length;i++){
    var m=lines[i].match(/^\s*((?:高|初)[一二三])([A-Z])班?学生/);
    if(!m) continue;
    var nm=m[1]+m[2]+'班';
    if(seen[nm]) continue;
    seen[nm]=1;
    var fac=hpFacultyOf(m[1]);
    if(!fac) continue;
    (out[fac]=out[fac]||[]).push(nm);
  }
  for(var f in out){
    out[f].sort(function(a,b){
      var d=(RANK[a.replace(/[A-Z]班$/,'')]||9)-(RANK[b.replace(/[A-Z]班$/,'')]||9);
      return d ? d : a.localeCompare(b);
    });
  }
  return out;
}
// 取某个班某一科被指派的老师；找不到就返回空串
// ——— 任课教师手动换人（代课，2026-09-21 用户要的）———
// studentCache.tOv[ '学部|班级|科目' ] = { to:'代课老师', why:'代课' }
// 随「新中市·身份卡缓存」一起持久化（hpStuSaveCache 序列化整个 studentCache）。
function hpTOvKey(fac, gc, sub){ return String(fac)+'|'+String(gc)+'|'+String(sub); }
function hpTOvOf(fac, gc, sub){
  var m=studentCache && studentCache.tOv;
  return (m && m[hpTOvKey(fac,gc,sub)]) || null;
}
function hpTOvApply(fac, gc, sub, to, why){
  if(!studentCache) return;
  if(!studentCache.tOv) studentCache.tOv={};
  var k=hpTOvKey(fac,gc,sub);
  if(!to) delete studentCache.tOv[k];                 // 空 = 恢复默认排课
  else studentCache.tOv[k]={to:String(to), why:String(why||'代课')};
  hpStuSaveCache();     // 落盘（含 tOv），否则刷新就白改
  try{ renderSchedule(); }catch(e){}
  hpAutoCardSync();     // 任课教师条目立刻跟着更新
}
// 同一科目的其他老师：跨学部都算（高中部老师可以来代初中部的课），标注学部/班级/是否班主任
function hpTeacherCandidates(subject, excludeName, ownFac){
  var out=[], facs=(studentCache && studentCache.teachers) || {}, fac, i, anyFlag=false;
  for(fac in facs){ if(facs[fac] && facs[fac].bySubject){ anyFlag=true; break; } }
  for(fac in facs){
    // 只从「按学科划分」的学部里挑（大学部/小学部/幼儿园没有学科分组，不参与代课）。
    // 旧缓存（解析器加标记之前存的）一个标记都没有 → 退而只允许本学部，宁可少也不能混进大学部。
    if(anyFlag){ if(!facs[fac] || !facs[fac].bySubject) continue; }
    else if(fac!==ownFac) continue;
    var arr=(facs[fac] && facs[fac].teachers) || [];
    for(i=0;i<arr.length;i++){
      var x=arr[i];
      if((x.subject||'其他')!==subject) continue;
      if(x.name===excludeName) continue;
      var dup=false, q;
      for(q=0;q<out.length;q++){ if(out[q].name===x.name && out[q].fac===fac){ dup=true; break; } }
      if(dup) continue;
      out.push({name:x.name, fac:fac, hr:!!x.hr, cls:x.cls||''});
    }
  }
  return out;
}
