function hpAssignedTeacher(fac, className, subject){
  var ov=hpTOvOf(fac, className, subject);
  if(ov && ov.to) return ov.to;            // 玩家手动指定过 → 优先
  return hpAssignedTeacherRaw(fac, className, subject);
}
function hpAssignedTeacherRaw(fac, className, subject){
  var all=(fac && studentCache && studentCache.teachers && studentCache.teachers[fac]) ? studentCache.teachers[fac].teachers : null;
  if(!all || !all.length || !subject) return '';
  var pool=[], i;
  for(i=0;i<all.length;i++){ if((all[i].subject||'其他')===subject) pool.push(all[i]); }
  if(!pool.length) return '';
  var target=hpClassNorm(className);
  var classes=(studentCache.classes && studentCache.classes[fac]) || [];
  if(!target || !classes.length) return pool[0].name;   // 没有班级（大学生等）→ 退回第一位
  var k=0;
  for(var m=0;m<classes.length;m++){
    var cn=hpClassNorm(classes[m]), hr=null;
    for(i=0;i<pool.length;i++){
      if(pool[i].hr && pool[i].cls && hpClassNorm(pool[i].cls)===cn){ hr=pool[i]; break; }
    }
    if(hr){ if(cn===target) return hr.name; continue; }  // 班主任优先，且不参与这一科的轮流
    var pick=pool[k % pool.length]; k++;
    if(cn===target) return pick.name;
  }
  return pool[0].name;
}
// 本班任课科目清单（按教师表出现顺序，滤掉行政/后勤）
function hpSubjectList(fac){
  var all=(fac && studentCache && studentCache.teachers && studentCache.teachers[fac]) ? studentCache.teachers[fac].teachers : null;
  var subs=[], seen={};
  if(!all) return subs;
  for(var i=0;i<all.length;i++){
    var s=all[i].subject||'其他';
    if(/非教学|职员|行政|后勤|教务/.test(s)) continue;
    if(seen[s]) continue;
    seen[s]=1; subs.push(s);
  }
  return subs;
}
function hpHomeRoomOf(fac, className){
  var all=(fac && studentCache && studentCache.teachers && studentCache.teachers[fac]) ? studentCache.teachers[fac].teachers : null;
  if(!all) return null;
  var t=hpClassNorm(className);
  if(!t) return null;
  for(var i=0;i<all.length;i++){
    var a=all[i];
    if(a.hr && a.cls && hpClassNorm(a.cls)===t) return a;
  }
