// ——— 座位拖拽换座（Pointer Events：桌面鼠标 + 手机触摸统一；同时支持点两格交换）———
function hpSeatDown(e){
  var el=e.currentTarget;
  if(!el || !el.getAttribute('data-name')) return;
  if(e.preventDefault) e.preventDefault();
  seatStart={ x:e.clientX, y:e.clientY, el:el,
    r:el.getAttribute('data-r'), c:el.getAttribute('data-c'), side:el.getAttribute('data-side') };
  seatDrag=null;
  try{ el.setPointerCapture(e.pointerId); }catch(err){}
}
function hpSeatMove(e){
  if(!seatStart) return;
  if(!seatDrag){
    if(Math.abs(e.clientX-seatStart.x)+Math.abs(e.clientY-seatStart.y) < 10) return;
    seatDrag={ r:seatStart.r, c:seatStart.c, side:seatStart.side, el:seatStart.el, over:null };
    seatStart.el.classList.add('dragging');
  }
  if(e.preventDefault) e.preventDefault();
  var el=document.elementFromPoint(e.clientX, e.clientY);
  var t=el;
  while(t && t!==document.body && !(t.classList && t.classList.contains('seatName'))){ t=t.parentElement; }
  var valid=(t && t.classList && t.classList.contains('seatName') && t.getAttribute('data-name') && t!==seatDrag.el);
  if(valid){
    if(seatDrag.over && seatDrag.over!==t){ seatDrag.over.classList.remove('over'); }
    seatDrag.over=t;
    t.classList.add('over');
  } else {
    if(seatDrag.over){ seatDrag.over.classList.remove('over'); seatDrag.over=null; }
  }
}
function hpSeatUp(e){
  var wasDrag=!!seatDrag;
  var target=seatDrag?seatDrag.over:null;
  if(seatDrag && seatDrag.el) seatDrag.el.classList.remove('dragging');
  if(target) target.classList.remove('over');
  var src=seatDrag||seatStart;
  seatDrag=null;
  var st=seatStart; seatStart=null;
  if(!src) return;
  if(wasDrag){
    if(!target || !target.getAttribute('data-name')) return;
    var tr=target.getAttribute('data-r'), tc=target.getAttribute('data-c'), ts=target.getAttribute('data-side');
    if(src.r===tr && src.c===tc && src.side===ts) return;
    seatPick=null;
    hpSwapSeat(src.r,src.c,src.side, tr,tc,ts);
    renderSeats();
    return;
  }
  if(st){
    var key=st.r+'-'+st.c+'-'+st.side;
    if(seatPick===null){ seatPick=key; hpMarkSeatPick(); }
    else if(seatPick===key){ seatPick=null; hpMarkSeatPick(); }
    else {
      var kp=seatPick.split('-');
      seatPick=null;
      hpSwapSeat(kp[0],kp[1],kp[2], st.r,st.c,st.side);
      renderSeats();
    }
  }
}
function hpSeatCancel(e){
  if(seatDrag){
    if(seatDrag.el) seatDrag.el.classList.remove('dragging');
    if(seatDrag.over) seatDrag.over.classList.remove('over');
  }
  seatDrag=null; seatStart=null;
}
function hpSwapSeat(r1,c1,s1,r2,c2,s2){
