function hpMarkPick(){
  var cells=document.querySelectorAll('#schedBody .schedCell[data-d]');
  for(var i=0;i<cells.length;i++){
    var k=cells[i].getAttribute('data-d')+'-'+cells[i].getAttribute('data-p');
    if(k===schedPick) cells[i].classList.add('picked');
    else cells[i].classList.remove('picked');
  }
}
// ——— 统一世界书上传 ———
// 所有功能（学生证/课表/座位表、日历标记……）共用一个世界书，各自只替换自己的同名条目，
// 其余条目原样保留，因此互不覆盖。旧的两个独立世界书会自动迁移合并后删除。
var HP_SYNC_WB='新中市-小手机同步';
var HP_LEGACY_WB=['新中市-学生助手同步','新中市-日历标记'];
function hpWbApi(){
  var TH=window.parent.TavernHelper;
  if(!TH || !TH.getOrCreateChatWorldbook || !TH.createOrReplaceWorldbook) return null;
  return TH;
}
function hpWbEntryName(e){ if(!e) return ''; return String(e.name || e.comment || ''); }
// 只保留写入 API 认得的四个字段：从 getWorldbook 读回的原始条目含 uid/key/comment 等一堆字段，
// 原样回写会让 createOrReplaceWorldbook 报错（uid 冲突 / 结构不符）
function hpWbNormalize(e){
  var en;
  if(e && e.enabled !== undefined) en = (e.enabled !== false);
  else en = !(e && e.disable === true);   // 酒馆原始格式用 disable 表示禁用
  return {
    name: hpWbEntryName(e),
    enabled: en,
    strategy: (e && e.strategy) ? e.strategy : {type:'constant'},
    content: (e && e.content !== undefined && e.content !== null) ? String(e.content) : ''
  };
}
// 建书/绑定：已存在时跳过（部分版本对已存在的世界书会直接报错），失败也不阻断后续写入
// 同步书是否已存在（**只判断，不创建**）：自动流程一律先问这个，避免打开手机就把书建出来
function hpWbExists(TH){
  try{ return (TH && TH.getWorldbookNames ? (TH.getWorldbookNames()||[]) : []).indexOf(HP_SYNC_WB)>=0; }catch(e){ return false; }
}
var hpWbHintShown=false;
function hpWbNeedUpload(){
  if(hpWbHintShown) return;
  hpWbHintShown=true;
  hpToast('同步书还没建立：点「📤 上传」后才会写入世界书');
}
// 抑制期（刚清空过）与「书还没建」是两回事：提示要说清，否则自动写入静默失效没法排查
var hpWbSuppHintShown=false;
function hpWbNeedUploadSuppressed(){
  if(hpWbSuppHintShown) return;
  hpWbSuppHintShown=true;
  hpToast('同步书刚被清空：自动同步已暂停，点「📤 上传」后才会恢复写入');
}
function hpWbEnsure(TH){
  var names=[];
  try{ names=TH.getWorldbookNames ? (TH.getWorldbookNames()||[]) : []; }catch(e){ names=[]; }
  if(names.indexOf(HP_SYNC_WB)>=0) return Promise.resolve();
  try{
    return Promise.resolve(TH.getOrCreateChatWorldbook('current', HP_SYNC_WB))
      .then(function(){}, function(e){ console.error('[小手机] 建/绑世界书被拒（继续尝试写入）', e); });
  }catch(e){ console.error('[小手机] 建/绑世界书异常', e); return Promise.resolve(); }
}
// 激活：把共用世界书绑定到「当前角色卡附加书」与「当前聊天」。
// ⚠ 调 rebindCharWorldbooks 时**绝不能带 primary 字段**：扩展里只要传了 primary，
//    就会 POST /api/characters/edit 重新保存角色卡，酒馆会重载角色、聊天被刷新。
//    只传 additional 时它只改角色卡的附加世界书列表，不动角色卡文件。
function hpWbActivate(TH){
  var chain=Promise.resolve();
  if(TH.getCharWorldbookNames && TH.rebindCharWorldbooks){
    chain=chain.then(function(){
      var cur=null;
      try{ cur=TH.getCharWorldbookNames('current'); }catch(e){ cur=null; }
      if(!cur) return null;
      var add=(cur.additional||[]).slice();
      if(add.indexOf(HP_SYNC_WB)>=0) return null;   // 已绑定，不重复写
      add.push(HP_SYNC_WB);
      return Promise.resolve(TH.rebindCharWorldbooks('current', {additional:add}))
        .catch(function(e){ console.error('[小手机] 绑定角色卡附加世界书失败', e); });
    });
  }
  if(TH.rebindChatWorldbook){
    chain=chain.then(function(){
      var cur=null;
      try{ if(TH.getChatWorldbookName) cur=TH.getChatWorldbookName('current'); }catch(e){ cur=null; }
      if(cur===HP_SYNC_WB) return null;
      return Promise.resolve(TH.rebindChatWorldbook('current', HP_SYNC_WB))
        .catch(function(e){ console.error('[小手机] 绑定聊天世界书失败', e); });
    });
  }
  return chain;
}
// 写入：直写失败时退回「先删后建」这条已验证可用的老路
function hpWbWrite(TH, list){
  var first;
  try{ first = TH.createOrReplaceWorldbook(HP_SYNC_WB, list); }
  catch(e){ first = Promise.reject(e); }
  return Promise.resolve(first).catch(function(err){
    console.error('[小手机] 直写世界书失败，退回「先删后建」', err);
    var chain=Promise.resolve();
    chain=chain.then(function(){
      if(!TH || !TH.deleteWorldbook) return null;
      try{ return Promise.resolve(TH.deleteWorldbook(HP_SYNC_WB)).catch(function(){}); }catch(e){ return null; }
    });
    chain=chain.then(function(){
      try{ return Promise.resolve(TH.getOrCreateChatWorldbook('current', HP_SYNC_WB)).catch(function(){}); }catch(e){ return null; }
    });
    chain=chain.then(function(){ return TH.createOrReplaceWorldbook(HP_SYNC_WB, list); });
    return chain;
  });
}
function hpWbRead(TH, name){
  // 守卫必须先判 TH 本身：写成 if(!TH.getWorldbook) 时，TH 为 undefined 会在这里直接抛错，
  // 把调用方的初始化流程整段打断（世界书 API 尚未就绪时就会踩到）。
  if(!TH || !TH.getWorldbook) return Promise.resolve([]);
  var pr;
  try{ pr=TH.getWorldbook(name); }catch(e){ return Promise.resolve([]); }
  return Promise.resolve(pr).then(function(eb){ return Array.isArray(eb)?eb:[]; }).catch(function(){ return []; });
}
// 迁移旧世界书的条目（保留玩家可能做过的改动），然后删掉旧书
function hpWbMigrateLegacy(TH){
  var names=[];
  try{ names=TH.getWorldbookNames ? (TH.getWorldbookNames()||[]) : []; }catch(e){ names=[]; }
  var todo=[], i;
  for(i=0;i<HP_LEGACY_WB.length;i++){
    if(HP_LEGACY_WB[i]!==HP_SYNC_WB && names.indexOf(HP_LEGACY_WB[i])>=0) todo.push(HP_LEGACY_WB[i]);
  }
  if(!todo.length) return Promise.resolve([]);
  var collected=[];
  var chain=Promise.resolve();
  todo.forEach(function(nm){
    chain=chain.then(function(){
      return hpWbRead(TH, nm).then(function(eb){
        for(var j=0;j<eb.length;j++){ if(hpWbEntryName(eb[j])) collected.push(hpWbNormalize(eb[j])); }
      });
    });
    chain=chain.then(function(){
      if(!TH || !TH.deleteWorldbook) return null;
      try{ return Promise.resolve(TH.deleteWorldbook(nm)).catch(function(){}); }
      catch(e){ return null; }
    });
  });
  return chain.then(function(){ return collected; });
}
// opts.partial=true：只 upsert 本次传入的条目，**不**按 MANAGED 清理其它管理条目。
// 单条目上传（如日历页只传「新中市日历·标记」）必须用这个，否则 keep() 会把本次没带的
// 身份卡/课表/座位表/今日 当成"该删的管理条目"整条丢掉（今日里是催眠规则/通知/电量）。
function hpWbUpload(entries, opts){
  var partial=!!(opts&&opts.partial);
  var TH=hpWbApi();
  if(!TH) return Promise.reject(new Error('世界书 API 不可用'));
  hpSyncSuppressed=false;        // 玩家点了上传 → 恢复正常自动同步
  var mine={}, i;
  for(i=0;i<entries.length;i++) mine[entries[i].name]=1;
  // 本功能管理的条目：一律以本次内容为准，旧名（如「学生助手·学生证」）与
  // 非学生时不再生成的课表/座位表都会被清理掉，不残留在世界书里
  var MANAGED=['新中市·身份卡','学生助手·当前课表','学生助手·任课教师','学生助手·班级座位表','学生助手·学生证','新中市·今日'];
  if(!partial){
    for(i=0;i<MANAGED.length;i++) mine[MANAGED[i]]=1;
  }
  var legacy=[];
  hpWbInvalidate();   // 本次要写盘 → 丢掉读缓存，写完后的回读必须是新内容
  return hpWbEnsure(TH)
    .then(function(){ return hpWbMigrateLegacy(TH); })
    .then(function(leg){ legacy=leg||[]; return hpWbRead(TH, HP_SYNC_WB); })
    .then(function(existing){
      var out=[], seen={};
      function keep(e){
        var nm=hpWbEntryName(e);
        if(!nm || mine[nm] || seen[nm]) return;   // 自己的条目跳过（稍后用新内容补上）
        seen[nm]=1;
        out.push(hpWbNormalize(e));
      }
      for(var a=0;a<existing.length;a++) keep(existing[a]);
      for(var b=0;b<legacy.length;b++) keep(legacy[b]);
      var cid=hpTavernChatId();
      if(cid){
        for(var q=out.length-1;q>=0;q--){ if(hpWbEntryName(out[q])===HP_SYNC_MARK) out.splice(q,1); }
        out.push({name:HP_SYNC_MARK, enabled:true, strategy:{type:'constant'}, content:'【新中市 · 同步标记】聊天：'+cid});
      }
      for(var c=0;c<entries.length;c++) out.push(entries[c]);
      // 合并写入若被编辑器拒绝（旧数据里有不合规条目），退回「只写自己的条目」，
      // 至少保证本次上传成功、而不是整个失败
      return hpWbWrite(TH, out).catch(function(err){
        console.error('[小手机] 合并写入失败，改为只写入本次条目', err);
        return hpWbWrite(TH, entries);
      });
    })
    .then(function(){ return hpWbActivate(TH); });   // 写完后确保已绑定到角色卡/聊天，否则 AI 读不到
}
// ——— 上传语义（2026-09-21 用户定）———
//  · 整体上传（身份卡页的按钮）：一次性把 app 所有条目写进同步书**并建书**。
//    只有它能建书；之后一切转为自动同步（换课/换座/日历标记 改了就去抖 1.2s 自动写，见 hpAuto*Sync）。
//  · 子页的「📤 上传」：兜底用 —— 立刻把该页那一条强制同步一次（不建书，走 partial，不碰别的条目）。
// 课表/座位表 只由自动同步写（走 hpSyncOne → hpWbSetEntry：**不建书**，书不存在时静默跳过）
function hpAutoSchedWrite(){ if(studentCache) hpSyncOne('学生助手·当前课表', 'sched', hpScheduleText(studentCache.schedule)); }
function hpAutoSeatsWrite(){ if(studentCache) hpSyncOne('学生助手·班级座位表', 'seats', hpSeatsText(studentCache.seats)); }
// ——— 各条目的策略集中在这里定义，避免「整体上传」与「自动同步」两边写法漂移 ———
// 座位表 / 任课教师 原先常驻，但只有"提到座位""提到老师"时才用得到 → 改触发（2026-09-21）
var HP_SEAT_KEYS=['座位','座位表','坐哪','坐在','换座','同桌','前排','后排'];
var HP_TEACHER_KEYS=['任课','授课','谁教','科任','这门课','这节课','老师','班主任'];
function hpEntryStrat(kind){
  if(kind==='sched')   return {type:'selective', keys:HP_SCHED_KEYS,    scan_depth:2};
  if(kind==='seats')   return {type:'selective', keys:HP_SEAT_KEYS,     scan_depth:2};
  if(kind==='teacher') return {type:'selective', keys:HP_TEACHER_KEYS,  scan_depth:2};
  return {type:'constant'};
}
// 单条目同步（书不存在时静默跳过，不建书）。content 为 null → 删除该条目
function hpSyncOne(name, kind, content){
  if(!hpIsTavern() || !hpWbApi()) return Promise.resolve(false);
  return hpWbSetEntry(name, content||null, false, hpEntryStrat(kind)).catch(function(e){
    console.warn('[小手机] 同步失败', name, e); return false;
  });
}
// 课表/座位表是拖拽出来的，一次拖拽会连改好几格 → 去抖 1.2s，只写最后一次
var hpSyncTimers={};
function hpSyncSoon(tag, fn){
  clearTimeout(hpSyncTimers[tag]);
  hpSyncTimers[tag]=setTimeout(function(){ try{ fn(); }catch(e){ console.warn(e); } }, 1200);
}
function hpAutoSchedSync(){ hpSyncSoon('sched', hpAutoSchedWrite); }
function hpAutoSeatsSync(){ hpSyncSoon('seats', hpAutoSeatsWrite); }
function hpAutoCardSync(){
  if(!studentCache) return;
  hpSyncSoon('card', function(){
    var c=studentCache.card||{};
    hpSyncOne('新中市·身份卡', 'card', hpCardText(c, studentCache.grades));
    var tTxt=(c.isStudent!==false) ? hpTeacherText(c.grade) : '';
    hpSyncOne('学生助手·任课教师', 'teacher', tTxt);   // 非学生/无教师编制 → 删掉该条目
  });
}
// 身份卡写进世界书的正文（含职业；学生额外带年级班级社团与成绩）
function hpCardText(c, grades){
  var lines=['【'+c.name+' 的身份卡】','姓名：'+c.name];
  lines.push('种族：'+(c.race||'—'));
  lines.push('性别：'+(c.gender||'—'));
  lines.push('年龄：'+(c.age||'—'));
  lines.push('职业：'+(c.job||'—'));
  if(c.isStudent!==false){
    lines.push('年级：'+(c.grade||'—'));
    lines.push('班级：'+(c.cls||'—'));
    lines.push('社团：'+(c.club||'未参加'));
  }
  if(grades && grades.length){
    var parts=[];
    for(var i=0;i<grades.length;i++) parts.push(grades[i].k+' '+grades[i].v);
    lines.push('成绩（各科满分100）：'+parts.join('　'));
  }
  return lines.join('\n');
}
function hpSyncWorld(from){
  if(!studentCache){ hpFeedback('⚠ 请先更新','stuFeedback'); return; }
  if(!hpIsTavern()){ hpFeedback('✓ 演示模式','stuFeedback'); return; }
  if(!hpWbApi()){ hpFeedback('⚠ 世界书 API 不可用','stuFeedback'); return; }
  var c=studentCache.card;
  var entries=[
    { name:'新中市·身份卡', enabled:true, strategy:{type:'constant'}, content:hpCardText(c, studentCache.grades) }
  ];
  if(c.isStudent!==false){
    // 完整周课表**不做常驻**：常驻时 AI 每轮都看到周一到周五整张表，会默认按第一列（周一）理解"今天上什么课"
    //（2026-09-21 用户报）。改成关键词触发 —— 日常由「新中市·今日」里的"当天那一列"供给，只有真的在讨论
    //课表安排（换课、明天上什么、下周的课）时才把整周表调进来。
    entries.push({ name:'学生助手·当前课表', enabled:true, strategy:hpEntryStrat('sched'), content:hpScheduleText(studentCache.schedule) });
    // 教师表：课表只说"这节是什么课"，不说谁来上 —— 缺这张表，AI 就会把课串给不相干的老师（2026-09-19 用户报）。
    // 该学部没有教师编制（小学/幼儿园等）时 hpTeacherText 返回空串，此时不写条目。
    var tTxt=hpTeacherText(c.grade);
    if(tTxt) entries.push({ name:'学生助手·任课教师', enabled:true, strategy:hpEntryStrat('teacher'), content:tTxt });
    entries.push({ name:'学生助手·班级座位表', enabled:true, strategy:hpEntryStrat('seats'), content:hpSeatsText(studentCache.seats) });
  }
  var t0=hpCalToday();
  var aux0=(hpRuleData&&hpRuleData.length)||(hpNotifData&&hpNotifData.length);
  // 日期未知但条目里有规则/通知时也要带上，否则 hpWbUpload 会把它当"本次没带的管理条目"删掉
  if(t0||aux0){ var tt=hpTodayEntryText(t0); if(tt) entries.push({name:'新中市·今日', enabled:true, strategy:{type:'constant'}, content:tt}); }
  hpFeedback('整体上传中…','stuFeedback');
  hpWbUpload(entries).then(function(){
    // 书到这一步才真正存在 → 其余条目立刻补写一次
    //（它们只有「更新」没有「建书」能力，书不存在时会被静默挡掉，所以必须跟在整体上传后面）
    if(hpRelData) hpRelSave();
    hpBatSave();
    if(galleryPhotos && galleryPhotos.length) hpGallerySave();
    try{ hpUploadCalendarInner(); }catch(e){}
    if(boardData){ try{ hpBoardSyncWb(boardData, boardRk); }catch(e){} }
    hpWbWarnCheck();     // 书建起来了 → 立刻收掉首页提示
    hpFeedback('✓ 已整体上传（之后自动同步）','stuFeedback');
  })
  .catch(function(e){
    console.error('[小手机] 学生助手上传失败', e);
    var m=(e && (e.message || e)) ? String(e.message || e) : '未知错误';
    hpFeedback('⚠ 失败：'+m.slice(0,14),'stuFeedback');
  });
}
function hpScheduleText(sched){
  if(!sched || !sched.days || !studentCache) return '（无课表）';
  var c=studentCache.card||{};
  var who=String(c.name||'当前角色');
  var gc=String(c.grade||'')+String(c.cls||'');            // 如「高二A班」（grade=高二, cls=A班）
  var lines=['【'+who+(gc?('（'+gc+'）'):'')+'的课表】'];
  // 先把「怎么用这张表」说清楚，AI 才不会把课串到别的时间去：
  // 角色 → 年级/班级 → 星期（取哪一列）→ 节次（取哪一行）
  var head=(gc?('说明：'+who+'是'+gc+'的学生，本表就是「'+gc+'」这个班的固定周课表；')
               :('说明：本表是'+who+'所在班级的固定周课表；'))
    +'判断"这节课是什么"的顺序是：先确定今天是星期几 → 只取对应那一列 → 再按节次对照该列的行。'
    +'每节课**只能在自己那一行标注的时间范围内进行，不得跨到下一行的时间去**；'
    +'课间与午休不是上课时间。表中没有课的时段不要凭空安排课程。';
  lines.push(head);
  for(var d=0;d<7;d++){
    var list=sched.days[d]||[];
    if(!list.length) continue;
    var parts=[];
    for(var p=0;p<list.length;p++){
      var tl=(sched.times && sched.times[p])?sched.times[p]:('第'+(p+1)+'节');
      var lab=String((sched.labels && sched.labels[p])||'');
      var what=String(list[p]||'');
      if(!what) continue;                       // 周末/空行不写，免得模型把空当成"自习"
      if(lab && lab===what) parts.push(tl+' '+lab);        // 如「11:00-12:30 午休」
      else if(lab) parts.push(tl+' '+lab+' '+what);        // 如「8:30-9:10 第一节 语文」
      else parts.push(tl+' '+what);
    }
    if(!parts.length) continue;
    lines.push(STU_DAYS[d]+'：'+parts.join('；'));
  }
  return lines.join('\n');
}
// 任课教师表：让 AI 知道"这节的科目由哪位老师上"，避免把课串给不相干的老师。
// 数据源＝「新-新中市教育局/老师」里解析出的该学部教师编制（hpParseTeachers）。
function hpTeacherText(grade){
  if(!studentCache) return '';
  var c=studentCache.card||{};
  var g=grade||c.grade||'';
  var fac=hpFacultyOf(g);
  var all=(fac && studentCache.teachers && studentCache.teachers[fac]) ? studentCache.teachers[fac].teachers : null;
  if(!fac || !all || !all.length) return '';      // 该学部没有教师编制（如小学/幼儿园）→ 不写条目
  var who=String(c.name||'当前角色');
  var gc=String(c.grade||'')+String(c.cls||'');
  // 有班级 → 只写本班的任课安排：科目→老师一一对应，AI 没有在年级段里挑人的余地
  if(gc){
    var subs=hpSubjectList(fac), hr0=hpHomeRoomOf(fac, gc), q, rows=[], hasOv=false;
    for(q=0;q<subs.length;q++){
      var nm=hpAssignedTeacher(fac, gc, subs[q]);
      if(!nm) continue;
      var ov=hpTOvOf(fac, gc, subs[q]);
      if(ov && ov.to){
        hasOv=true;
        rows.push(subs[q]+'：'+nm+'（代课）—— 原任课「'+hpAssignedTeacherRaw(fac,gc,subs[q])
                  +'」因故由「'+nm+'」代为授课（'+String(ov.why||'代课')+'）');
      } else rows.push(subs[q]+'：'+nm);
    }
    if(!rows.length) return '';
    var out=['【'+who+'（'+gc+'）的任课教师】'];
    out.push('说明：这是「'+gc+'」这一个班的任课安排，**每个科目只有一位老师**，照此写就好。'
      +'判断"这节是谁上"：看课表上这一节的**科目** → 到本表取对应的那位老师。'
      +'**不要换成别的老师，也不要把别的科目的老师安到这一节上**；表里查不到的科目就当自习或代课，不要现编人名。');
    if(hasOv) out.push('注：标了**（代课）**的科目，当前由代课老师上 —— 原任课老师因故（请假／出差／调课等）'
      +'请人代为授课。剧情里可以顺着这件事自然交代缘由，但**不要改回原老师**。');
    if(hr0) out.push('班主任：'+hr0.name+'（任教'+hr0.subject+'）');
    for(q=0;q<rows.length;q++) out.push(rows[q]);
    return out.join('\n');
  }
  // 没有班级（大学生选课制等）→ 退回列出该年级段的教师编制
  var lines=['【'+who+'的任课教师】'];
  lines.push('说明：本表列出「'+fac+'」各科目的任课老师。判断"这节是谁上"：先看课表这一节的**科目** → 到本表找**同名科目** → 从该科老师里选一位。'
    +'**不要用本表之外的老师，也不要把别的科目的老师安到这一节上**；表里查不到的科目，就当自习或代课，不要现编人名。');
  var order=[], map={}, j;
  for(j=0;j<all.length;j++){
    var t=all[j], k=t.subject||'其他';
    // 非教学职员（行政/后勤）不是授课老师，列进来只会让 AI 把他们安到课上 —— 直接剔除
    if(/非教学|职员|行政|后勤|教务/.test(k)) continue;
    if(!map[k]){ map[k]=[]; order.push(k); }
    map[k].push(t);
  }
  for(var m=0;m<order.length;m++){
    var arr=map[order[m]], ns=[];
    for(var n=0;n<arr.length;n++){
      ns.push(arr[n].name + ((arr[n].hr && arr[n].cls) ? ('（'+arr[n].cls+'班主任）') : ''));
    }
    lines.push(order[m]+'（'+arr.length+'人）：'+ns.join('、'));
  }
  return lines.join('\n');
}
function hpSeatsText(seats){
  if(!seats || !seats.desks || !seats.names || !studentCache) return '（无座位表）';
  var lines=['【'+studentCache.card.name+' 的班级座位表】'];
  lines.push('符号说明：[ ] 表示一张双人课桌；写在同一对 [ ] 内、用 ｜ 隔开的两个名字即为同桌——两人共用一张课桌、左右紧邻，是全班物理距离最近的一对，日常互动、传纸条、交头接耳都发生在同桌之间。「｜」左侧为左座、右侧为右座。读取本表时请以 [ ] 的成对关系判断同桌，不要只按排数理解。');
  lines.push('讲台');
  var pairs=[];
  for(var r=0;r<seats.rows;r++){
    var row='';
    for(var c=0;c<seats.cols;c++){
      var desk=seats.desks[r][c];
      row+='['+(desk.left||'空')+'｜'+(desk.right||'空')+']';
      if(c<seats.cols-1) row+=' ';
      if(desk.left && desk.right) pairs.push(desk.left+' = '+desk.right);
    }
    lines.push('第'+(r+1)+'排：'+row);
  }
  if(pairs.length) lines.push('同桌配对（同一行两人为同桌）：'+pairs.join('；'));
  return lines.join('\n');
}
// ═══ 关系账本：手动加减为主，必要时一键让 AI 结算最近剧情 ═══
// 写进同步世界书「新中市·关系账本」（常驻条目）→ AI 在主聊天里也能看到亲密度，
// 世界书那条「夫妻实习课：亲密度 ≥90 否则下学期继续配对」才真正可玩。
var HP_REL_ENTRY='新中市·关系账本';
