var hpRelEditIdx=-1;         // 正在编辑的行（-1=新增）
function hpRelFeedback(t){ hpFeedback(t,'relFeedback'); }
function hpRelParse(text){
  var s=String(text||''), owner='', list=[], lines=s.split(/\r?\n/), i;
  var mo=s.match(/当前角色\s*[:：]\s*([^\n]+)/); if(mo) owner=String(mo[1]).trim();
  for(i=0;i<lines.length;i++){
    var m=lines[i].match(/^\s*[-•·]\s*([^｜|\n]+?)\s*[｜|]\s*亲密度\s*(\d{1,3})\s*([\s\S]*)$/);
    if(!m) continue;
    var rest=String(m[3]||''), tag='', recent='';
    var mt=rest.match(/标签\s*[:：]\s*([^｜|\n]*)/); if(mt) tag=mt[1].trim();
    var mr=rest.match(/最近\s*[:：]\s*([^｜|\n]*)/); if(mr) recent=mr[1].trim();
    list.push({name:m[1].trim(), aff:Math.max(0,Math.min(100,parseInt(m[2],10)||0)), tag:tag, recent:recent});
  }
  return {owner:owner, list:list};
}
function hpRelText(d){
  var lines=['【新中市 · 关系账本】'];
