  if(!d.list.length) lines.push('（暂无记录）');
  for(var i=0;i<d.list.length;i++){
    var r=d.list[i];
    lines.push('- '+r.name+'｜亲密度 '+r.aff+'｜标签：'+(r.tag||'—')+'｜最近：'+(r.recent||'—'));
  }
  return lines.join('\n');
