function hpRelExtract(){
  hpRelFeedback('提取中…');
  hpReadMessages().then(function(msgs){
    var arr=Array.isArray(msgs)?msgs:[], replies=[], i;
    for(i=arr.length-1;i>=0 && replies.length<5;i--){          // 只取最近 5 条「酒馆回复」
      var m=arr[i]||{};
      if(m.is_user===true) continue;
      var t=String(m.mes||m.content||m.message||'').trim();
      if(t) replies.push(t);
    }
    if(!replies.length){ hpRelFeedback('⚠ 读不到最近的回复'); return null; }
    return hpContactsLoad().then(function(d){
      var text=replies.join('\n'), cand=[], seen={}, gi, ri, nm, c;
      for(gi=0;gi<d.groups.length;gi++){
        var g=d.groups[gi];
        for(ri=0;ri<g.names.length;ri++){
          nm=g.names[ri];
          if(nm.length<2 || seen[nm]) continue;
          c=text.split(nm).length-1;
          if(c<=0) continue;                                     // 出现过才算
          seen[nm]=1;
          var inBook=!!hpRelFind(nm);
          cand.push({name:nm, sub:g.name+(d.clubOf[nm]?(' · '+d.clubOf[nm]):''), hits:c, at:text.indexOf(nm), sel:!inBook, inBook:inBook});
        }
      }
      cand.sort(function(a,b){ return (b.hits-a.hits)||(a.at-b.at); });   // 提得多、出现得早的排前面
      hpRelCand=cand;
      hpRelRender();
      hpRelFeedback(cand.length?('✓ 找到 '+cand.length+' 个角色，勾选后保存'):'（没匹配到名册里的角色）');
    });
  }).catch(function(e){ hpRelFeedback('⚠ 提取失败：'+String((e&&e.message)||e).slice(0,14)); });
}
