// ——— 换聊天清空同步书里本 app 的条目 ———
// 书是共用的一个文件、且按角色卡绑定 → 不清的话新聊天会读到上一场聊天的身份卡/课表/今日/关系等。
var HP_SYNC_MARK='新中市·同步标记';
// 书里记着"这份数据属于哪个聊天"：打开手机时对不上说明是上一场聊天留下的 → 清空
function hpSyncMarkCheck(){
  var TH=hpWbApi(); if(!TH || !hpWbExists(TH)) return Promise.resolve(false);
  var cid=hpTavernChatId(); if(!cid) return Promise.resolve(false);
  return hpWbRead(TH, HP_SYNC_WB).then(function(eb){
    var mark='', i;
    for(i=0;i<eb.length;i++){ if(hpWbEntryName(eb[i])===HP_SYNC_MARK) mark=String(eb[i].content||''); }
    if(!mark){                                  // 旧版书（改造前建的、没有聊天标记）→ 里面只可能是旧数据，清掉并说明
      var hasApp=false;
      for(i=0;i<eb.length;i++){ if(HP_APP_ENTRIES.indexOf(hpWbEntryName(eb[i]))>=0){ hasApp=true; break; } }
      if(!hasApp) return false;
      hpToast('检测到旧版同步书（没有聊天标记），已清空 —— 需要时在小手机里点「📤 上传」重建');
      return hpSyncBookClear();
    }
    if(mark.indexOf(cid)>=0) return false;        // 就是当前聊天，保留
    // 标记里没带 chatId（写入时读不到 / 格式异常）→ **无法证明是别的聊天，宁可保留也不要清**。
    // 清掉的代价是把身份卡缓存/课表/今日一起毁掉，而保留最多只是数据偏旧（2026-09-17 加固）。
    var mcid=mark.match(/聊天：\s*(\S+)/);
    if(!mcid || !mcid[1]){ return false; }
    return hpSyncBookClear();                     // 确实是别的聊天 → 整本清掉
  }).catch(function(){ return false; });
}
var HP_APP_ENTRIES=['新中市·身份卡','学生助手·当前课表','学生助手·任课教师','学生助手·班级座位表','学生助手·学生证','新中市·布告板',
                    '新中市·今日','新中市·关系账本','新中市·催眠规则','新中市·小手机状态','新中市·相册','新中市日历·标记',
                    '新中市·身份卡缓存', HP_SYNC_MARK];
function hpSyncBookClear(){
  var TH=hpWbApi(); if(!TH || !hpWbExists(TH)) return Promise.resolve(false);
  hpWbInvalidate();
  return hpWbRead(TH, HP_SYNC_WB).then(function(existing){
    var others=[], removed=0, i;
    for(i=0;i<existing.length;i++){
      var e=existing[i], nm=hpWbEntryName(e);
      if(HP_APP_ENTRIES.indexOf(nm)>=0){ removed++; continue; }
      others.push(hpWbNormalize(e));            // 玩家自己写的条目要留着
    }
    // 书里没有本 app 的条目 → 根本没清掉任何东西，不能进入抑制态：
    // 否则今日/电量/相册/关系/规则的自动写入会全部静默停摆，用户看不出原因
    if(!removed) return false;
    // ⚠ 不再「整本删掉并解绑」（2026-09-17 改）：删书不可逆，任何一次误判都会把玩家的
    //   身份卡缓存/课表/今日/关系一起毁掉，还得手动重新上传才能恢复。改成**只清空 app 的条目、
    //   书留着** —— 效果相同（新聊天照样读不到旧数据），代价只是一个空书，而书还在就仍能自动写入。
    var act = hpWbWrite(TH, others);
    return Promise.resolve(act).then(function(){
      hpSyncSuppressed=true;                   // 清完先别再自动写：等玩家点「📤 上传」再恢复
      try{ hpWbWarnCheck(); }catch(e){}        // 首页提示条立刻亮起来
      return true;
    });
  }).catch(function(e){ hpWarn('同步书清理失败：'+((e&&e.message)||e)); return false; });
}
