// ═══ 手机通知：15~20 分钟自动来一条（角色私信 / 无聊推送）═══
// 未读以 +N 角标挂在悬浮球右上角（外壳每秒读 window.parent.__hpBadge）；
// 展开手机后显示在「今天」卡里：私信点开跳对应私信页，推送点一下清除。全部随今天卡同步进世界书。
var hpNotifData=[], hpNotifPending=null, hpNotifTimer=null;
function hpNotifParse(sec){
  var out=[], lines=String(sec||'').split(/\r?\n/), i;
  for(i=0;i<lines.length;i++){
    var m=lines[i].match(/^\s*[-•·]\s*\[(私信|推送)\]\s*([^：:\n]+)[：:]\s*([\s\S]*?)(?:\s*[｜|]\s*([^\n]*))?\s*$/);
    if(!m) continue;
    out.push({type:(m[1]==='私信'?'dm':'ad'), from:String(m[2]||'').trim(), text:String(m[3]||'').trim(), at:String(m[4]||'').trim()||hpRuleAt()});
  }
  return out;
}
function hpNotifBadge(){
  try{ window.parent.__hpBadge=hpNotifData.length; }catch(e){}
}
function hpNotifLoad(force){
  if(hpNotifPending && !force) return hpNotifPending;
  var TH=window.parent.TavernHelper;
  hpNotifPending = hpWbRead(TH, HP_SYNC_WB).then(function(eb){
    var txt='';
    for(var i=0;i<eb.length;i++){ if(hpWbEntryName(eb[i])===HP_TODAY_ENTRY) txt=String(eb[i].content||''); }
    hpNotifData=hpNotifParse(hpEntrySection(txt,'【手机通知'));
    while(hpNotifData.length>8) hpNotifData.shift();          // 读回来也限一下，防止旧数据超长
    hpNotifPending=null;
    hpNotifBadge();
    return hpNotifData;
  }).catch(function(e){ hpNotifData=[]; hpNotifPending=null; hpWarn('通知读取失败：'+((e&&e.message)||e)); return hpNotifData; });
  return hpNotifPending;
}
// 通知栏（像真手机）：主页顶部「N 条通知」，下拉展开、上滑收起
var hpShadeOpenFlag=false;
function hpShadeEl(){ return document.getElementById('hpShade'); }
function hpShadeH(){ var e=hpShadeEl(); return e?e.getBoundingClientRect().height:0; }
function hpShadeSet(y, anim){
  var e=hpShadeEl(); if(!e) return;
  e.style.transition=anim?'transform .18s ease-out':'none';
  e.style.transform='translateY('+Math.round(y)+'px)';
  e.style.pointerEvents=(y>-1)?'auto':'none';
  // ⚠ touch-action 是「与祖先求交」的：#hpShade 的 none 和 #phoneHome 的 pan-x 会把
  //   子元素 #shadeList 的 pan-y 抵消掉 → 通知列表滑不动、底部几条被裁（2026-09-18 用户报）。
  //   打开时把手机容器的约束放开（列表自带 overscroll-behavior:contain，不会带动页面滚动），
  //   关闭时清掉内联样式、让 CSS 的 pan-x 重新生效。
  try{
    var ph=e.parentElement;
    if(ph) ph.style.touchAction=(y>-1)?'auto':'';
  }catch(err){}
}
function hpShadeOpen(){ hpShadeOpenFlag=true; hpShadeSet(0,true); hpShadeRender(); }
function hpShadeClose(){ hpShadeOpenFlag=false; hpShadeSet(-hpShadeH(),true); }
function hpShadeRender(){
  var list=document.getElementById('shadeList');
  var c=document.getElementById('shadeCount');
  if(c) c.textContent=hpNotifData.length;
  if(list){
    if(!hpNotifData.length) list.innerHTML='<div class="shadeEmpty">没有新通知</div>';
    else {
      var h='', i;
      for(i=0;i<hpNotifData.length;i++){
        var n=hpNotifData[i];
        h+='<div class="shadeItem" onclick="hpNotifTap('+i+')">'
          +'<span class="siIcon">'+(n.type==='dm'?'💬':'📢')+'</span>'
          +'<span class="siBody"><span class="siFrom">'+hpEsc(n.from)+'</span>'
          +'<div class="siText">'+hpEsc(n.text)+'</div>'
          +'<div class="siAt">'+(n.type==='dm'?'私信':'推送')+' · '+hpEsc(n.at)+(n.media?(' · '+(n.media.kind==='photo'?'📷 照片':'🎵 歌曲')):'')+'</div></span></div>';
      }
      list.innerHTML=h;
    }
  }
  var t=document.getElementById('notifBarTxt');
  if(t) t.innerHTML=hpNotifData.length?('📩 <b>'+hpNotifData.length+'</b> 条通知 · 下拉查看'):'📩 暂无通知 · 下拉查看';
  if(hpShadeOpenFlag && !hpShadeEl().style.transform) hpShadeSet(0,false);
}
function hpNotifRefresh(){
  hpNotifBadge();
  hpShadeRender();
  hpTodaySig=''; hpRenderToday();
  hpSyncTodayEntry(true);
}
// 同一角色连续发私信时：通知栏**只保留最新一条**（用户要求），但被替换掉的旧消息不能丢 ——
// 私信只有在"点开通知"那一刻才写进聊天记录，若不暂存，除最后一条外全部再也看不到（2026-09-17 用户报的 bug）。
var hpNotifPend={};        // 角色名 -> [{text,at,media}]，按到达先后
function hpNotifPendPush(from, it){
  if(!it || !it.text) return;
  var q=hpNotifPend[from]||(hpNotifPend[from]=[]);
  q.push({text:it.text, at:it.at, media:it.media||null});
  while(q.length>10) q.shift();     // 上限，避免长聊堆爆
}
function hpNotifAdd(list){
  var changed=0, i, k;
  for(i=0;i<(list||[]).length;i++){
    var n=list[i]; if(!n || !n.text) continue;
    var isDm=(n.type==='dm');
    // 角色有几率"发东西给玩家看"：照片(画面描写) / 歌曲(歌名)
    var md=null;
    if(n.media && n.media.kind && n.media.data){
      var mk=(n.media.kind==='music')?'music':'photo';
      md={kind:mk, data:String(n.media.data).slice(0, mk==='photo'?300:40)};
    }
    var it={type:(isDm?'dm':'ad'), from:String(n.from||(isDm?'某人':'新中市')).slice(0,18), text:String(n.text).slice(0,60), at:hpRuleAt(), media:md};
    // 同一角色（dm）已有未读通知 → **不新增**，只把那一条的内容和时间换成最新的。
    //（用户要求：连续发消息时要替代，不能堆成一串；通知数不增加，内容和时间取最新）
    var hit=-1;
    if(isDm){
      for(k=0;k<hpNotifData.length;k++){
        if(hpNotifData[k].type==='dm' && hpNotifData[k].from===it.from){ hit=k; break; }
      }
    }
    if(hit>=0){ hpNotifPendPush(it.from, hpNotifData[hit]); hpNotifData[hit].text=it.text; hpNotifData[hit].at=it.at; hpNotifData[hit].media=it.media; changed++; }
    else { hpNotifData.push(it); changed++; }

  }
  if(!changed) return 0;
  // 上限 8 条：通知只靠点击才会消失，不点会无限堆进「今日」常驻条目 → 会白白吃上下文
  // 被挤掉的若是一条私信，先入「待补写」队列，别让它无声消失
  while(hpNotifData.length>8){ var _sh=hpNotifData.shift(); if(_sh && _sh.type==='dm') hpNotifPendPush(_sh.from, _sh); }
  hpNotifRefresh();
  return changed;
}
function hpNotifTap(i){
  var n=hpNotifData[i]; if(!n) return;
  var wasDm=(n.type==='dm'), from=n.from;
  hpNotifData.splice(i,1);
  hpNotifRefresh();
  if(wasDm){
    hpShadeClose(); hpShowTab('snsTab'); openDM(from, from, true);
    // 点开时才把这条私信写进聊天记录：私信页是从聊天记录恢复气泡的（写完了再恢复才读得到）
    var write=Promise.resolve();
    var tn=hpHHMMOf(n.at);
    var mediaObj=null, msgs=[];
    if(hpIsTavern()){
      // ⚠ 时间必须用**通知生成时的剧情时间**（n.at）：玩家可能过很久才点开，
      // 用"点进来那一刻"会让角色变成"刚刚才发消息"（用户报过这个问题）。
      // 先把「被后来的消息替换掉」的那几条按到达顺序补写回去，再写当前这条 ——
      // 否则同一角色连发时，除最后一条外全都不会进聊天记录，点进私聊页就看不到（2026-09-17 用户报的 bug）。
      var pendQue=(hpNotifPend[from]||[]).slice(); delete hpNotifPend[from];
      var allMsg=pendQue.concat([{text:n.text, at:n.at, media:n.media||null}]);
      for(var qi=0;qi<allMsg.length;qi++){
        var itm=allMsg[qi];
        var tnq=hpHHMMOf(itm.at);      // 每条用**它自己生成时**的剧情时间，不用点开那一刻
        var headq='【对方私信】@'+from+'（'+from+'）'+(tnq?('['+tnq+']'):'')+'：';
        msgs.push({role:'user',message:headq+itm.text,content:headq+itm.text});
        // 通知带了媒体（照片/歌曲）→ 单独写一行，恢复时会被还原成媒体气泡
        if(itm.media && itm.media.kind && itm.media.data){
          var moq=hpPushMedia(itm.media.kind, itm.media.data);
          if(qi===allMsg.length-1) mediaObj=moq;    // 兜底气泡只画最新那条的媒体
          var mlq=headq+hpMediaLine(from, moq.kind, moq.data);
          msgs.push({role:'user',message:mlq,content:mlq});
        }
      }
      try{ write=Promise.resolve(createChatMessages(msgs,{refresh:'none'})); }catch(e){}
    }
    write.then(function(){ return hpRestoreDM(from, from); }).then(function(found){
      if(!found){   // 聊天读不回来时兜底：直接把这条画成气泡（媒体也要画）
        addBubble('L', n.text, tn);
        if(mediaObj) addBubbleMedia('L', mediaObj.kind, mediaObj.data, mediaObj.idx, tn);
      }
    });
  }
  else hpToast('已清除推送：'+from);
}
function hpNotifGen(){
  if(!hpIsTavern() || !hpTodayAuxReady) return;
  var TH=window.parent.TavernHelper;
  if(!TH || !TH.generateRaw) return;
  Promise.all([hpLoadWorldbooks(TH), hpReadMessages()]).then(function(res){
    var entries=res[0]||[], msgs=res[1]||[];
