function hpExtractDate(t){
  var s=String(t||'');
  var m=s.match(/(20\d{2})\s*[年\-\/\.]\s*(\d{1,2})\s*[月\-\/\.]\s*(\d{1,2})\s*日?/);
  if(m) return m[1]+'年'+parseInt(m[2])+'月'+parseInt(m[3])+'日';
  m=s.match(/(\d{1,2})\s*月\s*(\d{1,2})\s*日/);
  if(m){
    var w=s.match(/星期([一二三四五六日天])|周([一二三四五六日天])|礼拜([一二三四五六日天])/);
    var wd=w?(w[1]||w[2]||w[3]):'';
    var base=parseInt(m[1])+'月'+parseInt(m[2])+'日';
    if(wd) base+=' 星期'+(wd==='天'?'日':wd);
    return base;
  }
  var w2=s.match(/星期([一二三四五六日天])|周([一二三四五六日天])|礼拜([一二三四五六日天])/);
  if(w2){
    var wd2=w2[1]||w2[2]||w2[3];
    return '星期'+(wd2==='天'?'日':wd2);
  }
  return '';
}
function hpExtractTime(t){
  var s=String(t||'');
  var m=s.match(/(\d{1,2})[:：](\d{2})/);
  if(m) return (m[1].length<2?'0':'')+m[1]+':'+m[2];
  var m2=s.match(/(凌晨|清晨|早上|早晨|上午|中午|正午|下午|傍晚|黄昏|晚上|夜里|深夜|夜晚)?\s*(\d{1,2})\s*[点时]\s*(半|(\d{1,2})\s*分)?/);
  if(m2){
    var part=m2[1]||'';
    var h=parseInt(m2[2]);
    var mm=(m2[3]==='半')?30:(m2[4]?parseInt(m2[4]):0);
    if(/凌晨|清晨/.test(part)){ if(h===12)h=0; }
    else if(/下午|傍晚|黄昏|晚上|夜里|深夜|夜晚/.test(part)){ if(h<12)h+=12; }
    else if(/中午|正午/.test(part)){ if(h<12)h+=12; }
    if(h>23)h=23;
    return (h<10?'0':'')+h+':'+(mm<10?'0':'')+mm;
  }
  return '';
}
// 日期/时间转可比较数值（无年份日期按同年处理）
function hpDateKey(d){
  if(!d) return null;
  var m=d.match(/(\d{4})年(\d{1,2})月(\d{1,2})日/);
  if(m) return (+m[1])*10000 + (+m[2])*100 + (+m[3]);
  var m2=d.match(/(\d{1,2})月(\d{1,2})日/);
  if(m2) return (+m2[1])*100 + (+m2[2]);
  return null;
}
function hpTimeKey(t){
