// 三级取数：① 主页 DOM 直读（最轻）→ ② 旧版 ST 的全局 chat → ③ TavernHelper API（节流兜底，避免频繁拉取整份聊天记录）
function hpSyncTime(){
  // ① 主页面 DOM 直读（最轻）
  var all=hpReadChatDomAll(40);
  if(all && all.length){ hpSyncFromList(all); return; }
  // ② 旧版酒馆的全局 chat 数组
  var chat=null;
  try{ var p=window.parent; chat=(p&&p.chat)||null; }catch(e){ chat=null; }
  if(chat && chat.length){ hpSyncFromList(chat); return; }
  // ③ API 兜底（多签名尝试，8 秒节流）——只走一条签名会读不到聊天，日期就永远推不出来
  if(hpClockBusy) return;
  var t=Date.now();
  if(hpApiLast && t-hpApiLast<8000) return;
  hpApiLast=t;
  hpClockBusy=true;
  hpReadMessages().then(function(msgs){
    hpClockBusy=false;
    hpSyncFromList(msgs);
  }).catch(function(){ hpClockBusy=false; hpUpdateClockDisplay(); });
}
function hpSyncFromList(list){
  if(Array.isArray(list) && list.length){
