          // 手动校准过：锚点只在剧情推进到**更晚的日期**时让位（防止被更早的旧日期覆盖回去）。
          // 但**同一天**内剧情往前走，时刻必须跟着走 —— 否则校准带时刻时（如 2025年3月14日 13:34），
          // 时钟会永远停在那一刻，之后再怎么演都不动（2026-09-20 用户报）。
          var c=hpDateCmp(d,hpManualDate);
          if(c>0){ hpManualDate=null; hpStoryDate=hpClockKeep(hpStoryDate,d); }
          else if(c===0){
            var merged=hpClockKeep(hpStoryDate,d);
