// ——— 从剧情推断「今天」 ———
// 先找最近一条出现的绝对日期作锚点，再把锚点之后的相对时间词（第二天/三天后/下周…）累加上去；
// 没有绝对日期时，退而用剧情里提到的日历事件名反推。
// 关键：全程只依据剧情，绝不用真实系统日期顶替——否则会凭空造出一个日期并和剧情冲突。
var hpStoryDate=null;   // {y,m,d,time,src} 由剧情推断出的"今天"；推断不出则为 null
// 玩家手动校准的锚点（终极保险）：自动推断推不出来时用；一旦剧情出现更晚的日期就自动让位
var hpManualDate=null;
// 剧情时钟**不许后退**：同一天内，从剧情里推断出的时刻若早于已知时刻，保留已知（更晚）的那个。
// 否则剧情里随便一句「11点见」「早上我去了…」都会把时钟拽回去，通知时间就会出现在剧情开始之前
//（2026-09-17 用户报的「剧情从 12 点开始、通知却显示 11 点」就是这个）。
function hpClockKeep(prev, next){
  if(!next) return prev;
  if(!prev) return next;
  if(prev.y===next.y && prev.m===next.m && prev.d===next.d){
    var pt=String(prev.time||''), nt=String(next.time||'');
    // 新推断没解析出时刻（nt 为空）时也保留旧的：否则已知时刻会被''抹掉，
    // 后续 hpStoryHHMM 会退回真实系统时钟，又造出与剧情冲突的时间。
    if(pt && (!nt || nt < pt)) next.time = pt;   // 'HH:MM' 已补零，可直接字典序比较
  }
  return next;
}
function hpDateCmp(a,b){
  var A=a.y*10000+a.m*100+a.d, B=b.y*10000+b.m*100+b.d;
  return A===B ? 0 : (A>B ? 1 : -1);
}
var hpDomKey='', hpApiLast=0, hpClockBusy=false;
function hpCnNum(s){
  s=String(s||'').trim();
  if(/^\d+$/.test(s)) return parseInt(s,10);
  var map={'零':0,'一':1,'两':2,'二':2,'三':3,'四':4,'五':5,'六':6,'七':7,'八':8,'九':9};
  if(s==='十') return 10;
  if(s.length===1) return (map[s]!==undefined)?map[s]:0;
  var m=s.match(/^([一二三四五六七八九])?十([一二三四五六七八九])?$/);
  if(m) return (m[1]?map[m[1]]:1)*10+(m[2]?map[m[2]]:0);
  return 0;
}
function hpParseAbsDate(t, defYear){
  var m=String(t||'').match(/(?:(\d{4})\s*年\s*)?(\d{1,2})\s*月\s*(\d{1,2})\s*日/);
  if(!m) return null;
  var y=m[1]?parseInt(m[1],10):(defYear||HP_GAME_YEAR);
  var mo=parseInt(m[2],10), d=parseInt(m[3],10);
  if(mo<1||mo>12||d<1||d>31) return null;
  return {y:y, m:mo, d:d};
}
// 句中出现"昨天/明天"且修饰的是那个日期时，要换算成"今天"
// （「昨天是9月1日」→ 今天 9/2；「明天是9月1日」→ 今天 8/31）
function hpParseAbsOffset(t){
  var s=String(t||'');
  if(/前天/.test(s)) return 2;
  if(/昨天|昨日/.test(s)) return 1;
  if(/明天|明日/.test(s)) return -1;
  if(/后天/.test(s)) return -2;
  return 0;
}
function hpParseRelOffset(t){
  var s=String(t||''), off=0, m;
  if(/(次日|翌日|第二天|第二日|隔天|转天)/.test(s)) off+=1;
  m=s.match(/([零一二两三四五六七八九十\d]+)\s*天\s*(?:后|之后|以后)/);
  if(m) off+=hpCnNum(m[1]);
  m=s.match(/([零一二两三四五六七八九十\d]+)\s*(?:周|星期|礼拜)\s*(?:后|之后|以后)/);
  if(m) off+=7*hpCnNum(m[1]);
  if(/下\s*(?:周|星期|礼拜)/.test(s)) off+=7;
  return off;
}
// 事件名的多种写法：整名 / 逗号或斜杠前的主名 / 去掉「日·活动·周·期间」尾缀
// 剧情里写「社团招新」也要能命中表里的「社团招新日」
function hpEventKeys(n){
  var out=[], base=String(n||'').replace(/[（(][^）)]*[）)]/g,'').trim();
  if(base.length<2) return out;
  out.push(base);
  var head=base.split(/[，,、／\/·]/)[0].trim();
  if(head.length>=2 && out.indexOf(head)<0) out.push(head);
  var arr=out.slice();
  for(var i=0;i<arr.length;i++){
    var k=arr[i].replace(/(日|活动|周|期间)$/,'').trim();
    if(k.length>=2 && out.indexOf(k)<0) out.push(k);
  }
  return out;
}
function hpParseEventDate(t){
  var s=String(t||''), i, q, keys;
  for(i=0;i<CAL_SCHOOL.length;i++){
    var e=CAL_SCHOOL[i];
    keys=hpEventKeys(e.n);
    for(q=0;q<keys.length;q++){
      if(s.indexOf(keys[q])>=0) return {y:HP_GAME_YEAR, m:e.m1, d:e.d1, m2:e.m2, d2:e.d2, time:'', src:'事件·'+e.n};
    }
  }
  for(i=0;i<CAL_FIXED.length;i++){
    if(s.indexOf(CAL_FIXED[i][2])>=0) return {y:HP_GAME_YEAR, m:CAL_FIXED[i][0], d:CAL_FIXED[i][1], m2:CAL_FIXED[i][0], d2:CAL_FIXED[i][1], time:'', src:'节日·'+CAL_FIXED[i][2]};
  }
  return null;
}
// 某天是否落在事件区间内
function hpInEvtRange(y,m,d,ev){
  if(!ev) return false;
