function hpInferStoryDate(list){
  if(!Array.isArray(list)||!list.length) return null;
  var texts=[], i, n=list.length, from=Math.max(0, n-40);
  for(i=from;i<n;i++){
    var m=list[i]; if(!m||typeof m!=='object') continue;
    var t=m.mes; if(typeof t!=='string'||!t) continue;
    texts.push(t);
  }
  if(!texts.length) return null;
  var time=hpExtractTime(texts[texts.length-1])||'';
  // ① 最近的绝对日期作锚点
  var anchor=null, at=-1;
  for(i=texts.length-1;i>=0;i--){
    var a=hpParseAbsDate(texts[i], HP_GAME_YEAR);
    if(a){ anchor=a; at=i; break; }
  }
  if(anchor){
    // 锚点之后若提到校历事件（如"今天是社团招新日"），以事件日期为准——
    // 比一个更早的绝对日期更贴近当下，否则会一直停在开学那天
    for(i=texts.length-1;i>at;i--){
      var ev0=hpParseEventDate(texts[i]);
      if(ev0){
        if(hpInEvtRange(anchor.y,anchor.m,anchor.d,ev0)) break;   // 锚点本身就落在这个事件期内 → 锚点更精确，用它
        var eoff=0;
        for(var q=i+1;q<texts.length;q++) eoff+=hpParseRelOffset(texts[q]);
        var edt=new Date(ev0.y, ev0.m-1, ev0.d);
        if(eoff) edt=new Date(edt.getTime()+eoff*86400000);
        return {y:edt.getFullYear(), m:edt.getMonth()+1, d:edt.getDate(), time:time, src:ev0.src};
      }
    }
    var off=hpParseAbsOffset(texts[at]);          // "昨天是9月1日" → 今天 9/2
    for(i=at+1;i<texts.length;i++) off+=hpParseRelOffset(texts[i]);
    var dt=new Date(anchor.y, anchor.m-1, anchor.d);
    if(off) dt=new Date(dt.getTime()+off*86400000);
    return {y:dt.getFullYear(), m:dt.getMonth()+1, d:dt.getDate(), time:time, src:'剧情日期'};
  }
  // ② 没有绝对日期时，用剧情提到的日历事件反推（如"今天是社团招新日"）
  for(i=texts.length-1;i>=0;i--){
    var ev=hpParseEventDate(texts[i]);
    if(ev){ ev.time=time; return ev; }
  }
  return null;
}
