// 把「4月8日–4月20日」「5月中上旬」「7月下旬–8月底」「3月上旬（10日左右）」「1月7–8日」解析成月/日区间
function hpCalSpecToRange(spec){
  var s=String(spec||'').trim();
  var m0=s.match(/^(\d{1,2})\s*月/);
  var topM=m0?parseInt(m0[1],10):0;
  function one(part, defM){
    part=String(part||'').trim();
    var m=defM, mm=part.match(/(\d{1,2})\s*月/); if(mm) m=parseInt(mm[1],10);
    if(!m||m<1||m>12) return null;
    var days=hpCalDaysInMonth(HP_GAME_YEAR,m);
    var dd=part.match(/(\d{1,2})\s*日/);
    if(dd){ var d=parseInt(dd[1],10); if(d<1||d>31) return null; return {m:m,a:d,b:d}; }
    var bare=part.match(/月\s*(\d{1,2})\s*$/);   // 「1月7」这种不带"日"的写法
    if(bare){ var bd=parseInt(bare[1],10); if(bd>=1&&bd<=31) return {m:m,a:bd,b:bd}; }
    if(/中上旬/.test(part)) return {m:m,a:1,b:20};
    if(/上旬/.test(part))  return {m:m,a:1,b:10};
    if(/中旬/.test(part))  return {m:m,a:11,b:20};
    if(/下旬/.test(part))  return {m:m,a:21,b:days};
    if(/底/.test(part))    return {m:m,a:days-2,b:days};
    return {m:m,a:1,b:days};
  }
  var paren=s.match(/[（(]\s*(\d{1,2})\s*日左右\s*[）)]/);
  var body=s.replace(/[（(][^）)]*[）)]/g,'').trim();
  var exact=/日/.test(body);   // 是否给出了确切日期（只有「上旬/中旬/下旬」这种模糊说法时为 false）
  var parts=body.split(/[–—~～或至到]|\s*-\s*/).filter(function(x){ return x.trim(); });
  if(!parts.length) return null;
  var A=one(parts[0], topM);
  if(!A) return null;
  var B=parts.length>1 ? one(parts[1], A.m) : A;
  if(!B) B=A;
  if(paren){   // 「3月上旬（10日左右）」这种 → 以括号里的确切日为准
    var pd=parseInt(paren[1],10);
    if(pd>=1&&pd<=31){ A={m:A.m,a:pd,b:pd}; B=A; exact=true; }
  }
  return {m1:A.m, d1:A.a, m2:B.m, d2:B.b, exact:exact};
}
// 从各活动小节里提取「为期N天」，用来修正时间轴里只给了模糊时段的条目
// （例如文化祭写「10月下旬–11月上旬」但实际「为期3天」，不该标成整整三周）
function hpCalParseDurations(text){
  var dur={}, name=null, lines=String(text||'').split(/\r?\n/), i;
  for(i=0;i<lines.length;i++){
    var ln=lines[i];
    var h=ln.match(/^\s*[零一二三四五六七八九十]+、\s*(.+?)\s*$/) || ln.match(/^\s*\d+\.\d+\s+(.+?)\s*$/);
    if(h){ name=h[1].replace(/[（(][^）)]*[）)]/g,'').trim(); continue; }
    var t=ln.match(/时间：([^\n]*)/);
    if(!t || !name || dur[name]) continue;
    var days=0, m=t[1].match(/为期\s*(\d+)\s*天/);
    if(m) days=parseInt(m[1],10);
    if(days>0) dur[name]=days;
  }
  return dur;
}
// 模糊时段且没写时长的活动，按单日标；寒暑假春假保持整段
function hpCalApplyDuration(item, spec, durMap){
  var k, days=0, keys=hpEventKeys(item.n);
  for(k in durMap){
    if(!Object.prototype.hasOwnProperty.call(durMap,k)) continue;
    var kk=hpEventKeys(k);
    for(var a=0;a<keys.length;a++){ for(var b=0;b<kk.length;b++){ if(keys[a]===kk[b]){ days=durMap[k]; break; } } if(days) break; }
    if(days) break;
  }
  if(days>0){
    var end=new Date(HP_GAME_YEAR, item.m1-1, item.d1+days-1);
    item.m2=end.getMonth()+1; item.d2=end.getDate();
  } else if(!spec.exact && !/暑假|寒假|春假|樱花|夏日祭|纳凉/.test(item.n)){
    item.m2=item.m1; item.d2=item.d1;   // 时段模糊又没写时长 → 按单日标
  }
  return item;
}
// 从「新-特殊事件」正文里抓活动：① 时间轴行「日期 ···· 名称」② 各小节里的「时间：…」
function hpCalParseSchoolEvents(text){
  var out=[], lines=String(text||'').split(/\r?\n/), i;
  var durMap=hpCalParseDurations(text);
  function markFes(it){
    if(/夏日祭|纳凉祭典|花火大会|樱花季|赏花|新年参拜|跨年校园晚会|情人节|七夕祭|圣诞节/.test(it.n)) it.t='fes';
    return it;
  }
  // ① 时间轴行
  for(i=0;i<lines.length;i++){
    var m=lines[i].match(/^\s*(\d{1,2}\s*月[^·…\n]{0,16}?)\s*[·…]{1,}\s*(.+?)\s*$/);
    if(!m) continue;
    var r=hpCalSpecToRange(m[1]);
    if(!r) continue;
    var nm=m[2].replace(/[（(][^）)]*[）)]/g,'').trim();
    if(!nm) continue;
    out.push(markFes(hpCalApplyDuration({m1:r.m1,d1:r.d1,m2:r.m2,d2:r.d2,n:nm}, r, durMap)));
  }
  // ② 小节里的「时间：」——补上时间轴没列的活动（如海滩合宿）
  var seen={};
  for(i=0;i<out.length;i++){
    var ks=hpEventKeys(out[i].n);
    for(var z=0;z<ks.length;z++) seen[ks[z]]=1;
  }
  function already(it){
    var kk=hpEventKeys(it);
    for(var z2=0;z2<kk.length;z2++){ if(seen[kk[z2]]) return true; }
    return false;
  }
  var dname=null;
  for(i=0;i<lines.length;i++){
    var ln=lines[i];
    if(/^\s*[零一二三四五六七八九十]+、/.test(ln)){ dname=null; continue; }   // 一级章节标题本身不是活动
    var h=ln.match(/^\s*\d+\.\d+\s+(.+?)\s*$/);   // 「3.1 修学旅行」这类子标题
    if(h){ dname=h[1].replace(/[（(][^）)]*[）)]/g,'').trim(); continue; }
    var t=ln.match(/时间：([^\n]*)/);
    if(!t || !dname) continue;
    var spec=t[1].replace(/^每年/,'').split(/[，,。]/)[0].trim();
    if(!spec) continue;
    var r2=hpCalSpecToRange(spec);
    if(!r2) continue;
    if(already(dname)) continue;   // 时间轴里已有同名的，别重复
    var kk2=hpEventKeys(dname);
    for(var z3=0;z3<kk2.length;z3++) seen[kk2[z3]]=1;
    out.push(markFes(hpCalApplyDuration({m1:r2.m1,d1:r2.d1,m2:r2.m2,d2:r2.d2,n:dname}, r2, durMap)));
  }
  return out;
}
