// 某天的全部事件：type = fes(节日) / evt(校历) / mine(自定义)
function hpCalEventsOf(y,m,d){
  var out=[];
  for(var i=0;i<CAL_FIXED.length;i++){
    if(CAL_FIXED[i][0]===m && CAL_FIXED[i][1]===d) out.push({n:CAL_FIXED[i][2], type:'fes'});
  }
  var lu=CAL_LUNAR[y];
  if(lu){ for(var j=0;j<lu.length;j++){ if(lu[j][0]===m && lu[j][1]===d) out.push({n:lu[j][2], type:'fes'}); } }
  for(var q=0;q<CAL_SCHOOL.length;q++){
    var e=CAL_SCHOOL[q];
    if(hpCalInRange(y,m,d,e)) out.push({n:e.n, type:(e.t||'evt'), start:(m===e.m1&&d===e.d1)});
  }
  var key=hpCalKey(y,m,d);
  for(var w=0;w<CAL_MARKS.length;w++){ if(CAL_MARKS[w].d===key) out.push({n:CAL_MARKS[w].t, type:'mine', mi:w}); }
  return out;
}
function hpCalInRange(y,m,d,e){
  var cur=m*100+d, a=e.m1*100+e.d1, b=e.m2*100+e.d2;
  if(a<=b) return cur>=a && cur<=b;
  return cur>=a || cur<=b;   // 跨年/跨月范围（如寒假、寒假跨 1-2 月）
}
function hpCalRangeLen(e){
  if(e.m1===e.m2) return e.d2-e.d1+1;
  return 31;   // 跨月按长区间处理（只做底色，不写字）
}
// 剧情当天：只用从剧情推断出的日期；推不出来就返回 null（绝不拿系统日期冒充剧情日期）
function hpCalToday(){
  if(!hpStoryDate) return null;
  return { y:hpStoryDate.y, m:hpStoryDate.m, d:hpStoryDate.d, time:hpStoryDate.time||'', src:hpStoryDate.src||'' };
