var hpSyncSuppressed=false;      // 刚清空过（或书还没建）：自动流程一律不写，等「📤 上传」
function hpWbSetEntry(name, content, allowCreate, strategy){
  var TH=hpWbApi(); if(!TH) return Promise.reject(new Error('世界书 API 不可用'));
  if(!allowCreate && hpSyncSuppressed){ hpWbNeedUploadSuppressed(); return Promise.resolve(false); }
  var ST=strategy||{type:'constant'};
  // 自动流程（今日条目/关系账本/催眠规则/电量/相册）不许自己把书建出来，
  // 否则开新聊天就会凭空多出一本带旧数据的书。只有「📤 上传」那条路传 allowCreate=true。
  if(!allowCreate && !hpWbExists(TH)){ hpWbNeedUpload(); return Promise.resolve(false); }
  hpWbInvalidate();
  return hpWbEnsure(TH).then(function(){ return hpWbRead(TH, HP_SYNC_WB); }).then(function(existing){
    var out=[], found=false, i;
    for(i=0;i<existing.length;i++){
      var e=existing[i], nm=hpWbEntryName(e);
      if(nm===name){
        found=true;
        if(content===null) continue;                       // content=null → 删除该条目
        out.push({name:name, enabled:true, strategy:ST, content:content});
      } else out.push(hpWbNormalize(e));
    }
    if(!found && content!==null) out.push({name:name, enabled:true, strategy:ST, content:content});
    return hpWbWrite(TH, out);
  }).then(function(){ return hpWbActivate(TH); });
}
