// 某校历活动是否覆盖指定月份（4/15-4/16 只算 4 月；仅跨年区间如 12月→1月 才用环状判断）
function hpCalRangeHitsMonth(e, m){
  if(e.m1<=e.m2) return m>=e.m1 && m<=e.m2;
  return m>=e.m1 || m<=e.m2;
}
// 上传日历到共用世界书（只更新「新中市日历·标记」这一个条目，不动学生助手等其它条目）
function hpUploadCalendarInner(){
  if(!hpIsTavern()){ hpCalFeedback('✓ 已上传（演示模式，仅本地）'); return; }
  if(!hpWbApi()){ hpCalFeedback('⚠ 世界书 API 不可用'); return; }
  var Y=hpCalY, M=hpCalM, i;
  var pad=hpCalPad;
  var lines=['【新中市日历 · 标记】',''];
  lines.push('（本条目由小手机日历上传；玩家标记格式：YYYY-MM-DD 内容）');
  lines.push('');

  // ① 玩家标记
  var sorted=CAL_MARKS.slice().sort(function(a,b){ return a.d<b.d?-1:(a.d>b.d?1:0); });
  lines.push('【玩家标记】');
  if(sorted.length){
    for(i=0;i<sorted.length;i++) lines.push(sorted[i].d+' '+sorted[i].t);
  } else {
    lines.push('（暂无，可在小手机日历里点日期添加）');
  }
  lines.push('');

  // ② 当前剧情日期 / 正在进行 —— 让 AI 一眼知道现在处于什么状态（在不在寒暑假等）
  var cur=hpCalToday();
  lines.push('【当前剧情日期】');
  if(cur){
    lines.push(cur.y+'-'+pad(cur.m)+'-'+pad(cur.d)+(cur.time?(' '+cur.time):''));
    var te=hpCalEventsOf(cur.y,cur.m,cur.d), tn=[];
    for(i=0;i<te.length;i++) tn.push(te[i].n);
    lines.push('当天：'+(tn.length?tn.join('、'):'无特殊安排'));
    var ongoing=[];
    for(i=0;i<CAL_SCHOOL.length;i++){
      var oe=CAL_SCHOOL[i];
      if(hpCalInRange(cur.y,cur.m,cur.d,oe)) ongoing.push(oe.n+'（'+oe.m1+'/'+oe.d1+' ~ '+oe.m2+'/'+oe.d2+'）');
    }
    lines.push('正在进行：'+(ongoing.length?ongoing.join('、'):'无'));
  } else {
    lines.push('（小手机未能从剧情中推断出日期——请一律以剧情正文为准，不要把小手机显示的时间当作剧情时间，也不要据此编造日期）');
  }
  lines.push('');

  // ③ 全年长期活动（跨月或多日）—— 不论当前翻到哪个月都完整列出，
  //    否则只看 9 月时就会漏掉「7/1~8/31 暑假」这类跨月状态
  var longs=[];
  for(i=0;i<CAL_SCHOOL.length;i++){
    var le=CAL_SCHOOL[i];
    if(le.m1===le.m2 && (le.d2-le.d1+1)<=7) continue;
    longs.push(le);
  }
  if(longs.length){
    lines.push('【长期活动（跨月/多日·全年）】');
    for(i=0;i<longs.length;i++){
      var e4=longs[i];
      lines.push(Y+'-'+pad(e4.m1)+'-'+pad(e4.d1)+' ~ '+Y+'-'+pad(e4.m2)+'-'+pad(e4.d2)+'　'+e4.n);
    }
    lines.push('');
  }

  // ④ 当月日程：节日 + 校历 + 玩家标记，多日条目一律写完整起止日期
  lines.push('【'+Y+'年'+M+'月 日程】');
  var rows=[];
  for(i=0;i<CAL_FIXED.length;i++){
    if(CAL_FIXED[i][0]===M) rows.push({d:CAL_FIXED[i][1], s:Y+'-'+pad(M)+'-'+pad(CAL_FIXED[i][1]), n:CAL_FIXED[i][2], t:'节日'});
  }
  var lu=CAL_LUNAR[Y];
  if(lu){ for(i=0;i<lu.length;i++){ if(lu[i][0]===M) rows.push({d:lu[i][1], s:Y+'-'+pad(M)+'-'+pad(lu[i][1]), n:lu[i][2], t:'节日'}); } }
  for(i=0;i<CAL_SCHOOL.length;i++){
    var se=CAL_SCHOOL[i];
    if(!hpCalRangeHitsMonth(se,M)) continue;
    var rs=Y+'-'+pad(se.m1)+'-'+pad(se.d1), re=Y+'-'+pad(se.m2)+'-'+pad(se.d2);
    rows.push({d:se.d1, s:(rs===re?rs:(rs+' ~ '+re)), n:se.n, t:'校历'});
  }
  for(i=0;i<sorted.length;i++){
    var mk=sorted[i].d.match(/^(\d{4})-(\d{2})-(\d{2})$/);
    if(!mk) continue;
    if(parseInt(mk[1],10)!==Y || parseInt(mk[2],10)!==M) continue;
    rows.push({d:parseInt(mk[3],10), s:sorted[i].d, n:sorted[i].t, t:'标记'});
  }
  rows.sort(function(p,q){ return p.d-q.d; });
  if(rows.length){
    for(i=0;i<rows.length;i++) lines.push('['+rows[i].t+'] '+rows[i].s+'　'+rows[i].n);
  } else {
    lines.push('（本月暂无日程）');
  }
  var entryContent=lines.join('\n');
  // 同课表/座位表：走 hpSyncOne（不建书，书不存在时静默跳过）
  hpSyncOne('新中市日历·标记', 'cal', entryContent);
}
