// ——— 主页下拉刷新（酒馆没有新输出时也能手动重取日期时间）———
var pullStartY=0, pullOn=false, pullDist=0, pullBusy=false, pullEl=null, pullPid=null, pullInList=false;
var PULL_TRIGGER=60;
function hpPullStart(e){
  var home=document.getElementById('phoneHome');
  if(!home || home.style.display==='none') return;
  pullStartY=e.clientY; pullDist=0; pullOn=false; pullEl=home; pullPid=e.pointerId;
  pullInList=!!(e.target && e.target.closest && e.target.closest('#shadeList'));
}
function hpPullMove(e){
  if(!pullEl || e.pointerId!==pullPid || pullBusy) return;
  var dy=e.clientY-pullStartY;
  if(hpShadeOpenFlag && pullInList){                    // 通知列表里滑动 → 交给列表自己滚，别收栏
    var lst=document.getElementById('shadeList');
    if(lst && lst.scrollTop>0) return;
  }
  if(!pullOn){
    if(Math.abs(dy)<8) return;
    if(!hpShadeOpenFlag && dy<0) return;          // 关着时只认"下拉"
    pullOn=true;
    try{ pullEl.setPointerCapture(e.pointerId); }catch(err){}
    if(e.preventDefault) e.preventDefault();
  }
  var H=hpShadeH(); if(!H) return;
  if(!hpShadeOpenFlag) hpShadeSet(-H+Math.max(0,Math.min(dy,H)), false);   // 手指跟着往下走
  else hpShadeSet(Math.max(-H,Math.min(0,dy)), false);                     // 开着时跟着往上滑
  pullDist=dy;
}
function hpPullEnd(e){
  if(pullPid!==null && e && e.pointerId!==undefined && e.pointerId!==pullPid) return;
  var was=pullOn, dy=pullDist;
  pullOn=false; pullDist=0; pullEl=null; pullPid=null;
  if(!was) return;
  var H=hpShadeH();
  if(!hpShadeOpenFlag){ if(dy>H*0.25) hpShadeOpen(); else hpShadeClose(); }   // 拉过 1/4 就展开
  else { if(dy<-H*0.25) hpShadeClose(); else hpShadeOpen(); }                // 上滑过 1/4 就收起
}
