            Object.keys(songs).forEach(function (k) { map[k] = songs[k]; });
        });
        Object.keys(BAND_SONGS).forEach(function (k) { map[k] = BAND_SONGS[k]; });
        Object.keys(SOLO_SONGS).forEach(function (k) { map[k] = pickUrl(SOLO_SONGS[k]); });
        Object.keys(STAGE_SONGS).forEach(function (k) { map[k] = STAGE_SONGS[k]; });
        return map;
    }

    var DONE = '__song_audio_done';

    function normName(raw) {
        return (raw || '').trim().replace(/^《+|》+$/g, '').replace(/^【+|】+$/g, '').trim();
    }

    function audioHtml(url, name, icon) {
        return '<span style="display:inline-flex;align-items:center;gap:8px;vertical-align:middle;margin:2px 0;">' +
            '<span style="color:#10a37f;font-weight:600;">' + (icon || '🎵') + ' ' + name + '</span>' +
            '<audio controls preload="none" title="' + name + '" src="' + url + '" style="height:34px;"></audio>' +
            '</span>';
    }

    // 取值：字符串（单 URL）原样返回；数组（同名多版本）随机选一
    function pickUrl(v) {
        if (!v) return null;
        return Array.isArray(v) ? v[Math.floor(Math.random() * v.length)] : v;
    }

    // 匹配三种标记，一次扫描完成（避免二次 replace 误处理生成的 <audio>）：
    //   唱歌：【歌曲：歌名】（全角方括号）；
    //   演奏：【演奏：曲目】（纯乐器无歌唱，渲染/上下文用「弹奏」而非「唱」）；
    //   演出：【演出：剧目】（情景剧/舞台剧演绎，非合唱非演奏）；
    //   退化兜底（曲名）（全角/半角圆括号）——仅命中歌库才替换，其余保留原样
    var RE_SONG = /【歌曲：\s*([^】]+?)\s*】|【演奏：\s*([^】]+?)\s*】|【演出：\s*([^】]+?)\s*】|（\s*([^）]+?)\s*）|\(\s*([^)]+?)\s*\)/g;

    function inject(message_id) {
        var mes = ST.chat[message_id];
        if (!mes || mes.is_user || mes.is_system) return;
        if (mes.extra && mes.extra[DONE]) return;

        var text = mes.mes || '';
        var SONG_MAP = buildSongMap();
        var SOLO_MAP = SOLO_SONGS;
        var STAGE_MAP = STAGE_SONGS;

        // 渲染：命中唱歌歌名 → 🎵+唱；命中独奏曲目 → 🎼+弹奏；命中情景剧 → 🎭+演绎
        function render(full, songName, soloName, stageName, parenFull, parenHalf) {
            if (songName) {
                var n = normName(songName);
                var u = SONG_MAP[n];
                return u ? audioHtml(u, n, '🎵') : full;
            }
            if (soloName) {
                var s = normName(soloName);
                var su = pickUrl(SOLO_MAP[s]);
                return su ? audioHtml(su, s, '🎼') : full;
            }
            if (stageName) {
                var st = normName(stageName);
                var stu = STAGE_MAP[st];
                return stu ? audioHtml(stu, st, '🎭') : full;
            }
            // 圆括号兜底：先当独奏曲目查，再当情景剧查，最后当唱歌歌名查
            var p = normName(parenFull || parenHalf);
            var sp = pickUrl(SOLO_MAP[p]);
            if (sp) return audioHtml(sp, p, '🎼');
            if (STAGE_MAP[p]) return audioHtml(STAGE_MAP[p], p, '🎭');
            var pu = SONG_MAP[p];
            return pu ? audioHtml(pu, p, '🎵') : full;
        }
        // 上下文：唱歌标记 → 「（唱了《歌名》）」；演奏标记 → 「（弹奏了《曲目》）」；演出标记 → 「（演绎了《剧目》）」
        function cleanUp(full, songName, soloName, stageName, parenFull, parenHalf) {
            if (songName) {
                var n = normName(songName);
                return SONG_MAP[n] ? '（唱了《' + n + '》）' : full;
            }
            if (soloName) {
                var s = normName(soloName);
                return SOLO_MAP[s] ? '（弹奏了《' + s + '》）' : full;
            }
            if (stageName) {
                var st = normName(stageName);
                return STAGE_MAP[st] ? '（演绎了《' + st + '》）' : full;
            }
            var p = normName(parenFull || parenHalf);
            if (SOLO_MAP[p]) return '（弹奏了《' + p + '》）';
            if (STAGE_MAP[p]) return '（演绎了《' + p + '》）';
            return SONG_MAP[p] ? '（唱了《' + p + '》）' : full;
        }

        var display = text.replace(RE_SONG, render);
        // 没匹配到任何已收录歌/曲 → 不改动、也不设 DONE（保持可重试，避免流式早期提前锁定）
        if (display.indexOf('<audio') === -1) return;

        var clean = text.replace(RE_SONG, cleanUp);

        if (!mes.extra) mes.extra = {};
        mes.extra[DONE] = true;
        mes.mes = clean;
        mes.extra.display_text = display;

        ST.updateMessageBlock(message_id, mes);
        if (typeof ST.saveChat === 'function') ST.saveChat();
    }

    function schedule(id) {
        var mid = parseInt(id, 10);
        if (isNaN(mid)) return;
        setTimeout(function () { inject(mid); }, 400);
    }

    // 多事件兜底：inject 内部有 DONE 防重 + 未匹配不设 DONE，重复触发安全
    eventOn(tavern_events.MESSAGE_RECEIVED, schedule);
    eventOn(tavern_events.CHARACTER_MESSAGE_RENDERED, schedule);
    eventOn(tavern_events.MESSAGE_UPDATED, schedule);
})();

/* 逃向夏日·MVU Schema（公路旅行）—— 卡内自包含接入
 * 顶层根：旅程 / 关系 / user / 雪乃 / 话语（与卡内既有 6 模块 22 键零重叠，stat_data 浅合并安全）
 * 模块感知：仅当世界书「【模块总览】逃向夏日」处于启用时才产出 schema，避免污染 stat_data
 * 静默规则：若 Ruby宇宙 MVU 统一注册中心已把「逃向夏日」纳入 MVU_MODS，本脚本自动让位，不重复注册 */
const HW = (() => { try { if (window.parent && window.parent !== window) return window.parent; } catch (_) {} return window; })();
(function () {
  'use strict';
  const SLOT = '__RUBY_TX_MVU__';
  if (HW[SLOT]) { try { console.log('[ruby-tx] 已装载，跳过重复执行'); } catch (_) {} return; }
  HW[SLOT] = true;
  const MOD = '逃向夏日';
  const fn = (name) => {
    const scopes = [];
    try { scopes.push(window, window.TavernHelper); } catch (_) {}
    try { scopes.push(HW, HW.TavernHelper); } catch (_) {}
    for (const s of scopes) { try { if (s && typeof s[name] === 'function') return s[name].bind(s); } catch (_) {} }
    return null;
  };
  let active = null; /* null=未探查(宽松:照常产出schema，漏注册比多注册有害) | true=模块开启 | false=模块关闭 */
  async function probe() {
    try {
      const getNames = fn('getCharWorldbookNames'), getWB = fn('getWorldbook');
      if (!getNames || !getWB) return;
      const n = await Promise.resolve(getNames('current'));
      const bn = String((n && (n.primary || n.name)) || '');
      if (!bn) return;
      const ents = await Promise.resolve(getWB(bn));
      if (!Array.isArray(ents) || !ents.length) return;
      let on = false;
      for (const e of ents) {
        if (String(e.comment || '') === '【模块总览】' + MOD) on = (e.enabled === true) || (e.enabled === undefined && e.disable !== true);
      }
      active = on;
    } catch (_) {}
  }
  function shape() {
    const S = (d) => z.string().prefault(d === undefined ? '' : d);
    const pct = (d) => z.coerce.number().transform(v => _.clamp(v, 0, 100)).prefault(d);
    return {
      旅程: z.object({
        天数: z.coerce.number().transform(v => _.clamp(v, 0, 999)).prefault(1),
        当前站: S('出逃夜'), 下一站: S('富良野'), 天气: S('雨'),
        资金档位: z.enum(['充裕', '一般', '紧张', '见底']).prefault('充裕'),
        旁白: S(''),
        载具: z.object({ 名称: S('租来的车'), 状态: S('正常') }).prefault({}),
      }).prefault({}),
      关系: z.object({
        亲近度: pct(0),
        越界阶梯: z.coerce.number().transform(v => _.clamp(v, 0, 5)).prefault(0),
        伪壳完整度: pct(100),
      }).prefault({}),
      user: z.object({ 情绪: pct(30), 自责: pct(60), 身体: S('疲惫'), 疲劳: pct(70) }).prefault({}),
      雪乃: z.object({ 压力: pct(20), 状态: S('强撑'), 心理: S('') }).prefault({}),
      话语: z.record(z.string(), z.coerce.boolean()).prefault({}),
    };
  }
  (async () => {
    let reg = null;
    const CDNS = ['https://testingcf.jsdelivr.net/gh/StageDog/tavern_resource/dist/util/mvu_zod.js',
                  'https://cdn.jsdelivr.net/gh/StageDog/tavern_resource/dist/util/mvu_zod.js'];
    for (const u of CDNS) { try { const m = await import(u); reg = m.registerMvuSchema || null; if (reg) break; } catch (_) {} }
    if (typeof reg !== 'function') { try { console.warn('[ruby-tx] mvu_zod.js 加载失败，Schema 未注册（其余机制不受影响）'); } catch (_) {} return; }
    const t0 = Date.now();
    while (!Array.isArray(HW.__RUBY_MVU_MODS__) && Date.now() - t0 < 6000) await new Promise(r => setTimeout(r, 100));
    if (Array.isArray(HW.__RUBY_MVU_MODS__) && HW.__RUBY_MVU_MODS__.indexOf(MOD) >= 0) {
      try { console.log('[ruby-tx] 注册中心已接管「逃向夏日」，本脚本静默'); } catch (_) {}
      return;
    }
    try { reg(() => ((active === false) ? z.object({}) : z.object(shape()))); }
    catch (err) { try { console.warn('[ruby-tx] schema注册被拒绝:', err && err.message); } catch (_) {} return; }
    try { console.log('[ruby-tx] 逃向夏日 MVU Schema 已注册（模块感知）'); } catch (_) {}
  })();
  $(() => { probe(); setInterval(probe, 45000); });
  try { HW.addEventListener('ruby-mvu-refresh', () => setTimeout(probe, 300)); } catch (_) {}
})();

