  var LS_NOTES = 'xzs_notes';       // 最近一次更新的更新日志（app 的修复页会读它显示「本版更新」）
  var UPDATER_NAME = '【新中式】新中市更新器';   // 我自己这条脚本的名字（自更新时用）
