        });
        pregSfwSection.appendChild(pregSfwGrid);
        galleryContainer.appendChild(pregSfwSection);

        const pregNsfwSection = document.createElement("div");
        pregNsfwSection.innerHTML = `<div class="section-title">怀孕情境 · 私密 (NSFW)</div>`;
        const pregNsfwGrid = document.createElement("div");
        pregNsfwGrid.className = "grid";
        presetConfig.nsfw.forEach((variant) => {
          const url = getPregImageUrl(char, variant.key);
          pregNsfwGrid.appendChild(createGridItem(`怀孕·${variant.label}`, `${char.id}_pregnant_${variant.key}.png`, char.id, false, "pregnant_" + variant.key, char.name));
