      div.innerHTML = `
        <div class="grid-thumb">
          <button class="single-switch-btn" title="单独切换该立绘版本" onclick="event.stopPropagation(); toggleSingleImage('${charId}', '${variantKey}', ${isSfw})">🔄</button>
