          <div class="placeholder-text" style="${imgSrc ? "display:none;" : "display:block;"}">${fallbackAvatars[charId] || "?"}</div>
        </div>
        <div class="grid-info">
          <div class="grid-tag">${tag}</div>
          <div class="grid-filename">${filename}</div>
        </div>
      `;
      return div;
    }

    init();
</script>
