<script>

(function(){
  if(window.__cgMobileChoiceDeckPatch) return;
  window.__cgMobileChoiceDeckPatch = true;

  const names = ["沈漾","沈澪"];
  const info = {
    "沈漾": { cls:"sy", sub:"BUTTERFLY · CHARACTER ARCHIVE", mark:"🦋", sigil:"✦", index:"01" },
    "沈澪": { cls:"sl", sub:"SANCTUM · DUAL FORM ARCHIVE", mark:"✧", sigil:"◌", index:"02" }
  };

  function exactTextNodes(name){
    return Array.from(document.querySelectorAll('button,a,[role="button"],h1,h2,h3,h4,h5,p,span,div,strong,b'))
      .filter(el => el.children.length < 6 && (el.textContent || '').trim() === name);
  }

  function clickableFrom(el){
    let p = el;
    for(let i=0; p && p !== document.body && i<7; i++, p=p.parentElement){
      if(p.matches('button,a,[role="button"],[onclick]')) return p;
      const cs = String(p.className || '');
      if(/(?:character|char|hero|portrait|choice|select|entry)[-_ ]?(?:card|item|option|tile)?/i.test(cs) && p.querySelector('img')) return p;
    }
    return el.closest('button,a,[role="button"],[onclick]') || el;
  }

  function cardFrom(labelEl, name){
    const click = clickableFrom(labelEl);
    let best = click;
    let p = click;
    for(let i=0; p && p !== document.body && i<6; i++, p=p.parentElement){
      const text = (p.textContent || '');
      if(p.querySelector('img') && text.includes(name)){
        best = p;
        const r = p.getBoundingClientRect();
        if(r.width > 110 && r.width < Math.max(680, document.documentElement.clientWidth*.92)) break;
      }
    }
    return {card:best, click};
  }

  function commonAncestor(a,b){
    if(!a || !b) return null;
    const seen = new Set();
    let p=a;
    while(p){ seen.add(p); p=p.parentElement; }
    p=b;
    while(p){ if(seen.has(p)) return p; p=p.parentElement; }
    return null;
  }

  function firstImageSource(card){
    const img = card && card.querySelector('img');
    if(!img) return '';
    return img.currentSrc || img.getAttribute('src') || img.getAttribute('data-src') || img.getAttribute('data-lazy-src') || '';
  }

  function chooseLabel(name){
    const list = exactTextNodes(name);
    if(!list.length) return null;
    list.sort((a,b)=>{
      const ai = a.closest('button,a,[role="button"],[onclick]') ? 0 : 1;
      const bi = b.closest('button,a,[role="button"],[onclick]') ? 0 : 1;
      if(ai !== bi) return ai-bi;
      return a.children.length - b.children.length;
    });
    return list[0];
  }

  function build(){
    if(document.getElementById('cg-mobile-choice-deck')) return true;

    const found = {};
    for(const name of names){
      const label = chooseLabel(name);
      if(!label) return false;
      found[name] = cardFrom(label,name);
      if(!found[name].card) return false;
    }
    if(found["沈漾"].card === found["沈澪"].card) return false;

    let host = commonAncestor(found["沈漾"].card, found["沈澪"].card);
    if(!host || host === document.body || host === document.documentElement){
      host = found["沈漾"].card.parentElement;
    }
    if(!host) return false;

    found["沈漾"].card.classList.add('cg-mobile-source-card');
    found["沈澪"].card.classList.add('cg-mobile-source-card');

    const deck = document.createElement('div');
    deck.id = 'cg-mobile-choice-deck';
    deck.innerHTML = '<div class="cg-mobile-deck-kicker">SELECT CHARACTER</div><div class="cg-mobile-choice-grid"></div>';
    const grid = deck.querySelector('.cg-mobile-choice-grid');

    for(const name of names){
      const meta = info[name];
      const src = firstImageSource(found[name].card);
      const btn = document.createElement('button');
      btn.type = 'button';
      btn.className = `cg-mobile-choice ${meta.cls}`;
      btn.setAttribute('aria-label', `选择${name}`);
      btn.innerHTML = `
        <span class="cg-mobile-choice-index">${meta.index}</span>
        <span class="cg-mobile-choice-sigil" aria-hidden="true">${meta.sigil}</span>
        <span class="cg-mobile-choice-media">
          ${src ? `<img alt="${name}" src="${src}">` : ''}
          <span class="cg-mobile-choice-fallback" aria-hidden="true">${name.slice(-1)}</span>
        </span>
        <span class="cg-mobile-choice-caption">
          <span class="cg-mobile-choice-titlewrap">
            <span class="cg-mobile-choice-name">${name}</span>
            <span class="cg-mobile-choice-sub">${meta.sub}</span>
          </span>
          <span class="cg-mobile-choice-mark" aria-hidden="true">${meta.mark}</span>
        </span>`;

      const img = btn.querySelector('img');
      if(img){
        img.addEventListener('error',()=>btn.classList.add('no-image'),{once:true});
      } else {
        btn.classList.add('no-image');
      }

      btn.addEventListener('click',()=>{
        const target = found[name].click || found[name].card;
        try { target.click(); }
        catch(e){
          try { target.dispatchEvent(new MouseEvent('click',{bubbles:true,cancelable:true,view:window})); } catch(_e){}
        }
      });
      grid.appendChild(btn);
    }

    const firstCard = found["沈漾"].card;
    if(firstCard.parentElement === host){
      host.insertBefore(deck, firstCard);
    } else {
      host.insertBefore(deck, host.firstChild);
    }
    return true;
  }

  let tries = 0;
  function attempt(){
    if(build()) return;
    if(++tries < 18) setTimeout(attempt,180);
  }
  attempt();

  const observer = new MutationObserver(()=>{
    if(!document.getElementById('cg-mobile-choice-deck')) build();
  });
  try { observer.observe(document.body,{childList:true,subtree:true}); } catch(e){}
  setTimeout(()=>{ try{observer.disconnect()}catch(e){} },10000);
})();

