      const exampleForumXML = `<forum>$1</forum>`;

      // 解析论坛XML数据
      function parseForumXML(xmlText) {
        console.log("开始解析地下论坛数据...");
        const result = {
          basicInfo: {},
          nav: [],
          sticky: [],
          boards: [],
        };

        try {
          // 提取基本信息
          const basicInfoMatch = xmlText.match(
            /<basic_info>([\s\S]*?)<\/basic_info>/i
          );
          if (basicInfoMatch && basicInfoMatch[1]) {
            const basicInfoText = basicInfoMatch[1].trim();

            const nameMatch = basicInfoText.match(/\[论坛名\|([^\]]+)\]/);
            if (nameMatch) result.basicInfo.name = nameMatch[1];

            const welcomeMatch = basicInfoText.match(/\[欢迎语\|([^\]]+)\]/);
            if (welcomeMatch) result.basicInfo.welcome = welcomeMatch[1];

            const onlineMatch = basicInfoText.match(/\[在线人数\|([^\]]+)\]/);
            if (onlineMatch) result.basicInfo.online = onlineMatch[1];
          }

          // 提取导航栏
          const navMatch = xmlText.match(/<nav>([\s\S]*?)<\/nav>/i);
          if (navMatch && navMatch[1]) {
            const navText = navMatch[1].trim();
            const navRegex = /\[板块\|([^\]]+)\]/g;
            let match;
            while ((match = navRegex.exec(navText)) !== null) {
              if (match[1]) result.nav.push(match[1]);
            }
          }

          // 提取置顶帖
          const stickyMatch = xmlText.match(/<sticky>([\s\S]*?)<\/sticky>/i);
          if (stickyMatch && stickyMatch[1]) {
            const stickyText = stickyMatch[1].trim();
            const lines = stickyText.split("\n");
            lines.forEach((line) => {
              const trimmedLine = line.trim();
              if (
                trimmedLine.startsWith("[置顶|") &&
                trimmedLine.endsWith("]")
              ) {
                const content = trimmedLine.slice("[置顶|".length, -1);
                const parts = content.split("|");
                result.sticky.push({
                  title: parts[0] || "",
                  author: parts[1] || "",
                  tag: parts[2] || "",
                  bounty: parts[3] || "",
                });
              }
            });
          }

          // 提取板块内容
          const boardsMatch = xmlText.match(/<boards>([\s\S]*?)<\/boards>/i);
          if (boardsMatch && boardsMatch[1]) {
            const boardsText = boardsMatch[1];
            console.log("找到boards标签，内容长度:", boardsText.length);
            const boardRegex = /<board>([\s\S]*?)<\/board>/gi;
            let boardMatch;

            while ((boardMatch = boardRegex.exec(boardsText)) !== null) {
              const boardContent = boardMatch[1];
              const board = {
                name: "",
                desc: "",
                posts: [],
              };

              const boardNameMatch = boardContent.match(/\[板块名\|([^\]]+)\]/);
              if (boardNameMatch) board.name = boardNameMatch[1];

              const boardDescMatch =
                boardContent.match(/\[板块简介\|([^\]]+)\]/);
              if (boardDescMatch) board.desc = boardDescMatch[1];

              console.log(`解析板块: ${board.name}`);

              // 按行分割，找到所有[帖子|...]行
              const lines = boardContent.split("\n");
              lines.forEach((line) => {
                const trimmedLine = line.trim();
                if (
                  trimmedLine.startsWith("[帖子|") &&
                  trimmedLine.endsWith("]")
                ) {
                  // 去掉头尾的[帖子|和]
                  const content = trimmedLine.slice("[帖子|".length, -1);
                  const parts = content.split("|");
                  board.posts.push({
                    title: parts[0] || "",
                    author: parts[1] || "",
                    type: parts[2] || "",
                    replies: parts[3] || "0",
                    views: parts[4] || "0",
                    lastReply: parts[5] || "",
                  });
                }
              });

              console.log(`  ${board.name} 共 ${board.posts.length} 个帖子`);
              result.boards.push(board);
            }
            console.log("总共解析到", result.boards.length, "个板块");
          }

          console.log("地下论坛数据解析完成:", result);
          return result;
        } catch (error) {
          console.error("解析地下论坛XML出错:", error);
          return result;
        }
      }

      // 渲染论坛界面
      function renderForum(forumData) {
        console.log("开始渲染地下论坛界面...");

        let html = `
                <div class="forum-header">
                    <div class="forum-title">${
                      forumData.basicInfo.name || "地下论坛"
                    }</div>
                    <div class="forum-subtitle">${
                      forumData.basicInfo.welcome || ""
                    }</div>
                    <div class="forum-stats">
                        <span>👥 在线人数：<strong>${
                          forumData.basicInfo.online || "0"
                        }</strong></span>
                    </div>
                </div>
            `;

        // 导航栏
        if (forumData.nav.length > 0) {
          html += '<div class="forum-nav">';
          forumData.nav.forEach((nav) => {
            html += `<div class="nav-item" onclick="navigateTo('${nav}')">${nav}</div>`;
          });
          html += "</div>";
        }

        // 置顶帖
        if (forumData.sticky.length > 0) {
          html += '<div class="sticky-section">';
          html += '<div class="section-title">📌 置顶公告</div>';
          forumData.sticky.forEach((post) => {
            html += `
                        <div class="sticky-post" onclick="viewPost('${
                          post.title
                        }')">
                            <div class="post-title">${post.title}</div>
                            <div class="post-meta">
                                <span class="post-tag">${post.tag}</span>
                                <span>👤 ${post.author}</span>
                                ${
                                  post.bounty
                                    ? `<span class="post-bounty">💰 ¥${post.bounty}</span>`
                                    : ""
                                }
                            </div>
                        </div>
                    `;
          });
          html += "</div>";
        }

        // 板块内容
        forumData.boards.forEach((board, boardIndex) => {
          console.log(
            `渲染板块 #${boardIndex}: ${board.name}, 帖子数: ${board.posts.length}`
          );
          html += `
                    <div class="board-section" id="board-${boardIndex}">
                        <div class="board-header">
                            <div>
                                <div class="board-name">${board.name}</div>
                                <div class="board-desc">${board.desc}</div>
                            </div>
                        </div>
                `;

          board.posts.forEach((post, postIndex) => {
            console.log(
              `  板块 #${boardIndex} 帖子 #${postIndex}: ${post.title}`
            );
            html += `
                        <div class="post-item" onclick="viewPost('${post.title}')">
                            <div class="post-info">
                                <div class="post-left">
                                    <span class="post-type">${post.type}</span>
                                    <span class="post-title">${post.title}</span>
                                </div>
                                <div class="post-right">
                                    <span class="post-stat">💬 ${post.replies}</span>
                                    <span class="post-stat">👁️ ${post.views}</span>
                                    <span class="post-stat">🕐 ${post.lastReply}</span>
                                </div>
                            </div>
                        </div>
                    `;
          });

          html += "</div>";
          console.log(
            `板块 #${boardIndex} 渲染完成，共 ${board.posts.length} 个帖子`
          );
        });

        document.getElementById("content").innerHTML = html;
        console.log("地下论坛界面渲染完成");
      }

      // 查看帖子（发送触发命令）
      function viewPost(title) {
        if (typeof triggerSlash === "function") {
          triggerSlash(`/send 查看帖子：${title}|/trigger`);
        } else {
          alert("查看帖子：" + title);
        }
      }

      // 导航到不同板块（发送触发命令）
      function navigateTo(navName) {
        console.log(`导航点击: ${navName}`);
        if (typeof triggerSlash === "function") {
          const command = `/send 进入${navName}|/trigger`;
          console.log(`发送命令: ${command}`);
          triggerSlash(command);
        } else {
          console.warn("triggerSlash 函数不可用");
          alert("进入：" + navName);
        }
      }

      // 解析并渲染
      function parseAndRender() {
        console.log("========== 地下论坛美化页面调试信息 ==========");
        console.log("1. 开始解析示例XML数据");

        try {
          console.log("2. XML数据长度:", exampleForumXML.length);
          console.log(
            "3. XML数据前100字符:",
            exampleForumXML.substring(0, 100)
          );

          console.log("4. 开始XML解析...");
          const parsedData = parseForumXML(exampleForumXML);
          console.log("5. 解析结果:", parsedData);

          console.log("6. 开始渲染界面...");
          renderForum(parsedData);
          console.log("7. 渲染完成！");
        } catch (error) {
          console.error("解析错误:", error);
          console.error("错误堆栈:", error.stack);
          document.getElementById("content").innerHTML =
            '<div class="loading">❌ 数据解析失败<br><br>错误信息: ' +
            error.message +
            "<br><br>请查看控制台详细信息</div>";
        }
      }

      // 页面加载时解析数据
      document.addEventListener("DOMContentLoaded", parseAndRender);
    </script>
  </body>
</html>
