    <script>
      // 示例专栏XML数据 - 这个会被St的正则替换成AI输出的实际内容
      const exampleColumnXML = `<column>$1</column>`;

      // 解析专栏XML数据
      function parseColumnXML(xmlText) {
        console.log("开始解析玥咚咚专栏数据...");
        const result = {
          basicInfo: {},
          sticky: [],
          posts: [],
        };

        try {
          // 提取基本信息
          const basicInfoMatch = xmlText.match(
            /<basic_info>([\s\S]*?)<\/basic_info>/i
          );
          if (basicInfoMatch && basicInfoMatch[1]) {
            const basicInfoText = basicInfoMatch[1].trim();

            const nameMatch = basicInfoText.match(/\[专栏名\|([^\]]+)\]/);
            if (nameMatch) result.basicInfo.name = nameMatch[1];

            const descMatch = basicInfoText.match(/\[专栏简介\|([^\]]+)\]/);
            if (descMatch) result.basicInfo.desc = descMatch[1];

            const followMatch = basicInfoText.match(/\[关注数\|([^\]]+)\]/);
            if (followMatch) result.basicInfo.followers = followMatch[1];

            const postCountMatch =
              basicInfoText.match(/\[帖子总数\|([^\]]+)\]/);
            if (postCountMatch) result.basicInfo.postCount = postCountMatch[1];
          }

          // 提取置顶帖
          const stickyMatch = xmlText.match(/<sticky>([\s\S]*?)<\/sticky>/i);
          if (stickyMatch && stickyMatch[1]) {
            const stickyText = stickyMatch[1].trim();
            const lines = stickyText.split("\n");
            lines.forEach((line) => {
              const trimmedLine = line.trim();
              if (
                trimmedLine.startsWith("[置顶|") &&
                trimmedLine.endsWith("]")
              ) {
                const content = trimmedLine.slice("[置顶|".length, -1);
                const parts = content.split("|");
                result.sticky.push({
                  title: parts[0] || "",
                  tags: parts[1] || "",
                  views: parts[2] || "0",
                  time: parts[3] || "",
                });
              }
            });
          }

          // 提取帖子列表
          const postsMatch = xmlText.match(/<posts>([\s\S]*?)<\/posts>/i);
          if (postsMatch && postsMatch[1]) {
            const postsText = postsMatch[1].trim();
            const lines = postsText.split("\n");
            lines.forEach((line) => {
              const trimmedLine = line.trim();
              if (
                trimmedLine.startsWith("[帖子|") &&
                trimmedLine.endsWith("]")
              ) {
                const content = trimmedLine.slice("[帖子|".length, -1);
                const parts = content.split("|");
                result.posts.push({
                  title: parts[0] || "",
                  tags: parts[1] || "",
                  type: parts[2] || "",
                  replies: parts[3] || "0",
                  views: parts[4] || "0",
                  time: parts[5] || "",
                });
              }
            });
          }

          console.log("玥咚咚专栏数据解析完成:", result);
          return result;
        } catch (error) {
          console.error("解析专栏XML出错:", error);
          return result;
        }
      }

