            const tagHtml = tagArray
              .map((tag) => `<span class="column-tag">${tag}</span>`)
              .join("");

            html += `
                        <div class="sticky-post" onclick="viewPost('${post.title}')">
                            <div class="post-title">${post.title}</div>
                            <div class="post-meta">
                                ${tagHtml}
                                <span>👁️ ${post.views}</span>
                                <span>🕐 ${post.time}</span>
                            </div>
                        </div>
                    `;
          });
          html += "</div>";
        }

        // 帖子列表
        html += '<div class="column-posts">';
        columnData.posts.forEach((post) => {
          const tagArray = post.tags.match(/\[([^\]]+)\]/g) || [];
          const tagHtml = tagArray
            .map((tag) => `<span class="column-tag">${tag}</span>`)
            .join("");

          html += `
                    <div class="column-post" onclick="viewPost('${post.title}')">
                        <div class="column-post-title">
                            ${post.title}
