                        </div>
                        <div class="column-post-tags">
                            ${tagHtml}
                        </div>
                        <div class="column-post-meta">
                            <span>💬 ${post.replies} 回复</span>
                            <span>👁️ ${post.views} 浏览</span>
                        </div>
                        <div class="column-post-meta" style="margin-top: 10px;">
                            <span>🕐 ${post.time}</span>
                        </div>
                    </div>
                `;
        });
        html += "</div>";

        document.getElementById("content").innerHTML = html;
        console.log("玥咚咚专栏界面渲染完成");
      }

