  <body>
    <div class="container" id="content">
      <div class="loading">正在加载帖子内容</div>
    </div>

    <script>
      // 示例帖子XML数据 - 这个会被St的正则替换成AI输出的实际内容
      const examplePostXML = `<post>$1</post>`;

      // 解析帖子详情XML数据
      function parsePostXML(xmlText) {
        console.log("开始解析帖子详情数据...");
        const result = {
          basicInfo: {},
          stats: {},
          content: {},
          comments: [],
        };

        try {
          // 提取基本信息
          const basicInfoMatch = xmlText.match(
            /<basic_info>([\s\S]*?)<\/basic_info>/i
          );
          if (basicInfoMatch && basicInfoMatch[1]) {
            const basicInfoText = basicInfoMatch[1].trim();

            const titleMatch = basicInfoText.match(/\[标题\|([^\]]+)\]/);
            if (titleMatch) result.basicInfo.title = titleMatch[1];

            const authorMatch = basicInfoText.match(/\[作者\|([^\]]+)\]/);
            if (authorMatch) result.basicInfo.author = authorMatch[1];

            const timeMatch = basicInfoText.match(/\[发布时间\|([^\]]+)\]/);
            if (timeMatch) result.basicInfo.time = timeMatch[1];

            const boardMatch = basicInfoText.match(/\[所属板块\|([^\]]+)\]/);
            if (boardMatch) result.basicInfo.board = boardMatch[1];

            const tagsMatch = basicInfoText.match(/\[标签\|([^\]]+)\]/);
            if (tagsMatch) result.basicInfo.tags = tagsMatch[1];
          }

          // 提取统计数据
          const statsMatch = xmlText.match(/<stats>([\s\S]*?)<\/stats>/i);
          if (statsMatch && statsMatch[1]) {
            const statsText = statsMatch[1].trim();

            const viewsMatch = statsText.match(/\[浏览量\|([^\]]+)\]/);
            if (viewsMatch) result.stats.views = viewsMatch[1];

            const likesMatch = statsText.match(/\[点赞数\|([^\]]+)\]/);
            if (likesMatch) result.stats.likes = likesMatch[1];

            const favMatch = statsText.match(/\[收藏数\|([^\]]+)\]/);
            if (favMatch) result.stats.favorites = favMatch[1];

            const commMatch = statsText.match(/\[评论数\|([^\]]+)\]/);
            if (commMatch) result.stats.comments = commMatch[1];
          }

          // 提取内容
          const contentMatch = xmlText.match(
            /<post_body>([\s\S]*?)<\/post_body>/i
          );
          if (contentMatch && contentMatch[1]) {
            const contentText = contentMatch[1].trim();

            const typeMatch = contentText.match(/\[内容类型\|([^\]]+)\]/);
            if (typeMatch) result.content.type = typeMatch[1];

            const descMatch = contentText.match(/\[内容描述\|([^\]]+)\]/);
            if (descMatch) result.content.desc = descMatch[1];

            const addMatch = contentText.match(/\[附加信息\|([^\]]+)\]/);
            if (addMatch) result.content.additional = addMatch[1];
          }

          // 提取评论
          const commentsMatch = xmlText.match(
            /<comments>([\s\S]*?)<\/comments>/i
          );
          if (commentsMatch && commentsMatch[1]) {
            const commentsText = commentsMatch[1].trim();
            const lines = commentsText.split("\n");
            lines.forEach((line) => {
              const trimmedLine = line.trim();
              if (
                trimmedLine.startsWith("[评论|") &&
                trimmedLine.endsWith("]")
              ) {
                const content = trimmedLine.slice("[评论|".length, -1);
                const parts = content.split("|");
                result.comments.push({
                  floor: parts[0] || "",
                  author: parts[1] || "",
                  time: parts[2] || "",
                  content: parts[3] || "",
                  likes: parts[4] || "0",
                });
              }
            });
          }

          console.log("帖子详情数据解析完成:", result);
          return result;
        } catch (error) {
          console.error("解析帖子详情XML出错:", error);
          return result;
        }
      }

      // 渲染帖子详情界面
      function renderPost(postData) {
        console.log("开始渲染帖子详情界面...");

        let html = `
                <div class="post-detail-container">
                    <div class="post-detail-header">
                        <div class="post-detail-title">${
                          postData.basicInfo.title || "帖子标题"
                        }</div>
                        <div class="post-detail-meta">
                            <span>👤 ${
                              postData.basicInfo.author || "匿名"
                            }</span>
                            <span>🕐 ${postData.basicInfo.time || ""}</span>
                            <span>📁 ${postData.basicInfo.board || ""}</span>
                            <span>${postData.basicInfo.tags || ""}</span>
                        </div>
                    </div>

                    <div class="post-stats">
                        <div class="stat-item">
                            <div class="stat-number">${
                              postData.stats.views || "0"
                            }</div>
                            <div class="stat-label">浏览</div>
                        </div>
                        <div class="stat-item">
                            <div class="stat-number">${
                              postData.stats.likes || "0"
                            }</div>
                            <div class="stat-label">点赞</div>
                        </div>
                        <div class="stat-item">
                            <div class="stat-number">${
                              postData.stats.favorites || "0"
                            }</div>
                            <div class="stat-label">收藏</div>
                        </div>
                        <div class="stat-item">
                            <div class="stat-number">${
                              postData.stats.comments || "0"
                            }</div>
                            <div class="stat-label">评论</div>
                        </div>
                    </div>

                    <div class="post-content">
                        <div class="content-type-badge">${
                          postData.content.type || "内容类型"
                        }</div>
                        <div>${postData.content.desc || ""}</div>
                        ${
                          postData.content.additional
                            ? `<div style="margin-top: 20px; color: #666; font-size: 14px;">${postData.content.additional}</div>`
                            : ""
                        }
                    </div>

                    <div class="comments-section">
                        <div class="comments-title">💬 评论区 (${
                          postData.comments.length
                        }条评论)</div>
            `;

        postData.comments.forEach((comment) => {
          html += `
                    <div class="comment-item">
                        <div class="comment-header">
                            <span class="comment-author">${comment.author}</span>
                            <span class="comment-floor">${comment.floor}</span>
                        </div>
                        <div class="comment-content">${comment.content}</div>
                        <div class="comment-footer">
                            <span class="comment-time">${comment.time}</span>
                            <span class="comment-like">👍 ${comment.likes}</span>
                        </div>
                    </div>
                `;
        });

        html += "</div></div>";

        document.getElementById("content").innerHTML = html;
        console.log("帖子详情界面渲染完成");
      }

      // 解析并渲染
      function parseAndRender() {
        console.log("========== 帖子详情美化页面调试信息 ==========");
        console.log("1. 开始解析示例XML数据");

        try {
          console.log("2. XML数据长度:", examplePostXML.length);
          console.log("3. XML数据前100字符:", examplePostXML.substring(0, 100));

          console.log("4. 开始XML解析...");
          const parsedData = parsePostXML(examplePostXML);
          console.log("5. 解析结果:", parsedData);

          console.log("6. 开始渲染界面...");
          renderPost(parsedData);
          console.log("7. 渲染完成！");
        } catch (error) {
          console.error("解析错误:", error);
          console.error("错误堆栈:", error.stack);
          document.getElementById("content").innerHTML =
            '<div class="loading">❌ 数据解析失败<br><br>错误信息: ' +
            error.message +
            "<br><br>请查看控制台详细信息</div>";
        }
      }

      // 页面加载时解析数据
      document.addEventListener("DOMContentLoaded", parseAndRender);
    </script>
  </body>
</html>
