            flex-wrap: wrap;
            gap: 12px;
        }

        .hud-box, .hud-gallery-box, .hud-mind-box {
            background: rgba(255, 255, 255, 0.3);
            border: 1px solid var(--clr-border);
            padding: 10px 12px;
            border-radius: 16px;
            box-shadow: inset 0 0 20px rgba(255,255,255,0.2);
            transition: border-color 0.3s, background 0.3s;
        }

        .hud-box-title {
            font-family: 'Courier New', monospace;
            color: var(--clr-text-dim);
            margin-bottom: 6px;
            border-bottom: 1px solid rgba(255,255,255,0.15);
            padding-bottom: 3px;
            display: flex;
            justify-content: space-between;
            letter-spacing: 1px;
        }
        .hud-box-title span { color: var(--clr-neon); }

        .hud-gallery-box {
            flex: 1 1 240px;
            min-width: 180px;
            display: flex;
            flex-direction: column;
        }

        .gallery-image-wrapper {
            position: relative;
            width: 100%;
            aspect-ratio: 3/4;
            background: rgba(255, 255, 255, 0.2);
            border: 1px solid var(--clr-border);
            border-radius: 12px;
            overflow: hidden;
            cursor: crosshair;
            box-shadow: 0 4px 20px rgba(0,0,0,0.03);
            transition: box-shadow 0.3s ease;
        }
        .gallery-image-wrapper:hover {
            box-shadow: 0 8px 30px var(--clr-neon-dim);
        }

        .val-gallery-img {
            width: 100%;
            height: 100%;
            object-fit: contain;
            opacity: 0.85;
            transition: opacity 0.3s, transform 0.5s ease;
            background: #f0f0f0;
            display: block;
        }
        .gallery-image-wrapper:hover .val-gallery-img {
            opacity: 1;
            transform: scale(1.03);
        }

        .gallery-overlay-hint {
            position: absolute;
            bottom: 6px;
            right: 6px;
            background: rgba(255,255,255,0.5);
            backdrop-filter: blur(4px);
            border: 1px solid var(--clr-border);
            padding: 2px 8px;
            border-radius: 20px;
            font-family: 'Courier New', monospace;
            color: var(--clr-text-main);
            pointer-events: none;
        }

        .hud-info-box {
            flex: 2 1 240px;
        }

        .hud-grid-main {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(140px, 1fr));
            gap: 10px;
            height: 100%;
        }

        .hud-box.compact {
            padding: 8px 10px;
        }
