            const textLabel = document.getElementById('fontScaleLabel');

            function applyTheme(themeIdx, fontIdx) {
                const t = COLORS[themeIdx];
                const f = FONT_COLORS[fontIdx];
                if (!t || !f) return;

                const root = wrapper;
                root.style.setProperty('--clr-primary', t.primary);
                root.style.setProperty('--clr-primary-light', t.light);
                root.style.setProperty('--clr-primary-dim', t.dim);
                root.style.setProperty('--clr-neon', t.primary);
                root.style.setProperty('--clr-border', t.light);
                root.style.setProperty('--clr-neon-dim', t.dim);
                root.style.setProperty('--clr-text-main', f.main);
                root.style.setProperty('--clr-text-dim', f.dim);

                document.querySelectorAll('.theme-swatch[data-theme]').forEach(el => {
                    el.classList.toggle('active', parseInt(el.dataset.theme) === themeIdx);
                });
                document.querySelectorAll('.theme-swatch[data-font]').forEach(el => {
                    el.classList.toggle('active', parseInt(el.dataset.font) === fontIdx);
                });

                if (themeLabel) themeLabel.textContent = t.name;
                if (fontLabel) fontLabel.textContent = f.name;

                try {
                    localStorage.setItem('hud_theme_idx', themeIdx);
                    localStorage.setItem('hud_font_idx', fontIdx);
                } catch(e) {}
            }

            function applyZoom(scale) {
                currentZoom = Math.min(1.5, Math.max(0.7, scale));
                wrapper.style.zoom = currentZoom;
                if (zoomLabel) zoomLabel.textContent = currentZoom.toFixed(2) + 'x';
                if (zoomSlider) zoomSlider.value = currentZoom;
                try {
                    localStorage.setItem('hud_zoom', currentZoom);
                } catch(e) {}
            }

            function applyTextScale(scale) {
                currentTextScale = Math.min(1.5, Math.max(0.7, scale));
                wrapper.style.setProperty('--text-scale', currentTextScale);
                if (textLabel) textLabel.textContent = currentTextScale.toFixed(2) + 'x';
                if (textSlider) textSlider.value = currentTextScale;
                try {
                    localStorage.setItem('hud_text_scale', currentTextScale);
                } catch(e) {}
            }

            function loadSavedTheme() {
                try {
                    const savedTheme = parseInt(localStorage.getItem('hud_theme_idx'));
                    const savedFont = parseInt(localStorage.getItem('hud_font_idx'));
                    if (!isNaN(savedTheme) && savedTheme >= 0 && savedTheme < COLORS.length) currentThemeIdx = savedTheme;
                    if (!isNaN(savedFont) && savedFont >= 0 && savedFont < FONT_COLORS.length) currentFontIdx = savedFont;
                    const savedZoom = parseFloat(localStorage.getItem('hud_zoom'));
                    if (!isNaN(savedZoom) && savedZoom >= 0.7 && savedZoom <= 1.5) currentZoom = savedZoom;
                    const savedText = parseFloat(localStorage.getItem('hud_text_scale'));
                    if (!isNaN(savedText) && savedText >= 0.7 && savedText <= 1.5) currentTextScale = savedText;
                } catch(e) {}
                applyTheme(currentThemeIdx, currentFontIdx);
                applyZoom(currentZoom);
                applyTextScale(currentTextScale);
            }

            function createSwatches() {
                const themeContainer = document.getElementById('themeSwatches');
                const fontContainer = document.getElementById('fontSwatches');
                if (!themeContainer || !fontContainer) return;

                themeContainer.innerHTML = '';
                fontContainer.innerHTML = '';

                COLORS.forEach((c, idx) => {
                    const swatch = document.createElement('div');
                    swatch.className = 'theme-swatch';
                    swatch.style.background = c.primary;
                    swatch.style.borderColor = c.light;
                    swatch.dataset.theme = idx;
                    swatch.title = c.name;
                    swatch.innerHTML = `<span class="swatch-label">${c.name}</span>`;
                    swatch.addEventListener('click', () => {
                        currentThemeIdx = idx;
                        applyTheme(currentThemeIdx, currentFontIdx);
                    });
                    themeContainer.appendChild(swatch);
                });

                FONT_COLORS.forEach((f, idx) => {
                    const swatch = document.createElement('div');
                    swatch.className = 'theme-swatch';
                    swatch.style.background = f.main;
                    swatch.style.borderColor = f.dim;
                    swatch.dataset.font = idx;
                    swatch.title = f.name;
                    swatch.innerHTML = `<span class="swatch-label">${f.name}</span>`;
                    swatch.addEventListener('click', () => {
                        currentFontIdx = idx;
                        applyTheme(currentThemeIdx, currentFontIdx);
                    });
                    fontContainer.appendChild(swatch);
                });
            }

            function toggleThemePanel() {
                const panel = document.getElementById('themePanel');
                if (panel) {
                    panel.style.display = panel.style.display === 'none' ? 'flex' : 'none';
                }
            }

            function resetTheme() {
                currentThemeIdx = 3;
                currentFontIdx = 3;
                currentZoom = 1.0;
                currentTextScale = 1.0;
                applyTheme(3, 3);
                applyZoom(1.0);
                applyTextScale(1.0);
                try {
                    localStorage.removeItem('hud_theme_idx');
                    localStorage.removeItem('hud_font_idx');
                    localStorage.removeItem('hud_zoom');
                    localStorage.removeItem('hud_text_scale');
                } catch(e) {}
                const panel = document.getElementById('themePanel');
                if (panel) panel.style.display = 'none';
