            const executeInjection = () => {
                try {
                    const scripts = document.querySelectorAll('script');
                    const currentScript = scripts[scripts.length - 1];
                    const wrapper = currentScript.previousElementSibling.previousElementSibling; 
                    const rawDataEl = currentScript.previousElementSibling.previousElementSibling.previousElementSibling; 

                    if(!rawDataEl || !wrapper) {
                        console.warn("[HUD] 未找到数据容器或包装器");
                        return;
                    }
                    let text = rawDataEl.innerText.trim();
                    if(!text) {
                        console.warn("[HUD] 原始数据为空");
                        return;
                    }

                    text = text.replace(/^[\s\S]*<\/\s*(?:think|thinking)\s*>/i, '').trim();

                    const extractData = (str) => {
                        const parsed = {};
                        let currentBlock = "", depth = 0;
                        for (let i = 0; i < str.length; i++) {
                            const char = str[i];
                            if (char === '[') {
                                if (depth > 0) currentBlock += char;
                                depth++;
                            } else if (char === ']') {
                                depth--;
                                if (depth === 0) {
                                    if (currentBlock.trim()) {
                                        const splitIdx = currentBlock.indexOf('|');
                                        if (splitIdx > -1) {
                                            let key = currentBlock.slice(0, splitIdx).trim().replace(/：|:/g, '');
                                            const val = currentBlock.slice(splitIdx + 1).trim();
                                            parsed[key] = val;
                                        }
                                    }
                                    currentBlock = "";
                                } else if (depth > 0) {
                                    currentBlock += char;
                                } else { depth = 0; }
                            } else {
