</div>

<script>
/* ================= 核心联动：自动读取并实时监听主卡白昼/暗夜模式 ================= */
(function(){
    function syncTheme() {
        try {
            const mode = localStorage.getItem('yanchao_theme');
            if (mode === 'light') {
                document.body.classList.add('light');
            } else {
                document.body.classList.remove('light');
            }
        } catch(e){}
    }
    syncTheme();
    // 监听同源主卡点击切换主题事件，毫秒级无缝同步
    window.addEventListener('storage', function(e) {
        if (e.key === 'yanchao_theme') syncTheme();
    });
    // 轮询兜底以防同页面 iframe storage 事件捕获延迟
    setInterval(syncTheme, 800);
})();

const REPO_BASE = "https://raw.githubusercontent.com/vmkudz-sys/Yanchao/main/";

