function hexToRgba(hex, alpha) {
    const c = hex.replace('#', '');
    const r = parseInt(c.substring(0, 2), 16),
          g = parseInt(c.substring(2, 4), 16),
          b = parseInt(c.substring(4, 6), 16);
    return `rgba(${r}, ${g}, ${b}, ${alpha})`;
}

function createLetterPlaceholder(surname, color) {
    const svg = `
    <svg xmlns="http://www.w3.org/2000/svg" width="200" height="260" viewBox="0 0 200 260">
        <rect width="200" height="260" fill="#111419"/>
        <circle cx="100" cy="110" r="50" fill="${color}" fill-opacity="0.1" stroke="${color}" stroke-width="1.5" stroke-dasharray="4,3"/>
        <text x="100" y="125" font-family="'STSong','Songti SC',serif" font-size="50" font-weight="900" fill="${color}" fill-opacity="0.8" text-anchor="middle">${surname}</text>
