  window.addEventListener('storage', function(e){
    if(e.key==='yanchao_theme'||e.key==='char_card_theme') syncTheme();
  });
  /* ▼ 性能优化③：接收主场景卡的 postMessage 主题广播（有则秒级同步，无则静默忽略） ▼ */
  window.addEventListener('message', function(e){
    if(e&&e.data&&e.data.type==='yanchao_theme_change') syncTheme();
  });

  /* ▼ 性能优化④：高度回写去重。原来每次 reheight 都无条件写
     frameElement.style.height（触发父页面回流），挂载时 60/300/800ms 三连发
     + onload + ResizeObserver，N 个气泡同时出现 = 约 5N 次父页布局抖动，
     正好与入场动画撞车。现在数值不变就不写 ▼ */
  var lastH=0;
  function reheight(){
    var h=document.getElementById('rpb').offsetHeight+14;
    if(h===lastH){return;}
    lastH=h;
    try{if(window.frameElement)window.frameElement.style.height=h+'px';}catch(e){}
  }
  reheight();
  setTimeout(reheight,60);
  setTimeout(reheight,300);
  setTimeout(reheight,800);
  if(document.fonts&&document.fonts.ready){document.fonts.ready.then(function(){reheight();});}
  if(window.ResizeObserver){new ResizeObserver(function(){reheight();}).observe(document.getElementById('rpb'));}
  window.addEventListener('resize',reheight);
})();
</script>
</body></html>

