      if (allVars && allVars.stat_data && allVars.stat_data[role]) {
        const val = parseInt(allVars.stat_data[role].亲密度);
        if (!isNaN(val)) return Math.min(100, Math.max(0, val));
      }
      return 0;
    }

    function getAllIllustKeysForHeroine(heroine) {
      const keys = { sfw: [], nsfw: {} };
      const ill = cgData[heroine];
      if (!ill) return keys;
      for (const outfit in ill.sfw) {
        keys.sfw.push({
          key: `${heroine}_SFW_${outfit}`,
          outfit: outfit,
          url: ill.sfw[outfit],
          name: outfitNames[heroine]?.[outfit] || outfit,
          type: 'sfw'
        });
      }
      for (const outfit in ill.nsfw) {
        keys.nsfw[outfit] = [];
        for (const pose of POSE_ORDER) {
          if (ill.nsfw[outfit][pose]) {
            keys.nsfw[outfit].push({
              key: `${heroine}_NSFW_${outfit}_${pose}`,
              outfit: outfit,
              pose: pose,
              url: ill.nsfw[outfit][pose],
              name: pose,
              outfitName: outfitNames[heroine]?.[outfit] || outfit,
              type: 'nsfw'
            });
          }
        }
      }
      return keys;
    }

    function getAllIllustFlatList(heroine) {
      const allKeys = getAllIllustKeysForHeroine(heroine);
      const flat = [];
      allKeys.sfw.forEach(item => {
        flat.push({
          key: item.key,
          url: item.url,
          label: item.name,
          subLabel: 'SFW',
          type: 'sfw'
        });
      });
      for (const outfit in allKeys.nsfw) {
        allKeys.nsfw[outfit].forEach(item => {
          flat.push({
            key: item.key,
            url: item.url,
            label: item.name,
            subLabel: item.outfitName,
            type: 'nsfw'
          });
        });
      }
      return flat;
    }

    function getUrlByKey(heroine, key) {
      const ill = cgData[heroine];
      if (!ill) return null;
      const parts = key.split('_');
      if (parts[1] === 'SFW') {
        const outfit = parts.slice(2).join('_');
        return ill.sfw[outfit] || null;
      } else if (parts[1] === 'NSFW') {
        const outfit = parts[2];
        const pose = parts.slice(3).join('_');
        return ill.nsfw?.[outfit]?.[pose] || null;
      }
      return null;
    }

    function renderGallery() {
      const heroine = currentRole;
      const ill = cgData[heroine];
      if (!ill) return;

      $("#gallery-title").text(heroine + " · 立绘画廊");
      const allKeys = getAllIllustKeysForHeroine(heroine);
      const affection = getAffection(heroine);
      const uaUsed = unlockAllUsed[heroine] || false;

      const $btn = $("#unlock-all-btn");
      if (uaUsed) {
        $btn.text("✅ 已解锁").addClass("used").prop("disabled", true);
      } else if (affection >= 100) {
        $btn.text("🔓 一键解锁").removeClass("used").prop("disabled", false)
          .attr("title", "亲密度已满，点击解锁全部立绘");
      } else {
        $btn.text("🔓 一键解锁").removeClass("used").prop("disabled", true)
          .attr("title", `亲密度需达到100（当前：${affection}）`);
      }

      let sfwHTML = '<div class="gallery-section-title">🖼️ SFW 立绘</div><div class="gallery-grid">';
      allKeys.sfw.forEach(item => {
        const unlocked = !!galleryUnlocks[item.key];
        const lockClass = unlocked ? '' : ' locked';
        const titleAttr = unlocked ? item.name : '尚未解锁';
        sfwHTML += `
          <div class="gallery-thumb${lockClass}" data-key="${item.key}" data-url="${item.url}" data-unlocked="${unlocked}" title="${titleAttr}">
            <img src="${item.url}" alt="${item.name}" loading="lazy">
            <div class="gallery-thumb-label">${item.name}</div>
          </div>`;
      });
      sfwHTML += '</div>';
      $("#gallery-sfw-section").html(sfwHTML);

      let nsfwHTML = '<div class="gallery-section-title">❤️ NSFW 立绘</div>';
      for (const outfit in allKeys.nsfw) {
        const outfitName = outfitNames[heroine]?.[outfit] || outfit;
        nsfwHTML += `<div class="gallery-section-title" style="font-size:12px;color:#aaa;">${outfitName}</div><div class="gallery-grid">`;
        allKeys.nsfw[outfit].forEach(item => {
          const unlocked = !!galleryUnlocks[item.key];
          const lockClass = unlocked ? '' : ' locked';
          const titleAttr = unlocked ? item.name : '尚未解锁';
          nsfwHTML += `
            <div class="gallery-thumb${lockClass}" data-key="${item.key}" data-url="${item.url}" data-unlocked="${unlocked}" title="${titleAttr}">
              <img src="${item.url}" alt="${item.name}" loading="lazy">
              <div class="gallery-thumb-label">${item.name}</div>
            </div>`;
        });
        nsfwHTML += '</div>';
      }
      $("#gallery-nsfw-section").html(nsfwHTML);

      bindGalleryThumbClicks();
    }

    function bindGalleryThumbClicks() {
      $("#gallery-content .gallery-thumb").off("click").on("click", function() {
        const unlocked = $(this).data("unlocked") === true || $(this).data("unlocked") === "true";
        if (!unlocked) { showToast("🔒 尚未解锁"); return; }
        const key = $(this).data("key");
        const url = $(this).data("url");
        openFullscreenViewer(currentRole, key, url);
      });
    }

    let fsViewerState = {
      active: false,
      heroine: '',
      flatList: [],
      currentIndex: 0
    };

    function openFullscreenViewer(heroine, key, url) {
      const flatList = getAllIllustFlatList(heroine);
      const unlockedList = flatList.filter(item => !!galleryUnlocks[item.key]);
      if (unlockedList.length === 0) {
        showToast("🔒 该角色没有已解锁的立绘");
        return;
      }
      let currentIndex = unlockedList.findIndex(item => item.key === key);
      if (currentIndex < 0) currentIndex = 0;

      fsViewerState = {
        active: true,
        heroine: heroine,
        flatList: unlockedList,
        currentIndex: currentIndex
      };

      showFullscreenImage();
      $("#fullscreen-viewer").addClass("active");
    }

    function showFullscreenImage() {
      const state = fsViewerState;
      if (!state.active || state.flatList.length === 0) return;
      const item = state.flatList[state.currentIndex];
      $("#fs-img").attr("src", item.url);
      $("#fs-counter").text((state.currentIndex + 1) + " / " + state.flatList.length);
      const typeLabel = item.type === 'sfw' ? '🖼️ SFW' : '❤️ NSFW';
      $("#fs-info").text(`${typeLabel} · ${item.subLabel} · ${item.label}`);
      // 单张图片时隐藏左右导航箭头
      if (state.flatList.length <= 1) {
        $("#fs-prev, #fs-next").css("display", "none");
      } else {
        $("#fs-prev, #fs-next").css("display", "flex");
      }
    }

    function closeFullscreenViewer() {
      $("#fullscreen-viewer").removeClass("active");
      fsViewerState.active = false;
    }

    function navigateFullscreen(direction) {
      const state = fsViewerState;
      if (!state.active || state.flatList.length <= 1) return;
      const len = state.flatList.length;
      state.currentIndex = (state.currentIndex + direction + len) % len;
      showFullscreenImage();
    }

    let toastTimer;
    function showToast(msg) {
      const $toast = $("#toast");
      $toast.text(msg).addClass("show");
      clearTimeout(toastTimer);
      toastTimer = setTimeout(() => $toast.removeClass("show"), 1800);
    }

    function updatePageBackgroundLayout() {
      if (!pageBackgroundImage?.naturalWidth || !pageBackgroundImage?.naturalHeight) return;

      const viewportWidth = window.innerWidth;
      const viewportHeight = window.innerHeight;
      const renderedHeight = viewportWidth * pageBackgroundImage.naturalHeight / pageBackgroundImage.naturalWidth;
      const $background = $("#page-background");

      $background.css("--background-rendered-height", `${renderedHeight}px`);

      if (renderedHeight <= viewportHeight) {
        // 纵向空间不足：完整原图贴顶，剩余区域使用底部模糊延展填充。
        $background
          .addClass("vertical-extension")
          .removeClass("vertical-crop")
          .css("--background-top", "0px");
        return;
      }

      // 页面偏宽：完整显示图片宽度，以原图 Y=40% 为视觉中心裁剪上下。
      const desiredTop = viewportHeight / 2 - renderedHeight * BACKGROUND_FOCUS_Y;
      const minimumTop = viewportHeight - renderedHeight;
      const backgroundTop = Math.min(0, Math.max(minimumTop, desiredTop));
      $background
        .addClass("vertical-crop")
        .removeClass("vertical-extension")
        .css("--background-top", `${backgroundTop}px`);
    }

    function schedulePageBackgroundLayout() {
      if (backgroundResizeFrame !== null) cancelAnimationFrame(backgroundResizeFrame);
      backgroundResizeFrame = requestAnimationFrame(() => {
        backgroundResizeFrame = null;
        updatePageBackgroundLayout();
      });
    }

    function initPageBackground() {
      pageBackgroundImage = new Image();
      pageBackgroundImage.onload = updatePageBackgroundLayout;
      pageBackgroundImage.onerror = error => {
        console.warn('[青恋状态栏] 背景图片尺寸读取失败，将使用默认居中背景。', error);
      };
      pageBackgroundImage.src = PAGE_BACKGROUND_URL;
      if (pageBackgroundImage.complete) updatePageBackgroundLayout();

      $(window).on("resize.pageBackground", schedulePageBackgroundLayout);
      $(window).on("pagehide.pageBackground", () => {
        $(window).off("resize.pageBackground");
        if (backgroundResizeFrame !== null) cancelAnimationFrame(backgroundResizeFrame);
      });
    }

    function loadChatUiState() {
      try {
        const chatVariables = getVariables({ type: 'chat' });
        const savedRole = _.get(chatVariables, `${CHAT_UI_STATE_PATH}.选中页签`);
        if (HEROINE_NAMES.includes(savedRole)) currentRole = savedRole;
        isStatusBarCollapsed = _.get(chatVariables, `${CHAT_UI_STATE_PATH}.已折叠`) === true;
      } catch (error) {
        console.warn('[青恋状态栏] 读取聊天界面状态失败，将使用默认状态。', error);
      }
    }

    function saveChatUiState(patch) {
      try {
        updateVariablesWith(variables => {
          if (Object.prototype.hasOwnProperty.call(patch, 'selectedRole')) {
            _.set(variables, `${CHAT_UI_STATE_PATH}.选中页签`, patch.selectedRole);
          }
          if (Object.prototype.hasOwnProperty.call(patch, 'collapsed')) {
            _.set(variables, `${CHAT_UI_STATE_PATH}.已折叠`, patch.collapsed);
          }
          return variables;
        }, { type: 'chat' });
      } catch (error) {
        console.warn('[青恋状态栏] 保存聊天界面状态失败。', error);
      }
    }

    function selectRole(name, shouldSave = false) {
      if (!HEROINE_NAMES.includes(name)) return;
      currentRole = name;
      $(".avatar-card").removeClass("active");
      $(`.avatar-card[data-role="${name}"]`).addClass("active");
      $(".profile-content").removeClass("active");
      $(`#profile-${name}`).addClass("active");
      updateUI();
      if (shouldSave) {
        saveChatUiState({ selectedRole: name });
        // 广播自定义事件，让所有聊天楼层的状态栏立即同步页签
        if (typeof eventEmit === 'function') {
          eventEmit('青恋状态栏:页签同步');
        }
      }
    }

    function setStatusBarCollapsed(collapsed, shouldSave = false) {
      isStatusBarCollapsed = !!collapsed;
      $("#statusbar-content").toggleClass("collapsed", isStatusBarCollapsed);
      $("#collapse-statusbar-btn")
        .text(isStatusBarCollapsed ? "▾ 展开" : "▴ 收起")
        .attr("aria-expanded", String(!isStatusBarCollapsed))
        .attr("title", isStatusBarCollapsed ? "展开状态栏" : "折叠状态栏");
      if (shouldSave) saveChatUiState({ collapsed: isStatusBarCollapsed });
    }

    function updateUI() {
      if (!allVars || !allVars.stat_data) return;
      const data = allVars.stat_data;

      $("#世界-日期").text(_.get(data, '世界.日期', '--'));
      $("#世界-星期").text(_.get(data, '世界.星期', '--'));
      $("#世界-时间").text(_.get(data, '世界.时间', '--'));
      $("#世界-地点").text(_.get(data, '世界.地点', '--'));
      $("#世界-天气").text(_.get(data, '世界.天气', '--'));

      const roleData = data[currentRole] || {};
      const isNsfw = String(roleData.NSFW).toLowerCase() === 'true';

      $("#nsfw-status").text(`NSFW: ${isNsfw}`);

      $("#右侧-内心独白").text(resolveUserMacro(roleData.内心独白) || '--');
      let favor = parseInt(roleData.亲密度 || 0);
      if (isNaN(favor)) favor = 0;
      if (favor < 0) favor = 0;
      if (favor > 100) favor = 100;
      $("#右侧-亲密度进度").css("width", favor + "%");
      $("#右侧-亲密度文本").text(favor + "%");

      $("#右侧-上装").text(roleData.上装 || '--');
      $("#右侧-下装").text(roleData.下装 || '--');
      $("#右侧-位置").text(roleData.位置 || '--');
      $("#右侧-动作").text(roleData.动作 || '--');
      $("#右侧-心情").text(roleData.心情 || '--');

      // 关系是 per-heroine 变量，显示在当前激活的 profile 卡片中
      $(".profile-content.active .profile-relation").text(roleData.关系 || '--');

      $("#记录-牵手").text(roleData.牵手次数 || '0');
      $("#记录-拥抱").text(roleData.拥抱次数 || '0');
      $("#记录-接吻").text(roleData.接吻次数 || '0');
      $("#记录-性爱").text(roleData.性爱次数 || '0');

      let cgUrl = getRolePortrait(currentRole, allVars);
      let cgKey = getCurrentIllustKey(currentRole, allVars);
      $("#center-portrait").css("background-image", `url('${cgUrl}')`);

      if (cgKey && !galleryUnlocks[cgKey]) {
        galleryUnlocks[cgKey] = true;
        saveGalleryUnlocks();
        if ($("#modal-gallery").hasClass("active")) renderGallery();
      }
    }

    function resolveUserMacro(text) {
      if (typeof text !== 'string') return text;
      if (typeof getCurrentPersonaName === 'function') {
        const userName = getCurrentPersonaName() || '玩家';
        return text.replace(/\{\{user\}\}/g, userName);
      }
      return text;
    }

    function populateCharacterData() {
      if (typeof getAllVariables === 'function') {
        allVars = getAllVariables();
        // 从聊天变量中重新读取页签选择，实现"变量变动→页签随之变动"
        loadChatUiState();
        selectRole(currentRole);
      }
    }

    async function init() {
      // ── 首页（消息0）立即隐藏，不等待任何异步操作，零闪烁 ──
      try {
        if (typeof getCurrentMessageId === 'function' && getCurrentMessageId() === 0) {
          document.body.style.display = 'none';
          console.info('[青恋状态栏] 检测到首页，已立即隐藏');
          return; // 不继续初始化，节省资源
        }
      } catch(e) {}

      initPageBackground();
      loadGalleryData();

      if (typeof waitGlobalInitialized === 'function') {
        await waitGlobalInitialized('Mvu');
      }
      loadChatUiState();
      populateCharacterData();
      selectRole(currentRole);
      setStatusBarCollapsed(isStatusBarCollapsed);

      if (typeof eventOn === 'function') {
        // 监听自定义事件：其他楼层切换页签时，本楼层立即同步
        eventOn('青恋状态栏:页签同步', () => {
          loadChatUiState();
          selectRole(currentRole);
        });

        // 每层聊天输出完毕后刷新界面（含页签同步）
        // 使用 MESSAGE_UPDATED（在消息显示更新后触发，MVU 变量已处理完毕）
        const messageCompleteEvent = typeof tavern_events !== 'undefined'
          ? tavern_events.MESSAGE_UPDATED
          : 'message_updated';
        eventOn(messageCompleteEvent, () => {
          populateCharacterData();
        });
      }

      if (typeof eventOn === 'function' && typeof Mvu !== 'undefined') {
        eventOn(Mvu.events.VARIABLE_UPDATE_ENDED, () => {
          populateCharacterData();
        });
      }

      $(".avatar-card").on("click", function() {
        selectRole($(this).data("role"), true);
      });

      $("#collapse-statusbar-btn").on("click", function() {
        setStatusBarCollapsed(!isStatusBarCollapsed, true);
      });

      $("[data-modal-target]").on("click", function() {
        const target = $(this).data("modal-target");
        $(`#${target}`).addClass("active");
        if (target === 'modal-gallery') renderGallery();
      });
      $(".modal-close, .modal-overlay").on("click", function(e) {
        if (e.target === this) {
          $(this).closest(".modal-overlay").removeClass("active");
        }
      });

      $("#unlock-all-btn").on("click", function() {
        if ($(this).prop("disabled")) return;
        if (unlockAllUsed[currentRole]) return;
        const affection = getAffection(currentRole);
        if (affection < 100) {
          showToast("⚠️ 亲密度不足，需达到100");
          return;
        }
        const allKeys = getAllIllustKeysForHeroine(currentRole);
        allKeys.sfw.forEach(item => { galleryUnlocks[item.key] = true; });
        for (const outfit in allKeys.nsfw) {
          allKeys.nsfw[outfit].forEach(item => { galleryUnlocks[item.key] = true; });
        }
        unlockAllUsed[currentRole] = true;
        saveGalleryUnlocks();
        saveUnlockAllUsed();
        renderGallery();
        showToast("✅ 已解锁 " + currentRole + " 全部立绘！");
      });

      $("#lock-all-btn").on("click", function() {
        const allKeys = getAllIllustKeysForHeroine(currentRole);
        let lockedCount = 0;
        allKeys.sfw.forEach(item => {
          if (galleryUnlocks[item.key]) { galleryUnlocks[item.key] = false; lockedCount++; }
        });
        for (const outfit in allKeys.nsfw) {
          allKeys.nsfw[outfit].forEach(item => {
            if (galleryUnlocks[item.key]) { galleryUnlocks[item.key] = false; lockedCount++; }
          });
        }
        unlockAllUsed[currentRole] = false;
        saveGalleryUnlocks();
        saveUnlockAllUsed();
        renderGallery();
        if (lockedCount > 0) {
          showToast("🔒 已锁定 " + currentRole + " 全部立绘（" + lockedCount + " 张）");
        } else {
          showToast("🔒 " + currentRole + " 立绘已是全部锁定状态");
        }
      });

      $("#fs-close").on("click", closeFullscreenViewer);
    $("#map-preview-wrapper").on("click", function() {
      const mapUrl = $("#map-img-thumb").attr("src");
      if (!mapUrl) return;
      fsViewerState = {
        active: true,
        heroine: '地图',
        flatList: [{
          key: 'map_fullscreen',
          url: mapUrl,
          label: '金陵市地图',
          subLabel: '',
          type: 'sfw'
        }],
        currentIndex: 0
      };
      showFullscreenImage();
      $("#fullscreen-viewer").addClass("active");
    });
      $("#fullscreen-viewer").on("click", function(e) {
        if (e.target === this) closeFullscreenViewer();
      });
      $("#fs-prev").on("click", () => navigateFullscreen(-1));
      $("#fs-next").on("click", () => navigateFullscreen(1));

      $(document).on("keydown", function(e) {
        if (fsViewerState.active) {
          if (e.key === 'ArrowLeft') navigateFullscreen(-1);
          if (e.key === 'ArrowRight') navigateFullscreen(1);
          if (e.key === 'Escape') closeFullscreenViewer();
        }
        if (e.key === 'Escape') {
          $(".modal-overlay.active").removeClass("active");
        }
      });
    }

    window.VNShell = {
      getCurrentHeroine: () => currentRole,
      setCurrentHeroine: (name) => {
        selectRole(name, true);
      },
      setAffection: (name, value) => {
        if (!allVars) allVars = { stat_data: {} };
        if (!allVars.stat_data[name]) allVars.stat_data[name] = {};
        allVars.stat_data[name].亲密度 = Math.min(100, Math.max(0, parseInt(value) || 0));
        if (name === currentRole) updateUI();
      },
      setNSFW: (name, value) => {
        if (!allVars) allVars = { stat_data: {} };
        if (!allVars.stat_data[name]) allVars.stat_data[name] = {};
        allVars.stat_data[name].NSFW = !!value;
        if (name === currentRole) updateUI();
      },
      setOutfit: (name, outfit) => {
        if (!allVars) allVars = { stat_data: {} };
        if (!allVars.stat_data[name]) allVars.stat_data[name] = {};
        if (name === '白初弦') {
          allVars.stat_data[name]['约会'] = outfit === '约会';
          allVars.stat_data[name]['日常'] = outfit === '日常';
        } else {
          allVars.stat_data[name]['校服'] = outfit === '校服';
          allVars.stat_data[name]['常服'] = outfit === '常服';
        }
        if (name === currentRole) updateUI();
      },
      setNSFWPose: (name, pose) => {
        if (!allVars) allVars = { stat_data: {} };
        if (!allVars.stat_data[name]) allVars.stat_data[name] = {};
        POSE_ORDER.forEach(p => { allVars.stat_data[name][p] = (p === pose); });
        if (name === currentRole) updateUI();
      },
      setMonologue: (name, text) => {
        if (!allVars) allVars = { stat_data: {} };
        if (!allVars.stat_data[name]) allVars.stat_data[name] = {};
        allVars.stat_data[name].内心独白 = text;
        if (name === currentRole) updateUI();
      },
      setStatus: (name, field, value) => {
        if (!allVars) allVars = { stat_data: {} };
        if (!allVars.stat_data[name]) allVars.stat_data[name] = {};
        const map = { topWear: '上装', bottomWear: '下装', location: '位置', action: '动作', mood: '心情', relationship: '关系' };
        if (map[field]) allVars.stat_data[name][map[field]] = value;
        if (name === currentRole) updateUI();
      },
      incrementIntimacy: (name, type) => {
        if (!allVars) allVars = { stat_data: {} };
        if (!allVars.stat_data[name]) allVars.stat_data[name] = {};
        const map = { handhold: '牵手次数', hug: '拥抱次数', kiss: '接吻次数', sex: '性爱次数' };
        if (map[type]) {
          const cur = parseInt(allVars.stat_data[name][map[type]]) || 0;
          allVars.stat_data[name][map[type]] = cur + 1;
        }
        if (name === currentRole) updateUI();
      },
      unlockIllust: (key) => {
        galleryUnlocks[key] = true;
        saveGalleryUnlocks();
      },
      isUnlocked: (key) => !!galleryUnlocks[key],
      getGalleryUnlocks: () => galleryUnlocks,
      refreshGallery: () => {
        if ($("#modal-gallery").hasClass("active")) renderGallery();
      },
      refreshUI: () => updateUI()
    };

    if (typeof errorCatched === 'function') {
      $(errorCatched(init));
    } else {
      $(init);
    }
  </script>
