                                pregnant: isPregnant
                            };
                        })
                        .filter(Boolean);
                }

                return { location, dateStr, weekdayStr, timeStr, sceneType, characters };
            }

            const parsed = parseScene(sceneText);
            const metaContainer = document.getElementById('scene-meta');
