        <!-- 第5页: 剧情 -->
        <div id="screen-scenario" class="screen">
            <div class="screen-header">
                <h2>开启美好生活</h2>
                <p>界定档案起始的时间与环境</p>
            </div>
            <div class="input-group" style="margin-bottom: 2rem;">
                <label for="scenario-worldview">特殊世界观</label>
                <textarea id="scenario-worldview" class="textarea-field" placeholder="在原本世界观基础上希望增加的特殊规定或设定。"></textarea>
            </div>
            <div class="input-group" style="margin-bottom: 2rem;">
                <label for="scenario-initial">开局情境</label>
                <textarea id="scenario-initial" class="textarea-field" placeholder="你想在哪里登场？遇到了什么事？留空则随机安排。"></textarea>
            </div>

            <div class="nav-buttons" style="align-items: flex-end;">
                <button class="btn back-btn" data-target="screen-sexuality" style="margin-bottom: 20px;">返回</button>

                <div class="stamp-container">
                    <button id="start-game" class="stamp-btn">
                        <svg viewBox="0 0 200 200" class="seal-svg">
                            <circle cx="100" cy="100" r="92" stroke="#dc2626" stroke-width="5" fill="none"/>
                            <circle cx="100" cy="100" r="82" stroke="#dc2626" stroke-width="2" fill="none"/>
                            <polygon points="100,50 112,85 148,85 118,105 130,140 100,118 70,140 82,105 52,85 88,85" fill="#dc2626"/>
                            <path id="seal-curve" d="M 32,105 A 68,68 0 1,1 168,105" fill="none" />
                            <text fill="#dc2626" font-family="'SimHei', 'Heiti SC', sans-serif" font-weight="bold" font-size="24" letter-spacing="4">
                                <textPath href="#seal-curve" startOffset="50%" text-anchor="middle">新中市居委会印</textPath>
                            </text>
                        </svg>
                    </button>
                </div>
            </div>
        </div>

    </div>

    <!-- 彻底作用域化逻辑 -->
    <script>
        setTimeout(() => {
            const containers = document.querySelectorAll('.generator-container');
            const root = containers[containers.length - 1];
            if (!root || root.dataset.initialized) return;
            root.dataset.initialized = 'true';

            function navigateTo(screenId) {
                root.querySelectorAll('.screen').forEach(s => s.classList.remove('active'));
                root.querySelector('#' + screenId)?.classList.add('active');
            }

            function checkAppearanceValidity() {
                const name = root.querySelector('#char-name').value.trim();
                const gender = root.querySelector('#char-gender').value;
                const appearance = root.querySelector('#char-appearance').value.trim();
                root.querySelector('#to-property').disabled = !(name && gender && appearance);
            }

            root.querySelectorAll('#screen-appearance .input-field, #screen-appearance .textarea-field, #screen-appearance .select-field').forEach(el => {
                el.addEventListener('input', checkAppearanceValidity);
            });
            root.querySelector('#char-gender').addEventListener('change', checkAppearanceValidity);

            const genderSelect = root.querySelector('#char-gender');
            const chestDataGroup = root.querySelector('#group-chest-data');
            const dislikesGroup = root.querySelector('#group-dislikes');
            const sexExpSelect = root.querySelector('#char-sex-exp');
            const sexExpCountGroup = root.querySelector('#group-sex-exp-count');

            genderSelect.addEventListener('change', () => {
                const gender = genderSelect.value;
                chestDataGroup.style.display = (gender === '女') ? 'flex' : 'none';
                dislikesGroup.style.display = (gender === '男') ? 'none' : 'flex';
                if (gender === '男') root.querySelector('#char-dislikes').value = '';
            });

            sexExpSelect.addEventListener('change', () => {
                sexExpCountGroup.style.display = (sexExpSelect.value === '有') ? 'flex' : 'none';
            });

            chestDataGroup.style.display = 'none';
            sexExpCountGroup.style.display = 'none';

            root.addEventListener('click', function(e) {
                const backBtn = e.target.closest('.back-btn');
                const nextBtn = e.target.closest('.btn-primary') || e.target.closest('#start-game');

                if (backBtn) {
                    navigateTo(backBtn.dataset.target);
                } else if (nextBtn && !nextBtn.disabled) {
                    if (nextBtn.id === 'start-game') {
                        setTimeout(() => startGame(), 150);
                    } else {
                        const targetScreen = nextBtn.id.replace('to-', 'screen-');
                         if(root.querySelector('#' + targetScreen)) {
                            navigateTo(targetScreen);
                         }
                     }
                }
            });

            async function startGame() {
                const sexExpValue = root.querySelector('#char-sex-exp').value;
                let sexExpDetail = sexExpValue;
                if (sexExpValue === '有') {
                    const count = root.querySelector('#char-sex-exp-count').value.trim();
                    sexExpDetail = `有 (${count || '未知'}人)`;
                }

                const userSettingsJSON = {
                    "基本信息": {
                        "姓名": root.querySelector('#char-name').value.trim(),
                        "性别": root.querySelector('#char-gender').value.trim(),
                        "年龄": root.querySelector('#char-age').value.trim() || "未填写",
                        "外貌情况": root.querySelector('#char-appearance').value.trim()
                    },
                    "背景设定": {
                        "家庭情况": root.querySelector('#char-family').value.trim() || "未描述",
                        "联动背景": root.querySelector('#char-background').value.trim() || "无",
                        "年龄段": root.querySelector('#char-age-group').value,
                        "职业或社团": root.querySelector('#char-occupation').value.trim() || "无",
                        "居住地": root.querySelector('#char-residence').value
                    },
                    "社会关系": {
                        "人际交往": root.querySelector('#char-other-relations').value.trim() || "无"
                    },
                    "私密设定": {
                        "性经验": sexExpDetail,
                        "胸部数据": root.querySelector('#char-chest-data').value.trim(),
                        "阴部数据": root.querySelector('#char-genital-data').value.trim() || "未描述",
                        "性癖": root.querySelector('#char-kinks').value.trim() || "未描述",
                        "反感": root.querySelector('#char-dislikes').value.trim() || "未描述",
                        "特殊能力": root.querySelector('#char-special-ability').value.trim() || "未描述"
                    }
                };

                if (userSettingsJSON.基本信息.性别 === '男') {
                    delete userSettingsJSON.私密设定.胸部数据;
                    delete userSettingsJSON.私密设定.反感;
                } else if (userSettingsJSON.基本信息.性别 === '女' && !userSettingsJSON.私密设定.胸部数据) {
                    userSettingsJSON.私密设定.胸部数据 = "未描述";
                }

                const scenarioSettingsJSON = {
                    "特殊世界观": root.querySelector('#scenario-worldview').value.trim() || "无",
                    "开局设定": root.querySelector('#scenario-initial').value.trim() || "随机生成"
                };

                // === 穿透沙盒强行给酒馆主页面注入 CSS ===
                try {
                    const topDoc = window.top.document;
                    if (!topDoc.getElementById('xinzhong-chat-style')) {
                        const style = topDoc.createElement('style');
                        style.id = 'xinzhong-chat-style';
                        style.innerHTML = `
                        @keyframes chatJitter {
                            0% { transform: translate(1px, 1px) rotate(0deg); }
                            10% { transform: translate(-1px, -2px) rotate(-1deg); }
                            20% { transform: translate(-3px, 0px) rotate(1deg); }
                            30% { transform: translate(3px, 2px) rotate(0deg); }
                            40% { transform: translate(1px, -1px) rotate(1deg); }
                            50% { transform: translate(-1px, 2px) rotate(-1deg); }
                            60% { transform: translate(-2px, 1px) rotate(0deg); }
                            70% { transform: translate(2px, 1px) rotate(-1deg); }
                            80% { transform: translate(-1px, -1px) rotate(1deg); }
                            90% { transform: translate(1px, 2px) rotate(0deg); }
                            100% { transform: translate(1px, -2px) rotate(-1deg); }
                        }
                        span[title="jitter-tag"] {
                            display: inline-block !important;
                            animation: chatJitter 0.4s infinite !important;
                            color: #0284c7 !important;
                            font-weight: bold !important;
                            cursor: pointer;
                        }
                        `;
                        topDoc.head.appendChild(style);
                    }
                } catch(e) {
                    console.warn("由于跨域安全策略，无法向主界面注入CSS动画", e);
                }

                const escapedUserJSON = JSON.stringify(userSettingsJSON, null, 2).replace(/</g, "&lt;").replace(/>/g, "&gt;");
                const escapedScenarioJSON = JSON.stringify(scenarioSettingsJSON, null, 2).replace(/</g, "&lt;").replace(/>/g, "&gt;");

                const chatPayload = `<details>
<summary><span title="jitter-tag">正在办理新中市入岛许可，请稍候...</span> (点击展开参数)</summary>

\`\`\`json
${escapedUserJSON}
\`\`\`

围绕主角展开一个有剧情张力的开头，需包含<场景标头>，并遵循叙事自检清单，需求如下：

\`\`\`json
${escapedScenarioJSON}
\`\`\`

</details>`;

                const fullCommand = `/send\n${chatPayload}`;

                function formatObjectToText(obj, indent = "") {
                    let text = "";
                    for (const key in obj) {
                        if (obj.hasOwnProperty(key)) {
                            const value = obj[key];
                            if (typeof value === 'object' && value !== null && !Array.isArray(value)) {
                                text += `${indent}${key}:\n${formatObjectToText(value, indent + "  ")}`;
                            } else if (value && String(value).trim() !== "") {
                                text += `${indent}${key}: ${value}\n`;
                            }
                        }
                    }
                    return text;
                }

                const worldInfoContent = `<user设定>\n${formatObjectToText(userSettingsJSON)}</user设定>`;

                root.innerHTML = `
                    <div class="screen active" style="text-align: center; padding: 3rem 0;">
                        <h2 style="color:var(--text-main); font-size:2rem; font-weight:700;">档案已盖章归档</h2>

                        <div style="margin-top: 2rem; margin-bottom: 2rem;">
                            <span class="jitter-text" id="status-text" style="color:var(--accent-color); font-size:1.2rem; font-weight:600;">指令正在执行中，请查看聊天窗口...</span>
                        </div>

                        <div id="manual-fallback" style="display:none; text-align: left; margin-top: 2rem;">
                            <details style="background:rgba(255,255,255,0.8); padding:1rem; border-radius: 12px; border:1px solid var(--border-color); margin-bottom: 1rem;">
                                <summary style="font-weight: 600; cursor: pointer; color: var(--text-main); outline: none;">► 点击展开：写入世界书的内容</summary>
                                <pre style="background:rgba(240,248,255,0.5); padding:1rem; border-radius: 8px; white-space: pre-wrap; font-size: 0.9rem; margin-top: 1rem; color: #333; overflow-x: auto;">${worldInfoContent}</pre>
                            </details>

                            <details style="background:rgba(255,255,255,0.8); padding:1rem; border-radius: 12px; border:1px solid var(--border-color);">
                                <summary style="font-weight: 600; cursor: pointer; color: var(--text-main); outline: none;">► 点击展开：发送至聊天框的内容</summary>
                                <pre style="background:rgba(240,248,255,0.5); padding:1rem; border-radius: 8px; white-space: pre-wrap; font-size: 0.9rem; margin-top: 1rem; color: #333; overflow-x: auto;">${fullCommand.replace(/</g, "&lt;").replace(/>/g, "&gt;")}</pre>
                            </details>
                        </div>
                    </div>`;

                // ==========================================
                                // ==========================================
                                // ==========================================
                                // ==========================================
                // 目标条目查找（不写死世界书名）：角色卡绑定书 → 全局书 → 聊天书 →（兜底）全量
                // 按「备注同时含 user设定/用户设定 与 别动」定位。
                // ⚠ 酒馆的几个坑（2026-09-13 踩过）：
                //   · /getcharbook type=all 与 /getglobalbooks 返回的是 **JSON 数组字符串**（["书A","书B"]），
                //     不能当逗号分隔文本切 —— 否则书名会带着 ["..."] 去查，必然找不到。
                //   · /getentryfield 的 uid 是**位置参数**：`field=comment 123`，写成 `uid=123` 读不到字段。
                // ==========================================
                const hpJsonList = (raw) => {
                    const t = String(raw == null ? '' : raw).trim();
                    if (!t) return [];
                    if (t.charAt(0) === '[') {
                        try {
                            const a = JSON.parse(t);
                            if (Array.isArray(a)) return a.map((x) => String(x).trim()).filter(Boolean);
                        } catch (e) {}
                    }
                    return t.split(/[,\n]/).map((x) => x.trim().replace(/^"|"$/g, '')).filter(Boolean);
                };
                const hpCandidateBooks = async () => {
                    const out = [], seen = {};
                    const push = (raw) => { hpJsonList(raw).forEach((n) => { if (n && !seen[n]) { seen[n] = 1; out.push(n); } }); };
                    try { push(await triggerSlash('/getcharbook type=all')); } catch (e) {}
                    try { push(await triggerSlash('/getglobalbooks')); } catch (e) {}
                    try { push(await triggerSlash('/getchatbook create=false')); } catch (e) {}
                    if (!out.length) {                       // 兜底：直接问酒馆助手要全部世界书名
                        try {
                            const TH = window.TavernHelper || (window.top && window.top.TavernHelper);
                            if (TH && TH.getWorldbookNames) push((TH.getWorldbookNames() || []).join('\n'));
                        } catch (e) {}
                    }
                    return out;
                };
                const hpFindUserSettingEntry = async () => {
                    const books = await hpCandidateBooks();
                    const tried = [];
                    for (const book of books) {
                        for (const q of ['user设定', '用户设定']) {
                            let uid = '';
                            try { uid = String(await triggerSlash('/findentry file="' + book + '" field=comment ' + q) || '').trim(); } catch (e) { uid = ''; }
                            if (!uid || uid === 'undefined' || uid === 'null') continue;
                            let cm = '';
                            try { cm = String(await triggerSlash('/getentryfield file="' + book + '" field=comment ' + uid) || ''); } catch (e) { cm = ''; }
                            cm = cm.replace(/^"|"$/g, '').trim();
                            if (cm.indexOf('别动') >= 0) return { book: book, uid: uid };
                            tried.push(book + ' / uid ' + uid + ' / 备注「' + (cm || '空') + '」');
                        }
                    }
                    window.__hpKjBooks = books;
                    window.__hpKjTried = tried;
                    return null;
                };
                // 当前聊天 ID：写进内容里当「归属标记」，换聊天时小手机才能认出这是上一场写的并清空。
                // 消息 iframe 可能被沙箱隔离，所以能想到的入口都试一遍；实在拿不到就写 `?`（小手机那边按「换聊天即清」处理）。
                const hpChatId = async () => {
                    const tries = [
                        () => window.SillyTavern && window.SillyTavern.getCurrentChatId && window.SillyTavern.getCurrentChatId(),
                        () => window.top && window.top.SillyTavern && window.top.SillyTavern.getCurrentChatId && window.top.SillyTavern.getCurrentChatId(),
                        () => window.TavernHelper && window.TavernHelper.getCurrentChatId && window.TavernHelper.getCurrentChatId(),
                        () => window.top && window.top.TavernHelper && window.top.TavernHelper.getCurrentChatId && window.top.TavernHelper.getCurrentChatId(),
                        () => { const ctx = window.SillyTavern && window.SillyTavern.getContext && window.SillyTavern.getContext(); return ctx && ctx.chatId; },
                        () => { const ctx = window.top && window.top.SillyTavern && window.top.SillyTavern.getContext && window.top.SillyTavern.getContext(); return ctx && ctx.chatId; },
                    ];
                    for (const f of tries) { try { const v = f(); if (v) return String(v); } catch (e) {} }
                    return '';
                };

                if (typeof triggerSlash === 'function') {
                    try {
                        const target = await hpFindUserSettingEntry();
                        if (!target) {
                            throw new Error('未找到「user设定（别动！）」条目。'
                                + '\n查过这些世界书：' + ((window.__hpKjBooks || []).join('、') || '（一本都没查到）')
                                + '\n备注匹配到但不含「别动」的：' + ((window.__hpKjTried || []).join(' ｜ ') || '无')
                                + '\n请在以上任意一本书里建一个备注同时含「user设定」和「别动」的条目。');
                        }
                        const cid = await hpChatId();
                        const marked = worldInfoContent + '\n【校准标记·聊天：' + (cid || '?') + '】';
                        await triggerSlash('/setentryfield file="' + target.book + '" uid=' + target.uid + ' field=content ' + marked);
                        await triggerSlash(fullCommand);
                        const statusText = root.querySelector('#status-text');
                        if (statusText) {
                            statusText.innerText = cid
                                ? '档案已归档，正在发送开局……'
                                : '档案已归档，正在发送开局……（未取到聊天标记，换聊天时可能不会自动清空）';
                        }
                    } catch (e) {
                        const statusText = root.querySelector('#status-text');
                        if (statusText) {
                            statusText.classList.remove('jitter-text');
                            statusText.style.color = '#dc2626';
                            statusText.innerText = '执行自动指令失败 (' + e.message + ')，请展开下方代码块手动复制处理：';
                        }
                        const fallbackBox = root.querySelector('#manual-fallback');
                        if (fallbackBox) fallbackBox.style.display = 'block';
                    }
                } else {



                     const statusText = root.querySelector('#status-text');
                     if (statusText) {
                         statusText.classList.remove('jitter-text');
                         statusText.innerText = "当前未检测到指令环境，请展开下方代码块手动复制处理：";
                     }
