        {id:'s4b',c:'温泉的雾',d:'水太烫了。他脸红的样子只瞄了一眼就不敢再看。\n这趟旅行，真是要了命了。'} ] },
    { name:'京都',      rg:'关西',   from:39, to:47, weather:'闷热',    fund:'一般', temp:70,
