  ];

  var day = 1;
  var LIVE = null;
  var openSet = {};          /* 记住哪些站是展开的，避免重建后被收回 */
  var lastSig = '__init__';
  var stopsEl = document.getElementById('stops');
  var shell = document.getElementById('shell');

  function stopInDay(d) {
    for (var i = 0; i < STOPS.length; i++) {
      var s = STOPS[i];
      if (d >= s.from && d <= s.to) return i;
      if (d < s.from) return i;
    }
    return STOPS.length - 1;
  }
  function el(tag, cls, text) {
    var n = document.createElement(tag);
    if (cls) n.className = cls;
    if (text != null) n.textContent = text;
    return n;
  }
  function clear(node) { while (node.firstChild) node.removeChild(node.firstChild); }

  function render() {
    /* 数据没变就不重建，避免每 2 秒把列表推倒重来 */
    var sig = day + '|' + (LIVE ? JSON.stringify(LIVE) : '');
    if (sig === lastSig) return;
    lastSig = sig;

    var cur = stopInDay(day);
    var s = STOPS[cur];

    var w = (LIVE && LIVE.旅程 && LIVE.旅程.天气) || s.weather;
    var fund = (LIVE && LIVE.旅程 && LIVE.旅程.资金档位) || s.fund;
    var temp = (LIVE && LIVE.关系 && typeof LIVE.关系.亲近度 === 'number') ? LIVE.关系.亲近度 : s.temp;
    var next = STOPS[cur + 1];
    var nextTxt = (LIVE && LIVE.旅程 && LIVE.旅程.下一站)
      ? LIVE.旅程.下一站
      : (next ? (next.name + '（' + next.rg + '）') : '— 路的尽头 —');

    document.getElementById('p-day').textContent = String(day);
    document.getElementById('p-bar').style.width = Math.min(100, (day / TOTAL) * 100) + '%';

    document.getElementById('j-day').textContent = '第 ' + day + ' 天';
    document.getElementById('j-cal').textContent = '7/31–9/30 · ' + w;
    document.getElementById('j-place').textContent = s.name + ' · ' + s.rg;
    document.getElementById('j-note').textContent = (LIVE && LIVE.旅程 && LIVE.旅程.旁白) || s.note;
    document.getElementById('j-mind').textContent = (LIVE && LIVE.雪乃 && LIVE.雪乃.心理) || s.mind;
    document.getElementById('j-fund').textContent = fund;
    document.getElementById('j-next').textContent = nextTxt;
    document.getElementById('j-tempbar').style.width = temp + '%';
    document.getElementById('j-tempval').textContent = temp + ' / 100';

    clear(stopsEl);
    STOPS.forEach(function (st, i) {
      var future = day < st.from;
      var state = future ? 'future' : (day > st.to ? 'past' : 'now');
      var li = el('li', 'stop ' + state + (future ? '' : ' reached'));
      li.appendChild(el('span', 'pin'));

      var ttl = el('div', 'ttl');
      ttl.appendChild(el('span', 'nm', future ? '？ ？ ？' : st.name));
      ttl.appendChild(el('span', 'rg', future ? '' : st.rg));
      ttl.appendChild(el('span', 'dt', future ? '— / —' : ('第' + st.from + '–' + st.to + '天')));
      li.appendChild(ttl);
      li.appendChild(el('div', 'beat', future ? '尚未抵达。' : st.note));

      if (!future) {
        var opened = !!openSet[i];
        if (opened) li.classList.add('open');
        li.appendChild(el('span', 'more', opened ? '▴ 收起' : '▾ 话语'));
        var album = el('div', 'album');
        (st.shots || []).forEach(function (sh) {
          var unlocked = !!(LIVE && LIVE.话语 && LIVE.话语[sh.id]);
          var d = el('div', 'diary' + (unlocked ? '' : ' locked'));
          d.appendChild(el('span', 'dh', unlocked ? sh.c : '？ 未解锁'));
          d.appendChild(el('span', 'dt', unlocked ? sh.d : '—'));
          album.appendChild(d);
        });
        li.appendChild(album);
        li.addEventListener('click', function () {
          var nowOpen = li.classList.toggle('open');
          openSet[i] = nowOpen;
          li.querySelector('.more').textContent = nowOpen ? '▴ 收起' : '▾ 话语';
        });
      }
      stopsEl.appendChild(li);
    });
  }

  function clampDay(d) { return Math.max(1, Math.min(63, d)); }

  /* 页签切换 */
  document.getElementById('tabs').addEventListener('click', function (e) {
    var btn = e.target.closest('button[data-view]');
    if (!btn) return;
    Array.prototype.forEach.call(this.children, function (b) { b.classList.toggle('on', b === btn); });
    document.getElementById('view-journal').classList.toggle('on', btn.dataset.view === 'journal');
    document.getElementById('view-route').classList.toggle('on', btn.dataset.view === 'route');
  });

  /* 收起/展开：只收内容，不收整块 */
  document.getElementById('fold').addEventListener('click', function () {
    var collapsed = shell.classList.toggle('collapsed');
    this.setAttribute('aria-expanded', String(!collapsed));
    this.textContent = collapsed ? '展开 ▼' : '收起 ▲';
  });

  /* 宿主变量：酒馆助手 getVariables(消息变量 stat_data) → Mvu → 演示数据 */
  function applyStat(stat) {
    if (!stat) return;
    LIVE = stat;
    try { var n = stat.旅程 && stat.旅程.天数; if (typeof n === 'number') day = clampDay(n); } catch (e) {}
  }
  function pullLive() {
    try {
      if (typeof getVariables === 'function') {
        var v = getVariables({ type: 'message', message_id: 'latest' });
        if (v && v.stat_data) { applyStat(v.stat_data); render(); return; }
      }
    } catch (e) {}
    try {
      if (window.Mvu && typeof window.Mvu.getMvuData === 'function') {
        var md = window.Mvu.getMvuData({ type: 'message', message_id: 'latest' });
        if (md && md.stat_data) { applyStat(md.stat_data); render(); }
      }
    } catch (e) {}
  }

  window.addEventListener('message', function (e) {
    var d = e.data;
    if (!d || d.type !== 'tw-data') return;
    if (d.stat) applyStat(d.stat);
    if (typeof d.day === 'number') day = clampDay(d.day);
    render();
    if (typeof d.view === 'string') {
      var t = document.querySelector('#tabs button[data-view="' + (d.view === 'route' ? 'route' : 'journal') + '"]');
      if (t) t.click();
    }
    if (typeof d.collapsed === 'boolean') shell.classList.toggle('collapsed', d.collapsed);
  });

  render();
  pullLive();
  setInterval(pullLive, 2000);
})();
</script>
</body>
