@keyframes kpz-spin-pop{0%{opacity:0;transform:rotate(-40deg) scale(.5)}60%{opacity:1;transform:rotate(8deg) scale(1.08)}100%{opacity:1;transform:rotate(12deg) scale(1)}}
#kpz-bg{position:absolute;inset:0;background-image:radial-gradient(rgba(192,58,43,.10) 1.6px,transparent 1.7px);background-size:26px 26px;pointer-events:none}
#kpz-head{position:relative;display:flex;align-items:center;gap:8px;background:#6b4a35;color:#f6efe0;border-radius:8px;padding:7px 12px;font-size:11px;font-weight:900;letter-spacing:.14em;margin:8px 8px 0;box-shadow:3px 3px 0 rgba(107,74,53,.35);animation:kpz-slide-l .5s cubic-bezier(.2,1.2,.4,1) .1s backwards}
#kpz-head .sq{width:11px;height:11px;background:#c03a2b;border:2px solid #f6efe0;border-radius:50%;flex:none}
#kpz-head-tag{margin-left:auto;background:#c03a2b;color:#fff;border-radius:4px;padding:2px 10px;font-size:10px;letter-spacing:.1em;white-space:nowrap;transform:rotate(2deg)}
#kpz-stage{position:relative;min-height:560px;display:flex}
#kpz-left{position:relative;z-index:2;width:45%;padding:22px 10px 18px 20px;display:flex;flex-direction:column;justify-content:center;gap:10px}
#kpz-left>*{animation:kpz-rise .5s ease backwards}
#kpz-left>*:nth-child(1){animation-delay:.2s}
#kpz-left>*:nth-child(2){animation-delay:.32s}
#kpz-left>*:nth-child(3){animation-delay:.44s}
#kpz-left>*:nth-child(4){animation-delay:.56s}
#kpz-left>*:nth-child(5){animation-delay:.68s}
#kpz-left>*:nth-child(6){animation-delay:.8s}
#kpz-ver{display:inline-block;background:#c03a2b;color:#fff;font-size:11px;font-weight:900;letter-spacing:.12em;border-radius:4px;padding:4px 12px;align-self:flex-start;transform:rotate(-3deg);box-shadow:2px 2px 0 #6b4a35}
#kpz-ver b{color:#ffe9a8}
#kpz-title{line-height:1.05;transform:rotate(-2deg);animation:kpz-stamp .55s cubic-bezier(.2,1.3,.4,1) .35s backwards}
#kpz-title .t1{display:block;font-size:50px;font-weight:900;font-style:italic;letter-spacing:.02em;color:#fff8ea;-webkit-text-stroke:2px #c03a2b;paint-order:stroke fill;text-shadow:4px 4px 0 #6b4a35;padding-bottom:6px}
#kpz-title .t1 i{display:inline-block;width:13px;height:22px;background:#c03a2b;margin-right:8px;transform:skewX(-12deg)}
#kpz-title .t2{display:inline-block;margin-top:8px;font-size:26px;font-weight:900;color:#fff;background:#c03a2b;border-radius:6px;padding:4px 14px;letter-spacing:.1em;white-space:nowrap;transform:rotate(1.5deg);box-shadow:3px 3px 0 #6b4a35}
#kpz-en{font-size:12px;font-weight:900;letter-spacing:.3em;color:#c03a2b}
#kpz-sub{font-size:12px;font-weight:800;letter-spacing:.28em;color:#a07c56}
#kpz-menu{display:flex;flex-direction:column;gap:8px;margin-top:2px;max-width:250px}
#kpz-menu::after{content:"";display:block;height:12px;margin-top:2px;background:repeating-conic-gradient(#6b4a35 0 25%,transparent 0 50%) 0 0/12px 12px;opacity:.8}
.kpz-opt{display:flex;align-items:center;gap:8px;background:#fff8ea;border:2.5px solid #6b4a35;border-radius:10px;box-shadow:3px 3px 0 #6b4a35;padding:10px 12px;font-size:17px;font-weight:900;letter-spacing:.16em;color:#6b4a35;text-align:left}
.kpz-opt small{margin-left:auto;font-size:10px;letter-spacing:.12em;opacity:.55}
.kpz-opt .arw{display:inline-flex;align-items:center;justify-content:center;width:24px;height:24px;background:#c03a2b;color:#fff;border-radius:50%;font-weight:900;font-size:13px;flex:none}
.kpz-opt:hover{background:#c03a2b;border-color:#c03a2b;color:#fff}
.kpz-opt:hover .arw{background:#fff;color:#c03a2b}
#kpz-start-hint{font-size:11px;font-weight:700;letter-spacing:.12em;color:#a07c56;min-height:16px}
/* right mosaic wall: white photo card taped on paper, slight tilt */
#kpz-wall{animation:kpz-wall-in 1s ease-out backwards;position:absolute;top:-10%;right:-8%;width:70%;height:122%;transform:rotate(2.5deg);display:grid;grid-template-columns:repeat(4,1fr);grid-auto-rows:1fr;grid-auto-flow:dense;gap:8px;background:#fffdf6;border:2.5px solid #6b4a35;border-radius:10px;padding:10px;box-shadow:-6px 6px 0 rgba(107,74,53,.35);z-index:1}
#kpz-wall::before,#kpz-wall::after{content:"";position:absolute;top:-13px;width:74px;height:26px;background:rgba(192,58,43,.28);border-left:2px dashed rgba(255,255,255,.7);border-right:2px dashed rgba(255,255,255,.7);z-index:5}
#kpz-wall::before{left:24px;transform:rotate(-8deg)}
#kpz-wall::after{right:24px;transform:rotate(7deg);background:rgba(245,165,36,.35)}
.kpz-cell{position:relative;overflow:hidden;border-radius:8px;background:linear-gradient(100deg,#efe3c8 40%,#faf3e3 50%,#efe3c8 60%);background-size:200% 100%;animation:kpz-shimmer 1.2s linear infinite;min-height:0;min-width:0}
.kpz-hero{background:linear-gradient(100deg,#efe3c8 40%,#faf3e3 50%,#efe3c8 60%);background-size:200% 100%;animation:kpz-shimmer 1.2s linear infinite}
@keyframes kpz-shimmer{to{background-position:-200% 0}}
.kpz-cell img{width:100%;height:100%;object-fit:cover;object-position:top center;display:block;background:#efe3c8;opacity:0;transition:opacity .45s ease}
.kpz-cell img.ld{opacity:1}
.s22{grid-column:span 2;grid-row:span 2}
.s21{grid-column:span 2}
.s12{grid-row:span 2}
.kpz-chip-purple{background:#e3d6ff}
.kpz-chip-green{background:#c2f0d8}
.kpz-chip-pink{background:#ffd3dd}
.kpz-chip-yellow{background:#ffedae}
.kpz-chip-teal{background:#c2e6f5}
.kpz-cell.kpz-miss{background:repeating-linear-gradient(45deg,#ffedae 0 12px,#ffd3dd 12px 24px)}
/* tile emerge: stagger from JS (idx*0.11s), last tile settles ~2s, reduced-motion disables all */
.kpz-cell.kpz-in{animation:kpz-soft-in .75s cubic-bezier(.22,1,.36,1) backwards}
#kpz-gview{position:absolute;right:12px;bottom:8px;z-index:3;text-align:right;font-size:10px;font-weight:900;letter-spacing:.22em;color:#a07c56;line-height:1.9;animation:kpz-rise .6s ease 1.55s backwards}
#kpz-gview::before{content:"";display:block;height:10px;margin-bottom:4px;background:repeating-conic-gradient(#c03a2b 0 25%,transparent 0 50%) 100% 0/10px 10px;opacity:.85}
/* transition v31: pure motion, zero text. Black band sweeps, red band chases,
   crosshair ring spins center, red squares pop. Overlay shares the paper bg
   so the 1250ms hard cut into character select is invisible. */
#kpz-trans{position:absolute;inset:0;z-index:40;background:#f6efe0;background-image:linear-gradient(#e9ddc2 1px,transparent 1px),linear-gradient(90deg,#e9ddc2 1px,transparent 1px);background-size:22px 22px;display:none;overflow:hidden}
#kpz-trans.go{display:block}
#kpz-trans.go .ix-band,#kpz-trans.go .ix-ring,#kpz-trans.go .ix-cross,#kpz-trans.go .ix-sq{will-change:transform}
.ix-band{position:absolute;top:-20%;bottom:-20%;transform:skewX(-14deg);pointer-events:none}
.ix-band.b1{width:22%;background:#262626}
.ix-band.b2{width:6%;background:#c03a2b}
#kpz-trans.go .ix-band.b1{animation:ix-fwd 1.1s cubic-bezier(.7,0,.3,1) 0s infinite}
#kpz-trans.go .ix-band.b2{animation:ix-fwd 1.1s cubic-bezier(.7,0,.3,1) .15s infinite}
@keyframes ix-fwd{from{transform:translate3d(-380%,0,0) skewX(-14deg)}to{transform:translate3d(640%,0,0) skewX(-14deg)}}
.ix-ring{position:absolute;left:50%;top:50%;width:120px;height:120px;margin:-60px 0 0 -60px;opacity:0;pointer-events:none}
.ix-ring::before{content:"";position:absolute;inset:0;border:2px solid #262626;border-radius:50%}
.ix-ring::after{content:"";position:absolute;inset:12px;border:2px dashed #c03a2b;border-radius:50%}
.ix-cross{position:absolute;left:50%;top:50%;width:168px;height:168px;margin:-84px 0 0 -84px;opacity:0;pointer-events:none;background:linear-gradient(#262626,#262626) center/2px 100% no-repeat,linear-gradient(#262626,#262626) center/100% 2px no-repeat}
#kpz-trans.go .ix-ring{animation:ix-ring 1.1s ease 0s backwards}
#kpz-trans.go .ix-cross{animation:ix-ring 1.1s ease .05s backwards}
@keyframes ix-ring{0%{opacity:0;transform:scale(.6) rotate(0deg) translateZ(0)}25%{opacity:1}80%{opacity:1;transform:scale(1) rotate(180deg) translateZ(0)}100%{opacity:0;transform:scale(1.15) rotate(220deg) translateZ(0)}}
.ix-sq{position:absolute;width:12px;height:12px;background:#c03a2b;opacity:0;pointer-events:none}
.ix-sq.s1{left:20%;top:28%}
.ix-sq.s2{left:74%;top:62%;background:#262626}
.ix-sq.s3{left:64%;top:24%}
.ix-sq.s4{left:28%;top:70%;background:#262626}
#kpz-trans.go .ix-sq{animation:ix-pop .5s ease backwards}
#kpz-trans.go .ix-sq.s1{animation-delay:.3s}
#kpz-trans.go .ix-sq.s2{animation-delay:.45s}
#kpz-trans.go .ix-sq.s3{animation-delay:.55s}
#kpz-trans.go .ix-sq.s4{animation-delay:.65s}
@keyframes ix-pop{0%{opacity:0;transform:scale(.3) rotate(0deg) translateZ(0)}60%{opacity:1}100%{opacity:0;transform:scale(1.2) rotate(90deg) translateZ(0)}}
@media(prefers-reduced-motion:reduce){#kpz-trans.go .ix-band,#kpz-trans.go .ix-ring,#kpz-trans.go .ix-cross,#kpz-trans.go .ix-sq{display:none}.ark-ph img{transition:none}}
/* character gacha v31: VOL badge, giant name, quote, chips, desc, pill route
   buttons; arch photo frame + ribbon + ghost letters. One accent theme per
   heroine via --acc/--acc-soft. Photos always fully visible. Block flow only.
   Information architecture borrows the card feel; all labels/copy original. */
#kpz-chars{position:absolute;inset:0;z-index:25;background:#f2f6fb;display:none;flex-direction:column}
#kpz-chars.open{display:flex}
#kpz-chars-head{display:flex;align-items:center;gap:8px;background:#22303e;color:#fff;padding:9px 12px;font-size:13px;font-weight:900;letter-spacing:.18em}
#kpz-chars-head .sq{width:10px;height:10px;background:var(--acc,#2f7fd0);border:2px solid #fff;border-radius:50%;flex:none}
#kpz-chars-back{margin-left:auto;background:#fff;border:2px solid #fff;border-radius:999px;font-weight:900;font-size:12px;padding:4px 14px;color:#22303e}
#kpz-char-grid{flex:1;overflow-y:auto;padding:12px;min-height:0;display:block}
.gt-sec{position:relative;display:block;background:#ffffff;border:1px solid #d7e3f2;border-radius:14px;margin:0 0 14px;overflow:hidden;box-shadow:0 4px 14px rgba(35,60,100,.08)}
.gt-ghost{position:absolute;left:-6px;top:2px;font-size:60px;font-style:italic;font-weight:900;color:transparent;-webkit-text-stroke:1.5px var(--acc-soft);line-height:1;pointer-events:none;white-space:nowrap}
.gt-ribbon{position:absolute;top:0;right:14px;z-index:2;background:var(--acc);color:#fff;font-size:10px;font-weight:900;letter-spacing:.06em;text-align:center;padding:6px 6px 10px;min-width:30px;clip-path:polygon(0 0,100% 0,100% 100%,50% 84%,0 100%)}
.gt-mid{position:relative;display:flex;gap:10px;padding:10px 12px 4px;align-items:flex-start}
.gt-info{flex:1;min-width:0;display:flex;flex-direction:column;gap:5px}
.gt-vol{align-self:flex-start;font-size:10px;font-weight:900;letter-spacing:.14em;color:#fff;background:var(--acc);border-radius:999px;padding:3px 12px}
.gt-cn{font-size:28px;font-weight:900;color:var(--acc-ink);line-height:1.12}
.gt-en{font-size:11px;font-weight:900;letter-spacing:.3em;color:var(--acc)}
.gt-quote{display:block;font-size:12px;font-weight:700;font-style:italic;color:var(--acc-ink);border-left:3px solid var(--acc);padding:2px 0 2px 10px;margin:2px 0 0;line-height:1.7}
.gt-tags{display:flex;flex-wrap:wrap;gap:6px}
.gt-tags span{font-size:10px;font-weight:800;color:var(--acc-ink);border:1.5px solid var(--acc);border-radius:999px;padding:2px 10px;background:#fff;white-space:nowrap}
.gt-desc{display:block;font-size:11px;line-height:1.65;color:#4a5a6e;background:var(--acc-soft);border-radius:0 0 10px 10px;padding:6px 10px;margin:0}
.gt-ph{flex:none;width:172px;position:relative}
.gt-frame{background:#fff;border:2px solid var(--acc);border-radius:110px 110px 14px 14px;padding:8px 8px 6px;box-shadow:0 4px 10px rgba(35,60,100,.12)}
.gt-frame img{width:100%;height:auto;display:block;border-radius:102px 102px 8px 8px;background:#eef3fa;opacity:0;transition:opacity .4s ease}
.gt-frame img.ld{opacity:1}
.gt-cap{display:block;font-size:9px;font-weight:800;text-align:center;letter-spacing:.12em;color:var(--acc-ink);padding-top:4px}
.gt-routes{position:relative;display:flex;flex-direction:column;gap:5px;padding:0}
.gt-route{display:flex;gap:8px;align-items:center;width:100%;text-align:left;background:var(--acc);border:none;color:#fff;border-radius:999px;padding:9px 16px 9px 20px;cursor:pointer;margin:0;box-shadow:0 3px 8px rgba(35,60,100,.2)}
.gt-route:active{transform:scale(.99)}
.gt-route.todo{background:#fff;border:2px dashed #9db2c9;color:#7d90a8;box-shadow:none}
.gt-rtxt{flex:1;min-width:0;font-size:12px;font-weight:900;letter-spacing:.12em;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.gt-go{flex:none;font-size:15px;font-weight:900}
@media(max-width:420px){.gt-mid{flex-direction:column}.gt-ph{width:210px;margin:0 auto}.gt-ghost{font-size:54px}}
/* per-character motifs v31: decoration-only variations. Photo geometry
   untouched (full image always visible). */
.m-arch .gt-frame{border-radius:110px 110px 14px 14px}
.m-arch .gt-frame img{border-radius:102px 102px 8px 8px}
.m-twin .gt-sec{background-image:radial-gradient(rgba(0,0,0,.05) 1.2px,transparent 1.3px);background-size:12px 12px}
.m-twin .gt-frame{border-radius:12px;box-shadow:0 0 0 3px #fff,0 0 0 5px var(--acc)}
.m-twin .gt-frame img{border-radius:6px}
.m-twin .gt-ribbon{clip-path:polygon(0 0,100% 0,100% 100%,50% 76%,0 100%);padding-bottom:14px}
.m-twin .gt-cn{border-bottom:3px double var(--acc);padding-bottom:2px}
.m-ticket .gt-sec{background-image:repeating-linear-gradient(-45deg,transparent 0 10px,rgba(0,0,0,.025) 10px 20px)}
.m-ticket .gt-frame{border-radius:8px}
.m-ticket .gt-frame img{border-radius:4px}
.m-ticket .gt-ribbon{clip-path:none;border-radius:0 0 8px 8px}
.m-ticket .gt-route{border-radius:6px}
.m-ticket .gt-vol{border-radius:4px}
.m-moon .gt-sec{background-image:radial-gradient(circle at 88% 12%,var(--acc-soft) 0 46px,transparent 47px),radial-gradient(circle at 94% 22%,var(--acc-soft) 0 22px,transparent 23px)}
.m-moon .gt-frame{border-radius:26px}
.m-moon .gt-frame img{border-radius:18px}
.m-moon .gt-vol{border-radius:50%;width:52px;height:52px;display:flex;align-items:center;justify-content:center;padding:0;text-align:center}
.m-moon .gt-quote{border-left:none;border-top:3px solid var(--acc);border-radius:0 0 8px 8px}
.m-blade .gt-sec{background-image:linear-gradient(rgba(0,0,0,.03) 1px,transparent 1px),linear-gradient(90deg,rgba(0,0,0,.03) 1px,transparent 1px);background-size:14px 14px}
.m-blade .gt-frame{border-radius:4px;border-width:3px}
.m-blade .gt-frame img{border-radius:0}
.m-blade .gt-ribbon{clip-path:polygon(0 0,100% 0,100% 85%,50% 100%,0 85%);padding-bottom:12px}
.m-blade .gt-cn{font-style:italic}
.m-blade .gt-route{border-radius:0}
/* library overlay shell */
#kpz-lib{position:absolute;inset:0;z-index:20;background:#f6efe0;background-image:linear-gradient(#e9ddc2 1px,transparent 1px),linear-gradient(90deg,#e9ddc2 1px,transparent 1px);background-size:22px 22px;display:none;flex-direction:column}
#kpz-lib.open{display:flex}
#kpz-lib-head{display:flex;align-items:center;gap:8px;background:#6b4a35;color:#f6efe0;padding:9px 12px;font-size:13px;font-weight:900;letter-spacing:.18em}
#kpz-lib-head .sq{width:10px;height:10px;background:#f5a524;border:2px solid #f6efe0;border-radius:50%;flex:none}
#kpz-lib-close{margin-left:auto;background:#fff8ea;border:2px solid #fff8ea;border-radius:999px;font-weight:900;font-size:12px;padding:4px 14px;color:#6b4a35}
/* album v31 remake: block sections + flex rows + fixed-ratio frames.
   No grid anywhere in the album: headers and photos can never share a row.
   Frame geometry is fixed before images load, so headers never misplace. */
#alb-tabs{display:flex;gap:6px;padding:8px 8px 0;flex-wrap:wrap}
#alb-tabs2{display:flex;gap:6px;padding:6px 8px 0;flex-wrap:wrap}
.alb-tab{border:2px solid #6b4a35;background:#fff8ea;color:#6b4a35;border-radius:999px;padding:4px 12px;font-weight:900;font-size:12px;box-shadow:2px 2px 0 #6b4a35}
.alb-tab[aria-pressed="true"]{background:#c03a2b;border-color:#c03a2b;color:#fff}
#alb-count{padding:6px 10px 0;font-size:11px;font-weight:800;letter-spacing:.15em;color:#a07c56}
#alb-grid{flex:1;overflow-y:auto;padding:8px 10px 12px;min-height:0;display:block}
.alb-sec{display:block;margin:0 0 10px}
.alb-head{display:block;font-weight:900;font-size:11px;letter-spacing:.15em;background:#c03a2b;color:#fff;border-radius:6px;padding:5px 12px;margin:2px 0 8px}
.alb-cells{display:flex;flex-wrap:wrap;gap:8px;margin:0 0 8px;align-items:stretch}
.alb-th{flex:1 1 120px;min-width:110px;max-width:170px;display:flex;flex-direction:column;border:2px solid #6b4a35;border-radius:8px;overflow:hidden;background:#fffdf6;cursor:pointer;padding:0;margin:0;appearance:none;-webkit-appearance:none;font:inherit}
.alb-ph{flex:1 1 auto;min-height:120px;aspect-ratio:3/4;display:flex;align-items:center;justify-content:center;background:#f3e8d2;overflow:hidden}
.alb-ph img{max-width:100%;max-height:100%;width:auto;height:auto;display:block;opacity:0;transition:opacity .3s ease}
.alb-ph img.ld{opacity:1}
.alb-cap{display:block;flex:none;font-size:9px;font-weight:800;text-align:center;letter-spacing:.08em;padding:2px;color:#6b4a35}
.alb-miss .alb-ph{background:repeating-linear-gradient(45deg,#ffedae 0 12px,#ffd3dd 12px 24px)}
.alb-gate{border:2px dashed #c03a2b;border-radius:10px;padding:26px 10px;text-align:center;display:flex;flex-direction:column;align-items:center;gap:8px;background:#fffdf6}
.alb-gate b{font-size:14px;letter-spacing:.15em;color:#6b4a35}
.alb-gate p{font-size:12px;color:#a07c56;margin:0}
.alb-gate button{background:#c03a2b;color:#fff;border-radius:8px;font-weight:900;font-size:13px;letter-spacing:.15em;padding:9px 20px;border:2px solid #c03a2b;box-shadow:2px 2px 0 #6b4a35}
/* lightbox */
#kpz-view{position:absolute;inset:0;z-index:30;background:rgba(60,40,28,.93);display:none;align-items:center;justify-content:center;flex-direction:column;gap:8px;padding:12px}
#kpz-view.open{display:flex}
#kpz-view img{max-width:94%;max-height:76%;border:3px solid #fff8ea;border-radius:10px;object-fit:contain;background:#222}
#kpz-view-cap{color:#f6efe0;font-size:12px;font-weight:800;letter-spacing:.15em}
#kpz-view-bar{display:flex;gap:8px}
#kpz-view-bar button{background:#fff8ea;border:2px solid #fff8ea;border-radius:999px;font-weight:900;font-size:13px;padding:6px 16px;color:#6b4a35}
#kpz-toast{position:absolute;left:50%;bottom:12px;transform:translateX(-50%);z-index:50;background:#6b4a35;color:#f6efe0;font-size:12px;font-weight:800;letter-spacing:.08em;border-radius:999px;padding:8px 16px;display:none;max-width:92%;text-align:center}
#kpz-toast.show{display:block;animation:kpz-rise .25s ease}
@media(max-width:560px){
#kpz-stage{flex-direction:column;min-height:0}
#kpz-left{width:100%;padding:18px 14px}
#kpz-wall{position:relative;top:auto;right:auto;width:auto;height:260px;transform:rotate(0);margin:0 10px;box-shadow:3px 3px 0 rgba(107,74,53,.5)}
#kpz-gview{position:relative;text-align:right;margin:6px 10px 10px}
#kpz-title .t1{font-size:32px}
#kpz-title .t2{font-size:22px}
#kpz-grid{grid-template-columns:repeat(2,1fr)}
#kpz-char-grid{grid-template-columns:1fr}
