function $(id){return document.getElementById(id);}
function hash(s){var h=5381;for(var i=0;i<s.length;i++){h=((h<<5)+h+s.charCodeAt(i))|0;}return Math.abs(h);}
function enc(f){try{return encodeURIComponent(f);}catch(_){return f;}}
function httpsOk(u){return /^https:\/\/(cdn\.jsdelivr\.net\/gh\/|raw\.githubusercontent\.com\/)/.test(u);}
function thumbOf(full,w){return "https://images.weserv.nl/?url="+full.replace(/^https:\/\//,"")+"&w="+w+"&q=70&output=jpg";}
function fadeIn(im){im.onload=function(){try{im.classList.add("ld");}catch(_){}};try{if(im.complete&&im.naturalWidth){im.classList.add("ld");}}catch(_){}}
function setThumb(im,full,w,onFail){
  var t=thumbOf(full,w); var tried=false;
  im.onload=function(){try{im.classList.add("ld");}catch(_){}};
  im.onerror=function(){
    if(!tried){tried=true; im.src=full;}
    else if(onFail){try{onFail();}catch(_){}}
  };
  try{im.decoding="async";}catch(_){}try{im.referrerPolicy="no-referrer";}catch(_){}im.src=t;
  try{if(im.complete&&im.naturalWidth){im.classList.add("ld");}}catch(_){}
}
var toastTimer=null;
function toast(msg){
  var el=$("kpz-toast"); el.textContent=msg; el.classList.add("show");
