}
/* ---- wall: 9 unique photos, mosaic sizes ---- */
function pool40(){var a=[];for(var c=0;c<CHARS.length;c++){for(var i=1;i<=8;i++){a.push({c:CHARS[c],i:i});}}return a;}
function shuffle(a,seed){var s=hash(seed);for(var i=a.length-1;i>0;i--){s=((s*1103515245+12345)&0x7fffffff);var j=s%(i+1);var t=a[i];a[i]=a[j];a[j]=t;}return a;}
function paintWall(seed){
  var pics=shuffle(pool40(),"wall|"+seed).slice(0,12);
  var w=$("kpz-wall"); w.innerHTML="";
  SLOTS.forEach(function(sl,idx){
    var pk=pics[idx%pics.length];
    var d=document.createElement("div");
    d.className="kpz-cell kpz-in "+(sl[1]||"");
    try{d.style.animationDelay=(idx*0.11).toFixed(2)+"s";}catch(_){}
    var im=document.createElement("img"); im.alt=pk.c; im.loading="lazy";
    d.appendChild(im); w.appendChild(d);
    setThumb(im,BASE+enc(pk.c+"_"+pk.i+".png"),600,function(){try{d.classList.add("kpz-miss");}catch(_){}});
  });
}
