function buildChars(){
  var g=$("kpz-char-grid"); g.innerHTML="";
  CHAR_INFO.forEach(function(ch,idx){
    var num=("0"+(idx+1)).slice(-2);
    var sec=document.createElement("section"); sec.className="gt-sec m-"+ch.motif;
    try{sec.style.setProperty("--acc",ch.acc);sec.style.setProperty("--acc-ink",ch.accInk);sec.style.setProperty("--acc-soft",ch.accSoft);}catch(_){}
    var ghost=document.createElement("span"); ghost.className="gt-ghost"; ghost.textContent=ch.en;
    var ribbon=document.createElement("span"); ribbon.className="gt-ribbon"; ribbon.textContent="★\n"+num;
    var mid=document.createElement("div"); mid.className="gt-mid";
    var info=document.createElement("div"); info.className="gt-info";
    var vol=document.createElement("span"); vol.className="gt-vol"; vol.textContent="VOL. "+num;
    var cn=document.createElement("div"); cn.className="gt-cn"; cn.textContent=ch.name;
    var en=document.createElement("div"); en.className="gt-en"; en.textContent=ch.en+" · "+ch.title;
    var q=document.createElement("div"); q.className="gt-quote"; q.textContent="“"+ch.quote+"”";
    var tags=document.createElement("div"); tags.className="gt-tags";
    ch.tags.forEach(function(t){var s2=document.createElement("span"); s2.textContent="#"+t; tags.appendChild(s2);});
    var desc=document.createElement("p"); desc.className="gt-desc"; desc.textContent=ch.desc;
    info.appendChild(vol); info.appendChild(cn); info.appendChild(en);
    info.appendChild(q); info.appendChild(tags); info.appendChild(desc);
    var ph=document.createElement("div"); ph.className="gt-ph";
    var frame=document.createElement("div"); frame.className="gt-frame";
    var im=document.createElement("img"); im.alt=ch.name; im.loading="lazy";
    try{im.style.width="100%";im.style.height="auto";im.style.display="block";}catch(_){}
    var cap=document.createElement("span"); cap.className="gt-cap"; cap.textContent=ch.name;
    frame.appendChild(im); frame.appendChild(cap); ph.appendChild(frame);
    var box=document.createElement("div"); box.className="gt-routes";
    var routes=[{sw:ch.sw,t:ch.rt,h:ch.rh}];
    if(ch.sw2!=null&&ch.sw2!==undefined)routes.push({sw:ch.sw2,t:ch.rt2,h:ch.rh2});
    if(ch.todo)routes=[{sw:ch.sw,t:ch.name+"线 · 待建",h:"新开场建好后生效",todo:true}];
    routes.forEach(function(r){
      var route=document.createElement("button"); route.type="button"; route.className="gt-route"+(r.todo?" todo":"");
      var txt=document.createElement("span"); txt.className="gt-rtxt";
      txt.textContent=(r.todo?"STORY · 待补":("READ STORY · 《"+r.t+"》"));
      var go=document.createElement("span"); go.className="gt-go"; go.textContent="→";
      route.appendChild(txt); route.appendChild(go);
      (function(a,n){route.addEventListener("click",function(){jumpToGreeting(a,n);});})(r.sw,ch.name);
      box.appendChild(route);
    });
    info.appendChild(box);
    mid.appendChild(info); mid.appendChild(ph);
    sec.appendChild(ghost); sec.appendChild(ribbon); sec.appendChild(mid);
    g.appendChild(sec);
    setThumb(im,BASE+enc(ch.img),400,function(){try{im.removeAttribute("src");}catch(_){}});
  });
}
async function jumpToGreeting(idx,name){
  try{
    if(typeof getChatMessages!=="function"||typeof setChatMessages!=="function"){toast("当前环境不支持自动跳转：新开对话后手动切到第"+(idx+2)+"页开场");return;}
    var floors=getChatMessages(0,{include_swipes:true});
    var fl=Array.isArray(floors)?floors[0]:floors;
    var n=(fl&&fl.swipes)?fl.swipes.length:0;
    if(n<=idx+1){toast(name+"的开场还没建：去角色卡新建一条开场白再来");return;}
    await setChatMessages([{message_id:0,swipe_id:idx+1}],{refresh:"affected"});
    toast("已切到"+name+"的开场");
  }catch(e){toast("自动跳转失败：新开对话后手动切到第"+(idx+2)+"页开场");}
}
