    var clientY = e.touches ? e.touches[0].clientY : e.clientY;
    var dx = clientX - startX;
    var dy = clientY - startY;
    if (Math.abs(dx) > 3 || Math.abs(dy) > 3) {
      hasMoved = true;
      var newLeft = startLeft + dx;
      var newTop = startTop + dy;
      var extraWidth = isMobile ? 0 : 170;
      var currentWidth = panel.style.display === 'flex' ? panel.offsetWidth + extraWidth : entry.offsetWidth;
      var currentHeight = panel.style.display === 'flex' ? root.offsetHeight : entry.offsetHeight;
      newLeft = Math.max(0, Math.min(newLeft, hostWindow.innerWidth - currentWidth));
      newTop = Math.max(0, Math.min(newTop, hostWindow.innerHeight - currentHeight));
      root.style.left = newLeft + 'px';
      root.style.top = newTop + 'px';
      root.style.transform = 'none';
    }
    if (hasMoved && e.cancelable) e.preventDefault();
  }

  function onPointerUp(e) {
    if (!isDragging) return;
    isDragging = false;
    panel.style.cursor = 'grab';
    entry.style.cursor = 'grab';
    hostWindow.removeEventListener('mousemove', onPointerMove);
    hostWindow.removeEventListener('touchmove', onPointerMove);
    hostWindow.removeEventListener('mouseup', onPointerUp);
    hostWindow.removeEventListener('touchend', onPointerUp);
    if (!hasMoved && panel.style.display !== 'flex') {
      entry.style.display = 'none';
      panel.style.display = 'flex';
      playlistEl.style.display = 'flex';
      var rect = root.getBoundingClientRect();
      if (rect.left + 320 > hostWindow.innerWidth) {
        root.style.left = (hostWindow.innerWidth - 330) + 'px';
        root.style.transform = 'none';
      }
    }
  }

  root.addEventListener('mousedown', onPointerDown);
  root.addEventListener('touchstart', onPointerDown, { passive: false });

  btnClose.addEventListener('click', function(e) {
    panel.style.display = 'none';
    playlistEl.style.display = 'none';
    entry.style.display = 'flex';
  });

  btnNext.addEventListener('click', function(e) {
    nextSong();
  });

  btnPrev.addEventListener('click', function(e) {
    prevSong();
  });

  // 音频事件监听 - 更新播放/暂停按钮状态
  audio.addEventListener('play', function() {
    updatePlayPauseButton();
  });

  audio.addEventListener('pause', function() {
    updatePlayPauseButton();
  });

  audio.addEventListener('ended', function() {
    if (!isLoopMode) {
      nextSong();
    }
  });

  audio.addEventListener('loadedmetadata', function() {
    if (audio.duration && !isNaN(audio.duration) && isFinite(audio.duration)) {
      timeTotal.innerText = formatTime(audio.duration);
    }
  });

  function updateProgress() {
    if (audio.duration && !isNaN(audio.duration) && isFinite(audio.duration)) {
      timeCurrent.innerText = formatTime(audio.currentTime);
      var percent = (audio.currentTime / audio.duration) * 100;
      progressFill.style.width = percent + '%';
    }
    hostWindow.requestAnimationFrame(updateProgress);
  }
  hostWindow.requestAnimationFrame(updateProgress);

  progressBar.addEventListener('click', function(e) {
    if (!audio.duration || isNaN(audio.duration) || !isFinite(audio.duration)) return;
    var rect = progressBar.getBoundingClientRect();
    var clickX = e.clientX - rect.left;
    var width = rect.width;
    var percent = Math.max(0, Math.min(1, clickX / width));
    audio.currentTime = percent * audio.duration;
  });

  hostDocument.addEventListener('click', function firstInteraction() {
    if (audio.paused) {
      audio.play().catch(function(){});
    }
    hostDocument.removeEventListener('click', firstInteraction);
  }, { once: true });

  // ========== 页面可见性控制 ==========
  var wasPlayingBeforeHide = false;

  function handleVisibilityChange() {
    if (hostDocument.hidden || hostDocument.visibilityState === 'hidden') {
      wasPlayingBeforeHide = !audio.paused;
      audio.pause();
    } else {
      showPlayer();
      if (wasPlayingBeforeHide) {
        audio.play().catch(function(){});
      }
    }
  }

  hostDocument.addEventListener('visibilitychange', handleVisibilityChange);

  // ========== 页面卸载控制 ==========
  function cleanup() {
    audio.pause();
    audio.src = '';
    if (root && root.parentNode) {
      root.parentNode.removeChild(root);
    }
    var styleEl = hostDocument.getElementById('qz-pro-mp3-style');
    if (styleEl && styleEl.parentNode) {
      styleEl.parentNode.removeChild(styleEl);
    }
  }

  hostWindow.addEventListener('beforeunload', cleanup);
  hostWindow.addEventListener('pagehide', cleanup);
  hostWindow.addEventListener('unload', cleanup);

  // ========== 角色卡切换检测 ==========
  var lastChatMessageCount = 0;
  var isPlayerHidden = false;
  var stableCount = 0;

  function checkChatState() {
    var chatMessages = 0;
    try {
      chatMessages = hostDocument.querySelectorAll('.mes').length;
    } catch (e) {}

    if (chatMessages > 0) {
      if (chatMessages === lastChatMessageCount) {
        stableCount++;
      } else {
        stableCount = 0;
        lastChatMessageCount = chatMessages;
      }

      if (stableCount >= 2 && isPlayerHidden) {
        isPlayerHidden = false;
        root.style.display = 'block';
        entry.style.display = 'flex';
        panel.style.display = 'none';
        playlistEl.style.display = 'none';
      }
    } else {
      stableCount = 0;
      if (!isPlayerHidden) {
        isPlayerHidden = true;
        audio.pause();
        root.style.display = 'none';
      }
    }
  }

  var checkInterval = setInterval(checkChatState, 400);

  var observer = new MutationObserver(function(mutations) {
    var hasChatChange = false;
    mutations.forEach(function(mutation) {
      var target = mutation.target;
      if (target && (
        target.classList && (target.classList.contains('mes') || target.classList.contains('mes_text')) ||
        (target.id && target.id.indexOf('chat') !== -1)
      )) {
        hasChatChange = true;
      }
    });
    if (hasChatChange) {
      setTimeout(checkChatState, 150);
    }
  });

  if (hostDocument.body) {
    observer.observe(hostDocument.body, { childList: true, subtree: true });
  }

  // SillyTavern 事件监听
  try {
    if (hostWindow.SillyTavern && hostWindow.SillyTavern.getContext) {
      var ctx = hostWindow.SillyTavern.getContext();
      if (ctx.eventSource && ctx.event_types) {
        ctx.eventSource.on(ctx.event_types.CHAT_CHANGED, function() {
          isPlayerHidden = true;
          audio.pause();
          root.style.display = 'none';
          lastChatMessageCount = 0;
          stableCount = 0;
        });
      }
    }
  } catch (e) {}

  // iframe 上下文检测
  try {
    if (window.self !== window.top) {
      var frameCheckInterval = setInterval(function() {
        try {
          var _ = window.parent.document;
          if (!hostDocument.body || !hostDocument.body.contains(root)) {
            audio.pause();
            root.style.display = 'none';
          }
        } catch (err) {
          audio.pause();
          root.style.display = 'none';
        }
      }, 500);
    }
  } catch (e) {}

})();

