.clTime{flex:none;color:#9d8db8;font-size:11px;}
.callLogEmpty{color:#7e7096;font-size:12px;text-align:center;padding:16px 0;}
/* ——— 音乐播放器（第 5 个应用）——— */
.ic-music{background:linear-gradient(135deg,#ffb347,#ff5e62);}
.musicHead{display:flex;align-items:center;gap:8px;padding:12px 18px 2px;color:#fff;}
.musicTit{font-size:18px;font-weight:bold;}
.musicCount{font-size:12px;color:#8b7aa6;}
.musicCats{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;padding:10px 18px;}
.musicCat{display:block;text-align:center;padding:7px 6px;border-radius:999px;border:1px solid #4a3a6a;background:rgba(255,255,255,.06);color:#c8c8d4;font-size:13px;cursor:pointer;white-space:nowrap;user-select:none;}
.musicCat.on{background:linear-gradient(135deg,#ffb347,#ff5e62);border-color:transparent;color:#fff;font-weight:bold;}
.musicList{flex:1;padding:4px 18px 8px;}
.musicPage{display:flex;align-items:center;justify-content:center;gap:14px;padding:8px 18px 10px;}
.pageBtn{padding:6px 16px;border:1px solid #4a3a6a;border-radius:999px;background:rgba(255,255,255,.06);color:#c8c8d4;font-size:13px;cursor:pointer;}
.pageBtn:disabled{opacity:.4;cursor:default;}
.pageInfo{color:#8b7aa6;font-size:12px;}
.songRow{display:flex;flex-direction:column;gap:2px;padding:11px 12px;margin-bottom:6px;border-radius:10px;background:rgba(255,255,255,.05);border:1px solid rgba(255,255,255,.06);cursor:pointer;}
.songRow:hover{background:rgba(255,255,255,.1);}
.songRow.on{border-color:#ffb347;background:rgba(255,179,71,.14);}
.songName{color:#fff;font-size:14px;}
.songSub{color:#8b7aa6;font-size:11px;}
.miniPlayer{background:rgba(13,17,34,.96);border-top:1px solid #3a2a55;padding:10px 14px;display:flex;flex-direction:column;gap:8px;}
.miniName{color:#ffd9a8;font-size:13px;font-weight:bold;text-align:center;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}
.miniPlayer audio{width:100%;height:34px;}
.pushBtn{width:100%;padding:10px;border:none;border-radius:10px;font-size:14px;font-weight:bold;color:#fff;background:linear-gradient(120deg,#ffb347,#ff5e62);cursor:pointer;letter-spacing:2px;}
.pushBtn:disabled{opacity:.45;cursor:default;}
/* ——— 学生助手（第 6 个应用）——— */
.ic-stu{background:linear-gradient(135deg,#4aa3ff,#2056c9);}
/* 学生助手三页固定为手机视口高度，内部滚动（修复课表/座位表被 overflow:hidden 裁掉） */
#studentTab{height:100vh;height:100dvh;min-height:0;}
#studentCard,#schedTab,#seatTab,#relTab{display:flex;flex-direction:column;flex:1;min-height:0;overflow:hidden;}
.stuHead{display:flex;align-items:center;gap:8px;padding:10px 14px 4px;color:#fff;flex:none;}
.stuTit{font-size:16px;font-weight:bold;}
.stuUpd{background:rgba(74,163,255,.18);border:1px solid #4aa3ff;color:#a8d0ff;border-radius:999px;padding:3px 9px;font-size:11px;cursor:pointer;white-space:nowrap;flex:none;}
.stuUpd:active{transform:scale(.96);}
.stuHead .headFb{flex:1;min-width:0;font-size:11px;text-align:right;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;margin:0;padding:0 2px;}
.stuHead .pHome{flex:none;}
/* 当前角色手动指定行 */
.stuWho{display:flex;align-items:center;gap:6px;padding:5px 14px 3px;flex:none;}
.stuWho .swLabel{color:#8e93a8;font-size:11px;flex:none;}
.stuWho input{flex:1;min-width:0;background:rgba(255,255,255,.08);border:1px solid rgba(255,255,255,.18);border-radius:8px;color:#fff;font-size:12px;padding:4px 8px;outline:none;}
.stuWho input::placeholder{color:#6b7086;}
.swBtn{flex:none;background:rgba(255,255,255,.1);border:1px solid rgba(255,255,255,.22);color:#cfd4e6;border-radius:999px;padding:4px 10px;font-size:11px;cursor:pointer;}
.swBtn.on{background:rgba(255,214,110,.18);border-color:#ffd66e;color:#ffd66e;}
.stuScroll{flex:1;overflow:auto;padding:10px 13px 14px;min-height:0;display:flex;flex-direction:column;-webkit-overflow-scrolling:touch;}
/* 卡片/表格必须保持自然高度：flex 列容器里 overflow:hidden 的卡片会被压扁、
   内容被裁掉（成绩雷达图就是这么被切掉的），超出部分交给 .stuScroll 内部滚动。
   #stuBody / .stuCard 自带 flex:1，必须用同等或更高优先级覆盖。 */
.stuScroll > *{flex:0 0 auto;}
.stuScroll > #stuBody{flex:0 0 auto;}
#stuBody > .stuCard{flex:0 0 auto;}
#stuBody{flex:1;display:flex;flex-direction:column;min-height:0;}
.stuCard{background:linear-gradient(150deg,#0d2a52 0%,#143c74 50%,#0a1b36 100%);border:1px solid #2b5da8;border-radius:16px;padding:15px 13px;position:relative;overflow:hidden;box-shadow:0 6px 18px rgba(0,0,0,.32);flex:1;display:flex;flex-direction:column;}
.stuCard::before{content:'';position:absolute;top:-50px;right:-50px;width:180px;height:180px;background:radial-gradient(circle,rgba(74,163,255,.35),transparent 70%);pointer-events:none;}
.stuCard::after{content:'';position:absolute;bottom:-60px;left:-40px;width:150px;height:150px;background:radial-gradient(circle,rgba(160,90,255,.22),transparent 70%);pointer-events:none;}
.stuSchool{color:#7fb4e8;font-size:11px;letter-spacing:2px;text-align:center;position:relative;}
.stuAvatar{width:52px;height:52px;border-radius:50%;margin:10px auto 7px;display:flex;align-items:center;justify-content:center;font-size:22px;font-weight:bold;color:#fff;background:linear-gradient(135deg,#4aa3ff,#8a4dff);box-shadow:0 0 0 3px rgba(74,163,255,.2);position:relative;}
.stuName{color:#fff;font-size:23px;font-weight:bold;text-align:center;margin:0 0 3px;letter-spacing:1px;position:relative;}
.stuSub{color:#8fb6e0;font-size:11px;text-align:center;margin-bottom:13px;position:relative;letter-spacing:1px;}
.stuGrid{display:grid;grid-template-columns:repeat(2,1fr);gap:8px;position:relative;}
.stuField{background:rgba(255,255,255,.06);border:1px solid rgba(255,255,255,.1);border-radius:9px;padding:7px 11px 8px;display:flex;flex-direction:column;gap:2px;min-width:0;}
.stuField i{font-style:normal;color:#7fb4e8;font-size:10px;letter-spacing:1px;}
.stuField b{color:#fff;font-size:14px;font-weight:bold;line-height:1.35;overflow-wrap:break-word;word-break:break-word;}
.stuField.wide{grid-column:1 / -1;}
.stuSrc{position:relative;color:#7fb4e8;font-size:10px;text-align:center;margin-top:8px;line-height:1.5;overflow-wrap:break-word;word-break:break-word;}
/* 绩点维度图 */
.gradeBox{margin-top:auto;background:rgba(255,255,255,.05);border:1px solid rgba(255,255,255,.1);border-radius:12px;padding:8px 10px 9px;position:relative;}
.gradeSvg{width:100%;max-width:186px;height:auto;display:block;margin:0 auto;}
.gradeLegend{display:flex;flex-wrap:wrap;gap:3px 10px;justify-content:center;margin-top:2px;}
.gradeLegend span{color:#9db8d8;font-size:11px;}
.gradeLegend b{color:#dcebff;}
/* 任课教师 */
.teacherBox{margin-top:16px;border-top:1px solid rgba(74,163,255,.2);padding-top:12px;}
.teacherTit{color:#a8d0ff;font-size:13px;font-weight:bold;margin-bottom:8px;letter-spacing:1px;}
.teacherRow{display:flex;gap:8px;align-items:flex-start;background:rgba(255,255,255,.04);border:1px solid rgba(255,255,255,.08);border-radius:10px;padding:7px 10px;margin-bottom:6px;}
.teacherRow.hr{background:rgba(74,163,255,.12);border-color:rgba(74,163,255,.3);}
.tSub{flex:none;color:#7fb4e8;font-size:11px;min-width:42px;padding-top:2px;}
/* 任课教师可点选换人（代课） */
.tPick{color:#bcd9ff;border-bottom:1px dashed rgba(160,200,255,.55);cursor:pointer;}
.tPick:hover{color:#fff;}
.tOv{color:#ffd479;font-size:11px;}
.tWas{color:#9fb6cc;font-size:11px;}
.tOvNow{font-size:12px;color:#3a4a5a;margin:2px 0 8px;line-height:1.6;}
.tOvList{max-height:46vh;overflow:auto;display:flex;flex-direction:column;gap:6px;margin-bottom:10px;}
.tOvItem{text-align:left;background:#f2f6fb;border:1px solid #d5e2ef;border-radius:8px;padding:7px 10px;
         font-size:13px;color:#24404f;cursor:pointer;}
.tOvItem.cur{background:#eaf2ff;border-color:#9cc2ef;}
.tOvTag{color:#7a8fa3;font-size:11px;}
.tOvEmpty{color:#8a9aa8;font-size:12px;padding:6px 2px;}
.tNames{flex:1;min-width:0;color:#dcebff;font-size:12px;line-height:1.75;overflow-wrap:break-word;word-break:break-word;}
.tNames .star{color:#ffd479;}
.stuBtns{display:flex;gap:9px;margin-top:auto;padding-top:10px;flex:none;}
.stuBtn{flex:1;padding:13px;border:none;border-radius:11px;font-size:14px;font-weight:bold;color:#fff;cursor:pointer;background:linear-gradient(135deg,#4aa3ff,#2056c9);}
.stuBtn:active{transform:scale(.97);}
/* 关系账本 */
.stuBtn.ghost{background:rgba(255,255,255,.12);border:1px solid rgba(255,255,255,.25);color:#dcebff;font-weight:normal;}
.relTit{color:#a8d0ff;font-size:12px;margin:0 0 8px;line-height:1.5;}
.relWarn{color:#ffb4c8;font-size:11px;margin:0 0 8px;line-height:1.5;}
.relRow{display:flex;flex-wrap:wrap;align-items:center;gap:4px 8px;background:rgba(255,255,255,.05);border:1px solid rgba(255,255,255,.1);border-radius:11px;padding:8px 10px;margin-bottom:7px;}
.relNm{flex:0 0 auto;color:#dcebff;font-size:13px;font-weight:bold;overflow-wrap:break-word;word-break:break-word;}
.relAff{flex:0 0 auto;color:#ffd479;font-size:14px;font-weight:bold;}
.relMeta{flex:1 1 100%;min-width:0;order:9;}
.relMeta i{display:block;font-style:normal;color:#9db8d8;font-size:11px;line-height:1.45;overflow-wrap:break-word;word-break:break-word;}
.relOps{flex:1 0 auto;display:flex;gap:5px;justify-content:flex-end;}
.relOps button{background:rgba(255,255,255,.1);border:1px solid rgba(255,255,255,.22);color:#cfd4e6;border-radius:7px;padding:3px 8px;font-size:11px;cursor:pointer;white-space:nowrap;}
.relForm{margin-top:12px;border-top:1px solid rgba(74,163,255,.2);padding-top:10px;display:flex;flex-direction:column;gap:6px;}
.relFormTit{color:#a8d0ff;font-size:12px;font-weight:bold;}
/* 提取候选：多选后保存到关系人 */
.relCandBox{margin:4px 0 10px;border:1px solid rgba(255,214,110,.35);background:rgba(255,214,110,.07);border-radius:11px;padding:9px 10px;}
.relCandRow{display:flex;align-items:center;gap:8px;padding:6px 8px;border-radius:8px;background:rgba(255,255,255,.05);margin-bottom:5px;cursor:pointer;}
.relCandRow.in{opacity:.5;}
.relCandRow input{pointer-events:none;flex:none;}
.relCandRow b{flex:0 0 auto;color:#dcebff;font-size:13px;}
.relCandRow i{flex:1;min-width:0;font-style:normal;color:#9db8d8;font-size:11px;overflow-wrap:break-word;word-break:break-word;}
.relIn{flex:none;color:#ffd479;font-size:10px;border:1px solid rgba(255,214,110,.5);border-radius:999px;padding:1px 6px;}
/* 催眠：生效中的规则页 */
#ruleTab{flex:1;min-height:0;flex-direction:column;overflow:hidden;}
.ruleBody{flex:1;min-height:0;overflow-y:auto;padding:12px 14px;-webkit-overflow-scrolling:touch;}
.ruleRow{display:flex;flex-wrap:wrap;align-items:center;gap:5px 8px;background:rgba(255,255,255,.05);border:1px solid rgba(255,255,255,.1);border-radius:11px;padding:8px 10px;margin-bottom:7px;}
.ruleTag{flex:none;color:#e0b3ff;font-size:10px;border:1px solid rgba(224,179,255,.45);border-radius:999px;padding:1px 7px;}
.ruleTgt{flex:0 1 auto;color:#dcebff;font-size:12px;font-weight:bold;}
.ruleAt{flex:none;margin-left:auto;color:#7d88a0;font-size:10px;}
.ruleTxt{flex:1 1 100%;order:9;color:#c9d4e8;font-size:12px;line-height:1.5;overflow-wrap:break-word;word-break:break-word;}
.ruleOps{flex:1 0 100%;order:10;display:flex;justify-content:flex-end;}
.ruleOps button{background:rgba(255,255,255,.1);border:1px solid rgba(255,255,255,.22);color:#cfd4e6;border-radius:7px;padding:3px 8px;font-size:11px;cursor:pointer;}
.ruleForm{margin-top:10px;border-top:1px solid rgba(160,90,255,.25);padding-top:10px;display:flex;flex-direction:column;gap:6px;}
.ruleFormTit{color:#c9a6ff;font-size:12px;font-weight:bold;}
.ruleForm input{background:rgba(255,255,255,.08);border:1px solid rgba(255,255,255,.18);border-radius:8px;color:#fff;font-size:12px;padding:6px 9px;outline:none;}
.ruleForm input::placeholder{color:#6b7086;}
.ruleBtns{display:flex;gap:8px;}
/* 电量：状态栏显示 + 没电时整机黑屏 */
.pBat{color:#8fa3c8;}
.pBat.low{color:#ff9aa8;}
.pBat.dead{color:#ff6b6b;}
#phoneOff{position:fixed;left:0;right:0;top:0;bottom:0;background:#07070b;z-index:2147482000;display:none;align-items:center;justify-content:center;}
#phoneOff.on{display:flex;}
.offInner{text-align:center;color:#cfd4e6;padding:0 24px;}
.offIcon{font-size:54px;margin-bottom:10px;}
.offTit{font-size:18px;font-weight:bold;margin-bottom:6px;}
.offSub{font-size:12px;color:#8b93a8;margin-bottom:16px;line-height:1.6;}
.offBtn{background:linear-gradient(135deg,#4aa3ff,#2056c9);border:none;border-radius:11px;color:#fff;font-size:14px;font-weight:bold;padding:12px 22px;cursor:pointer;}
.relForm input{background:rgba(255,255,255,.08);border:1px solid rgba(255,255,255,.18);border-radius:8px;color:#fff;font-size:12px;padding:6px 9px;outline:none;}
.relForm input::placeholder{color:#6b7086;}
.relBtns{display:flex;gap:8px;margin-top:2px;}
.stuBtn:disabled,.stuBtn.off{opacity:.38;cursor:not-allowed;filter:grayscale(.55);}
.stuBtn:disabled:active,.stuBtn.off:active{transform:none;}
/* 身份卡：校准弹窗 */
#studentTab .modalBg{display:none;position:absolute;top:0;left:0;right:0;bottom:0;background:rgba(0,0,0,.6);z-index:30;align-items:center;justify-content:center;}
#studentTab .modalBg.show{display:flex;}
#studentTab .modal{background:#fff;border-radius:12px;padding:16px;width:86%;max-width:340px;max-height:82vh;display:flex;flex-direction:column;overflow:hidden;box-shadow:0 4px 20px rgba(0,0,0,.4);}
#studentTab .modal h4{margin:0 0 8px;font-size:15px;color:#2b3a4a;flex:none;}
#studentTab .modal input,#studentTab .modal textarea{width:100%;box-sizing:border-box;border:1px solid #e3e5e8;border-radius:8px;padding:7px 10px;font-size:14px;font-family:inherit;margin-bottom:8px;flex:none;}
#studentTab .modal textarea{resize:vertical;min-height:88px;}
#studentTab .calGrid{display:grid;grid-template-columns:1fr 1fr;gap:7px 10px;margin-bottom:8px;flex:none;}
#studentTab .calGrid label{display:flex;align-items:center;gap:6px;min-width:0;}
#studentTab .calGrid label span{flex:none;color:#6b7787;font-size:12px;width:28px;}
#studentTab .calGrid input{flex:1;min-width:0;width:auto;margin-bottom:0;padding:6px 8px;font-size:13px;}
#studentTab .modal .calCalHint{font-size:12px;color:#6b7787;line-height:1.6;margin-bottom:8px;flex:none;}
#studentTab .modal .mrow{display:flex;justify-content:flex-end;gap:8px;flex:none;}
#studentTab .modal .cancel{background:#f0f4f8;color:#5a6b7d;border:none;border-radius:6px;padding:5px 14px;font-size:13px;cursor:pointer;}
/* 课表 */
.schedGrid{display:grid;grid-template-columns:64px repeat(7,1fr);gap:3px;}
.schedHead{background:rgba(74,163,255,.16);border:1px solid rgba(74,163,255,.3);color:#a8d0ff;text-align:center;padding:6px 2px;font-size:12px;font-weight:bold;border-radius:6px;}
.schedCorner{color:#7fb4e8;}
.schedTime{background:rgba(255,255,255,.05);border:1px solid rgba(255,255,255,.08);color:#9db8d8;text-align:center;padding:5px 1px;font-size:10px;border-radius:6px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:1px;line-height:1.3;}
.schedTime b{color:#cfe2ff;font-size:11px;font-weight:bold;}
.schedTime span{color:#8fa8c6;font-size:9px;}
.schedCell{background:rgba(74,163,255,.1);border:1px solid rgba(74,163,255,.25);color:#e6f0ff;text-align:center;padding:8px 2px;font-size:12px;border-radius:6px;min-height:34px;display:flex;align-items:center;justify-content:center;word-break:break-all;}
.schedCell.empty{background:rgba(255,255,255,.03);border-color:rgba(255,255,255,.06);color:#5a6b85;}
.schedCell.club{font-size:10px;line-height:1.3;padding:5px 1px;background:rgba(160,90,255,.14);border-color:rgba(160,90,255,.32);color:#e2d3ff;}
.schedCell.lunch{font-size:10px;background:rgba(255,180,80,.14);border-color:rgba(255,180,80,.32);color:#ffd9a0;}
/* 课表拖动换课（同座位表；空格列/时间列仍可滚动） */
.schedCell[data-d]{cursor:grab;}
.schedCell[data-d].has{touch-action:none;-webkit-user-select:none;user-select:none;}
.schedCell.dragging{opacity:.4;}
.schedCell.over{border-color:#37c871;background:rgba(55,200,113,.22);}
.schedCell.picked{border-color:#ffd479;box-shadow:inset 0 0 0 1px #ffd479;}
/* 当前时间高亮（按剧情时钟） */
.schedHead.todayCol{background:rgba(255,212,121,.22);border-color:rgba(255,212,121,.55);color:#ffd479;}
.schedTime.now{border-color:#ffd479;background:rgba(255,212,121,.18);}
.schedTime.now b{color:#ffd479;}
.schedTime.now span{color:#e8c98a;}
.schedCell.todayCol{background:rgba(255,212,121,.07);}
.schedCell.now{border-color:#ffd479;background:rgba(255,212,121,.3);color:#fff;font-weight:bold;box-shadow:inset 0 0 0 1px #ffd479;}
.schedExtra{color:#8b9bb8;font-size:12px;text-align:center;margin-top:12px;line-height:1.7;}
/* 座位表（紧凑：整体缩小，多桌均分宽度，尽量单屏放下、不横滚） */
.seatLegend{color:#8b9bb8;font-size:12px;text-align:center;margin-bottom:10px;}
.seatRoom{display:flex;flex-direction:column;gap:6px;align-items:stretch;}
.seatRow{display:flex;gap:3px;align-items:stretch;}
.seatAisle{width:10px;flex:none;}
.seatDesk{flex:1;min-width:0;background:rgba(255,255,255,.06);border:1px solid rgba(255,255,255,.14);border-radius:6px;padding:3px;display:flex;gap:2px;align-items:center;}
.seatSide{display:flex;flex-direction:column;gap:2px;flex:1;min-width:0;}
.seatDivider{width:1px;align-self:stretch;background:rgba(255,255,255,.1);}
.seatName{background:rgba(74,163,255,.16);border:1px solid rgba(74,163,255,.35);color:#dcebff;border-radius:4px;padding:3px 1px;font-size:10px;line-height:1.2;text-align:center;cursor:grab;min-height:22px;display:flex;align-items:center;justify-content:center;word-break:break-all;touch-action:none;-webkit-user-select:none;user-select:none;}
.seatName.empty{background:rgba(255,255,255,.03);border-color:rgba(255,255,255,.06);cursor:default;}
.seatName.dragging{opacity:.4;}
.seatName.over{border-color:#37c871;background:rgba(55,200,113,.2);}
.seatName.picked{border-color:#ffd479;background:rgba(255,212,121,.22);box-shadow:inset 0 0 0 1px #ffd479;}

/* ═══ 内置 app：SNS ═══ */
#snsTab .app {max-width:640px;margin:0 auto;border-radius:14px;overflow:hidden;border:1px solid #e3e5e8;background:#f2f3f5;font-size:14px;color:#222;position:relative;}
#snsTab .topbar {display:flex;align-items:center;gap:8px;background:#fff;border-bottom:1px solid #e3e5e8;padding:10px 14px;}
#snsTab .brand {font-weight:bold;color:#ff8200;}
#snsTab .small {color:#9aa0a6;font-size:12px;}
#snsTab .feedBody {padding:12px;}
#snsTab .card {border:1px solid #e3e5e8;border-radius:10px;padding:10px 12px;margin:8px 0;background:#fff;}
#snsTab .name {color:#1b73e8;font-weight:bold;}
#snsTab .gtime {color:#9aa0a6;font-size:12px;}
#snsTab .img {color:#5a5a6a;font-size:13px;margin:6px 0;}
#snsTab .topic {color:#1da1f2;font-size:13px;}
#snsTab .stat {color:#9aa0a6;font-size:12px;margin-top:6px;}
#snsTab .cmtArea {border-left:3px solid #e3e5e8;padding-left:10px;margin-top:8px;}
#snsTab .cmt {margin:4px 0;}
#snsTab .chip {display:inline-block;border:1px solid #dbe3ea;border-radius:12px;padding:2px 8px;font-size:12px;color:#1b73e8;cursor:pointer;background:#f7f9fb;}
