#boardTab .bSheetNote {color:#8a7358;font-size:11px;margin-top:8px;text-align:center;line-height:1.6;}
/* 成绩单默认是卷起来的（刚贴上去还没人展开）；点一下才摊开并生成 */
#boardTab .bRolled {position:relative;background:#efe7d2;border:1px solid #d9cfb6;padding:16px 14px 24px;
  box-shadow:0 4px 12px rgba(0,0,0,.4);transform:rotate(-1.1deg);cursor:pointer;text-align:center;margin-top:4px;}
#boardTab .bRolled:after {content:'';position:absolute;left:2px;right:2px;bottom:-7px;height:15px;
  background:linear-gradient(180deg,#e6dcc3,#c6b997);border-radius:0 0 50% 50%/0 0 100% 100%;
  box-shadow:0 3px 7px rgba(0,0,0,.32);}
#boardTab .bRolled:hover {filter:brightness(1.03);}
#boardTab .bRollTit {font-weight:bold;color:#3a2b1c;font-size:14px;letter-spacing:1.5px;}
#boardTab .bRollHint {color:#8a7358;font-size:11.5px;margin-top:7px;}
#boardTab .bSmall {color:#d8c0a0;font-size:11px;margin-top:8px;line-height:1.6;}
#boardTab .bHint {color:#d8c0a0;font-size:11.5px;text-align:center;margin:16px 0 6px;line-height:1.7;}
#boardTab .bBtn {display:block;width:100%;box-sizing:border-box;background:#7a5433;color:#f3ddb8;border:1px solid #96714a;
  border-radius:9px;padding:10px;font-size:13px;cursor:pointer;margin-bottom:16px;}
#boardTab .bBtn:hover {background:#8a5f38;}
#boardTab .bDetail {position:relative;background:#fdf6e3;border-radius:2px;padding:18px 16px 16px;margin:12px 4px;
  box-shadow:0 5px 16px rgba(0,0,0,.45);transform:rotate(-.4deg);}
