.calCell{background:rgba(255,255,255,.045);border:1px solid rgba(255,255,255,.08);border-radius:7px;min-height:46px;padding:3px 2px 2px;display:flex;flex-direction:column;align-items:center;cursor:pointer;overflow:hidden;}
