.calCell.range{background:rgba(160,90,255,.13);}
.cdNum{color:#e6dcff;font-size:12px;font-weight:bold;line-height:1.25;flex:none;}
.cdDots{display:flex;gap:2px;margin-top:2px;flex-wrap:wrap;justify-content:center;flex:none;}
