// 通话记录列表：本地缓存（本次会话即时可见）+ 聊天历史（跨重载恢复），两条路合并
var hpCallLogLocal=[];
function hpRenderCallLog(items){
  var list=document.getElementById('callLogList'); if(!list) return;
  list.innerHTML='';
  if(!items.length){
    var em=document.createElement('div'); em.className='callLogEmpty'; em.textContent='暂无通话记录，拨一通电话试试';
    list.appendChild(em);
    return;
  }
  for(var j=0;j<items.length;j++){
    (function(it){
