      list.appendChild(row);
    })(items[j]);
  }
}
function hpLoadCallLog(){
  var list=document.getElementById('callLogList'); if(!list) return;
  hpRenderCallLog(hpCallLogLocal.slice().reverse().slice(0,20));
  hpReadMessages().then(function(msgs){
    var arr=Array.isArray(msgs)?msgs:[];
    var remote=[];
    for(var i=arr.length-1;i>=0 && remote.length<20;i--){
      var m=arr[i]; if(!m||typeof m!=='object') continue;
      var txt=m.mes||''; if(typeof txt!=='string'||!txt) continue;
      var cc=txt.match(/^【通话记录】@([^\s]+)\s+(\d{1,2}:\d{2})/);
      if(cc) remote.push({name:cc[1], time:cc[2]});
    }
    var local=hpCallLogLocal.slice().reverse();
    var seen={}, merged=[];
    for(var a=0;a<local.length;a++){ seen[local[a].name+'|'+local[a].time]=1; merged.push(local[a]); }
    for(var b=0;b<remote.length;b++){
      var k=remote[b].name+'|'+remote[b].time;
      if(!seen[k]){ seen[k]=1; merged.push(remote[b]); }
    }
    if(merged.length) hpRenderCallLog(merged.slice(0,20));
  }).catch(function(){});
}
// 通话记录 = **私聊会话列表**（不是真实通话、也不是"再拨一次"）：
// 点进去只做一件事 —— 打开这段私聊并恢复历史。绝不在这里写新的通话记录或画「拨出」行，
// 否则每点一次就多一条记录（用户报过）。
function hpRedial(name, real){
  name=String(name||'').trim(); if(!name) return;
  hpShowTab('snsTab');
  openDM(name, real||name);          // 走 openDM 的默认恢复（内部会 hpRestoreDM）
}
// 只走 API 的读取：app 用 refresh:'none' 写进聊天的消息不在 DOM 里，
// 私信页/通话记录这类「刚写完就要读回来」的场景必须走 API，否则读到的还是旧内容。
var hpReadMsSrc='';   // 本次内容是从哪条通道读到的（诊断用：私信页显示不出记录时看这个）
// 酒馆助手 getChatMessages 返回的是 {role, message}：**没有 is_user，正文在 message 里**；
// 而 app 内部一律按 {mes, is_user} 读（hpLastUserInputs / hpDmParseRows / hpEnsureCallLog …），
// 于是只要读取走 API 通道，这些地方全部落空（身份卡认不出当前角色、私信页空白、
// 通话记录判重永不命中）。在唯一的读取出口补齐字段，别再让每个调用方各猜一套。
function hpNormMsg(m){
  if(!m || typeof m!=='object') return m;
  if(m.mes==null && typeof m.message==='string') m.mes=m.message;
  if(m.mes==null && typeof m.content==='string') m.mes=m.content;
  if(m.is_user==null) m.is_user=(m.role==='user');
  return m;
}
function hpReadMessagesApi(){
  var dom=null;
  // range 必须是 string|number：传 null 每次都会失败，再退回 DOM 就读不到刚用
  // refresh:'none' 写进来的消息（私信页空白就是这么来的）。
  var calls=[
    // hide_state:'all' 显式带上：app 写的纯 UI/元数据消息是隐藏楼层（is_hidden），
    // 不显式要就可能读不到，私信记录/通话记录就恢复不出来。带参数的放前面，不支持时自动退回下面的旧写法。
    function(){ return getChatMessages('0-{{lastMessageId}}',{hide_state:'all'}); },
    function(){ return getChatMessages('0-{{lastMessageId}}'); },
    function(){ return getChatMessages('0-{{lastMessageId}}',{}); },
    function(){ return getChatMessages('0-{last}'); },
    function(){ return getChatMessages(-1,{hide_state:'all'}); },
    function(){ return getChatMessages(-1); }
  ];
  var i=0;
  hpReadMsSrc='';
  function next(){
    if(i>=calls.length){
      // API 全失败时：先试旧版全局 chat（它含 refresh:'none' 写的消息），最后才退回 DOM
      var c=null; try{ var p=window.parent; c=(p&&p.chat)||null; }catch(e){ c=null; }
      if(c && c.length){ hpReadMsSrc='parent.chat'; return Promise.resolve(c); }
      var d=hpReadChatDomAll();
      hpReadMsSrc='dom';                 // DOM 里没有 refresh:'none' 写的消息 → 刚写的读不回来
      return Promise.resolve(d||[]);
    }
    var idx=i, fn=calls[i++], pr;
    try{ pr=fn(); }catch(e){ return next(); }
    return Promise.resolve(pr).then(function(msgs){
      if(Array.isArray(msgs) && msgs.length){ hpReadMsSrc='api#'+(idx+1); return msgs; }
      return next();
    }, function(){ return next(); });
  }
  // 唯一出口：把 API 形状（role/message）补齐成 app 内部认的 {mes, is_user}
  return next().then(function(msgs){
    if(!Array.isArray(msgs)) return msgs;
    for(var z=0;z<msgs.length;z++) hpNormMsg(msgs[z]);
    return msgs;
  });
}
// 进私信页后，如果这段对话里有内容（对方或玩家发过消息/有过通话），补一条通话记录到电话页。
// 只在"一条记录都没有"时补，避免每次点进去都多一行。
function hpEnsureCallLog(name, real){
  name=String(name||'').trim(); if(!name) return;
  for(var i=0;i<hpCallLogLocal.length;i++){ if(hpCallLogLocal[i].name===name) return; }
  hpReadMessagesApi().then(function(msgs){
    var arr=Array.isArray(msgs)?msgs:[], has=false;
    for(var j=0;j<arr.length;j++){
      var m=arr[j]; if(!m||typeof m!=='object') continue;
      var cc=String(m.mes||'').match(/^【通话记录】@([^\s]+)\s+/);
      if(cc && (cc[1]===name)){ has=true; break; }
    }
    if(has) return;
    var hh='', mm='';
    if(hpStoryDate && hpStoryDate.time){ var t=hpStoryDate.time.match(/(\d{1,2}:\d{2})/); if(t) hh=t[1].slice(0,2), mm=t[1].slice(3,5); }
    if(!hh){ var now=new Date(); hh=('0'+now.getHours()).slice(-2); mm=('0'+now.getMinutes()).slice(-2); }
    if(hpLogCall(name, hh, mm, real)){          // 写进聊天 + 本地缓存 → 电话页立刻能看到
      var list=document.getElementById('callLogList');
      if(list && document.getElementById('dialTab') && document.getElementById('dialTab').style.display!=='none') hpLoadCallLog();
    }
  }).catch(function(){});
}
// ——— 统一读取聊天消息（顺序：① TavernHelper API 多签名 → ② 旧版全局 chat → ③ 主页面 DOM 直读）———
// **必须 API 优先**：app 用 refresh:'none' 写进聊天的消息（通话记录/日历标记/私信）不在 DOM 里，
// 只要酒馆页面上有别的楼层，DOM 优先就会返回"缺这些行"的残缺列表 —— 这个坑复发过三次。
// 不同酒馆版本对 getChatMessages 的 range/options 支持不一致，单用某个签名会静默返回空。
var hpReadWarned=false;
function hpReadMessages(){
  return hpReadMessagesApi().then(function(msgs){
    if(msgs && msgs.length) return msgs;
