// 从聊天记录里解析出「这一段私聊」的气泡行。SNS 私信与论坛私信共用同一份解析，
// 免得两处规则各自漂移 —— 论坛私信此前就是因为没有解析方而完全恢复不出历史。
function hpDmParseRows(arr, account, real){
  var rows=[], lastWasDM=false;
  // 正文若是一条「媒体记录」→ 变成媒体行（恢复时画成可查看/可播放的气泡，而不是一串文字）
  var pushRow=function(side,body,time){
    var md=hpMediaOfText(body);
    if(md) rows.push({side:side, kind:md.kind, data:md.data, time:time||''});
    else rows.push({side:side, text:body, time:time||''});
  };
  for(var i=0;i<arr.length;i++){
    var m=arr[i];
    if(!m||typeof m!=='object') continue;
    var txt=m.mes||'';
    if(typeof txt!=='string'||!txt) continue;
    var isAssistant=(m.is_user===false)||(m.role==='assistant');
    var cc=txt.match(/^【通话记录】@([^\s]+)\s+(\d{1,2}:\d{2})/);
    // 时间戳可选（形如「[16:15]」）：新写的私信会带，老记录没有 → 两种情况都要能解析
    var mm=txt.match(/^私信 @([^（(]+)[（(]([^）)]*)[）)]\s*(?:[\[［](\d{1,2}:\d{2})[\]］])?\s*：/);
    var om=txt.match(/^【对方私信】@([^（(]+)[（(]([^）)]*)[）)]\s*(?:[\[［](\d{1,2}:\d{2})[\]］])?\s*：/);   // 对方发来的（通知推送/私信回复写的），气泡靠左
    if(om && (om[1]===account||om[2]===real||om[1]===real||om[2]===account)){
      pushRow('L',txt.slice(om[0].length),om[3]);
      lastWasDM=false;
    } else if(cc && (cc[1]===account||cc[1]===real)){
      rows.push({type:'call', name:cc[1], time:cc[2]});
      lastWasDM=false;
    } else if(mm && (mm[1]===account||mm[2]===real||mm[1]===real||mm[2]===account)){
      pushRow('R',txt.slice(mm[0].length),mm[3]);
      lastWasDM=true;
    } else if(isAssistant && lastWasDM){
      var t=txt.replace(/<swl>[\s\S]*?<\/swl>/g,'').replace(/<\/?swl>/g,'').trim();
      if(t) rows.push({side:'L',text:t});
      lastWasDM=false;
    } else {
      lastWasDM=false;
    }
  }
  return rows;
}
function hpRestoreDM(account,real){
  var body=document.getElementById('dmBody'); if(!body)return Promise.resolve();
  return hpReadMessagesApi().then(function(msgs){
    // 期间已经切到别的会话 → 返回 'stale'（不是 false）：调用方据此区分
    // 「没历史」和「这次恢复作废」，别把 A 的内容画进 B 的页面
    if(dmAccount!==account) return 'stale';
    var rows=hpDmParseRows(Array.isArray(msgs)?msgs:[], account, real);
    // 记下「对方最后一条消息的时间」：玩家回复时据此算间隔，角色就能抱怨/追问"怎么这么久才回"
    hpDmInboundAt='';
    for(var wi=0;wi<rows.length;wi++){ if(rows[wi].side==='L' && rows[wi].time) hpDmInboundAt=rows[wi].time; }
    // 补充本地通话记录：通话记录用 refresh:'none' 写入，不渲染进酒馆 DOM，跨路径读取可能拿不到，
    // 本次会话内用本地缓存兜底（去重后追加）
    var haveCall={}, lc;
    for(var w=0;w<rows.length;w++){ if(rows[w].type==='call') haveCall[rows[w].name+'|'+rows[w].time]=1; }
    for(var q=0;q<hpCallLogLocal.length;q++){
      lc=hpCallLogLocal[q];
      if(lc.name!==account && lc.name!==real) continue;
      if(haveCall[lc.name+'|'+lc.time]) continue;
      haveCall[lc.name+'|'+lc.time]=1;
      rows.push({type:'call', name:lc.name, time:lc.time});
    }
    body.innerHTML='';
    if(rows.length) hpEnsureCallLog(account, real);      // 有内容 → 电话页补一条通话记录（不管从哪跳进来的）
    if(!rows.length){
      // 读不全时把通道名显示出来（这个坑复发过多次：只有 DOM 通道就必然读不到刚写的私信）
      var src=hpReadMsSrc||'失败', viaApi=(src.indexOf('api#')===0);
      body.innerHTML='<div id="dmStart" style="color:#9aa0a6;font-size:12px;text-align:center;margin:4px 0;">你已进入与 @'+hpEsc(account)+'（'+hpEsc(real)+'）的通话，说点什么吧</div>'
        + (viaApi?'':'<div style="color:#c08a52;font-size:11px;text-align:center;margin:6px 0;line-height:1.5;">⚠ 私信记录读取通道：'+hpEsc(src)+'（非 API）<br>此前写过的私信可能读不回来</div>');
    } else {
      for(var j=0;j<rows.length;j++){
        if(rows[j].type==='call') hpAddCallRow(rows[j].name, rows[j].time);
        else if(rows[j].kind){
          var mp3=hpPushMedia(rows[j].kind, rows[j].data);
          addBubbleMedia(rows[j].side, mp3.kind, mp3.data, mp3.idx, rows[j].time);
        }
        else addBubble(rows[j].side, rows[j].text, rows[j].time);
      }
    }
    body.scrollTop=body.scrollHeight;
    return rows.length>0;
  }).catch(function(e){ hpWarn('私信/通话记录恢复失败：'+((e&&e.message)||e)); return false; });
}
