function createChatMessages(msgs,opts){
  // 写入前统一剥掉模型漏出来的推理过程与内心独白：内部组装路径不带酒馆的 reasoning 剥离，
  // 模型偶尔会把 "Thinking Process: …" 或 <swl>/🧠 独白整段当正文吐出来（后者该留在气泡折叠里）。
  var out=[];
  if(msgs && msgs.forEach){ msgs.forEach(function(m){
    if(!m || typeof m!=='object') return;
    var raw=(m.message!=null?m.message:m.content);
    if(m.role==='assistant'){
      var c=hpDropThought(hpStripReasoning(raw));
      m.message=c; m.content=c;
      out.push(m);
      return;
    }
    var txt=String(raw||'').trim();
