  if(!out.length) return Promise.resolve();
  msgs=out;
  var TH=window.parent.TavernHelper;
  if(!TH || !TH.createChatMessages){ hpWarn('聊天写入不可用（TavernHelper 缺失）：本段内容不会进入上下文'); return Promise.resolve(); }
  // 写失败必须看得见：界面上气泡已经画好了，静默失败的话重载后记录就没了
  try{
