function hpErrBind(){
  try{
    var pd=window.parent;
    if(!pd || !pd.addEventListener || pd.__hpErrBound) return;
    pd.__hpErrBound=1;
    pd.addEventListener('error', function(ev){
      var msg=(ev && ev.message) || '';
      var f=(ev && ev.filename) ? (' @'+String(ev.filename).split('/').pop()+':'+(ev.lineno||'?')) : '';
      if(msg) hpErrPush('error', msg+f);
    });
    pd.addEventListener('unhandledrejection', function(ev){
      var r=ev && ev.reason;
      hpErrPush('reject', (r && (r.message || r)) || r);
    });
    // 酒馆很多失败路径只走 console.error（例如拦截器中止的说明就是 console 里才有细节）
    var c=pd.console;
    if(c && typeof c.error==='function' && !c.__hpWrapped){
      c.__hpWrapped=1;
      var orig=c.error;
      c.error=function(){
        try{ hpErrPush('console', Array.prototype.join.call(arguments,' ')); }catch(e){}
        return orig.apply(c, arguments);
      };
    }
  }catch(e){}
}
