function hpOpenHistory(){ hpShowTab('histTab'); hpHistoryRender(); }
// 渲染版本列表：新 → 旧。正文里「- 」开头＝条目，其它非空行＝小节标题
function hpHistoryRender(){
  var list=document.getElementById('histList'); if(!list) return;
  var h='';
  (HP_HISTORY||[]).forEach(function(it){
    var lines=String(it.body||'').split('\n'), buf='', open=false;
    for(var i=0;i<lines.length;i++){
      var ln=lines[i].replace(/\s+$/,'');
      if(!ln.trim()) continue;
      if(ln.charAt(0)==='-'){
        if(!open){ buf+='<ul>'; open=true; }
        buf+='<li>'+hpEsc(ln.slice(1).trim())+'</li>';
      }else{
        if(open){ buf+='</ul>'; open=false; }
        buf+='<div class="histSec">'+hpEsc(ln.trim())+'</div>';
      }
    }
    if(open) buf+='</ul>';
    h+='<div class="histCard"><p class="histVer">'+hpEsc(it.v||'（未标注版本）')+'</p>'+buf+'</div>';
  });
  list.innerHTML=h||'<div class="histCard"><p>暂无版本记录</p></div>';
  hpBuildRender();
}
// 读卡里 app 脚本的 /*XZS_BUILD:<构建号>*/ 标记，显示「当前版本」
function hpBuildRender(){
  var el=document.getElementById('histCur'); if(!el) return;
  el.textContent='当前版本：读取中……';
  var TH=null; try{ TH=window.parent.TavernHelper; }catch(e){}
  if(!TH || !TH.getCharacter){ el.textContent='当前版本：读取失败（TavernHelper 不可用）'; return; }
  Promise.resolve(TH.getCharacter('current')).then(function(ch){
    var ss=[];
    try{ ss=ch.extensions.tavern_helper.scripts||[]; }catch(e){}
    var app=null, hasUpdater=false, i;
    for(i=0;i<ss.length;i++){
      var nm=String(ss[i].name||'');
      if(!app && nm.indexOf('通讯')>=0) app=ss[i];
      if(nm.indexOf('更新器')>=0) hasUpdater=true;
    }
    if(!app){ el.textContent='当前版本：读取失败（卡里找不到应用脚本）'; return; }
    var m=/\/\*XZS_BUILD:([\w.\-]+)\*\//.exec(app.content||'');
    el.innerHTML='当前版本：'+hpEsc(m?m[1]:'未标记（还没通过更新器更新过）')+
                 '<br>自动更新：'+(hasUpdater?'已就绪 ✓':'未安装 ✗（这张卡需要重新导入带更新器的版本）');
  }).catch(function(e){ el.textContent='当前版本：读取失败：'+((e&&e.message)||e); });
}
// 重载酒馆整页：消息没上屏/发了没反应时的自救按钮。
// 之所以有效：那类故障是「渲染那一步抛异常」导致发送流程中断，消息其实已经存进聊天了 ——
// 重载会按存档重新渲染一遍，消息就回来了（和「切卡再切回来」同一个道理，但不用切卡）。
function hpReloadPage(){
  try{ window.parent.location.reload(); }
  catch(e){ try{ location.reload(); }catch(e2){} }
}
function hpCtxDiagRender(){
  var el=document.getElementById('ctxDiag'); if(!el) return;
  var pd=null; try{ pd=window.parent; }catch(e){}
  if(!pd || !pd.document){ el.textContent='（演示模式：不在酒馆页面里）'; return; }
  // ⚠ 不要用 window.parent.chat：酒馆没把聊天数组挂到 window 上，而 HTML 的「命名元素访问」
  // 会让 window.chat 变成 <div id="chat"> 那个 DOM 元素（有值、但没有 length）——
  // 实测就打印成了「undefined 层」。数组要从 SillyTavern.getContext().chat 拿。
  var arrLen=null, last='(读不到)';
  try{
    var ctx=(pd.SillyTavern && pd.SillyTavern.getContext) ? pd.SillyTavern.getContext() : null;
    var arr=ctx && ctx.chat;
    if(Array.isArray(arr)){
      arrLen=arr.length;
      var m=arr[arr.length-1];
      if(m) last=(m.is_user?'玩家：':'AI：')+String(m.mes||'').replace(/\s+/g,' ').slice(0,36);
    }
  }catch(e){}
  if(arrLen===null){   // 退一步：问酒馆助手要最后一条楼层号
    try{ var TH=pd.TavernHelper; if(TH && TH.getLastMessageId){ var lid=TH.getLastMessageId();
      if(typeof lid==='number' && lid>=-1) arrLen=lid+1; } }catch(e){}
  }
  var domLen=-1; try{ domLen=pd.document.querySelectorAll('#chat .mes').length; }catch(e){}
  var sending=null; try{ if(typeof pd.is_send_press!=='undefined') sending=!!pd.is_send_press; }catch(e){}
  var stopShown=false;
  try{ var sb=pd.document.getElementById('mes_stop'); stopShown=!!(sb && sb.getClientRects && sb.getClientRects().length); }catch(e){}
  var out=[];
  out.push('聊天数组：'+(arrLen===null?'读不到':arrLen+' 层'));
  out.push('页面已渲染：'+(domLen<0?'读取失败':domLen+' 层'));
  if(arrLen!==null && domLen>=0) out.push('差值：'+(arrLen-domLen)+(arrLen>domLen?'（页面少于数组**很常见，不等于出问题**：① cocktail 的「聊天渲染优化」默认只渲染首屏 20 条，往上滚会加载更多；② app 写的消息本来就不渲染）':' ✓ 两边一致'));
  out.push('末尾消息：'+last);
  out.push('生成状态：'+((sending===true||stopShown)?'⚠ 正在生成中（此时点发送会被静默忽略）':'空闲 ✓'));
  out.push('最近酒馆报错：'+(hpErrLog.length?'':'（无）'));
  for(var q=0;q<hpErrLog.length;q++) out.push('　· '+hpErrLog[q]);
  el.innerHTML=out.map(function(s){ return hpEsc(s); }).join('<br>');
}
