// ═══ 通讯录（浮层）：学生人员表（班级×名单）+ 社团表（社团归属）→ 可搜索名册 ═══
// crossover 大卡里「这人是谁、哪个班、在哪个社团」随手可查；点名字直接进 X站主页
var hpContactData=null;      // {groups:[{name,names:[]}], clubOf:{名字:社团}}
function hpContactParse(rosterText, clubText){
  var groups=[], clubOf={}, all=[], i, j;
  var lines=String(rosterText||'').split(/\r?\n/);
  for(i=0;i<lines.length;i++){
    var m=lines[i].match(/^\s*([^\s:：][^:：]{0,20}?)\s*[:：]\s*(.+)$/);
    if(!m) continue;
    var head=hpCleanName(m[1]);
    if(head.indexOf('学生')<0) continue;              // 只收「XX班学生 / 大二学生」这类名单行
    var names=hpSplitNames(m[2]);
    if(!names.length) continue;
    groups.push({name:head, names:names});
    for(j=0;j<names.length;j++) all.push(names[j]);
  }
  // 社团归属：把社团表按【社团名】切段，段内出现过该名字 → 算这个社团的成员
  var secs=String(clubText||'').split(/【([^】]{2,14})】/);
  for(i=1;i+1<secs.length;i+=2){
    var club=String(secs[i]).trim(), body=String(secs[i+1]||'');
    if(!/(部|社|团|会|研讨会)$/.test(club)) continue;
    if(/[↔·\s\/]/.test(club)) continue;              // 「A ↔ B」「A·B」是关系行，不是社团
    for(j=0;j<all.length;j++){ if(!clubOf[all[j]] && body.indexOf(all[j])>=0) clubOf[all[j]]=club; }
  }
  return {groups:groups, clubOf:clubOf};
}
function hpContactsLoad(force){
  if(hpContactData && !force) return Promise.resolve(hpContactData);
  var TH=window.parent.TavernHelper;
  return hpLoadWorldbooks(TH).then(function(entries){
    var roster=hpFindEntry(entries,'新中市国立学校学生人员表');
    var clubTbl=hpFindEntry(entries,'新-新中市国立学校社团表（38）');
    hpContactData=hpContactParse(roster?roster.content:'', clubTbl?clubTbl.content:'');
    return hpContactData;
  }).catch(function(e){
    hpContactData={groups:[], clubOf:{}};
    hpWarn('通讯录读取失败：'+((e&&e.message)||e));
    return hpContactData;
  });
}
function hpContactsFilter(v){ hpContactsRender(v); }
function hpContactsRender(filter){
  var box=document.getElementById('ctList'); if(!box) return;
  var d=hpContactData;
  if(!d){ box.innerHTML='<div class="hint">正在读取名册…</div>'; return; }
  var q=String(filter||'').trim(), out=[], total=0, gi, ri;
  for(gi=0;gi<d.groups.length;gi++){
    var g=d.groups[gi], rows=[];
    for(ri=0;ri<g.names.length;ri++){
      var n=g.names[ri], club=d.clubOf[n]||'';
      if(q && n.indexOf(q)<0 && g.name.indexOf(q)<0 && club.indexOf(q)<0) continue;
      rows.push({n:n, c:club});
    }
    total+=rows.length;
    if(rows.length) out.push({g:g.name, rows:rows});
  }
  var h='<div class="ctCount">共 '+total+' 人'
        +(q?('（筛选「'+hpEsc(q)+'」）'):'')
        +(d.groups.length?'':' —— 没找到「学生人员表」条目')+'</div>';
  for(gi=0;gi<out.length;gi++){
    h+='<div class="ctGroup">'+hpEsc(out[gi].g)+' · '+out[gi].rows.length+' 人</div>';
    for(ri=0;ri<out[gi].rows.length;ri++){
      var r=out[gi].rows[ri];
      h+='<div class="ctRow" data-n="'+hpEsc(r.n)+'"><b>'+hpEsc(r.n)+'</b>'+(r.c?('<i class="ctClub">'+hpEsc(r.c)+'</i>'):'')+'</div>';
    }
  }
  box.innerHTML=h;
}
