// ═══ 走廊布告板（App 页）═══
// 板面：一次生成 10 张布告，**全部混贴不分栏**（新闻/通告/失物招领/社团海报随手贴在一起）；
// 成绩单是单独一张卷着的纸，点开才生成展开。
// 打开时由 AI 现场生成一份，并把摘要写进同步世界书「新中市·布告板」（常驻），
// 让 AI 在剧情正文里也能引用同一块板 —— 玩家才能拿板上的事去跟角色聊。
var boardLoaded=false, boardLoading=false, boardFlat=[], HP_BOARD_ENTRY='新中市·布告板';
// 成绩单单独懒生成：板面先出来，成绩单是「卷着的」，玩家点一下才展开并生成
var boardData=null, boardRk=null, boardExam=null, boardExamLoading=false;

function hpOpenBoard(){
  hpShowTab('boardTab'); hpBoardShowList(); hpEnsureActor();
  if(!boardLoaded){ boardLoaded=true; hpBoardGenerate(); }
}
function hpBoardShowList(){
  var a=document.getElementById('boardList'), b=document.getElementById('boardDetail');
  if(a) a.style.display=''; if(b) b.style.display='none';
}
function hpBoardBack(){ hpBoardShowList(); }
function hpBoardRefresh(){ boardLoaded=true; hpBoardGenerate(); }

// 玩家在这次大型考试里的名次：把身份卡已有的各科成绩折算成**本年级**排名。
// 人数取本年级花名册的真实人数；只在同年级内排 —— 初中部和高中部不会同场考试。
// 只算名次与总分，榜上其他人由 AI 填 —— 这样名次必定与自己的成绩自洽。
function hpBoardRank(){
  if(!studentCache || !studentCache.card) return null;
  var g=studentCache.grades||[];
  if(!g.length) return null;
  var total=0, max=0, i;
  for(i=0;i<g.length;i++){ total+=Number(g[i].v)||0; max+=100; }
  if(!max) return null;
  var grade=String(studentCache.card.grade||'');
  var names=studentCache.gradeNames||[];
  var N=names.length;
  if(!N){                                              // 读不到花名册 → 按本年级班级数估
    try{
      var fac=hpFacultyOf(grade);
      var arr=(studentCache.classes && studentCache.classes[fac]) || [];
      var cnt=0;
      for(i=0;i<arr.length;i++){ if(hpClassNorm(arr[i]).indexOf(grade)===0) cnt++; }
      N=cnt?cnt*28:56;
    }catch(e){ N=56; }
  }
  var pct=total/max;
  return { name:String(studentCache.card.name||'该角色'), grade:grade||'本年级',
           total:total, max:max,
           rank:Math.max(1,Math.min(N,Math.round((1-pct)*N))), of:N };
}

function hpBoardGenerate(){
  if(boardLoading) return;
  var body=document.getElementById('boardBody'); if(!body) return;
  if(!hpIsTavern() || !hpWbApi()){ body.innerHTML='<div class="bSmall">演示模式：布告板要在酒馆里才生成得出内容。</div>'; return; }
  var TH=window.parent.TavernHelper;
  if(!TH || !TH.generateRaw){ body.innerHTML='<div class="bSmall">生成接口不可用。</div>'; return; }
  boardLoading=true;
  boardExam=null; boardExamLoading=false;         // 重新张贴 → 成绩单重新卷起
  body.innerHTML='<div class="bSmall">正在看板……</div>';
  var rk=hpBoardRank();
  Promise.all([hpLoadWorldbooks(TH), hpReadMessages()]).then(function(res){
    var entries=res[0]||[], msgs=res[1]||[], i;
    var roster=hpFindEntry(entries,'新中市国立学校学生人员表');
    var club=hpFindEntry(entries,'新-新中市国立学校社团表（38）');
    var t=hpCalToday();
    var txt='';
    for(i=Math.max(0,msgs.length-10);i<msgs.length;i++){ var mm=msgs[i]||{}; txt+=String(mm.mes||mm.content||mm.message||'')+'\n'; }
    var ps=[
      { role:'system', content:'【任务】你在演「新中市国立学校」一层走廊的布告板。根据最近的剧情与当前日期，生成**今天贴在板上的 10 张布告**，只输出 JSON。\n'
        +'【内容配比】10 张**混在一起、顺序打乱**（看起来像随手一张张贴上去的，**不要按类型归类排布**）：\n'
        +'· 新闻部（部长畑兰子）的校报短讯 2~3 张：校园里最近发生的事、社团动向、人物八卦，客观报道口吻。\n'
        +'· 学生会的通告与启事 2~3 张：通知、值周、集会。其中要有 1~2 张**失物招领**——有人捡到东西写 "tag":"found"，有人丢了东西写 "tag":"lost"。\n'
        +'· 各社团的海报 2~3 张：招新、活动预告、比赛战报，加 "by":"社团名"，社团名必须取自下方【社团表】里真实存在的社团。\n'
        +'· 剩下的可以是校园杂项：寻人、约球、转让、拼单、找人还书之类。\n'
        +'【硬性】\n'
        +'· 名字一律用下方名册里的真实角色，不要编造。\n'
        +'· 内容是**板上公开可见**的公告文字，不要写成旁白、心理描写或小说叙述。\n'
        +'· 与最近剧情呼应，但别剧透玩家还没经历过的事。\n'
        +'· 标题短（12 字以内），正文一两句话。\n'
        +'【输出格式】严格只输出：{"notes":[{"t":"标题","x":"正文"},{"t":"标题","x":"正文","tag":"lost"},{"t":"标题","x":"正文","by":"漫画研究社"}]}，恰好 10 条，不要输出其它内容。' },
      { role:'system', content:'【全校学生名册】'+(roster?String(roster.content).slice(0,3000):'（读不到，名字可取自最近剧情里的学生）') },
      { role:'system', content:'【社团表】'+(club?String(club.content).slice(0,2500):'（读不到）') },
      { role:'system', content:'【当前剧情日期】'+(t?(t.y+'年'+t.m+'月'+t.d+'日'):'未知') },
      { role:'system', content:'【最近剧情】\n'+(txt.trim()||'（读不到剧情，按普通校园日常来）') }
    ];
    var order=['world_info_before','persona_description','char_description','char_personality','scenario','world_info_after'].concat(ps).concat(['chat_history','user_input']);
    return TH.generateRaw({ user_input:'【请生成今天的走廊布告板。】', ordered_prompts: order });
  }).then(function(reply){
    boardLoading=false;
    var s=hpCleanText(reply), obj=null;
    try{ obj=JSON.parse(s); }catch(e){ var m=s.match(/\{[\s\S]*\}/); if(m){ try{ obj=JSON.parse(m[0]); }catch(e2){ obj=null; } } }
    if(!obj){ body.innerHTML='<div class="bSmall">这次没生成出来，点「重新张贴」再试一次。</div>'; return; }
    hpBoardRender(obj, rk);
    hpBoardSyncWb(obj, rk);
  }).catch(function(e){
    boardLoading=false;
    body.innerHTML='<div class="bSmall">布告板生成失败：'+hpEsc(String((e&&e.message)||e).slice(0,40))+'</div>';
  });
}

function hpBoardRender(d, rk){
  if(d){ boardData=d; boardRk=rk; }
  // 再渲染（切成"正在展开"、展开完成、加载中）时传的是 (null,null)：
  // 必须回落到上次存下的数据与名次，否则 rk 变 null，玩家那一行就没了
  else { d=boardData; rk=boardRk; }
  boardFlat=[];
  var body=document.getElementById('boardBody'); if(!body) return;
  var h='', i, n=0;
  var PINS=['#e04b4b','#e8a33d','#5b9bd5','#4caf7d','#b06ad6'];
  var PAPERS=['#fdf3a8','#ffdbe9','#d9f2c9','#d3e7fb','#ffe4bd','#f6e6c8','#e8f5d8','#ffe9c9'];
  var ROT=[-7,4,-3,8,-5,2,6,-8,3,-2];     // 角度参差（更大，才够乱）
  // 全部混贴，不分栏 —— 通告、新闻、社团海报、失物招领随手贴在一起
  var list=(d&&d.notes)||[];
  h+='<div class="bNotes" id="boardNotes">';
  for(i=0;i<list.length;i++){
    var it=list[i], idx=boardFlat.length, tg=String(it.tag||'');
    boardFlat.push({kicker:(tg==='lost'||tg==='found')?'失物招领':(it.by?String(it.by):'布告'),
                    t:hpBoardTitle(it), x:String(it.x||'')});
    var decor=(n%3===2)
      ? '<span class="tape"></span>'
      : '<span class="pin" style="background:'+PINS[n%PINS.length]+'"></span>';
    var tag='';
    if(tg==='lost') tag='<span class="bTag lost">失物</span>';
    else if(tg==='found') tag='<span class="bTag">招领</span>';
    else if(it.by) tag='<span class="bTag act">'+hpEsc(it.by)+'</span>';
    // 宽度/位置由 hpBoardLayout 统一算，这里只给纸张颜色、角度、字号、内边距（大小不一）
    // 纸型轮换：普通 / 撕边 / 折角 / 普通 —— 板面才像被人撕过、折过
    var pkind=(n%4), cls='bNote', clip='';
    if(pkind===1){ cls+=' torn'; clip=';clip-path:'+hpTornClip(n+3); }
    else if(pkind===2){ cls+=' fold'; }
    h+='<div class="'+cls+'" style="background:'+PAPERS[n%PAPERS.length]
      +';transform:rotate('+ROT[n%ROT.length]+'deg);z-index:'+(10+(n%9))
      +';font-size:'+(10.4+((n*3)%4)*0.75).toFixed(1)+'px'
      +';padding:'+(12+((n*5)%4)*2)+'px 9px 9px'+clip+'"'
      +' onclick="hpBoardItem('+idx+')">'+decor
      +'<div class="bt">'+tag+hpEsc(hpBoardTitle(it))+'</div>'
      +'<div class="bx">'+hpEsc(String(it.x||'').replace(/\n/g,' '))+'</div></div>';
    n++;
  }
  h+='</div>';
  // 成绩单：默认卷着，点一下才展开并现场生成。占满一整行。
  h+='<div class="bSheetWrap">';
  if(boardExam && boardExam.rows && boardExam.rows.length){
    h+=hpBoardExamSheet(boardExam, rk);
  } else if(boardExamLoading){
    h+='<div class="bRolled"><span class="pin" style="background:#e04b4b"></span>'
      +'<div class="bRollTit">📜 大型考试成绩公示</div><div class="bRollHint">正在展开……</div></div>';
  } else {
    h+='<div class="bRolled" onclick="hpBoardExpandExam()"><span class="pin" style="background:#e04b4b"></span>'
      +'<div class="bRollTit">📜 大型考试成绩公示</div><div class="bRollHint">卷着呢 —— 点一下展开</div></div>';
  }
  h+='</div>';
  h+='<div class="bSmall">本板由 AI 依据最近的剧情生成，随时可点「重新张贴」换一批。</div>';
  body.innerHTML=h;
  hpBoardLayout();          // 便利贴要等 DOM 就位后才能量高度、算错落位置
}

// 标题里若自带「招领：」这类前缀就去掉 —— 标签由系统另行加，否则会「招领 招领：…」重复一遍
function hpBoardTitle(it){
  var s=String((it&&it.t)||''), tg=String((it&&it.tag)||'');
  if(tg==='lost'||tg==='found') s=s.replace(/^\s*(招领|失物|寻物|认领|启示|启事)\s*[：:·\-]?\s*/,'');
  return s;
}
// 生成一圈带抖动的轮廓，模拟手撕的毛边：四边各 6 段，只向内咬（0~4%），不会超框
function hpTornClip(seed){
  var N=6, pts=[], j;
  function bite(k){ return Number((((k*seed*7)%6)*1.3).toFixed(1)); }
  for(j=0;j<=N;j++) pts.push((j*100/N).toFixed(1)+'% '+bite(j+1)+'%');            // 上边：左→右
  for(j=1;j<=N;j++) pts.push((100-bite(j+11))+'% '+(j*100/N).toFixed(1)+'%');     // 右边：上→下
  for(j=N-1;j>=0;j--) pts.push((j*100/N).toFixed(1)+'% '+(100-bite(j+21))+'%');   // 下边：右→左
  for(j=N-1;j>=1;j--) pts.push(bite(j+31)+'% '+(j*100/N).toFixed(1)+'%');         // 左边：下→上
  return 'polygon('+pts.join(',')+')';
}
// 把便利贴按「当前最矮的那一栏」错落摆开：宽度/水平抖动/垂直错位都带参差，并允许压边。
// 目标是看起来像随手一张张糊上去的 —— flex 那种整齐两列排不出这个效果。
function hpBoardLayout(){
  var wrap=document.getElementById('boardNotes'); if(!wrap) return;
  var notes=wrap.querySelectorAll('.bNote');
  var W=wrap.clientWidth;
  if(!W || !notes.length){ wrap.style.height=notes.length?'auto':'0px'; return; }
  var lanes=[{x:0,      w:W*0.575, b:0},     // 左栏偏宽
             {x:W*0.60, w:W*0.395, b:9}];    // 右栏偏窄，且整体往下压一点
  var i, maxB=0;
  for(i=0;i<notes.length;i++){
    var el=notes[i];
    var lane=(lanes[0].b<=lanes[1].b) ? lanes[0] : lanes[1];   // 挑最矮的一栏 → 高低不齐
    var wf=0.78+((i*7)%9)*0.062;                               // 宽度在带宽 78%~128% 之间抖 → 大小不一
    var w=Math.round(lane.w*wf);
    if(w>W*0.80) w=Math.round(W*0.80);
    if(w<W*0.33) w=Math.round(W*0.33);
    el.style.width=w+'px';
    var h=el.offsetHeight;
    // 水平抖动主要往右推，免得左边缘排成一条直线；宽纸会压进另一栏
    var x=Math.round(lane.x+(((i*5)%7)-1)*9);
    if(x<0) x=0;
    if(x+w>W) x=W-w;
    var y=Math.round(lane.b+(((i*5)%5)-2)*8);
    if(y<0) y=0;
    el.style.left=x+'px';
    el.style.top=y+'px';
    lane.b=y+h+4+(((i*3)%3)-1)*5;      // 负值＝下一张压到这张上
    if(lane.b>maxB) maxB=lane.b;
  }
  wrap.style.height=Math.round(maxB+20)+'px';
}

// 成绩单那张打印纸（把玩家那一行按名次插进榜里）
function hpBoardExamSheet(ex, rk){
  var rows=ex.rows.slice(), myRank=rk?rk.rank:0, i, h='';
  if(rk && myRank>0){
    var placed=false;
    for(i=0;i<rows.length;i++){
      if(Number(rows[i].no)===myRank){ rows[i]={no:myRank, name:rk.name, score:rk.total, me:true}; placed=true; break; }
    }
    if(!placed) rows.push({no:myRank, name:rk.name, score:rk.total, me:true, sep:true});
  }
  h+='<div class="bSheet"><span class="pin" style="background:#e04b4b"></span>'
    +'<div class="bSheetTit">'+hpEsc(ex.title||'成绩公示')+'</div>';
  for(i=0;i<rows.length;i++){
    var r=rows[i];
    if(r.sep) h+='<div class="bSheetNote">……</div>';
    h+='<div class="bRankRow'+(r.me?' bMe':'')+'"><span class="bRankNo">'+hpEsc(r.no)+'</span>'
      +'<span class="bRankName">'+hpEsc(r.name)+'</span><span class="bRankScore">'+hpEsc(r.score)+' / 600</span></div>';
  }
  if(rk) h+='<div class="bSheetNote">本年级（'+hpEsc(rk.grade)+'）共 '+rk.of+' 人参加；你的名次由身份卡里的成绩折算。</div>';
  return h+'</div>';
}

// 成绩单要知道「你是哪个年级的」。玩家可能还没开过身份卡（studentCache 为空）→ 这里先补一次。
// 和身份卡页「🔄 更新」走同一条路（判角色 → 读世界书 → 建缓存），但不碰它的界面；判不出角色就返回 null。
function hpBoardEnsureStudent(){
  if(studentCache && studentCache.card) return Promise.resolve(studentCache);
  return Promise.resolve()
    .then(function(){ return hpJudgeActor(); })
    .then(function(actor){ return actor ? hpLoadStudentData(actor) : null; })
    .then(function(data){
      if(data){ studentCache=data; hpStuSaveCache(); }
      return studentCache;
    })
    .catch(function(){ return studentCache; });
}

// 展开成绩单：这时才让 AI 生成榜单
function hpBoardExpandExam(){
  if(boardExamLoading) return;
  if(boardExam && boardExam.rows && boardExam.rows.length) return;
  var TH=window.parent.TavernHelper;
  if(!hpIsTavern() || !TH || !TH.generateRaw) return;
  boardExamLoading=true;
  hpBoardRender(null, null);                      // 先切成「正在展开」
  hpBoardEnsureStudent().then(function(sc){
    if(!sc || !sc.card){
      // 判不出当前角色：与其生成一张没有年级、也没有你名次的榜，不如说清原因
      boardExamLoading=false;
      hpToast('先去「身份卡」点「🔄 更新」确定当前角色，成绩单才知道按哪个年级排');
      hpBoardRender(null, null);
      return null;
    }
    boardRk=hpBoardRank();                        // 补上身份卡后重算名次
    var gradeName=String((sc.card&&sc.card.grade)||'');
    var gNames=sc.gradeNames||[];
    return Promise.all([hpLoadWorldbooks(TH), hpReadMessages()]).then(function(res){
      var entries=res[0]||[], msgs=res[1]||[], i;
      var txt='';
      for(i=Math.max(0,msgs.length-10);i<msgs.length;i++){ var mm=msgs[i]||{}; txt+=String(mm.mes||mm.content||mm.message||'')+'\n'; }
      var t=hpCalToday();
      var ps=[
        { role:'system', content:'【任务】你在给「新中市国立学校」的布告板生成一张**'+gradeName+'**的大型考试成绩公示，只输出 JSON。\n'
          +'【硬性】\n'
          +'· 范围**只限「'+gradeName+'」这一个年级**——初中部和高中部不会同场考试，绝不许把别的年级的学生写进来。\n'
          +'· 榜上写该年级排名前 10，姓名**必须取自下方【本年级名册】**，不要编造。\n'
          +'· **分数必须按这些角色既有的学业设定来定，不要随机分配**：设定里公认聪明的、认真的、优等生、学生干部一类排前面、分数高；'
          +'设定上是笨蛋、吊车尾、明显不学习的角色**不许进前十**。若一时判断不出，就优先选名册里以学业见长的角色。\n'
          +'· 总分满分 600，从高到低递减，相邻名次差 3~12 分。\n'
          +'· title 要写明年级与考试名，例如「'+gradeName+'期中考试成绩公示」。\n'
          +'【输出格式】严格只输出 {"title":"'+gradeName+'期中考试成绩公示","rows":[{"no":1,"name":"姓名","score":588}]}，不要输出其它内容。' },
        { role:'system', content:'【本年级名册（'+gradeName+'）】'+(gNames.length?gNames.join('、'):'（读不到，改用最近剧情里同年级的学生）') },
        { role:'system', content:'【当前剧情日期】'+(t?(t.y+'年'+t.m+'月'+t.d+'日'):'未知') },
        { role:'system', content:'【最近剧情】\n'+(txt.trim()||'（读不到剧情，按普通校园日常来）') }
      ];
      var order=['world_info_before','persona_description','char_description','char_personality','scenario','world_info_after'].concat(ps).concat(['chat_history','user_input']);
      return TH.generateRaw({ user_input:'【请生成这张成绩公示。】', ordered_prompts: order });
    });
  }).then(function(reply){
    if(reply===null || reply===undefined) return;   // 上面已经处理过（缺角色）
    boardExamLoading=false;
    var s=hpCleanText(reply), obj=null;
    try{ obj=JSON.parse(s); }catch(e){ var m=s.match(/\{[\s\S]*\}/); if(m){ try{ obj=JSON.parse(m[0]); }catch(e2){ obj=null; } } }
    if(obj && obj.rows && obj.rows.length) boardExam=obj;
    hpBoardRender(null, null);
    if(boardExam) hpBoardSyncWb(boardData, boardRk);
  }).catch(function(e){
    boardExamLoading=false;
    hpWarn('成绩单展开失败：'+((e&&e.message)||e));
    hpBoardRender(null, null);
  });
}

function hpBoardItem(i){
  var it=boardFlat[i]; if(!it) return;
  document.getElementById('boardDetailKicker').textContent=it.kicker;
  document.getElementById('boardDetailTit').textContent=it.t;
  document.getElementById('boardDetailBody').textContent=it.x;
  document.getElementById('boardList').style.display='none';
  document.getElementById('boardDetail').style.display='';
}

// 把板面摘要写进同步世界书（常驻）——AI 在正文里就能引用板上写了什么
function hpBoardSyncWb(d, rk){
  if(!hpIsTavern() || !hpWbApi()) return;
  var L=['【新中市 · 走廊布告板】','（学校一层走廊的布告板，玩家随时可以去看。以下是当前贴在上面的内容。）'];
  var list=(d&&d.notes)||[], i;
  for(i=0;i<list.length && i<10;i++){
    var it=list[i], tg=String(it.tag||''), pre='';
    if(tg==='lost') pre='[失物] ';
    else if(tg==='found') pre='[招领] ';
    else if(it.by) pre='['+it.by+'] ';
    // 正文长度上限只是防 AI 单次跑飞（无视"一两句话"的指令）；条目本身是按名覆盖 + 最多 10 条，
    // 不会随时间累积。真被砍了就补省略号，别留半截话。
    var body=String(it.x||'').replace(/\n/g,' ');
    if(body.length>120) body=body.slice(0,120)+'…';
    L.push('- '+pre+hpBoardTitle(it)+'：'+body);
  }
  var ex=boardExam;                                  // 成绩单是点开才生成的，没展开就不写这条
  if(ex && ex.rows && ex.rows.length){
    var top=[];
    for(var j=0;j<Math.min(3,ex.rows.length);j++) top.push(ex.rows[j].name);
    L.push('- [成绩] '+(ex.title||'成绩公示')+'：'
      +((rk&&rk.grade)?(rk.grade+'共 '+rk.of+' 人，前几名 '):'前几名 ')+top.join('、')
      +(rk?('；'+rk.name+' 第 '+rk.rank+' 名（总分 '+rk.total+'/600）'):''));
  }
  hpWbSetEntry(HP_BOARD_ENTRY, L.join('\n')).catch(function(e){ hpWarn('布告板同步失败：'+((e&&e.message)||e)); });
}

