// ——— 动态/帖子里的媒体（2026-09-16 用户要求：SNS 与论坛也同理）———
// 生成内容里允许 <photo>画面描述</photo> / <music>歌名</music>：
// · HTML 场合（动态卡片）→ 直接换成 chip 的 HTML（hpRenderInlineMedia）
// · 纯文本场合（帖子正文/回复）→ 抽出来交给调用方用 mediaChip 渲染（hpTextAndMedia）
function hpMediaChipHTML(kind,data,idx){
  if(kind==='music'){
    var nm=hpEsc(((data&&data.sub)?(data.sub+' · '):'')+((data&&data.name)||''));
    return '<span class="mChip"><span class="mic">🎵</span><span class="mtxt">'+nm+'</span>'
      +'<button class="mPlay" onclick="playSentMedia('+idx+')">▶ 播放</button></span>';
  }
  return '<span class="mChip"><span class="mic">🖼</span><span class="mtxt">[照片] 点击查看</span>'
    +'<button class="mView" onclick="viewSentPhoto('+idx+')">👁 查看</button></span>';
}
function hpRenderInlineMedia(html){
  var out=String(html||'');
  out=out.replace(/<photo>([\s\S]*?)<\/photo>/gi,function(m,p){
    var t=String(p).replace(/<[^>]*>/g,'').trim(); if(!t) return '';
    var it=hpPushMedia('photo',t); return hpMediaChipHTML(it.kind,it.data,it.idx);
  });
  out=out.replace(/<music>([\s\S]*?)<\/music>/gi,function(m,p){
    var t=String(p).replace(/<[^>]*>/g,'').trim(); if(!t) return '';
    var it=hpPushMedia('music',t); return hpMediaChipHTML(it.kind,it.data,it.idx);
  });
  return out.replace(/<\/?(?:photo|music)>/gi,'');
}
function hpTextAndMedia(raw){
  var media=[], s=String(raw||'');
  function take(kind,re){
    s=s.replace(re,function(m,p){ var t=String(p).trim(); if(t){ media.push(hpPushMedia(kind,t)); } return ''; });
  }
  take('photo',/<photo>([\s\S]*?)<\/photo>/gi);
  take('music',/<music>([\s\S]*?)<\/music>/gi);
  s=s.replace(/<\/?(?:photo|music)>/gi,'');
  return { text:s.trim(), media:media };
}
function renderFeedCards(raw){
