  tmp.innerHTML=hpRenderInlineMedia(String(raw||'').replace(/<swl>[\s\S]*?<\/swl>/g,'').replace(/<\/?swl>/g,''));
  var cards=tmp.querySelectorAll('.card');
  if(cards.length){
    for(var i=0;i<cards.length;i++){
      var c=cards[i];
      if(!c.querySelector('.name')){
        var nb=c.querySelector('[onclick*="openProfile("]')||c.querySelector('b');
        if(nb && !nb.className) nb.className='name';
      }
      feedCards.appendChild(c);
    }
  }else{
    var d=document.createElement('div');
    d.className='card';
    d.textContent=(tmp.textContent||'暂时没有更多动态了').replace(/\s+/g,' ').trim().slice(0,120);
