function addSet(s,v){ s[v]=1; }
function buildNameMap(){
  var map={},acc={},real={};
  var els=document.querySelectorAll('#feed [onclick],#profile [onclick]');
  for(var i=0;i<els.length;i++){
    var oc=els[i].getAttribute('onclick')||'';
    var m;
    var re=/openProfile\(['"]([^'"]+)['"],['"]([^'"]+)['"]\)/g;
    while((m=re.exec(oc))){ addNameMap(map,m[1],m[2]); addSet(acc,m[1]); addSet(real,m[2]); }
    var re2=/openDM\(['"]([^'"]+)['"],['"]([^'"]+)['"]\)/g;
    while((m=re2.exec(oc))){ addNameMap(map,m[1],m[2]); addSet(acc,m[1]); addSet(real,m[2]); }
  }
  window.__snsNameMap=map;
  window.__snsAccounts=acc;
  window.__snsReals=real;
  return map;
}
