  if(acc[v]&&map[v]){ target={a:v,r:Array.from(map[v])[0]}; }
  else if(real[v]){
    var keys=Object.keys(acc);
    for(var i=0;i<keys.length&&!target;i++){
      if(map[keys[i]]&&map[keys[i]].has(v))target={a:keys[i],r:v};
