// 私信/群聊/回帖气泡上的时间一律用**剧情时间**（hpStoryDate），不是现实时间（2026-09-15 用户报）。
// 剧情时间还推不出来时（新聊天、刚开局）才退回系统时间，否则会和剧情里的日期对不上。
function hpStoryHHMM(){
  var hh='', mm='';
  if(hpStoryDate && hpStoryDate.time){
    var t=String(hpStoryDate.time).match(/(\d{1,2}):(\d{2})/);
    if(t){ hh=('0'+t[1]).slice(-2); mm=t[2]; }
  }
  if(!hh){ var now=new Date(); hh=('0'+now.getHours()).slice(-2); mm=('0'+now.getMinutes()).slice(-2); }
  return hh+':'+mm;
}
// 从「4月8日 16:15」这类剧情时间串里抠出 HH:MM（补零）
function hpHHMMOf(s){ var m=String(s||'').match(/(\d{1,2}):(\d{2})/); return m?(('0'+m[1]).slice(-2)+':'+m[2]):''; }
// 剧情时间的「可比较刻度」（粗略但单调递增，够用来算"隔了多久"）：
// 把 年-月-日 时:分 压成一个分钟数。日期未知时返回 null。
function hpStoryMinutes(){
  var d=hpStoryDate; if(!d) return null;
  var t=String(d.time||'').match(/(\d{1,2}):(\d{2})/);
  var hh=t?parseInt(t[1],10):0, mm=t?parseInt(t[2],10):0;
  return ((((d.y||0)*12+(d.m||0))*31+(d.d||0))*1440)+hh*60+mm;
}
// 两个「剧情时间」之间的差值（分钟）。now 缺省取当前剧情时间。
function hpStoryGapMin(fromMin, toMin){
  if(fromMin==null) return null;
  var now=(toMin==null)?hpStoryMinutes():toMin;
  if(now==null) return null;
  var g=now-fromMin;
  return g>0?g:0;
}
// 把分钟差说成人话：90 → "1 小时 30 分钟"
function hpHumanGap(min){
  if(min==null) return '';
  if(min<60) return min+' 分钟';
  var h=Math.floor(min/60), m=min%60;
  return h+' 小时'+(m?(' '+m+' 分钟'):'');
}
// ——— 「玩家隔了多久才回私信」———
// 打开私信页时会记下**对方最后一条消息的时间**（从聊天记录的标记里取），玩家回复时据此算间隔。
// 用途：角色可以在回复里抱怨/追问"怎么这么久才回"。
var hpDmInboundAt='';
var HP_DM_GAP_MIN=30;         // 半小时以内不算"长时间不回"
function hpDMGapMin(){
  if(!hpDmInboundAt) return null;
  function toMin(s){ var m=String(s||'').match(/(\d{1,2}):(\d{2})/); return m?(parseInt(m[1],10)*60+parseInt(m[2],10)):null; }
  var a=toMin(hpDmInboundAt), b=toMin(hpStoryHHMM());
  if(a==null || b==null) return null;
  var d=b-a; if(d<0) d+=1440;      // 跨天：剧情日期拿不准时按 24 小时回绕，够用
  return d;
}
function hpDMGapHint(){
  var d=hpDMGapMin();
  if(d==null || d<HP_DM_GAP_MIN) return '';
  return '【回复间隔】距你上一次发消息已经过了 '+hpHumanGap(d)+'（剧情时间），玩家这才回你。'
    + '如果以你的性格合情合理，可以在这条回复里**抱怨或追问**这件事（例如"怎么这么久才回我""我等了半天了"）；'
    + '不想提也可以不提。禁止编造别的理由来解释这段时间。';
}
// ——— 让「对方角色」也能发媒体（2026-09-16 用户要求：只有玩家能发不真实）———
// 做法：把内容塞进既有的 sentMediaSongs / sentMediaPhotos 两个数组，复用 mediaChip/查看/播放，
// 完全不改旧逻辑（那些按钮本来就是按下标取内容的）。
function hpFindSongByName(nm){
  var t=String(nm||'').trim(); if(!t) return null;
  var all=(typeof mediaAllSongs==='function')?mediaAllSongs():(MUSIC_LIB||[]);
  var i;
  for(i=0;i<all.length;i++){ if(String(all[i].name||'').trim()===t) return all[i]; }
  for(i=0;i<all.length;i++){
    var n=String(all[i].name||'');
    if(n && (n.indexOf(t)>=0 || t.indexOf(n)>=0)) return all[i];
  }
  return null;   // 曲库里没有 → 当"提到了一首歌"，不给播放按钮
}
function hpPushMedia(kind,data){
  if(kind==='music'){
    var song=hpFindSongByName(data);
    var item=song||{name:String(data||'').trim(), sub:'', url:''};
    sentMediaSongs.push(item);
    return {kind:'music', data:item, idx:sentMediaSongs.length-1};
  }
  sentMediaPhotos.push(String(data||'').trim());
  return {kind:'photo', data:String(data||'').trim(), idx:sentMediaPhotos.length-1};
}
// 从回复里剥出「角色发来的媒体」：<photo>画面内容</photo> / <music>歌名</music>
function hpExtractMedia(raw){
  var media=[], s=String(raw||'');
  s=s.replace(/<photo>([\s\S]*?)<\/photo>/gi,function(m,p){ var t=String(p).trim(); if(t) media.push({kind:'photo',data:t}); return ''; });
  s=s.replace(/<music>([\s\S]*?)<\/music>/gi,function(m,p){ var t=String(p).trim(); if(t) media.push({kind:'music',data:t}); return ''; });
  s=s.replace(/<\/?(?:photo|music)>/gi,'');
  return { text:s.trim(), media:media };
}
// 把「媒体」写成聊天记录里的一行（与玩家发媒体同一套措辞，恢复时才能认出来）
function hpMediaLine(who,kind,data){
  if(kind==='music') return (who?who+' ':'')+'发送了一首歌《'+String((data&&data.name)||data||'')+'》';
  return (who?who+' ':'')+'发送了一张照片，画面内容是：'+String(data||'');
}
// 判断一段私信正文是不是「媒体记录」；是就返回 {kind,data}，否则 null
function hpMediaOfText(text){
  var t=String(text||'').trim();
  var m1=t.match(/^(?:[^\s：:]{1,12}\s+)?发送了一张照片，画面内容是：([\s\S]+)$/);
  if(m1) return {kind:'photo', data:m1[1].trim()};
  var m2=t.match(/^(?:[^\s：:]{1,12}\s+)?发送了一首歌《([^》]+)》/);
  if(m2) return {kind:'music', data:m2[1].trim()};
  return null;
}
