function buildDMHistory(account,real,actor){
  var rows=document.querySelectorAll('#dmBody .rowL,#dmBody .rowR');
  var lines=[];
  for(var i=0;i<rows.length;i++){
    var b=rows[i].querySelector('.bubble'); if(!b)continue;
    var isR=rows[i].className.indexOf('rowR')>=0;
    lines.push((isR?((actor||'对方')+'：'):'@'+account+'（'+real+'）：')+b.textContent);
  }
  return lines.join('\n')||'（暂无历史，这是第一条私信）';
}
function extractCard(card){
  return card?card.textContent.replace(/\s+/g,' ').trim():'';
