function captureDMContext(account,real){
  var els=document.querySelectorAll('#feed .chip,#feed .name,#feed .statCmt,#profile .chip,#profile .statCmt');
  for(var i=0;i<els.length;i++){
    var oc=els[i].getAttribute('onclick')||'';
    if(oc.indexOf("openDM('"+account+"','"+real+"')")>=0){
      var c=els[i];
      while(c&&String(c.className||'').indexOf('card')<0)c=c.parentElement;
      return extractCard(c);
    }
  }
  return '';
}
function splitThought(raw){
  var thoughts=[];
  var clean=hpStripReasoning(raw||'').replace(/<swl>[\s\S]*?<\/swl>/g,function(m){ thoughts.push(m.replace(/<\/?swl>/g,'').trim()); return ''; });
  clean=clean.replace(/<swl>/g,'').replace(/<\/swl>/g,'');
  return { thoughts:thoughts, text:clean.trim() };
}
