    .then(function(){
      var prompts=[
        { role:'system', content:'【群聊回复模式】你们是 X站 群聊里的成员，群成员是：'+members.join('、')+'。现在有人在群里发了一条消息。\n【硬性规则】\n1. 只输出群内各成员本次的发言，每条单独一行，格式：「成员名：发言内容」。\n2. 成员名必须使用群成员名单里的名字原文，严禁编造或改写成员名，严禁出现"群员A/路人/观众"等非成员名字。\n3. 严禁输出任何非对话内容：场景描写、心理独白、剧情旁白、思考推理、叙述性说明。\n4. 不要用 *星号动作*，不要用引号包裹整段，不要出现"XX说道"等旁白。\n5. 保持各成员人设与口吻，像真实群聊一样简短自然，通常 2~4 名成员回应即可，不必全员说话。\n6. 若确有内心想法想表达，放在 <swl>...</swl> 标记内（app 会自动折叠），不要写进正式回复。' }
      ];
      prompts.push({ role:'system', content:'【对方身份】在群里发消息的是 '+actor+'（玩家当前扮演的角色，正在以 '+actor+' 的身份发言）。各成员按各自与 '+actor+' 的关系自然回应。' });
      if(grpDMContext)prompts.push({ role:'system', content:'【私聊记忆】私聊对象（'+members[0]+'）与 '+actor+' 之前私聊过这些内容，'+members[0]+' 记得并可在群里自然衔接或回应：\n'+grpDMContext+'\n（这段私聊只有 '+members[0]+' 与 '+actor+' 知道，'+members[0]+' 不要向其他成员复述私聊内容，除非剧情合适。）' });
      prompts.push({ role:'system', content:'【群聊历史】\n'+buildGroupHistory(actor)+'\n\n现在群成员们回应 '+actor+' 刚才这条消息：' });
      return hpGenReply('【你们是群成员 '+members.join('、')+'，回复 '+actor+' 刚才这条群聊消息。只输出各成员发言，每人一行「成员名：内容」，别的不输出。】', prompts, 'sns');
    })
    .then(function(reply){
      setTyping(false,gbody);
      if(reply&&typeof reply==='object'&&reply.content)reply=reply.content;
      var replies=parseGroupReplies(reply,members);
      for(var i=0;i<replies.length;i++){
        addGroupBubble(replies[i].name,replies[i].text,'L');
        if(replies[i].thoughts.length)addThought(replies[i].thoughts,gbody);
      }
      return createChatMessages([{role:'assistant',message:reply,content:reply}],{refresh:'none'});
    })
    .catch(function(e){ setTyping(false,gbody); console.error(e); hpWarn('群聊生成失败（AI 未返回内容）：'+((e&&e.message)||e)); });
  document.getElementById('grpText').value='';
