function buildGroupHistory(actor){
  var rows=document.querySelectorAll('#grpBody .rowL,#grpBody .rowR');
  var lines=[];
  for(var i=0;i<rows.length;i++){
    var b=rows[i].querySelector('.bubble'); if(!b)continue;
    var g=rows[i].querySelector('.gname');
    var c=b.querySelector('.gcontent');
    var txt=c?c.textContent:b.textContent;
    var nm=g?g.textContent:(rows[i].className.indexOf('rowR')>=0?(actor||'对方'):'');
    lines.push((nm?nm+'：':'')+txt);
  }
  return lines.join('\n')||'（暂无消息，这是群聊第一条）';
}
function parseGroupReplies(raw,members){
  var replies=[];
  var lines=String(raw||'').split(/\r?\n+/);
  var last=null;
  for(var i=0;i<lines.length;i++){
    var line=lines[i].trim();
    if(!line)continue;
    var m=line.match(/^(.+?)[:：]\s*(.*)$/);
    var name=m?m[1].trim():'';
    var content=m?m[2].trim():line;
    if(name){ var nc=hpCleanName(name); if(nc && members.indexOf(nc)>=0) name=nc; }   // 「小滴（林雨涵）」这种带真名的也认
    if(name&&members.indexOf(name)>=0){
      var p=splitThought(content);
      last={name:name,text:p.text,thoughts:p.thoughts};
      replies.push(last);
    }else if(last&&content){
      var p2=splitThought(content);
      last.text=(last.text?last.text+'\n':'')+p2.text;
      for(var k=0;k<p2.thoughts.length;k++)last.thoughts.push(p2.thoughts[k]);
    }else if(!last&&content){
      var p3=splitThought(content);
      if(p3.text)replies.push({name:'',text:p3.text,thoughts:p3.thoughts});
    }
  }
  return replies;
}
