function renderAnchorText(text){
  var esc=String(text||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
  var bar=document.getElementById('liveSongBar');
  if(!bar){
    // 兜底：历史直播消息 / AI 漏生成 liveSongBar 时，动态创建进画面区（不依赖 FORMAT 是否含该 div）
    var va=document.querySelector('.videoArea');
    if(va){
      bar=document.createElement('div');
      bar.id='liveSongBar';
      bar.style.cssText='position:absolute;left:12px;right:12px;top:30px;z-index:4;background:rgba(18,20,26,.88);border:1px solid #333844;border-radius:8px;padding:4px 8px;display:none;';
      va.appendChild(bar);
    }
  }
  return esc.replace(/【歌曲：\s*([^】]+?)\s*】|【演奏：\s*([^】]+?)\s*】|【演出：\s*([^】]+?)\s*】/g,function(full,songN,soloN,stageN){
    var name=(songN||soloN||stageN||'').trim().replace(/^《+|》+$/g,'').trim();
    var v=LIVE_SONGS[name];
    var url=Array.isArray(v)?v[Math.floor(Math.random()*v.length)]:v;
    if(url){
      var icon=stageN?'🎭':(soloN?'🎼':'🎵');
      if(bar){ bar.innerHTML=liveSongHtml(url,name,icon); bar.style.display='block'; }
      return icon+'《'+name+'》';
    }
    return full;
  });
}
