  liveLoading=true;
  document.getElementById('livePageInfo').textContent='加载第 '+page+' 页…';
  createChatMessages([{role:'user',message:'翻看X站直播首页第 '+page+' 页',content:'翻看X站直播首页第 '+page+' 页'}],{refresh:'none'})
    .then(function(){ return generateRaw(livePrompt(page)); })
    .then(function(reply){
      liveLoading=false;
      if(reply&&typeof reply==='object'&&reply.content)reply=reply.content;
