    var cards=tmp.querySelectorAll('.card');
    for(var i=0;i<cards.length;i++){ out.push(cards[i].textContent.replace(/\s+/g,' ').trim()); }
  }
  return out.join('\n')||'（当前无直播推荐）';
}
