function uniqueDanmu(cat,scene,host){
  var t=contextDanmu(cat,scene,host),c=0;
  while(RECENT_DM.indexOf(t)>=0&&c<5){ t=contextDanmu(cat,scene,host); c++; }
  RECENT_DM.push(t);
