function autoTick(){
  if(!AUTO_ON)return;
  var room=document.getElementById('room');
  var liveTab=document.getElementById('liveTab');
  var inRoom=!!(room && room.style.display==='block' && liveTab && liveTab.style.display!=='none');
  if(inRoom&&!KEEP_TYPING){
    var typeEl=document.getElementById('roomType');
    var cat=typeEl?typeEl.textContent.trim():'';
    var sceneEl=document.getElementById('roomScene');
    var scene=sceneEl?sceneEl.textContent.trim():'';
    var hostEl=document.getElementById('roomHost');
    var host=hostEl?hostEl.textContent.trim():'';
    var heat=parseHeat();
    var n=1;
    if(heat>=100000)n=Math.random()<.6?3:2;
    else if(heat>=30000)n=Math.random()<.7?2:1;
    else if(heat>=10000&&Math.random()<.4)n=2;
    for(var i=0;i<n;i++)addFlyDanmu(uniqueDanmu(cat,scene,host),'normal');
    var g=0;
    if(heat>=100000)g=Math.random()<.5?1:0;
    else if(heat>=30000)g=Math.random()<.12?1:0;
    else if(heat>=10000)g=Math.random()<.07?1:0;
    else g=Math.random()<.03?1:0;
    for(var j=0;j<g;j++)autoGiftDanmu(cat,scene,host);
    setTimeout(autoTick,pickInterval(heat));
  }else{
    AUTO_ON=false;   // 离开直播间即停表，下次进房由 startAutoDanmu 重启，避免后台空转
  }
}
function parseHeat(){
  var el=document.getElementById('heat');
  var t=el?el.textContent.trim():'';
  var m=t.match(/([\d.]+)(万|w|k)?/i);
  if(!m)return 20000;
  var v=parseFloat(m[1]);
  if(/万|w/i.test(m[2]||''))v*=10000;
  else if(/k/i.test(m[2]||''))v*=1000;
  return v||1;
}
function pickInterval(heat){
  if(heat>=100000)return 500+Math.random()*500;
  if(heat>=30000) return 700+Math.random()*600;
  if(heat>=10000) return 1100+Math.random()*700;
  if(heat>=5000)  return 1800+Math.random()*1200;
  return 2600+Math.random()*1800;
}
