function addFlyDanmu(text,cls,color){
  var track=document.getElementById('danmuTrack');
  if(!track)return;
  var d=document.createElement('div');
  d.className='flyDanmu'+(cls==='mine'?' mine':(cls==='gift'?' gift':' normal'));
  if(color)d.style.color=color;
  d.textContent=text;
  var row=pickRow(d);
  d.style.top=(3+row*22)+'px';
  track.appendChild(d);
  flyEl(d);
  while(track.children.length>40){ track.removeChild(track.firstChild); }
}
function flyEl(d){
  var track=document.getElementById('danmuTrack');
  var trackW=track?track.offsetWidth:600;
  var dur=(trackW+d.offsetWidth)/DANMU_SPEED;
  d.setAttribute('data-dur',String(Math.round(dur)));
  d.setAttribute('data-start',String(Date.now()));
  d.animate(
    [{transform:'translateX('+trackW+'px)'},{transform:'translateX(-100%)'}],
    {duration:dur,easing:'linear',fill:'both'}
  );
}
function pickRow(d){
  var w=d.offsetWidth||40;
  var rows=[],empty=[],i,info;
  for(i=0;i<FLY_ROWS;i++){
    info=youngestInRow(i);
    if(!info){ empty.push(i); }
    else if((info.elapsed/1000)*DANMU_SPEED>=w+40){ rows.push(i); }
  }
  if(empty.length)return empty[Math.floor(Math.random()*empty.length)];
  if(rows.length)return rows[Math.floor(Math.random()*rows.length)];
  return Math.floor(Math.random()*FLY_ROWS);
}
// 用时间戳算进度，避免对每条弹幕调 getAnimations()（原先每加一条弹幕就 O(n) 次重调用，弹幕多时严重卡顿）
function youngestInRow(row){
  var track=document.getElementById('danmuTrack');
  if(!track)return null;
  var top=3+row*22;
  var now=Date.now();
  var best=null,bestEl=0,all=track.querySelectorAll('.flyDanmu'),i,elm,dur,st,el;
  for(i=0;i<all.length;i++){
    elm=all[i];
    if(Math.round(parseFloat(elm.style.top)||0)!==top)continue;
    dur=parseFloat(elm.getAttribute('data-dur'))||0;
    st=parseFloat(elm.getAttribute('data-start'))||0;
    if(!dur||!st)continue;
    el=now-st;
    if(el<0||el>dur)continue;
    if(!best||el<bestEl){ best=elm; bestEl=el; }
  }
  return best?{el:best,elapsed:bestEl}:null;
}
function flyExisting(){
