  for(var i=list.length-1;i>=0 && out.length<(n||2);i--){
    var m=list[i]; if(!m||typeof m!=='object') continue;
    if(m.is_user===true && typeof m.mes==='string' && m.mes.trim()) out.push(m.mes);
  }
  return out.reverse();
}
// 从已激活世界书里汇总候选角色名（角色条目「名字（班级）」+ 学生人员表）
function hpActorNamesFromEntries(entries){
  var out=[], seen={};
  function add(n){
    n=String(n||'').trim();
    if(n.length<2 || n.length>12) return;
    if(seen[n]) return;
    seen[n]=1; out.push(n);
  }
  for(var i=0;i<entries.length;i++){
    var nm=String(entries[i].name||'');
    var m=nm.match(/^(.{2,12}?)\s*[（(](.{1,24})[）)]$/);
    if(m && /学生|老师|教师|校长|部员|社员|从者|主任|会长/.test(m[2])){ add(m[1]); continue; }
    var c=String(entries[i].content||'');
    var h=c.match(/【([^（(\n]{2,12})[（(]/);
    if(h) add(h[1]);
  }
  // 学生人员表里的全部姓名
  for(var j=0;j<entries.length;j++){
    if(String(entries[j].name||'').indexOf('学生人员表')<0) continue;
    var lines=String(entries[j].content||'').split(/\r?\n/);
    for(var k=0;k<lines.length;k++){
      var mm=lines[k].match(/^\s*[^\n:：]*学生\s*[:：]\s*([^\n]+)$/);
      if(!mm) continue;
      var arr=hpSplitNames(mm[1]);
      for(var q=0;q<arr.length;q++) add(arr[q]);
    }
  }
  out.sort(function(a,b){ return b.length-a.length; });
  return out;
}
// 文本里最早出现、且名字最长的候选角色
function hpNameInText(text, names){
  var s=String(text||''), best='', bestAt=-1;
  for(var i=0;i<names.length;i++){
    var at=s.indexOf(names[i]);
    if(at<0) continue;
    if(bestAt<0 || at<bestAt || (at===bestAt && names[i].length>best.length)){ bestAt=at; best=names[i]; }
  }
  return best;
}
