function hpParseActorName(reply){
  var s=hpCleanText(reply);
  if(!s) return '';
  var name='';
  try{ var o=JSON.parse(s); if(o&&o.name) name=String(o.name).trim(); }
  catch(e){ name=''; }
  if(!name){ var m=s.match(/"name"\s*[:：]\s*"([^"]*)"/); if(m) name=m[1].trim(); }
  if(!name){
    name=s.replace(/[{}"']/g,'').trim();
    name=name.replace(/^.*?(?:当前|现在|目前|玩家|角色|主角|人物|是|为|：|:)+/,'');
    name=name.replace(/[，。！？、,\.!?\s]+/g,'').trim();
    if(name.length>12 || /[a-z]{3,}/i.test(name)) name='';
  }
  return name;
}
// 读取所有「已启用」世界书（角色卡绑定 + 全局）并合并条目
function hpLoadWorldbooks(TH){
  if(!TH || !TH.getWorldbook) return Promise.resolve([]);
  if(HP_WB_CACHE && (new Date().getTime()-HP_WB_CACHE_T)<4000) return Promise.resolve(HP_WB_CACHE);
  var names=[];
  function add(n){ if(!n)return; if(names.indexOf(n)<0) names.push(n); }
  try{
    if(TH.getCharWorldbookNames){ var cw=TH.getCharWorldbookNames('current')||{}; if(cw.primary) add(cw.primary); var a=cw.additional||[]; for(var i=0;i<a.length;i++) add(a[i]); }
  }catch(e){}
  try{
    if(TH.getGlobalWorldbookNames){ var g=TH.getGlobalWorldbookNames()||[]; for(var j=0;j<g.length;j++) add(g[j]); }
  }catch(e){}
  try{
    // 聊天绑定的世界书也要读，否则「只绑到聊天」时脚本自己取不到刚上传的数据
    if(TH.getChatWorldbookName) add(TH.getChatWorldbookName('current'));
  }catch(e){}
  var out=[];
  var chain=Promise.resolve();
  for(var k=0;k<names.length;k++){
    (function(nm){
      chain=chain.then(function(){
        return TH.getWorldbook(nm).then(function(eb){
          // key 也带上：领域条目注入时要用触发词判断「酒馆是不是已经注入过」
          for(var x=0;x<eb.length;x++){ var en=eb[x]; if(en && en.enabled && en.content){ out.push({name:en.name, content:en.content, key:(en.key||en.keys||'')}); } }
          return null;
        }).catch(function(){ return null; });
      });
    })(names[k]);
  }
  return chain.then(function(){
    HP_WB_CACHE=out; HP_WB_CACHE_T=new Date().getTime();
    return out;
  });
}
