function hpFindEntry(entries, name){
  var i, best=null;
  for(i=0;i<entries.length;i++){ if(entries[i].name===name) return entries[i]; }        // 精确优先
  for(i=0;i<entries.length;i++){                                                       // 只认「条目名比查询长」＝带后缀（如 （高一C））
    var nm=entries[i].name||'';
    if(nm.indexOf(name)>=0 && nm.length-name.length<=8){ if(!best || nm.length<best.name.length) best=entries[i]; }
  }
