// 在人员表里反查角色所属年级/班级，并返回该班全体名单
function hpFindClass(content, actor){
  if(!content || !actor) return null;
  var target=hpCleanName(actor);
  var lines=String(content).split(/\r?\n/);
  for(var i=0;i<lines.length;i++){
    var m=lines[i].match(/^\s*([^\n:：]+?)\s*[:：]\s*([^\n]+)\s*$/);
    if(!m) continue;
    var head=m[1].trim();
    if(!/学生$/.test(head)) continue;
    var names=hpSplitNames(m[2]);
    for(var j=0;j<names.length;j++){
      var nn=names[j];
      if(nn===target || nn.indexOf(target)>=0 || target.indexOf(nn)>=0){
        return { grade:hpGradeOfHead(head), cls:hpClassOfHead(head), names:names };
      }
    }
  }
  return null;
}
