function hpRaceWordZh(w){
  var t=String(w||'').trim();
  if(!t) return '';
  var hasZh=/[\u4e00-\u9fff]/.test(t);
  if(!hasZh){
    var k=t.toLowerCase().replace(/\s+/g,' ');
    if(STU_RACE_EN[k]) return STU_RACE_EN[k];
  }
  var out=t;
  var keys=Object.keys(STU_RACE_EN).sort(function(a,b){ return b.length-a.length; });
  for(var i=0;i<keys.length;i++){
    if(hasZh && keys[i].length<3) continue;
    var re=new RegExp('\\b'+keys[i].replace(/[.*+?^$\{\}()|[\]\\]/g,'\\$&')+'\\b','gi');
    out=out.replace(re, STU_RACE_EN[keys[i]]);
  }
  out=out.replace(/\bAI\b/g,'人工智能');
  return out;
}
function hpRaceZh(raw){
  var s=String(raw||'').trim();
  if(!s) return '';
  if(/^gender\s*[:：]/i.test(s)) return '';
  s=s.replace(/\(/g,'（').replace(/\)/g,'）').replace(/\s*\/\s*/g,'/').trim();
  var m=s.match(/^([^（]+)(（.*）)?$/);
  var main=m?m[1].trim():s;
  var tail=(m&&m[2])?m[2]:'';
  main=hpRaceWordZh(main);
  if(tail){
    var inner=hpRaceWordZh(tail.replace(/^（/,'').replace(/）$/,'').trim());
    if(!inner || inner===main) tail='';
    else if(inner.indexOf(main)>=0 && main.length>=2){ main=inner; tail=''; }
    else if(main.indexOf(inner)>=0 && inner.length>=2){ tail=''; }
    else tail='（'+inner+'）';
  }
  return main+tail;
}
// 从自由文本里认年级班级（如「高一c班」「高二A班」「小学B班」）
function hpGradeClassFromText(text){
  var s=String(text||'');
  var m=s.match(/(高[一二三]|初[一二三])\s*([A-Za-z])?\s*班/);
  if(m) return {grade:m[1], cls:(m[2]?m[2].toUpperCase():'')+'班'};
  m=s.match(/(大[一二三四五六])\s*班/);
  if(m) return {grade:m[1], cls:''};
  m=s.match(/小学\s*([A-Za-z])?\s*班/);
  if(m) return {grade:'小学', cls:(m[2]?m[2].toUpperCase():'')+'班'};
  m=s.match(/幼儿园\s*([^\s，,。；;]{1,6}?)\s*班/);
  if(m) return {grade:'幼儿园', cls:m[1]+'班'};
  return null;
}
function hpParseRole(content){
  var r={gender:'', age:'', occupation:'', major:'', race:'', grade:'', cls:'', club:''};
  if(!content) return r;
  var gm=content.match(/(?:gender|性别)\s*[:：]\s*([^\n\r,，]+)/i); if(gm) r.gender=gm[1].trim();
  var am=content.match(/(?:age|年龄)\s*[:：]\s*(\d+)/i); if(am) r.age=am[1];
  var rm=content.match(/(?:race|种族)\s*[:：]\s*([^\n\r,，]+)/i); if(rm) r.race=hpRaceZh(rm[1]);
  var om=content.match(/(?:Occupation|职业|身份)\s*[:：]\s*([^\n\r]+)/i); if(om){ r.occupation=om[1].trim(); r.major=om[1].trim(); }
  var grm=content.match(/(?:年级)\s*[:：]\s*([^\n\r,，]+)/); if(grm) r.grade=grm[1].trim();
  var clm=content.match(/(?:班级)\s*[:：]\s*([^\n\r,，]+)/); if(clm) r.cls=clm[1].trim();
  var clm2=content.match(/(?:社团|参加社团)\s*[:：]\s*([^\n\r,，]+)/); if(clm2) r.club=clm2[1].trim();
  if(r.cls && !/班$/.test(r.cls)) r.cls=r.cls+'班';
  return r;
}
