// 职业短名（身份卡「职业」栏用）；支持「学生、作家」这类多重身份
function hpJobShort(p){
  p=String(p||'').trim();
  if(!p) return '';
  if(/学生/.test(p)) return '学生';
  if(/副校长/.test(p)) return '副校长';
  if(/校长/.test(p)) return '校长';
  if(/理事长/.test(p)) return '理事长';
  if(/副局长/.test(p)) return '副局长';
  if(/局长/.test(p)) return '局长';
  if(/老师|教师|教授/.test(p)) return '教师';
  if(/主任|总管/.test(p)) return '主任';
  if(/职员|行政/.test(p)) return '行政职员';
  if(/研究员|博士/.test(p)) return '研究员';
  var m=p.match(/^(.+?)(?:的)?(?:部长|副部长|社长|副社长|会长|副会长|团长|组长|成员|部员|社员|顾问|经理)$/);
  if(m && m[1]){
    var r=m[1].replace(/[、\s]+$/,'');
    if(hpLooksLikeJob(r)) return r.length>12?r.slice(0,12):r;
  }
  // 兜底：只有像「职务」的文本才当职业显示（「雪之下家族长女」这类身份/社团描述丢弃）
  return hpLooksLikeJob(p) ? (p.length>12?p.slice(0,12):p) : '';
}
// 判断文本是否像「职业/职务」——职业栏兜底用，避免把家族称谓、社团名当职业
var HP_JOB_TAIL=/(长|员|师|工|手|监|管|理|席|厨|医|警|官|商|主|兵|役|者|士|徒|匠|生|人|导|演|播|唱|舞|侍|从|业)$/;
var HP_JOB_WORD=/兼职|打工|实习|就职|在职|职位|职业|工作|店员|店长|老板|服务生|学生|老师|主任|总管|负责人|代表|顾问|经理|作家|画家|演员|偶像|主播|歌手|司机|厨师|医生|护士|警察|教师|研究员|博士|理事长|校长|局长/;
function hpLooksLikeJob(s){
  s=String(s||'').trim();
  if(s.length<2) return false;
  if(HP_JOB_WORD.test(s)) return true;
  return HP_JOB_TAIL.test(s);
}
function hpJobOf(occ, grade){
  var s=String(occ||'').trim();
  if(!s) return grade?('学生'):'';
  var parts=s.split(/[、，,；;\/|]/);
  var out=[];
  for(var i=0;i<parts.length;i++){
    var k=hpJobShort(parts[i]);
    if(k && out.indexOf(k)<0) out.push(k);
  }
  // 超长时整项丢弃，避免把最后一项切成半截（如「雪之下家族长女」→「雪之」）
  while(out.length>1 && out.join('·').length>14) out.pop();
  var r=out.join('·')||hpJobShort(s);
  return r.length>14?r.slice(0,14):r;
}
// 按「年级+班级」从学生人员表取整班名单（用于玩家新建、不在名单里的角色）
