// 布告板的成绩公示按年级出榜 —— 初中部和高中部不会同场考试，混在一起是错的。
function hpRosterNamesOfGrade(content, grade){
  var out=[];
  if(!content || !grade) return out;
  var g=String(grade).replace(/班$/,'');
  var lines=String(content).split(/\r?\n/);
  for(var i=0;i<lines.length;i++){
    var m=lines[i].match(/^\s*([^\n:：]+?)\s*[:：]\s*([^\n]+)\s*$/);
    if(!m) continue;
    var head=m[1].trim();
    if(!/学生$/.test(head)) continue;
    if(head.indexOf(g)!==0) continue;          // 「初三A班学生」「大一学生」都以年级名开头
    var arr=hpSplitNames(m[2]);
