  }
  return out;
}
function hpRosterNamesOfClass(content, grade, cls){
  if(!content || !grade || !cls) return [];
  var key=grade+String(cls).replace(/班$/,'');
  var lines=String(content).split(/\r?\n/);
  for(var i=0;i<lines.length;i++){
    var m=lines[i].match(/^\s*([^\n:：]+?)\s*[:：]\s*([^\n]+)\s*$/);
    if(!m) continue;
    var head=m[1].trim();
    if(!/学生$/.test(head)) continue;
    if(head.indexOf(key)<0) continue;
    return hpSplitNames(m[2]);
  }
  return [];
}
