// 现在落在课表的哪一节（供「今日」条目写进上下文用）。
// 与 hpScheduleNowIdx 的区别：它只回一个下标，这里回一句能直接读的话（含课间/午休/放学后）。
function hpPeriodDesc(){
  var t=hpCalToday(); if(!t || !t.time) return '';
  var sch=studentCache && studentCache.schedule;
  if(!sch || !sch.times || !sch.times.length) return '';     // 没有课表就不硬套节次
  var m=String(t.time).match(/^(\d{1,2}):(\d{2})$/); if(!m) return '';
  var cur=parseInt(m[1],10)*60+parseInt(m[2],10), prevEnd=null;
  for(var i=0;i<sch.times.length;i++){
    var r=String(sch.times[i]).match(/(\d{1,2}):(\d{2})\s*[-~－—]\s*(\d{1,2}):(\d{2})/);
    if(!r) continue;
    // ⚠ 必须用 labels 而不是下标 +1：课表里「午休」是插在第三、四节之间的独立一行，
    //   用下标当节次会从午休之后整体多说一节（2026-09-17 实测：12:45 被说成"第5节课"）。
    var lab=(sch.labels && sch.labels[i]) ? String(sch.labels[i]) : ('第'+(i+1)+'节');
    var a=parseInt(r[1],10)*60+parseInt(r[2],10), b=parseInt(r[3],10)*60+parseInt(r[4],10);
    if(cur>=a && cur<b){
      if(lab==='大课间') return '大课间（'+sch.times[i]+'，30 分钟）—— 一天里最长的一个课间：'
        +'课间操、小卖部、操场、串班、掏手机看消息。'
        +'**这段时间不要一句话带过**，至少让一件具体的事发生在主角身边'
        +'（有人来找他/她／手机震了一下／有人在背后议论／有人塞东西过来）。';
      return lab+'（'+sch.times[i]+'）';
    }
    if(cur<b){
      if(lab==='午休') return '午休（'+sch.times[i]+'）';
      if(prevEnd===null) return '上课前，接下来是'+lab+'（'+sch.times[i]+'）';
      // 课间改成「场景态」：不写「接下来是第X节」（那等于催 AI 跳到下一节），
      // 而是把它当成一个可写、要写的时段，并点明这段时间学生都在干什么（2026-09-21 用户反馈：
      // 剧情全挤在上课，课间被一笔带过；而学生在校的主要活动时间恰恰是课间）
      var _f=function(x){ return ('0'+Math.floor(x/60)).slice(-2)+':'+('0'+(x%60)).slice(-2); };
      var _gap=a-prevEnd;
      return (_gap>=40?'大休息':'课间')+'（'+_f(prevEnd)+'-'+_f(a)+'，'+_gap+' 分钟）'
        +' —— 这是学生在校期间互动最密集的时段：串班、去小卖部、楼道里传话、递东西、掏手机看消息。'
        +'**这段时间不要一句话带过**，至少让一件具体的事发生在主角身边'
        +'（有人来找他/她／手机震了一下／有人在背后议论／有人塞东西过来）。'
        +'下一节是'+lab+'（'+sch.times[i]+'）。';
    }
    prevEnd=b;
  }
  return '放学后（社团／自由活动时间 15:20-17:00）';
}
