    h+='<div class="schedTime'+(p===nowP?' now':'')+'">'+(lb?'<b>'+hpEsc(lb)+'</b>':'')+(tl?'<span>'+hpEsc(tl)+'</span>':'')+'</div>';
    for(var d2=0;d2<7;d2++){
      var txt=(s.days[d2] && s.days[d2][p])?s.days[d2][p]:'';
      var cls='', attrs='';
      if(txt==='午休'){ cls=' lunch'; }
      else {
        if(!s.college && p===maxP-1 && txt) cls+=' club';
        if(txt) cls+=' has';
        attrs=' data-d="'+d2+'" data-p="'+p+'"';
        if(txt) attrs+=' onpointerdown="hpSchedDown(event)" onpointermove="hpSchedMove(event)" onpointerup="hpSchedUp(event)" onpointercancel="hpSchedCancel(event)"';
      }
      if(d2===todayC) cls+=' todayCol';
      if(d2===todayC && p===nowP && txt) cls+=' now';
      h+='<div class="schedCell'+(txt?'':' empty')+cls+'"'+attrs+'>'+hpEsc(txt)+'</div>';
    }
  }
  h+='</div>';
  var tip='';
  if(nowP>=0) tip='⏰ 当前节次：'+((s.labels&&s.labels[nowP])||('第'+(nowP+1)+'节'))+(todayC>=0?(' · '+STU_DAYS[todayC]):'');
  h+='<div class="schedExtra">🖐 拖动课程到另一格互换 · 也可点两格依次交换<br>午休与节次不可拖动 · 调整后自动同步进世界书'+(tip?('<br>'+tip):'')+'</div>';
  h+=hpTeacherHtml(studentCache.card?studentCache.card.grade:'');
  body.innerHTML=h;
  if(schedPick) hpMarkPick();
}
function renderSeats(){
  var body=document.getElementById('seatBody'); if(!body) return;
  if(!studentCache || !studentCache.seats || !studentCache.seats.desks || studentCache.seats.names===0){
    body.innerHTML='<div class="feedback">暂无班级成员数据，请点「🔄 更新」</div>';
