      var desk=seats.desks[r][c];
      h+='<div class="seatDesk"><span class="seatSide">'+hpSeatName(desk.left,r,c,'left')+'</span><span class="seatDivider"></span><span class="seatSide">'+hpSeatName(desk.right,r,c,'right')+'</span></div>';
      if(c<seats.cols-1 && ((seats.leftCols>0 && c===seats.leftCols-1) || (seats.midCols>0 && c===seats.leftCols+seats.midCols-1))){
        h+='<div class="seatAisle"></div>';
