// ═══ 催眠规则持久化：写进同步世界书「新中市·催眠规则」（常驻条目）═══
// 以前规则只活在聊天里 → AI 会漂、玩家也看不到有哪些生效；现在落条目 + 可逐条解除。
var HP_RULE_ENTRY='新中市·催眠规则';
var hpRuleData=null;      // [{tag,target,rule,at}]
var hpRulePending=null;   // 并发调用共用同一次读取，避免「后到的读取把刚追加的规则覆盖掉」
function hpRuleParse(text){
  var out=[], lines=String(text||'').split(/\r?\n/), i;
  for(i=0;i<lines.length;i++){
    var m=lines[i].match(/^\s*[-•·]\s*\[([^\]]+)\]\s*目标[:：]\s*([^｜|\n]*?)\s*[｜|]\s*规则[:：]\s*([\s\S]*?)(?:\s*[｜|]\s*写入[:：]\s*([^\n]*))?\s*$/);
    if(!m) continue;
    out.push({tag:m[1].trim()||'规则', target:String(m[2]||'').trim()||'—', rule:String(m[3]||'').trim()||'—', at:String(m[4]||'').trim()||'—'});
  }
  return out;
}
function hpRuleText(list){
  var lines=['【新中市 · 催眠规则（当前生效）】'];
  lines.push('说明：以下规则由手机催眠 App 写下，剧情中相关角色默认照此行事，直到被解除。');
  if(!list.length) lines.push('（当前没有生效中的规则）');
  for(var i=0;i<list.length;i++){
    var r=list[i];
    lines.push('- ['+r.tag+'] 目标：'+r.target+'｜规则：'+r.rule+'｜写入：'+r.at);
  }
  return lines.join('\n');
}
function hpRuleAt(){
  var t=hpCalToday();
  if(!t) return '未知日期';
  return t.m+'月'+t.d+'日'+(t.time?(' '+t.time):'');
}
function hpRuleLoad(force){
  if(hpRuleData && !force) return Promise.resolve(hpRuleData);
  if(hpRulePending) return hpRulePending;
  var TH=window.parent.TavernHelper;
  hpRulePending = hpWbRead(TH, HP_SYNC_WB).then(function(eb){
    var txt='';
    for(var i=0;i<eb.length;i++){ if(hpWbEntryName(eb[i])===HP_TODAY_ENTRY) txt=String(eb[i].content||''); }
    hpRuleData=hpRuleParse(hpEntrySection(txt,'【生效中的催眠规则】'));   // 规则就存在「今日」条目里
    hpRulePending=null;
    return hpRuleData;
  }).catch(function(e){ hpRuleData=[]; hpRulePending=null; hpWarn('催眠规则读取失败：'+((e&&e.message)||e)); return hpRuleData; });
  return hpRulePending;
}
function hpRuleSave(){
  if(!hpRuleData) return Promise.resolve(false);
  if(!hpIsTavern()) return Promise.resolve(false);
  hpSyncTodayEntry(true);          // 规则并入「新中市·今日」，不再单独建条目
  hpTodaySig=''; hpRenderToday();
  return Promise.resolve(true);
}
function hpRuleRecord(tag, target, rule){
  if(!String(rule||'').trim()) return;
  hpRuleLoad().then(function(list){                     // 先读再追加，避免把已有规则覆盖掉
    list.push({tag:tag||'规则', target:target||'在场所有人', rule:String(rule).slice(0,200), at:hpRuleAt()});
    hpRuleData=list;
    return hpRuleSave();
  }).catch(function(e){ hpWarn('规则记录失败：'+((e&&e.message)||e)); });
}
function hpRuleRender(){
  var box=document.getElementById('ruleList'); if(!box) return;
  if(!hpRuleData){ box.innerHTML='<div class="ruleFormTit">正在读取…</div>'; return; }
  var h='', i;
  h+='<div class="ruleFormTit">共 <b>'+hpRuleData.length+'</b> 条生效中（作为常驻条目注入，AI 每轮都看得到）</div>';
  if(!hpRuleData.length) h+='<div class="ruleFormTit" style="font-weight:normal">当前没有生效中的规则。</div>';
  for(i=0;i<hpRuleData.length;i++){
    var r=hpRuleData[i];
    h+='<div class="ruleRow">'
      +'<span class="ruleTag">'+hpEsc(r.tag)+'</span>'
      +'<span class="ruleTgt">'+hpEsc(r.target)+'</span>'
      +'<span class="ruleAt">'+hpEsc(r.at)+'</span>'
      +'<span class="ruleTxt">'+hpEsc(r.rule)+'</span>'
      +'<span class="ruleOps"><button onclick="hpRuleDel('+i+')">解除</button></span>'
      +'</div>';
  }
  box.innerHTML=h;
