// ═══ 电量：屏幕亮着就掉电（1% / 30 秒），在「网络修复」里充电；0% 整机黑屏 ═══
// 存进同步世界书「新中市·小手机状态」——AI 也能据此在剧情里写「手机快没电了」。
var HP_BAT_ENTRY='新中市·小手机状态';
var hpBatPct=100, hpBatLoaded=false, hpBatLastSaved=100;
function hpBatClamp(v){ return Math.max(0, Math.min(100, v)); }
function hpBatPanelOpen(){
  try{ var fe=window.frameElement; if(fe && getComputedStyle(fe).display==='none') return false; }catch(e){}   // 面板关着 = 锁屏放着，不耗电
  try{ if(document.hidden) return false; }catch(e){}
  return true;
}
function hpBatText(){
  if(!hpBatLoaded) return '新中市网络 📶 🔋 --';
  return '新中市网络 📶 '+(hpBatPct>20?'🔋':'🪫')+' '+Math.round(hpBatPct)+'%';
