function hpBatMarkSpans(){                       // 给每个页面的状态栏插/标记电量位，不用改 15 处 HTML
  var bars=document.querySelectorAll('.pStatus');
  for(var i=0;i<bars.length;i++){
    var kids=bars[i].children, sp=null, j;
    for(j=0;j<kids.length;j++){ if(String(kids[j].textContent||'').indexOf('🔋')>=0){ sp=kids[j]; break; } }
    if(!sp){ sp=document.createElement('span'); bars[i].insertBefore(sp, bars[i].lastElementChild); }
    sp.classList.add('pBat');
  }
