function hpBatRender(){
  var spans=document.querySelectorAll('.pBat'), t=hpBatText(), i;
  for(i=0;i<spans.length;i++){
    spans[i].textContent=t;
    spans[i].className='pBat'+(hpBatPct<=0?' dead':(hpBatPct<=20?' low':''));
  }
  var off=document.getElementById('phoneOff');
  if(off){ if(hpBatPct<=0) off.classList.add('on'); else off.classList.remove('on'); }
  var d=document.getElementById('batDesc');
  if(d) d.textContent=hpBatLoaded?('当前电量 '+Math.round(hpBatPct)+'%（手机开着约每 30 秒掉 1%，没电就整机黑屏）'):'电量读取中…';
}
function hpBatSave(){
  if(!hpIsTavern() || !hpBatLoaded) return;
  hpWbSetEntry(HP_BAT_ENTRY, '【新中市 · 小手机状态】\n电量：'+Math.round(hpBatPct)+'%\n说明：电量低于 20% 时剧情里可体现「手机快没电了」；为 0 时手机暂时关机，需要充电。')
    .catch(function(e){ hpWarn('电量写入失败：'+((e&&e.message)||e)); });
}
function hpBatLoad(){
  var TH=window.parent.TavernHelper;
  return hpWbRead(TH, HP_SYNC_WB).then(function(eb){
    var txt='';
    for(var i=0;i<eb.length;i++){ if(hpWbEntryName(eb[i])===HP_BAT_ENTRY) txt=String(eb[i].content||''); }
    var m=txt.match(/电量\s*[:：]\s*(\d{1,3})/);
    hpBatPct=m?hpBatClamp(parseInt(m[1],10)):100;
    hpBatLoaded=true; hpBatLastSaved=Math.round(hpBatPct);
    hpBatRender();
  }).catch(function(e){ hpBatLoaded=true; hpBatRender(); hpWarn('电量读取失败：'+((e&&e.message)||e)); });
}
function hpBatCharge(){
  hpBatPct=100; hpBatLoaded=true; hpBatLastSaved=100;
  hpBatRender(); hpBatSave();
  var off=document.getElementById('phoneOff'); if(off) off.classList.remove('on');
  hpFeedback('🔌 已充满电','repairStatus');
}
function hpBatTick(){
  if(!hpBatLoaded || hpBatPct<=0) return;
  if(!hpBatPanelOpen()) return;                 // 面板关着不耗电（锁屏放着）
  hpBatPct=hpBatClamp(hpBatPct-1);
  hpBatRender();
  if(Math.abs(Math.round(hpBatPct)-hpBatLastSaved)>=5){ hpBatSave(); hpBatLastSaved=Math.round(hpBatPct); }
}
function hpBatInit(){
  hpBatMarkSpans();
  hpBatRender();
  hpBatLoad();
  setInterval(hpBatTick, 30000);
}
// 中性提示（通知到达之类，不用告警的红色样式）
function hpToast(msg){
  try{ console.log('[小手机] '+msg); }catch(e){}
  if(!hpIsTavern()) return;
  try{
    if(!hpWarnBox || !hpWarnBox.parentNode){
      hpWarnBox=document.createElement('div');
      hpWarnBox.id='hpWarnBox';
      hpWarnBox.style.cssText='position:fixed;left:50%;bottom:14px;transform:translateX(-50%);z-index:2147483000;display:flex;flex-direction:column;gap:6px;align-items:center;pointer-events:none;max-width:92%;';
      document.body.appendChild(hpWarnBox);
    }
    var d=document.createElement('div');
    d.className='feedback';
