// ═══ 主页「今天」卡：剧情日期 + 今日课表 + 同桌 + 今日活动（全部来自已有真源，不新增数据）═══
// 现在几点落在哪节课（时间区间如 '8:30-9:10'）
function hpPeriodHas(range, nowStr){
  var m=String(range||'').match(/^\s*(\d{1,2}):(\d{2})\s*[-~–—]\s*(\d{1,2}):(\d{2})/);
  var t=String(nowStr||'').match(/^\s*(\d{1,2}):(\d{2})/);
  if(!m || !t) return false;
  var a=(+m[1])*60+(+m[2]), b=(+m[3])*60+(+m[4]), c=(+t[1])*60+(+t[2]);
  return c>=a && c<b;
}
// 今天落在哪些活动里（校历 + 节日），校历首日不加「进行中」
function hpTodayEvents(t){
  var out=[], later=[], seen={}, i;
  function push(n){ n=String(n||'').trim(); if(!n || seen[n]) return; seen[n]=1; out.push(n); }
  for(i=0;i<CAL_SCHOOL.length;i++){
    var e=CAL_SCHOOL[i];
    if(!hpCalInRange(t.y,t.m,t.d,e)) continue;
    if(t.m===e.m1 && t.d===e.d1) push(e.n);                 // 今天开始的活动排前面
    else later.push(e.n+'（进行中）');
  }
  out=out.concat(later);
  var lu=CAL_LUNAR[t.y];
  if(lu){ for(i=0;i<lu.length;i++){ if(lu[i][0]===t.m && lu[i][1]===t.d) push(lu[i][2]); } }
  for(i=0;i<CAL_FIXED.length;i++){ if(CAL_FIXED[i][0]===t.m && CAL_FIXED[i][1]===t.d) push(CAL_FIXED[i][2]); }
  return out;
}
