  var secs=hpSchoolSections(CAL_SCHOOL_TEXT), want={}, i, k;
  for(i=0;t && i<CAL_SCHOOL.length;i++){
    var e=CAL_SCHOOL[i];
    if(!hpCalInRange(t.y,t.m,t.d,e)) continue;
