    return hpSyncMarkCheck().then(function(cleared){       // 上一场聊天的数据 → 清掉再看
      if(cleared){ hpRuleData=null; hpNotifData=[]; hpRelData=null; galleryPhotos=[]; studentCache=null; hpNotifBadge(); hpShadeRender(); }
    });
  }).then(function(){
    hpTodayAuxReady=true;
    hpSyncTodayEntry(true);
    hpWbSetEntry('新中市·催眠规则', null).catch(function(){});   // 清掉改造前那个独立的规则条目
  }).catch(function(e){ hpTodayAuxReady=true; hpWarn('今日附加内容读取失败：'+((e&&e.message)||e)); });
