    +'|b'+Math.round(hpBatPct/10)
    +'|n'+(hpNotifData?hpNotifData.map(function(x){ return x.type+x.from+x.text; }).join(''):'')
    +'|r'+(hpRuleData?hpRuleData.map(function(r){ return r.tag+r.target+r.rule; }).join(''):'');
}
function hpSyncTodayEntry(force){
  if(!hpIsTavern()) return;
