// 给主页日期补上星期（剧情只写「9月11日」时也算出来）
function hpFillWeekday(d){
  if(!d) return d;
  if(/星期|周[一二三四五六日天]/.test(d)) return d;
  var m=d.match(/(?:(\d{4})年)?(\d{1,2})月(\d{1,2})日/);
  if(!m) return d;
  var y=m[1]?parseInt(m[1],10):HP_GAME_YEAR;
  var dt=new Date(y, parseInt(m[2],10)-1, parseInt(m[3],10));
  if(isNaN(dt.getTime())) return d;
  var wd=CAL_WD[dt.getDay()];
  return m[1] ? (m[1]+'年'+m[2]+'月'+m[3]+'日 星期'+wd) : (m[2]+'月'+m[3]+'日 星期'+wd);
}
