function hpCalRender(){
  var grid=document.getElementById('calGrid'); if(!grid) return;
  var yEl=document.getElementById('calYear'); if(yEl) yEl.textContent=hpCalY;
  var mEl=document.getElementById('calMonth'); if(mEl) mEl.textContent=hpCalM+'月';
  var t=hpCalToday();
  var tdEl=document.getElementById('calToday');
  if(tdEl) tdEl.textContent=t ? ('今天 '+t.m+'月'+t.d+'日 星期'+CAL_WD[new Date(t.y,t.m-1,t.d).getDay()]+(t.time?(' · '+t.time):'')+(t.src?(' · '+t.src):'')) : '剧情日期未知（可在剧情中写明日期后自动同步）';
  var stEl=document.getElementById('calStatusTime');
  if(stEl && t && t.time) stEl.textContent=t.time;

  var dim=hpCalDaysInMonth(hpCalY,hpCalM);
  var first=hpCalFirstWd(hpCalY,hpCalM);
  var prevDim=(hpCalM===1)?hpCalDaysInMonth(hpCalY-1,12):hpCalDaysInMonth(hpCalY,hpCalM-1);
  var cells=[], i;
  for(i=first-1;i>=0;i--) cells.push({d:prevDim-i, out:true, m:(hpCalM===1?12:hpCalM-1), y:(hpCalM===1?hpCalY-1:hpCalY)});
  for(i=1;i<=dim;i++) cells.push({d:i, out:false, m:hpCalM, y:hpCalY});
  while(cells.length%7!==0 || cells.length<35) cells.push({d:cells.length-first-dim+1, out:true, m:(hpCalM===12?1:hpCalM+1), y:(hpCalM===12?hpCalY+1:hpCalY)});

  var h='';
  for(i=0;i<cells.length;i++){
    var c=cells[i];
    var wd=(first+i)%7;   // 0=周日
    var evs=hpCalEventsOf(c.y,c.m,c.d);
    var isToday=(t && c.y===t.y && c.m===t.m && c.d===t.d && !c.out);
    var cls='calCell'+(c.out?' out':'')+(wd===0?' sun':'')+(wd===6?' sat':'')+(isToday?' today':'');
    if(!c.out && hpCalSel===hpCalKey(c.y,c.m,c.d)) cls+=' sel';
    // 长区间底色（暑假/寒假等）
    var inLong=false;
    for(var q=0;q<CAL_SCHOOL.length;q++){
      var e=CAL_SCHOOL[q];
