      else if(evs[k].type==='evt'){ hasEvt=true; if(evs[k].start && !evtTag) evtTag=evs[k].n; }
      else { hasMine=true; if(!mineTag) mineTag=evs[k].n; }
    }
    var tag=fesTag||evtTag||mineTag;   // 同一天既是节日又是活动时，优先显示节日
    if(hasFes) dots+='<span class="cdDot fes"></span>';
    if(hasEvt) dots+='<span class="cdDot evt"></span>';
    if(hasMine) dots+='<span class="cdDot mine"></span>';
    h+='<div class="'+cls+'" onclick="hpCalOpenDay('+c.y+','+c.m+','+c.d+')">'
      +'<span class="cdNum">'+c.d+'</span>'
      +(dots?('<span class="cdDots">'+dots+'</span>'):'')
      +(tag?('<span class="cdTag">'+hpEsc(tag.slice(0,6))+'</span>'):'')
      +'</div>';
  }
  grid.innerHTML=h;

  // 本月日程列表
  var list=document.getElementById('calList');
  var tit=document.getElementById('calListTit');
