  if(list){
    var rows=[], dd;
    for(dd=1;dd<=dim;dd++){
      var es=hpCalEventsOf(hpCalY,hpCalM,dd);
      for(var z=0;z<es.length;z++){
        if(es[z].start===false) continue;   // 跨天活动只在开始日列一次
        rows.push({d:dd, n:es[z].n, type:es[z].type, mi:es[z].mi});
