// 注意：这里**不能**叫 hpCalKey —— 7032 行已有 hpCalKey(y,m,d)（返回 2026-09-13）。
// 同名会因函数声明提升被这条覆盖，导致 CAL_MARKS[w].d（日期串）永远 !== hpCalKey(y,m,d)，
// 自定义日历标记在日历上直接不显示。
function hpCalMarkKey(d,t){ return d+'|'+t; }
function hpCalMergeMark(d,t){
  if(CAL_DELS[hpCalMarkKey(d,t)]) return;            // 已被删除过的，别再合并回来
  for(var i=0;i<CAL_MARKS.length;i++){ if(CAL_MARKS[i].d===d && CAL_MARKS[i].t===t) return; }
  CAL_MARKS.push({d:d, t:t});
}
// 只解析「【玩家标记】」段，别把下面的当月日程误当标记
function hpCalParseMarkContent(content){
  if(!content) return;
  var lines=String(content).split(/\r?\n/);
  var inMarks=false;
  for(var i=0;i<lines.length;i++){
    var ln=lines[i];
    if(ln.indexOf('【玩家标记】')===0){ inMarks=true; continue; }
    if(ln.charAt(0)==='【'){ inMarks=false; continue; }
    if(!inMarks) continue;
    var mm=ln.match(/^(\d{4}-\d{2}-\d{2})\s+([\s\S]+)$/);
    if(mm) hpCalMergeMark(mm[1], mm[2].trim());
  }
}
