    for(var i=0;i<arr.length;i++){
      var m=arr[i]; if(!m||typeof m!=='object') continue;
      var txt=m.mes||''; if(typeof txt!=='string') continue;
      var mc=txt.match(/^【剧情日期校准】(\d{4})-(\d{2})-(\d{2})(?:\s+(\d{1,2}:\d{2}))?/);
      if(mc) lastCal={y:parseInt(mc[1],10), m:parseInt(mc[2],10), d:parseInt(mc[3],10), time:mc[4]||''};
      var md=txt.match(/^【日历标记】删除\s+(\d{4}-\d{2}-\d{2})\s+([\s\S]+)$/);
      if(md){ CAL_DELS[hpCalMarkKey(md[1], md[2].trim())]=1; continue; }
      var mm=txt.match(/^【日历标记】(\d{4}-\d{2}-\d{2})\s+([\s\S]+)$/);
      if(mm) hpCalMergeMark(mm[1], mm[2].trim());
    }
