      hpManualDate={y:lastCal.y, m:lastCal.m, d:lastCal.d};
      HP_GAME_YEAR=lastCal.y;
      hpUpdateClockDisplay();
    }
    if(hpCalY&&hpCalM) hpCalRender();
  }).catch(function(e){ hpWarn('日历标记读取失败（①聊天记录）：'+((e&&e.message)||e)); });
  var TH=window.parent.TavernHelper;
