  // ③ 直读共用世界书（不依赖它是否出现在角色卡/全局世界书列表里）
  if(TH && TH.getWorldbook){
    hpWbRead(TH, HP_SYNC_WB).then(function(eb){
      for(var i=0;i<eb.length;i++){
