// 剥掉模型漏进正文的推理过程（内部组装路径没有酒馆侧 reasoning 剥离）：
// ① <thinking>/<reasoning> 等标签块与同名代码围栏；② 开头的 "Thinking Process:" / "思考过程：" 段落
//（模型常把它写成一串数字/星号列表，正文跟在列表结束后）。
// 若整条回复都是推理、剥完为空，则原样返回 —— 宁可留着也不要吞掉整条回复。
function hpStripReasoning(t){
  if(t==null) return '';
  var s=String(t), F='\x60\x60\x60';
  // **内容即推理**的标签：整块丢。2026-09-14 在用户真实记录里见到 <draft>（预设里的规划块，
  // 一条就 2900 字，占满整个上下文），以及 learning 的闭标签孤零零漏在正文中间。
  var RB='thinking|think|thought|thoughts|reasoning|analysis|analyze|scratchpad|reflection|deliberation|learning|monologue|inner_monologue|chain_of_thought|draft|draft_notes';
  // **只删标签、保留内容**的包装：这些里面装的是正文（bginfor/catsay 来自用户预设的输出格式）
  var RT=RB+'|content|recap|details|summary|bginfor|catsay|peip';
  var out=s.replace(new RegExp(F+'(?:'+RB+')\\s*\\n[\\s\\S]*?'+F,'gi'),'');
  out=out.replace(new RegExp('<('+RB+')\\b[^>]*>[\\s\\S]*?<\\/\\1>','gi'),'');
  // 前导块：从消息开头到第一个 </thinking> 之间全是计划文本 → 整段删。
  // 专治「开标签丢失、只剩 </thinking>」的形态（2026-09-14 实测：一整段『1. 分析当前情境…』
  // 裸露在正文前，看起来就是剧情跳转）。**必须排在下面的「落单标签」之前** ——
  // 那一步会把 </thinking> 删掉，之后就再也匹配不到了。
  out=out.replace(/^[\s\S]*?<\/think(ing)?>/i,'');
  // 落单的开/闭标签也要去掉：开标签可能在被截掉的前文里，只剩一个 </learning> 挂在正文中间
  out=out.replace(new RegExp('<\\/?(?:'+RT+')\\b[^>]*>','gi'),'');
  var lines=out.replace(/^\s+/,'').split('\n');
  var head=/^[\s*>#]*\**\s*(?:thinking process|thought process|reasoning|chain of thought|scratchpad|思考过程|分析过程|推理过程)\**\s*[:：]/i;
  var li=/^\s*(?:\d+[.、)）]|[-*•·]|#{1,4}\s|\*\*)/;
  if(lines.length && head.test(lines[0])){
    var i=0;
    while(i<lines.length){
      var ln=lines[i], nxt=(i+1<lines.length)?lines[i+1]:'';
      if(ln.trim()===''){ if(nxt.trim()!=='' && li.test(nxt)){ i++; continue; } break; }
      if(i>0 && !li.test(ln)) break;
      i++;
    }
    out=lines.slice(i).join('\n');
  }
  // 模型有时把内心独白直接写成正文开头的一段「🧠 …」——整段丢掉
  out=out.replace(/^\s*🧠[\s\S]*?(?:\n\s*\n|$)/,'');
  out=out.replace(/^\s+/,'').trim();
  return out || String(t).trim();
}
// 丢弃 <swl> 内心独白块（连同内容）：swl 是气泡里的折叠思考，不该进聊天正文。
// 注意不能放进 hpStripReasoning —— splitThought* 正是靠 swl 提取气泡里的思考。
// 与 hpStripReasoning 同一条兜底规则：整条只有独白时不吐空消息，回退原文。
function hpDropThought(t){
  if(t==null) return '';
  var out=String(t).replace(/<swl>[\s\S]*?<\/swl>/gi,'').replace(/<\/?swl>/gi,'');
  return out.trim() ? out : String(t);
}
// 把 AI 回复清洗为纯文本剧情：剥 markdown 围栏、HTML 标签（换行标签转行），避免酒馆按代码块/富文本渲染
function hpCleanText(t){
  if(t==null)return '';
  var s=hpDropThought(hpStripReasoning(String(t)));
  s=s.replace(/\s*\x60{3}[a-zA-Z\x20]*\s*/g,'');           // 剥 markdown html 代码围栏
  s=s.replace(/<br\s*\/?\s*>/gi,'\n');                      // br → 换行
  s=s.replace(/<\/(?:p|div|li|ul|ol|blockquote|section|h[1-6])\s*>/gi,'\n');
  s=s.replace(/<\/?(?:b|strong|em|i|u|s|a|span|font|h[1-6])[^>]*>/gi,'');
  s=s.replace(/<[^>]+>/g,'');                               // 其余标签一律剥除
  s=s.replace(/&nbsp;/g,' ').replace(/&amp;/g,'&').replace(/&lt;/g,'<').replace(/&gt;/g,'>').replace(/&#39;/g,"'").replace(/&quot;/g,'"');
  s=s.replace(/[ \t]+\n/g,'\n').replace(/\n{3,}/g,'\n\n');
  return s.trim();
}
