  if(!TH) return Promise.reject(new Error('生成 API 不可用'));
  if(HP_USE_PRESET && TH.generate){
    // injects 会像深度提示一样插进上下文；should_silence 让酒馆只生成、不自动把消息写进聊天
    //（写不写由各调用方自己决定，避免出现两条一样的回复）
    var inj=[], i;
    for(i=0;i<(prompts||[]).length;i++){
      var p=prompts[i]||{};
      if(!p.content) continue;
      inj.push({ role:p.role||'system', content:String(p.content), position:'in_chat', depth:0, should_scan:true });
    }
    return Promise.resolve(TH.generate({ user_input:action, injects:inj, should_silence:true }));
  }
