function hpGenerateReply(action, promptSys, okCb, errCb){
  var TH=window.parent.TavernHelper;
  var prompts=promptSys||[];
  var beforeCount=-1;
  function fail(e){ if(errCb){ try{ errCb(e); }catch(x){} } }
  try{
    // generateRaw 用 ordered_prompts 时只处理「列出」的占位符；漏掉 chat_history 会让 AI 看不到此前输出，
    // 导致连续能力（先发情再催眠）各自从零写、剧情脱节。故带全内置顺序 + 自定义指令 + 聊天历史 + 用户输入。
    hpGenReply(action, prompts, '')
    .then(function(reply){
      if(reply&&typeof reply==='object'&&reply.content!=null)reply=reply.content;
      var text=hpCleanText(reply);
      beforeCount=hpChatMesCount();
      return createChatMessages([{ role:'assistant', message:text }], { refresh:'affected' });   // 走 app 的 shim（内部优先 TH，缺失时安全返回）
    })
    .then(function(){
      if(okCb){ try{ okCb(); }catch(x){} }
      // 兜底改为「按需触发」：个别酒馆版本 refresh:'affected' 不建新增楼层的 DOM，此时才全量重载。
      // 原实现每次生成都无条件 refreshChat()，长聊天下会整屏重渲染，是卡顿的主要来源之一。
      setTimeout(function(){
        var after=hpChatMesCount();
        if(beforeCount>=0 && after>=0 && after<=beforeCount){
          try{ var pd=window.parent; if(pd&&typeof pd.refreshChat==='function') pd.refreshChat(); }catch(e){}
        }
      }, 400);
    })
    .catch(fail);
  }catch(e){ fail(e); }
